window.NHZ_YUWEN ={"grammar":{"categories":[{"id":"cilei","items":[{"name":"名词","例子":["老师、北京（人物/处所）","春天、昨天（时间）","上面、中间（方位）","我的书包、小明的生日","三本书、两个人（名词前能加数量词）","花开了、春天来了（名词能作主语）","妈妈在厨房做饭。","小狗在院子里跑来跑去。","秋天，树叶黄了。","书包里装着课本和文具。","桌子上面放着一杯水。","孩子们在操场上踢足球。"],"口诀":"人事物时地，名词要牢记","易错":"方位词常被误认为副词","讲解":"表示人、事物、时间、处所、方位等的词","深讲":"名词是给人、事物、时间、处所、方位起的名字。分五小类：人物（老师、妈妈）、事物（书包、苹果）、时间（春天、昨天）、处所（北京、学校）、方位（上面、中间）。名词一般能做主语和宾语，前面常能加数量词，如“三本书”“两个人”。","分类":[{"类":"人物名词","说明":"给人起的名字。","代表":"老师、妈妈、小明、爷爷","例子":["小明在教室里看书。"]},{"类":"事物名词","说明":"给具体东西起的名字。","代表":"书包、苹果、桌子","例子":["书包放在桌子上。"]},{"类":"时间名词","说明":"表示时间的词。","代表":"春天、昨天、早上","例子":["春天，花开了。"]},{"类":"处所名词","说明":"表示地方的词。","代表":"学校、北京、家里","例子":["我们在学校上课。"]},{"类":"方位名词","说明":"表示上下、前后、里外的词。","代表":"上面、中间、里、外","例子":["书在桌子上面。"]}],"怎么认":["前面能不能加数量词？能加“三本、两个”的，多半是名词。","能不能回答“谁/什么”？能回答“谁来了、什么掉了”的，多半是名词。","前面能不能加“很”？名词一般不能说“很书包、很北京”。"],"辨析":"名词和代词都指人或事物，但代词是“替身”：他、这、那不指具体名字，换了场合指的东西就变了；名词是固定名字，换场合还是它。方位词是名词里的一小类，只表示方向和位置。","例句解析":[{"句":"小明在北京看书。","析":"“北京”是处所名词，说明看书的地方；“书”是事物名词，是“看”的对象。"},{"句":"春天来了，花开了。","析":"“春天”是时间名词，作主语，说明什么时候；“花”是事物名词。"}],"练习":[{"q":"下面哪个词是名词？","options":["跑步","桌子","很快","在"],"answer":1,"解析":"“桌子”是事物名词；“跑步”是动词，“很快”是副词加形容词，“在”是介词。","类":"事物名词"},{"q":"“昨天”是什么词？","options":["动词","时间名词","副词","形容词"],"answer":1,"解析":"“昨天”表示时间，是时间名词。","类":"时间名词"},{"q":"“书在上面”中，“上面”是？","options":["副词","方位名词","动词","连词"],"answer":1,"解析":"“上面”是方位词，属于名词，不要因为它在句末就当成副词。","类":"方位名词"}],"图示":"<svg viewBox=\"0 0 600 220\" id=\"svg\">  <!-- 句子 -->  <text x=\"300\" y=\"40\" text-anchor=\"middle\" font-size=\"22\" fill=\"#2c3328\" id=\"sent\" opacity=\"0\">小狗在院子里快乐地跑    <animate attributeName=\"opacity\" values=\"0;1\" keyTimes=\"0;1\" dur=\"0.8s\" begin=\"0s\" fill=\"freeze\"/>  </text>  <!-- 词 -->  <g font-size=\"20\" text-anchor=\"middle\">    <text x=\"120\" y=\"100\" fill=\"#2c3328\" id=\"w1\" opacity=\"0\">小狗      <animate attributeName=\"opacity\" values=\"0;1\" keyTimes=\"0;1\" dur=\"0.4s\" begin=\"0.8s\" fill=\"freeze\"/>    </text>    <text x=\"210\" y=\"100\" fill=\"#2c3328\" id=\"w2\" opacity=\"0\">在      <animate attributeName=\"opacity\" values=\"0;1\" keyTimes=\"0;1\" dur=\"0.4s\" begin=\"1.2s\" fill=\"freeze\"/>    </text>    <text x=\"300\" y=\"100\" fill=\"#2c3328\" id=\"w3\" opacity=\"0\">院子里      <animate attributeName=\"opacity\" values=\"0;1\" keyTimes=\"0;1\" dur=\"0.4s\" begin=\"1.6s\" fill=\"freeze\"/>    </text>    <text x=\"400\" y=\"100\" fill=\"#2c3328\" id=\"w4\" opacity=\"0\">快乐地      <animate attributeName=\"opacity\" values=\"0;1\" keyTimes=\"0;1\" dur=\"0.4s\" begin=\"2.0s\" fill=\"freeze\"/>    </text>    <text x=\"490\" y=\"100\" fill=\"#2c3328\" id=\"w5\" opacity=\"0\">跑      <animate attributeName=\"opacity\" values=\"0;1\" keyTimes=\"0;1\" dur=\"0.4s\" begin=\"2.4s\" fill=\"freeze\"/>    </text>  </g>  <!-- 黑三角掉落到名词上 -->  <g id=\"tri1\" opacity=\"0\">    <polygon points=\"120,60 105,85 135,85\" fill=\"#1a1a1a\"/>    <animate attributeName=\"opacity\" values=\"0;1\" keyTimes=\"0;1\" dur=\"0.3s\" begin=\"2.8s\" fill=\"freeze\"/>    <animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,-30;0,0\" dur=\"0.3s\" begin=\"2.8s\" fill=\"freeze\"/>  </g>  <g id=\"tri2\" opacity=\"0\">    <polygon points=\"300,60 285,85 315,85\" fill=\"#1a1a1a\"/>    <animate attributeName=\"opacity\" values=\"0;1\" keyTimes=\"0;1\" dur=\"0.3s\" begin=\"3.2s\" fill=\"freeze\"/>    <animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,-30;0,0\" dur=\"0.3s\" begin=\"3.2s\" fill=\"freeze\"/>  </g>  <!-- 非名词变灰 -->  <animate xlink:href=\"#w2\" attributeName=\"fill\" values=\"#2c3328;#9aa39a\" dur=\"0.4s\" begin=\"3.6s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <animate xlink:href=\"#w4\" attributeName=\"fill\" values=\"#2c3328;#9aa39a\" dur=\"0.4s\" begin=\"3.8s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <animate xlink:href=\"#w5\" attributeName=\"fill\" values=\"#2c3328;#9aa39a\" dur=\"0.4s\" begin=\"4.0s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <!-- 说明文字 -->  <text x=\"300\" y=\"160\" text-anchor=\"middle\" font-size=\"15\" fill=\"#4a7a59\" opacity=\"0\">小狗、院子是名词 → 戴上黑三角    <animate attributeName=\"opacity\" values=\"0;1\" keyTimes=\"0;1\" dur=\"0.5s\" begin=\"4.2s\" fill=\"freeze\"/>  </text>  <text x=\"300\" y=\"185\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">在、快乐地、跑不是名词 → 变灰    <animate attributeName=\"opacity\" values=\"0;1\" keyTimes=\"0;1\" dur=\"0.5s\" begin=\"4.5s\" fill=\"freeze\"/>  </text></svg>","类比":"名词的符号是一座<b>黑色小山</b>▲，稳稳地立在那里——就像万物的名字，稳定、实在。你能摸到、看到、想到的东西，都有名字：桌子、北京、勇气、昨天。","subtitle":"万物的名字「黑三角」","变式表":{"不变":"表示人、事物、时间、处所、方位等的名称","可变":{"小类":["人物名词（老师/妈妈）","事物名词（桌子/书）","时间名词（春天/昨天）","处所名词（北京/学校）","方位词（上面/中间）"],"句中位置":["作主语（老师来了）","作宾语（买书）","作定语（北京人）"]},"边界":"方位词易误判为副词；时间名词、处所名词可以直接作状语（明天见、我们北京见），一般名词作状语要借助介词（在桌子上写）","覆盖已确认":["小类","句中位置"],"覆盖缺失":[]},"前置知识":[]},{"name":"动词","例子":["跑、吃（动作）","喜欢、害怕（心理）","有、在（存在）","我每天跑步上学","会游泳、能跑步（能愿动词）","跑着、吃了、去过（动词后能加着、了、过）","我每天跑步锻炼身体。","小鸟在枝头唱歌。","他认真地思考问题。","妈妈正在洗衣服。","我们明天去公园春游。","同学们热烈地讨论起来。"],"口诀":"动作心理变化，动词来表达","易错":"“是”有时是动词（判断），有时是副词（强调）","讲解":"表示动作、行为、心理活动、存在变化的词","深讲":"动词表示动作、行为、心理活动和存在变化。分动作（跑、吃）、心理（喜欢、害怕）、存在（有、在）、能愿（会、能、要）、趋向（来、去、上、下）。动词一般能作谓语，常常能带宾语，动作动词后面常能加“着、了、过”。","分类":[{"类":"动作动词","说明":"表示具体动作。","代表":"跑、跳、写、吃","例子":["小明在操场上跑步。"]},{"类":"心理动词","说明":"表示心里想、感觉。","代表":"喜欢、害怕、想、爱","例子":["我喜欢画画。"]},{"类":"存在动词","说明":"表示有、在。","代表":"有、在","例子":["教室里有许多书。"]},{"类":"能愿动词","说明":"表示愿意、能够、应该。","代表":"会、能、要、应该","例子":["我会写自己的名字。"]},{"类":"趋向动词","说明":"表示动作的方向。","代表":"来、去、上、下、进、出","例子":["妈妈走进教室。"]}],"怎么认":["能不能带宾语？“吃什么、看什么”能接上宾语的，多半是动词。","后面能不能加“着、了、过”？“跑着、吃了、去过”都通顺的，多半是动词。","前面能不能加“很”？动作动词一般不能说“很跑、很吃”（喜欢这类心理动词是例外）。"],"辨析":"动词和形容词都常作谓语，但动词讲“做什么”，形容词讲“怎么样”；“他跑得快”里“跑”是动词，“快”是形容词，讲跑的样子。动词和副词也别混：副词是修饰动词的“小跟班”，自己不当谓语中心。","例句解析":[{"句":"小狗在草地上跑。","析":"“跑”是动作动词，作谓语；“在草地上”是地点，说明跑的地方。"},{"句":"我喜欢踢足球。","析":"“喜欢”是心理动词，作谓语；“踢足球”是它带的宾语，说明喜欢什么。"}],"练习":[{"q":"下面哪个词是动词？","options":["美丽","跳绳","很","的"],"answer":1,"解析":"“跳绳”是动作动词；“美丽”是形容词，“很”是副词，“的”是助词。","类":"动作动词"},{"q":"“害怕”属于哪类动词？","options":["动作动词","心理动词","形容词","副词"],"answer":1,"解析":"“害怕”表示心理活动，是心理动词。","类":"心理动词"},{"q":"“他跑得很快”中，“跑”是？","options":["形容词","副词","动词","名词"],"answer":2,"解析":"“跑”讲做什么，是动词；“快”讲跑的样子，是形容词。","类":"动作动词"}],"图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">跑、吃</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">动作动词：看得见的动作</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">喜欢、害怕</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">心理动词：看不见的感受</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">会、能</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">能愿动词：表示可能、愿望</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">动词=大红太阳●，句子的发动机<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","类比":"动词的符号是一颗<b>大红太阳</b>●，散发能量——句子没有动词就像汽车没有发动机，跑不起来。跑、吃、喜欢、是，都是动作或状态。","subtitle":"动作的发动机「大红圆」","变式表":{"不变":"表示动作、行为、心理活动、存在、变化","可变":{"小类":["行为动词（跑/吃）","心理动词（喜欢/想）","判断动词（是）","能愿动词（会/能/要）","趋向动词（来/去/上）"],"及物性":["及物（吃+饭）","不及物（跑/睡）"]},"边界":"心理动词不能用于把字句（✗我把他喜欢）；能愿动词后必须接动词（✗我会书）","覆盖已确认":["小类","及物性"],"覆盖缺失":[]},"前置知识":[]},{"name":"形容词","例子":["红、方（形状）","善良、勇敢（性质）","迅速、雪白（状态）","今天的太阳暖洋洋的","很红、非常勇敢（形容词前能加很）","花很红（形容词能作谓语）","这朵花真美丽。","湖水清澈见底。","他跑得很快。","夜晚的星空格外明亮。","她的声音很甜美。","这个问题比较复杂。","他很高。（'很'修饰性质形容词'高'）","雪白的床单✗很雪白。（状态形容词一般不受'很'修饰）"],"口诀":"形状性质状态，形容词来扮","易错":"副词“很”+形容词是常见搭配，别把“很”当形容词","讲解":"表示人或事物的形状、性质、状态的词","深讲":"形容词表示人或事物的形状、性质和状态。分性质（善良、勇敢）、形状（方、圆）、状态（雪白、暖洋洋）。形容词一般能受“很、非常”修饰，不能带宾语；作定语时常带“的”，作谓语时直接说明主语怎么样，作补语时说明动作的结果或样子。","分类":[{"类":"性质形容词","说明":"表示人或事物的性质、好坏。","代表":"善良、勇敢、聪明、美丽","例子":["她是一个勇敢的孩子。"]},{"类":"形状形容词","说明":"表示形状、大小。","代表":"方、圆、大、小、长","例子":["桌子是方的。"]},{"类":"状态形容词","说明":"表示当时的样子、状态，常是叠词。","代表":"雪白、暖洋洋、亮晶晶","例子":["雪白的墙，真好看。"]}],"怎么认":["前面能不能加“很”？“很红、很勇敢”通顺的，多半是形容词。","后面能不能带宾语？形容词一般不能说“红书、快饭”这样的搭配。","能不能回答“怎么样”？能回答主语“怎么样”的，多半是形容词。"],"辨析":"形容词和副词都和程度有关，但形容词能作谓语（“花很红”），副词不能单独作谓语，只能修饰别人。“很”本身是副词，不是形容词。状态形容词如“雪白、暖洋洋”一般不受“很”修饰，不能说“很雪白”。","例句解析":[{"句":"今天的太阳暖洋洋的。","析":"“暖洋洋”是状态形容词，作谓语，说明太阳的样子。"},{"句":"雪白的墙真干净。","析":"“雪白”是形容词，作定语，修饰“墙”；“干净”也是形容词，作谓语。"}],"练习":[{"q":"下面哪个词是形容词？","options":["跑","美丽","在","把"],"answer":1,"解析":"“美丽”表示性质，是形容词；“跑”是动词，“在”是介词，“把”是介词。","类":"性质形容词"},{"q":"“雪白的墙”中，“雪白”是？","options":["名词","动词","形容词","副词"],"answer":2,"解析":"“雪白”表示墙的样子，作定语，是形容词。","类":"状态形容词"},{"q":"“很”是什么词？","options":["形容词","副词","动词","名词"],"answer":1,"解析":"“很”修饰形容词和动词，自己是副词，别把跟班当主角。","类":"综合"}],"图示":"<svg viewBox=\"0 0 640 280\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g id=\"wrongG\"><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"20\" fill=\"#b85a52\">雪白的床单很雪白</text><text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">✘ 状态形容词不能加\"很\"</text><animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-5,0;5,0;-5,0;0,0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/><animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.5s\" begin=\"1.5s\" fill=\"freeze\"/></g><text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"32\" fill=\"#4a7a59\" opacity=\"0\">✓<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/></text><text x=\"320\" y=\"200\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">雪白的床单 / 山很高<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.2s\" fill=\"freeze\"/></text><text x=\"320\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">性质形容词（高、红）才能加\"很\"<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.6s\" fill=\"freeze\"/></text></svg>","subtitle":"名词的化妆师「蓝三角」","类比":"形容词的符号是一座<b>蓝色小山</b>▲，紧挨着名词的黑三角——它是名词的化妆师，专门描述样子：红的花、善良的人、雪白的墙。","变式表":{"不变":"表示人或事物的性质、状态、形状","可变":{"小类":["性质形容词（大/红/好）","状态形容词（雪白/冰凉/笔直）"],"程度修饰":["可受'很/非常'修饰（很大）","一般不受程度修饰（雪白✗很雪白）"]},"边界":"状态形容词（ABB式）一般不受'很'修饰；形容词作状语通常要加'地'（高兴地说）","覆盖已确认":["小类"],"覆盖缺失":["程度修饰"]},"前置知识":[]},{"name":"数词","例子":["一、两、百","第一、初三","我们班有45个同学","一、二、三（基数）","第一、第二（序数）","几、许多（概数）","三个苹果、第一名","两个人、两本书（量词前用两）","二月、第二名（读数和序数用二）","一年有四个季节。","我们班有三十名同学。","他得了第一名。"],"口诀":"数目次序，数词管住","易错":"“两”和“二”用法不同：序数用“二”，量词前多用“两”","讲解":"表示数目和次序的词","深讲":"数词表示数目和次序。分基数（一、二、三……）、序数（第一、第二……）和概数（几、许多、大约）。数词常常和量词一起用，组成数量短语，如“三个苹果”“第一名”。数词本身不指具体东西，要和量词、名词搭在一起才完整。","分类":[{"类":"基数词","说明":"表示数目多少。","代表":"一、二、三、十","例子":["桌上有三个苹果。"]},{"类":"序数词","说明":"表示第几个。","代表":"第一、第二、第三","例子":["他得了第一名。"]},{"类":"概数词","说明":"表示大概的数目。","代表":"几、许多、大约、十来个","例子":["篮子里有十来个苹果。"]}],"怎么认":["是不是表示“几个、第几个”？是的，多半是数词。","后面能不能跟量词？“三只、五本、第一”后面常跟量词或名词。","“二”和“两”要分场合：读数、序数用“二”（二月、第二），量词前面多用“两”（两个人、两本书）。"],"辨析":"数词和量词是一对搭档：数词管“多少”，量词管“用什么单位量”。“三”单独不能说“三书”，要说“三本书”；“只”单独也不能表数，要说“三只”。","例句解析":[{"句":"教室里有三只小猫。","析":"“三”是数词，“只”是量词，“三只”合起来修饰“小猫”，说明数量。"},{"句":"他在比赛中得了第一名。","析":"“第一”是序数词，表示次序，不是数量；“名”是量词。"}],"练习":[{"q":"下面哪个词是数词？","options":["只","三","本","个"],"answer":1,"解析":"“三”表示数目，是数词；“只、本、个”都是量词。","类":"基数词"},{"q":"“两个人”中，为什么不用“二”？","options":["量词前多用“两”","读数用“两”","序数用“两”","都可以"],"answer":0,"解析":"量词前面多用“两”，如两个人、两本书；读数和序数才用“二”。","类":"基数词"},{"q":"“第二名”中，“第二”是？","options":["基数","序数","量词","概数"],"answer":1,"解析":"“第二”表示次序，是序数词。","类":"序数词"}],"图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">一、两、百</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">基数：数多少</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">第一、第二</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">序数：排第几</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">几、许多</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">概数：大概多少</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">数词=会计，专管数量<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","类比":"数词是词里的<b>会计</b>，专门管数量：一、二、三、第一、百、千。数一数多少，都靠它。","变式表":{"不变":"表示数目","可变":{"类型":["基数词（一/二/十）","序数词（第一/初一）","概数（几/多/左右）","分数/倍数/百分数"],"组合":["单独（三个）","与量词组合（三本书）"]},"边界":"'两'和'二'分工：读数用二（二十），量词前用两（两个人）；'一'在去声前读阳平是变调不是变词","覆盖已确认":["类型","组合"],"覆盖缺失":[]},"前置知识":[]},{"name":"量词","例子":["个、只、条","米、公斤、次","一本书、三只小猫","个、只、条、本（名量词）","次、遍、回（动量词）","三个苹果、这本书","看三遍、跑两趟","一条鱼、一座山","一本鱼（错：量词搭配不对）","一双筷子","一群孩子在公园玩耍。","一阵风吹过，树叶沙沙响。"],"口诀":"名量（个只条）+动量（次回遍）","易错":"量词重叠表“每一”，如“个个”","讲解":"表示计量单位的词","深讲":"量词表示计量单位，分名量词和动量词。名量词量人或事物（个、只、条、本、张、座），动量词量动作的次数（次、遍、回、趟）。量词前面常有数词或指示代词（这、那），后面跟名词或动词，如“这本书”“看三遍”。","分类":[{"类":"名量词","说明":"量人或事物，后面跟名词。","代表":"个、只、条、本、张、座","例子":["一座桥横在河上。"]},{"类":"动量词","说明":"量动作的次数，后面跟动词。","代表":"次、遍、回、趟","例子":["这篇课文我读了三遍。"]}],"怎么认":["是不是跟在数词或“这、那”后面量东西？“三个、这本”里的“个、本”就是量词。","量的是人或物，还是动作次数？量人或物的是名量词，量次数的是动量词。","换一个量词试试：说“一条鱼”通顺，“一本鱼”就不通顺，量词和名词要搭配。"],"辨析":"量词和名词别混：名词是东西的名字，量词是量的单位。“书”是名词，“本”是量词。量词也不能单独表数，“本”不说“有几本”，要说“有几本书”。","例句解析":[{"句":"桌上有一条鱼。","析":"“条”是名量词，和鱼搭配；换成“本”就不通顺，说明量词要和名词配对。"},{"句":"这篇课文我读了三遍。","析":"“遍”是动量词，量动作“读”的次数，不是量课文本身。"}],"练习":[{"q":"“一座桥”中，量词是？","options":["一","座","桥","的"],"answer":1,"解析":"“座”是量词，量桥；“一”是数词，“桥”是名词。","类":"名量词"},{"q":"下面哪个是动量词？","options":["只","本","遍","条"],"answer":2,"解析":"“遍”量动作的次数，是动量词；其余都是名量词。","类":"动量词"},{"q":"下面哪组搭配不对？","options":["一条鱼","一本书","一座山","一本鱼"],"answer":3,"解析":"鱼用“条”不用“本”，量词要和名词搭配。","类":"名量词"}],"图示":"<svg viewBox=\"0 0 640 280\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g id=\"wrongG\"><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"20\" fill=\"#b85a52\">一本鱼</text><text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">✘ 量词搭配不对</text><animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-5,0;5,0;-5,0;0,0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/><animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.5s\" begin=\"1.5s\" fill=\"freeze\"/></g><text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"32\" fill=\"#4a7a59\" opacity=\"0\">✓<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/></text><text x=\"320\" y=\"200\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">一条鱼 / 一本书<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.2s\" fill=\"freeze\"/></text><text x=\"320\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">量词要和名词搭配：条→鱼，本→书<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.6s\" fill=\"freeze\"/></text></svg>","类比":"量词像给名词配的<b>量杯</b>：一<b>本</b>书、三<b>个</b>人、一<b>头</b>牛。没有量杯，数字就端不起来。","变式表":{"不变":"表示计量单位，与数词组合","可变":{"类型":["名量词（个/只/条/张）","动量词（次/遍/趟）","复合量词（人次）"],"搭配":["通用（个）","专用（头牛/匹马/艘船）"]},"边界":"量词不能单独作主宾语（✗个来了）；'一下'是动量词不是时间副词","覆盖已确认":["类型","搭配"],"覆盖缺失":[]},"前置知识":["数词"]},{"name":"代词","例子":["我、你、他（人称）","这、那（指示）","谁、怎么（疑问）","这是我的铅笔，那是你的","这、那、这里（指示）","谁、什么、哪里（疑问）","小明来了，他也来了","这是什么、那是谁","我们、你们、他们","这是谁的书包？","他们明天要去爬山。","大家安静一下，听老师讲。","你这么做不对。（'这么'=这样做，代词代替动词短语）","他长得那么高。（'那么'=那么高，代词代替形容词）"],"口诀":"人称指示疑问，代词三剑客","易错":"“这”“那”+量词+名词是代词性用法","讲解":"代替名词、动词、形容词等的词","深讲":"代词是代替名词、动词、形容词等实词的词，分人称（我、你、他、我们）、指示（这、那、这里、那里）、疑问（谁、什么、哪里、怎么）。代词的好处是不用重复名字：说过“小明”后，后面用“他”代替，句子就简洁了。","分类":[{"类":"人称代词","说明":"代替人的词。","代表":"我、你、他、我们、你们、他们","例子":["小明来了，他也来了。"]},{"类":"指示代词","说明":"指东西、地方的词。","代表":"这、那、这里、那里","例子":["这是我的铅笔，那是你的。"]},{"类":"疑问代词","说明":"用来提问的词。","代表":"谁、什么、哪里、怎么","例子":["这是什么？"]}],"怎么认":["是不是在代替前面出现过的人或事物？是的，多半是代词。","换一个具体名字试试：把“他”换成“小明”，句子意思不变，说明“他”是代词。","是不是在提问？“谁、什么、哪里”提问的，多半是疑问代词。"],"辨析":"代词和名词都能指人指物，但名词是固定名字，代词是“替身”，离开上下文就不知道指谁。“他”在不同句子里可以是小明，也可以是小刚；“小明”永远是小明。","例句解析":[{"句":"小明来了，他手里拿着一本书。","析":"第二个分句的“他”代替前面的“小明”，避免重复。"},{"句":"这是什么？","析":"“这”是指示代词，指眼前这个东西；“什么”是疑问代词，用来提问。"}],"练习":[{"q":"下面哪个词是代词？","options":["桌子","他们","跑步","美丽"],"answer":1,"解析":"“他们”是人称代词；“桌子”是名词，“跑步”是动词，“美丽”是形容词。","类":"人称代词"},{"q":"“谁来了？”中，“谁”是？","options":["名词","疑问代词","动词","副词"],"answer":1,"解析":"“谁”用来提问，是疑问代词。","类":"疑问代词"},{"q":"“他”在不同句子里指的人一样吗？","options":["一样","不一定，要看上下文","永远是小明","不能指人"],"answer":1,"解析":"代词是替身，指谁要看上下文，不能只看词本身。","类":"人称代词"}],"图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我、你、他</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">人称代词</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">这、那</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">指示代词</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">谁、什么</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">疑问代词</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">代词=替身演员，不用每次都喊全名<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","subtitle":"名词的替身「紫三角」","类比":"代词的符号是一座<b>紫色小山</b>▲，和名词的黑三角是亲戚——它是名词的替身演员：我、你、他、这、那、谁，不用每次都喊全名。","变式表":{"不变":"代替名词、动词、形容词、数量词的词","可变":{"小类":["人称代词（我/你/他）","指示代词（这/那）","疑问代词（谁/什么/怎么）"],"所替":["替名词（他=小明）","替动词（这么=这样做）","替形容词（那么=那么高）"]},"边界":"'这/那'作定语是代词（这本书），单独成句是指示；'怎么'问方式，'为什么'问原因，不混","覆盖已确认":["小类"],"覆盖缺失":["所替"]},"前置知识":["名词"]},{"name":"副词","例子":["很、非常（程度）","都、只（范围）","已经、正在（时间）","他跑得非常快","常常、总是（频率）","不、没（否定）","也许、大概（语气）","他非常喜欢读书。","我们都去过北京。","小明也参加了比赛。","天渐渐黑了下来。","妈妈已经做好了晚饭。","他已经走了。（'已经'在动词'走'前面）","这件衣服很好看。（'很'在形容词'好看'前面）"],"口诀":"程度范围时间，副词来限制","易错":"副词一般不能单独做谓语","讲解":"修饰动词、形容词，表示程度、范围、时间等的词","深讲":"副词修饰动词、形容词，表示程度、范围、时间、频率、语气、否定等。分程度（很、非常）、范围（都、只）、时间（已经、正在）、频率（常常、总是）、否定（不、没）、语气（也许、大概）。副词一般放在谓语前面，不能修饰名词，前面一般不能再加“很”。","分类":[{"类":"程度副词","说明":"表示程度深浅。","代表":"很、非常、最、更","例子":["他跑得非常快。"]},{"类":"范围副词","说明":"表示范围大小。","代表":"都、只、也、全","例子":["同学们都来了。"]},{"类":"时间副词","说明":"表示动作的时间。","代表":"已经、正在、马上","例子":["火车已经到了。"]},{"类":"频率副词","说明":"表示动作常常发生。","代表":"常常、总是、有时","例子":["他常常帮妈妈做家务。"]},{"类":"否定副词","说明":"表示否定。","代表":"不、没、别","例子":["我不去，你去吧。"]},{"类":"语气副词","说明":"表示说话人的推测、语气。","代表":"也许、大概、一定","例子":["也许明天会下雨。"]}],"怎么认":["是不是站在动词或形容词前面修饰它？“已经来了、非常快”里的“已经、非常”就是副词。","能不能修饰名词？副词一般不能说“很书包、都桌子”。","删掉它试试：删掉副词，句子主干还在，只是程度、时间、范围的意思弱了。"],"辨析":"副词和形容词都和程度有关，但形容词能作谓语（“花很红”），副词不能单独作谓语，只能修饰别人。“很”本身是副词，不是形容词。","例句解析":[{"句":"他已经写完了作业。","析":"“已经”是时间副词，放在动词“写”前面，说明动作完成了。"},{"句":"同学们都来了。","析":"“都”是范围副词，说明“同学们”一个不落，全都来了。"}],"练习":[{"q":"下面哪个词是副词？","options":["桌子","已经","跑步","美丽"],"answer":1,"解析":"“已经”表示时间，是副词；“桌子”是名词，“跑步”是动词，“美丽”是形容词。","类":"时间副词"},{"q":"“非常快”中，“非常”是？","options":["形容词","副词","动词","名词"],"answer":1,"解析":"“非常”修饰形容词“快”，自己是副词。","类":"程度副词"},{"q":"副词一般不能修饰？","options":["动词","形容词","名词","谓语"],"answer":2,"解析":"副词修饰动词和形容词，一般不能修饰名词。","类":"综合"}],"图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">很、非常</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">程度：多深</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">都、只</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">范围：多大圈</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">已经、正在</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">时间：何时</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">副词=小橙圆，紧挨动词给动作加说明<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","subtitle":"动词的小跟班「小橙圆」","类比":"副词的符号是一颗<b>小橙圆</b>，紧挨着动词的大红圆——小圆是大圆的跟班，专门给动作加说明：怎么跑（飞快地跑）、多深（很爱）、什么时候（已经走了）。","变式表":{"不变":"修饰动词、形容词，表示程度、范围、时间、语气等","可变":{"小类":["程度副词（很/非常）","范围副词（都/只）","时间副词（已经/正在）","语气副词（难道/究竟）","否定副词（不/没）"],"位置":["动词前（已经走了）","形容词前（很好）"]},"边界":"副词不能修饰名词（✗很桌子）；'不'和'没'分工：'不'表意愿/经常，'没'表完成/客观","覆盖已确认":["小类"],"覆盖缺失":["位置"]},"前置知识":["动词","形容词"]},{"name":"介词","例子":["在、从、向（方向）","把、被（对象）","关于、对于","我在教室里写作业","在教室、从北京（处所）","给妈妈、对他（对象）","向老师请教（方向）","为班级争光（目的）","比他高（比较）","把书放在桌上（处置）","他在北京住。（'在北京'在动词'住'前面）","他住在北京。（'在北京'在动词'住'后面）"],"口诀":"在从把被关于，介词引对象","易错":"“把”字句和“被”字句是中考重点句式","讲解":"用在名词、代词前，组成介词短语，表示方向、对象等的词","深讲":"介词引出时间、处所、对象、方式、原因等，和后面的名词、代词组成介宾短语。常见介词有在、从、向、往、给、对、为、比、跟、把、被。介宾短语常常作状语（“在教室里读书”）、补语（“来自北京”）或定语（“对他的关心”），但介词自己不能单独作谓语中心。","分类":[{"类":"处所方向介词","说明":"表示地方、方向。","代表":"在、向、往、从","例子":["他在教室里读书。"]},{"类":"时间介词","说明":"表示时间。","代表":"从、自、到","例子":["我们从早上读到中午。"]},{"类":"对象介词","说明":"表示动作的对象。","代表":"对、给、为、跟","例子":["妈妈给弟弟讲故事。"]},{"类":"方式介词","说明":"表示用的办法、工具。","代表":"用、按、照","例子":["他用铅笔画画。"]}],"怎么认":["后面是不是跟了一个名词或代词？“在教室、给妈妈、对他”这种结构，多半是介词短语。","能不能单独作谓语？介词自己不能单独作谓语中心，要和后面的词组成短语。","换成动词试试还通不通？介词后面的词不能像动词那样带“着、了、过”。"],"辨析":"介词和连词最容易混，关键看换位：连词“和”连接的“苹果和香蕉”可以换成“香蕉和苹果”，意思不变；介词引出的部分换位置就变味或不通，如“他向老师请教”换成“老师向他请教”，主角就换了人。","例句解析":[{"句":"小明在教室里看书。","析":"“在教室里”是介宾短语，作状语，说明看书的地点；“在”是介词。"},{"句":"妈妈给弟弟讲故事。","析":"“给弟弟”是介宾短语，说明讲故事的对象；这里的“给”引出对象，是介词。"}],"练习":[{"q":"“在教室里”中，“在”是？","options":["动词","介词","副词","连词"],"answer":1,"解析":"“在”引出地点，和“教室里”组成介宾短语，是介词。","类":"处所方向介词"},{"q":"下面哪个是介词短语？","options":["跑得快","在学校","很美丽","三本书"],"answer":1,"解析":"“在学校”是介词加名词组成的介宾短语；其余不是。","类":"处所方向介词"},{"q":"介词一般不能？","options":["跟名词","作状语","单独作谓语中心","组成短语"],"answer":2,"解析":"介词要和后面的词组成短语，不能单独作谓语中心。","类":"综合"}],"图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">在公园</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">处所：在哪里</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">从北京</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">起点：从哪里</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">向南</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">方向：向哪里</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">介词=绿色新月☽，总在名词前面带路<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","subtitle":"方位的月亮「绿新月」","类比":"介词的符号是一弯<b>绿色新月</b>☽，总在名词前面带路：在哪里（在公园）、从哪里（从北京）、向哪里（向南）。它像路标，指引方向。","变式表":{"不变":"引出动作的对象、时间、处所、方式等，与名词组成介宾短语","可变":{"类型":["对象（把/被/对）","时间（在/从/到）","处所（在/往）","方式（用/以）","原因（为/因为）"],"位置":["动词前（在北京住）","动词后（住在北京）"]},"边界":"介词不能单独作谓语（✗我在）；'在'作动词（他在家）vs作介词（在家住）看后接什么","覆盖已确认":["类型"],"覆盖缺失":["位置"]},"前置知识":["名词","动词"]},{"name":"连词","例子":["和、跟（并列）","但是、然而（转折）","因为、所以（因果）","我喜欢画画，也喜欢唱歌","苹果和香蕉（并列）","虽然累，但是坚持（转折）","因为下雨，所以取消（因果）","如果下雨，就回家（假设）","不是苹果，而是香蕉（选择）","老师和同学（可换位）","我喜欢唱歌和跳舞。（'和'连接短语）","他唱歌，而且跳得很好。（'而且'连接分句）"],"口诀":"连接上下，关系靠它","易错":"关联词搭配要完整，如“不仅……而且”不能丢一半","讲解":"连接词、短语、句子，表示并列、转折等关系的词","深讲":"连词连接词、短语或分句，表示并列、转折、因果、假设、选择等关系。常见连词有和、及、或、但是、因为、所以、如果、虽然。连词本身没有实在意义，只起连接作用；它连接的两部分在逻辑上是并列或有关系，不是修饰关系。","分类":[{"类":"并列连词","说明":"连接平等的两部分。","代表":"和、及、以及","例子":["苹果和香蕉都很好吃。"]},{"类":"转折连词","说明":"前后意思转折。","代表":"但是、可是、然而","例子":["他累了，可是还坚持跑。"]},{"类":"因果连词","说明":"表示原因和结果。","代表":"因为、所以、因此","例子":["因为下雨，所以我们没去公园。"]},{"类":"假设连词","说明":"表示假设。","代表":"如果、假如","例子":["如果努力，就会进步。"]},{"类":"选择连词","说明":"表示二选一。","代表":"或者、还是","例子":["你喝水还是喝牛奶？"]}],"怎么认":["是不是在连接两个词、短语或句子？“苹果和香蕉、虽然累但是坚持”里的“和、虽然……但是”就是连词。","连接的两个部分能不能换位置？并列连词连接的部分换位置意思基本不变。","删掉它试试：删掉连词，两部分就散了，关系也看不出来了。"],"辨析":"连词和介词最容易混，关键看换位：连词“和”连接的“老师和同学”可以换成“同学和老师”，意思不变；介词引出的对象换位置意思就变了，如“他向老师请教”不能随便换成“老师向他请教”。","例句解析":[{"句":"老师和同学一起打扫教室。","析":"“和”是连词，连接“老师”和“同学”，两个都是打扫的人，地位平等。"},{"句":"虽然下雨，但是运动会照常进行。","析":"“虽然……但是”是一对连词，连接两个分句，表示转折关系。"}],"练习":[{"q":"下面哪个词是连词？","options":["在","和","的","很"],"answer":1,"解析":"“和”连接两个词，是连词；“在”是介词，“的”是助词，“很”是副词。","类":"并列连词"},{"q":"“苹果和香蕉”换成“香蕉和苹果”，意思？","options":["变了","基本不变","变成介词","不能换"],"answer":1,"解析":"并列连词连接的部分换位置，意思基本不变。","类":"并列连词"},{"q":"“虽然……但是”表示？","options":["因果","转折","并列","选择"],"answer":1,"解析":"“虽然……但是”表示转折关系。","类":"转折连词"}],"图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">和、跟</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">并列：系在一起</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">但是</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">转折：拐个弯</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">因为…所以…</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">因果：前因后果</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">连词=绳子，语言里的胶水<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","类比":"连词像<b>绳子</b>，把词和句子系在一起：和、跟、因为、所以。它是语言里的胶水。","变式表":{"不变":"连接词、短语、分句，表示并列、递进、转折等关系","可变":{"类型":["并列（和/跟）","递进（而且）","转折（但是）","因果（因为）","假设（如果）"],"连接对象":["连词（老师和学生）","连短语","连分句"]},"边界":"'和'连名词是连词（我和他），连动词可能是介词（和他商量）；关联词成对出现不能残缺","覆盖已确认":["类型"],"覆盖缺失":["连接对象"]},"前置知识":["名词","动词"]},{"name":"助词","例子":["的、地、得（结构助词）","了、着、过（动态助词）","吗、呢（语气助词）","妈妈做的饭真好吃","我的书、红红的苹果（的）","快地跑、认真地写（地）","跑得快、写得好（得）","吃了、看着、去过（了、着、过）","好吗、走吧（吗、吧）","的、地、得分工要记牢"],"口诀":"的定地状得后补，时态语气也清楚","易错":"“的地得”用法：“的”定语、“地”状语、“得”补语","讲解":"附着在词、短语后表示语法意义的词","深讲":"助词附着在词、短语或句子后面，起结构、动态或语气作用，本身没有实在意义。分结构助词（的、地、得）、动态助词（了、着、过）、语气助词（吗、呢、吧、啊）。助词不能单独作句子成分，要和前面的词一起看。","分类":[{"类":"结构助词","说明":"放在词后面，起连接、结构作用。","代表":"的、地、得","例子":["红红的苹果真好看。"]},{"类":"动态助词","说明":"表示动作完成、进行、经历。","代表":"了、着、过","例子":["我看过这本书。"]},{"类":"语气助词","说明":"放在句末，表语气。","代表":"吗、呢、吧、啊","例子":["你去吗？"]}],"怎么认":["是不是附在别的词后面？“我的、快地、跑得快、吃了、好吗”里的“的、地、得、了、吗”就是助词。","删掉它试试：删掉助词，句子主干还在，但结构关系或语气就不清楚了。","“的、地、得”分工：的后跟名词，地后跟动词、形容词，得后跟补充说明。"],"辨析":"助词和语气词、叹词别混：语气词是助词里的一小类，只在句末表语气；叹词是独立成句的感叹词，多在句首。助词“了”表完成或变化，“着”表持续，“过”表经历，三者不能互换。","例句解析":[{"句":"红红的苹果真好吃。","析":"“的”是结构助词，连接定语“红红”和名词“苹果”。"},{"句":"他吃过北京烤鸭。","析":"“过”是动态助词，放在动词“吃”后面，表示曾经有过的经历。"}],"练习":[{"q":"“快地跑”中，“地”是？","options":["介词","结构助词","副词","连词"],"answer":1,"解析":"“地”连接状语和动词，是结构助词。","类":"结构助词"},{"q":"“吃了饭”中，“了”表示？","options":["持续","经历","完成","疑问"],"answer":2,"解析":"动词后的“了”表示动作完成。","类":"动态助词"},{"q":"下面哪个是语气助词？","options":["的","着","吗","得"],"answer":2,"解析":"“吗”在句末表示疑问语气，是语气助词。","类":"语气助词"}],"图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">的</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">定语标记：红红的苹果</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">地</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">状语标记：飞快地跑</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">得</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">补语标记：跑得快</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">助词=小跟班：的/地/得分工记牢<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","类比":"助词像<b>小跟班</b>，附在词后面帮忙：的、地、得、了、着、过。自己没独立意思，专门辅助别人。","变式表":{"不变":"附着在词、短语后，表示结构关系或语气","可变":{"类型":["结构助词（的/地/得）","动态助词（了/着/过）","语气助词（吗/呢/吧）"],"位置":["词后（书的）","句末（好吗）"]},"边界":"的/地/得：定语用'的'，状语用'地'，补语用'得'；'了'表完成（吃了）vs语气（太好了）","覆盖已确认":["类型","位置"],"覆盖缺失":[]},"前置知识":[]},{"name":"语气词","例子":["吗、呢、吧、啊","明天一起去打球吧！","好吗、吃饭了吗（吗）","一起去吧、走吧（吧）","你呢、他呢（呢）","真美啊、好啊（啊）","走吧是商量、走吗是提问","语气词在句末","你去过长城吗？","多美的风景啊！","我们一起去吧。","你怎么还没来呢？","是啊！","谁啊？","你好啊！","对啊！","快走啊！","多好的天啊！"],"口诀":"句尾表语气，吗呢吧啊","易错":"语气词不重读 “啊”表感叹、疑问、应答，不表平直陈述（✗“我是学生啊。”→“我是学生。”）。","讲解":"表示语气，常用在句尾的词","深讲":"语气词用在句末，表示陈述、疑问、祈使、感叹等语气。常见语气词有吗、呢、吧、啊、呀、么。语气词不表示实在意义，读起来语气不同，意思和态度就不同：说“走吧”是商量，说“走吗”是提问。\n“啊”是最活泼的语气词，有4种常用法：①感叹（多美啊！/多好的天啊！）；②疑问追问（谁啊？/你说什么啊？）；③应答认同（是啊/对啊/好啊）；④催促提醒（快点啊！/小心啊！）。注意：“啊”常跟在别的语气词后（好吧啊），读的时候按前一个字的尾音变读（呀/哇/哪）。（来源：AllSet Chinese Grammar Wiki，CC BY-NC-SA 3.0）","分类":[{"类":"陈述语气词","说明":"句末表平静陈述的语气。","代表":"了、啊","例子":["下雨了。"]},{"类":"疑问语气词","说明":"表提问。","代表":"吗、呢","例子":["你去吗？"]},{"类":"祈使语气词","说明":"表商量、希望对方做。","代表":"吧、啊","例子":["我们一起去吧。"]},{"类":"感叹语气词","说明":"表感叹。","代表":"啊、呀、哇","例子":["多美的花呀！"]}],"怎么认":["是不是在句末？句末的“吗、呢、吧、啊”多半是语气词。","换一个语气词试试：把“好吗”换成“好吧”，句子从提问变成了商量，说明语气词管的是语气。","删掉它试试：删掉语气词，句子意思还在，但语气、态度就没了。"],"辨析":"语气词和叹词都和语气有关，但语气词在句末、附着在句子上；叹词独立成句、多在句首。“啊，真美！”里的“啊”是叹词；“这花真美啊”里的“啊”是语气词。","例句解析":[{"句":"我们一起去公园吧。","析":"句末的“吧”是语气词，表示商量、建议。"},{"句":"你吃饭了吗？","析":"句末的“吗”是语气词，把陈述句变成了疑问句。"}],"练习":[{"q":"“一起去吧”中，“吧”是？","options":["动词","语气词","叹词","名词"],"answer":1,"解析":"句末的“吧”表示商量语气，是语气词。","类":"祈使语气词"},{"q":"语气词一般在？","options":["句首独立","句末","动词前","名词后"],"answer":1,"解析":"语气词用在句末，表示全句的语气。","类":"综合"},{"q":"“好吗”换成“好吧”，变的是？","options":["主语","语气","宾语","时间"],"answer":1,"解析":"换语气词，句子意思基本不变，变的是语气和态度。","类":"综合"},{"q":"“多美啊！”中“啊”表什么语气？","options":["疑问","感叹","祈使","陈述"],"answer":1,"解析":"“多美啊”是感叹：多美！","类":"感叹"},{"q":"哪句的“啊”表追问？","options":["是啊","谁啊？","快点啊","好啊"],"answer":1,"解析":"“谁啊？”是没听清、追问对方。","类":"疑问"}],"图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">…吗？</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">提问：你去过长城吗</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">…吧。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">商量：我们一起去吧</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">…啊！</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">感叹：多美的风景啊</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">语气词=句尾表情符号，味道全变<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","类比":"语气词像句尾的<b>表情符号</b>：吗、呢、吧、啊。同样一句话，加不同的语气词，味道完全不同。","变式表":{"不变":"附在句末，表示陈述、疑问、祈使、感叹等语气","可变":{"语气":["陈述（了/呢）","疑问（吗/呢）","祈使（吧）","感叹（啊）"],"位置":["句末（好吗）","句中停顿（我的天啊）"]},"边界":"语气词不表实在意义，去掉不影响基本句意；'呢'表疑问（你呢）vs表持续（看着呢）","覆盖已确认":["语气","位置"],"覆盖缺失":[]},"前置知识":[]},{"name":"叹词","例子":["啊、哎、哦、喂","哎呀，我忘带作业了！","啊，真美（感叹）","喂，你好（呼唤）","嗯，知道了（应答）","哈哈，真有趣（笑声）","哎呀，疼死我了","啊在句首是叹词、在句末是语气词","哎呀，我忘带钥匙了！","嘿，加油啊！","哇，这座山真高！","哼，我才不信呢！"],"口诀":"感叹呼唤应答，叹词来表达","易错":"叹词常独立成句，后用逗号或感叹号","讲解":"表示感叹、呼唤、应答的词","深讲":"叹词表示感叹、呼唤、应答等，独立成句或独立成分，常常在句首，后面常带感叹号或逗号。常见叹词有啊、哎呀、哦、喂、嗯、哈哈。叹词不作句子的主要成分，删掉它，句子主干还在，只是感情色彩弱了。","分类":[{"类":"感叹叹词","说明":"表惊讶、高兴、心疼等感情。","代表":"啊、哎呀、哇","例子":["哎呀，太好了！"]},{"类":"呼唤叹词","说明":"表叫人、引起注意。","代表":"喂、嘿","例子":["喂，你听到了吗？"]},{"类":"应答叹词","说明":"表答应、明白。","代表":"嗯、哦、好","例子":["嗯，我知道了。"]}],"怎么认":["是不是独立在句首、后面有感叹号或逗号？“啊，真美！喂，你好！”里的“啊、喂”就是叹词。","是不是在表示感叹、呼唤或应答？是的，多半是叹词。","删掉它试试：删掉叹词，句子还能成立，只是少了那股感情劲儿。"],"辨析":"叹词和语气词最容易混：叹词独立、多在句首（“啊，真美！”）；语气词附着在句末（“真美啊！”）。同一个“啊”字，位置不同，词类就不同——这正是“看位置、看作用”的好例子。","例句解析":[{"句":"啊，祖国的山河真壮丽！","析":"句首的“啊”是叹词，独立成成分，表达赞叹，后面用逗号隔开。"},{"句":"喂，你听见了吗？","析":"“喂”是叹词，表示呼唤，引起对方注意；句末的“吗”才是语气词。"}],"练习":[{"q":"“哎呀，疼死我了！”中，“哎呀”是？","options":["语气词","叹词","副词","形容词"],"answer":1,"解析":"句首独立的“哎呀”表示感叹，是叹词。","类":"感叹叹词"},{"q":"叹词常常在？","options":["句末","句首独立","动词后","名词前"],"answer":1,"解析":"叹词独立成句或成分，常常在句首。","类":"综合"},{"q":"“真美啊”中，“啊”是？","options":["叹词","语气词","动词","介词"],"answer":1,"解析":"句末的“啊”附着在句子上表语气，是语气词，不是叹词。","类":"综合"}],"图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">哎呀</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">惊讶：哎呀忘带钥匙了</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">喂</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">呼唤：喂，你好</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">哈哈</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">笑声：哈哈真有趣</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">叹词=突然喊出的一声，情绪的出口<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","类比":"叹词像突然喊出来的<b>一声</b>：啊、哎呀、唉、哼。是情绪的直接出口，不参与句子结构。","变式表":{"不变":"表示感叹、呼唤、应答的感叹声","可变":{"情感":["喜（哈哈）","悲（哎呀）","惊（啊）","应答（嗯/喂）"],"位置":["句首独立（哎呀，迟到了）","句中（我的天啊）"]},"边界":"叹词独立成句不作其他成分；'啊'作叹词（啊，春天）vs作语气词（好啊）看位置","覆盖已确认":["情感","位置"],"覆盖缺失":[]},"前置知识":[]},{"name":"离合词","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我们见过面。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“见面”是离合词，中间加“过”表经历：见+过+面。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">帮我一个忙。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“帮忙”是离合词，不能直接说“帮忙我”，用“我”放在中间：帮+我+一个+忙。</text></g></svg>","讲解":"动词和宾语合成一个词，平时合在一起像一个词，用的时候又能分开，中间可以加字。","深讲":"离合词 = 动词 + 宾语，两个字合起来表示一个动作，比如“睡觉”（睡+觉）、“见面”（见+面）。它最大的本事是“能分”：中间可以加“了/过”、数量词（一次、两小时），比如“睡了一觉”“见过面”“开了三小时会”。但它不能再带宾语：“见面他”是错的，要说“跟他见面”。（来源：AllSet Chinese Grammar Wiki，CC BY-NC-SA 3.0）","类比":"离合词像一个汉堡：两片面包（动词+宾语）夹在一起是一个汉堡，但中间能加生菜番茄（了、数量词）；只是你不能再往汉堡外面贴一块肉（不能再加宾语）。","口诀":"动宾合成词，中间能加料；再带宾语错，介词来介绍","例子":["我们见过面。","我睡了一个小时觉。","他结过两次婚。","跟朋友见面（不说“见面朋友”）","帮我一个忙（不说“帮忙我”）","生他的气。","洗了个热水澡。","他生气了（不说“生气他”）"],"易错":"“了/过”要放在中间（睡了觉✓，睡觉了✗）；后面不能直接加人或物，要加“跟/给”介绍（跟他见面✓，见面他✗）。","分类":[{"类":"加数量","说明":"中间加数量词，表示次数或时长。","代表":"见一面、睡两小时","例子":["我们见了一面。","我游了两次泳。"]},{"类":"表经历","说明":"中间加“过”，表示曾经做过。","代表":"见过面、结过婚","例子":["我们见过面。","他结过两次婚。"]},{"类":"加修饰","说明":"中间加形容词或动词，细化动作。","代表":"洗热水澡、理个发","例子":["洗了个热水澡。","我理了一次发。"]}],"怎么认":["能不能拆开加“了”？“睡了觉”说得通→是离合词；“喜了欢”说不通→不是。","后面能不能直接加人？“见面他”说不通→是离合词。","是不是“动词+宾语”合成的？睡觉=睡+觉，见面=见+面。"],"辨析":"离合词和一般动词的区别：一般动词后直接加宾语（“喜欢他”✓）；离合词后不能直接加宾语（“见面他”✗，要说“跟他见面”）。记住：离合词肚子里已经有一个宾语了，装不下第二个。","例句解析":[{"句":"我们见过面。","析":"“见面”是离合词，中间加“过”表经历：见+过+面。"},{"句":"帮我一个忙。","析":"“帮忙”是离合词，不能直接说“帮忙我”，用“我”放在中间：帮+我+一个+忙。"}],"练习":[{"q":"“睡了八个小时觉”中，“了”加在哪里？","options":["睡觉后面","睡和觉中间","句末","不能加"],"answer":1,"解析":"离合词的“了”加在中间：睡+了+觉。","类":"结构"},{"q":"哪句是对的？","options":["见面他","跟他见面","帮忙我","结婚她"],"answer":1,"解析":"离合词后不能直接加宾语，要用“跟”介绍：跟他见面。","类":"易错"},{"q":"“喜欢”是不是离合词？","options":["是","不是"],"answer":1,"解析":"“喜了欢”说不通，喜欢不能拆，不是离合词。","类":"辨析"},{"q":"“结过两次婚”中间加了什么？","options":["了","过+数量","的","着"],"answer":1,"解析":"“过”表经历，“两次”表数量，都加在中间。","类":"结构"}],"前置知识":["动词","宾语"]}],"name":"词的分类（13类）"},{"id":"duanyu","items":[{"name":"并列式","例子":["老师和同学","又高又大","调查研究","爸爸和妈妈","花草树木","聪明伶俐","吃喝玩乐","风雨雷电","父母兄弟","山川河流","笔墨纸砚","春夏秋冬"],"口诀":"地位平等是并列","易错":"“和”连接的也可能是介词短语，要看语境","讲解":"前后成分地位平等，无主次之分","深讲":"并列式是前后成分地位平等、谁也不修饰谁的短语，中间常有顿号、“和”“又……又……”连接；去掉任何一个成分，剩下的还能说得通，只是意思少了一半。","分类":[{"类":"名词并列","说明":"并列的成分是名词。","代表":"老师和同学、花草","例子":["老师和同学一起去春游。"]},{"类":"动词并列","说明":"并列的成分是动词。","代表":"调查研究、又唱又跳","例子":["同学们调查研究了校园植物。"]},{"类":"形容词并列","说明":"并列的成分是形容词。","代表":"又高又大、又红又香","例子":["苹果又红又香。"]}],"怎么认":["前后换个位置，意思基本不变？是的，多半是并列。","中间有没有顿号、“和”“又……又……”？有，多半是并列。","去掉一个成分，剩下的还能成话？能，说明地位平等。"],"辨析":"并列和偏正的区别：偏正是一个修饰一个（红旗：红修饰旗），并列是谁也不修饰谁（红花绿草：红花和绿草平等）。“又高又大”里高和大谁也不修饰谁，是并列，不是偏正。","例句解析":[{"句":"老师和同学一起去春游。","析":"“老师”和“同学”地位平等，中间用“和”连接，去掉一个，句子还通，只是人少了。"},{"句":"苹果又红又香。","析":"“红”和“香”都说苹果，地位平等，是形容词并列。"}],"练习":[{"q":"下面哪个是并列式短语？","options":["红旗","老师和同学","认真学习","跑得快"],"answer":1,"解析":"老师和同学地位平等，是并列；红旗是偏正，认真学习是偏正，跑得快是补充。","类":"名词并列"},{"q":"“又高又大”中，“高”和“大”的关系是？","options":["修饰关系","并列关系","支配关系","补充关系"],"answer":1,"解析":"高和大都说同一个人或物，地位平等。","类":"形容词并列"},{"q":"“调查研究”属于？","options":["并列式","偏正式","动宾式","主谓式"],"answer":0,"解析":"调查和研究都是动词，地位平等。","类":"动词并列"}],"类比":"并列式像<b>双胞胎肩并肩</b>：花草树木、又唱又跳。谁也不管谁，地位平等。","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" id=\"fullChar\">花草<animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.4s\" begin=\"0.5s\" fill=\"freeze\"/></text><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">花<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-140,0\" dur=\"0.8s\" begin=\"1s\" fill=\"freeze\"/></text><text x=\"180\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">并列</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.4s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">草<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;140,0\" dur=\"0.8s\" begin=\"1.4s\" fill=\"freeze\"/></text><text x=\"460\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">并列</text></g><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" opacity=\"0\">花草<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"两个以上成分并列，同等重要，可互换位置而不改变基本意思","可变":{"成分词性":["名词+名词（老师和学生）","动词+动词（唱歌跳舞）","形容词+形容词（又高又大）"],"连接":["用连词（和/跟）","不用连词（风雨雷电）","用顿号"]},"边界":"互换后意思不变才是并列（'调查研究'✓）；'牛奶面包'是并列，'面包牛奶'意思变了就不是典型并列","覆盖已确认":["成分词性","连接"],"覆盖缺失":[]},"前置知识":["名词","动词","形容词"]},{"name":"偏正式","例子":["红旗（定中）","认真学习（状中）","伟大的祖国","漂亮的新书包","红苹果","三本书","认真学习","飞快地跑","美丽的校园","轻轻地放","新衣服","大声朗读","美丽的花开了。（'美丽'是定语，用'的'）","他高兴地说着。（'高兴'是状语，用'地'）","漂亮的女孩儿","辣的菜","可爱的小宝宝","我喜欢新鲜的果汁。","他常常买便宜的东西。","妈妈做的菜","去北京的火车","你教的学生","老板请的朋友","我画的画","他写的书","妈妈给我买的衣服","客户问的问题"],"口诀":"前偏后正，修饰中心","易错":"是短语中数量最多的一种","讲解":"前偏后正，修饰限制关系","深讲":"偏正式是前偏后正、一个修饰一个的短语：前面的词说明后面的词怎么样、什么样的；后面的词是中心，前面的词去掉，中心还在，只是说得不具体了。双音节形容词的“的”一般不能省：“漂亮的书”“高兴的人”（不能说“漂亮书”）；只有单音节形容词才可省（新书）。（来源：AllSet Grammar Wiki）“形容词＋的”可以独立使用，代替“什么样的（人/东西）”：你喜欢哪种女孩？——漂亮的。（来源：AllSet Grammar Wiki）；\"短语＋的＋名词\"：的还能连整个短语，短语多是\"名词＋动词\"，如\"妈妈做的菜\"\"去北京的火车\"\"你教的学生\"；整个短语在\"的\"前面，时态不讲究（过去/现在/将来都行）（来源：AllSet Grammar Wiki）；\"短语＋的\"还能独立用，代替\"……的东西/人\"：妈妈做的（妈妈做的东西）、我画的、他写的（来源：AllSet Grammar Wiki）\"短语＋的\"独立用时指代可指\"东西\"也可指\"人\"（\"你教的\"=你教的学生/你教的东西），听话人按语境判断。（来源：AllSet Grammar Wiki）","分类":[{"类":"定中式","说明":"前面定语修饰后面的中心语，中心语是名词。","代表":"红旗、伟大的祖国","例子":["伟大的祖国真美丽。"]},{"类":"状中式","说明":"前面状语修饰后面的中心语，中心语是动词或形容词。","代表":"认真学习、快快跑","例子":["小明认真学习。"]}],"怎么认":["后面的词是不是中心？是的，前面在修饰它。","前后能不能加“的”（名词中心）或“地”（动词、形容词中心）？能，多半是偏正。","去掉前面的词，句子还通吗？通，只是变笼统了。"],"辨析":"偏正和并列的区别：偏正前偏后正，有主次；并列地位平等，无主次。“红旗”红修饰旗，是偏正；“红花绿草”红花和绿草平等，是并列。","例句解析":[{"句":"伟大的祖国真美丽。","析":"“伟大”修饰“祖国”，祖国是中心，是定中式。"},{"句":"小明认真学习。","析":"“认真”修饰“学习”，学习是中心，是状中式。"}],"练习":[{"q":"下面哪个是偏正式短语？","options":["老师和同学","红旗","祖国繁荣","学习语文"],"answer":1,"解析":"红修饰旗，前偏后正；其他分别是并列、主谓、动宾。","类":"定中式"},{"q":"“认真学习”中，“认真”和“学习”的关系是？","options":["并列","修饰（状中）","支配","补充"],"answer":1,"解析":"认真修饰学习，学习是中心。","类":"状中式"},{"q":"“漂亮的新书包”中，中心语是？","options":["漂亮","新","书包","的"],"answer":2,"解析":"漂亮、新都修饰书包，书包是中心。","类":"定中式"}],"类比":"偏正式像<b>月亮围着地球转</b>：红的花、飞快地跑。前面的修饰后面的，偏+正，中心在后。","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" id=\"fullChar\">红花<animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.4s\" begin=\"0.5s\" fill=\"freeze\"/></text><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">红<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-140,0\" dur=\"0.8s\" begin=\"1s\" fill=\"freeze\"/></text><text x=\"180\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">修饰（偏）</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.4s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">花<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;140,0\" dur=\"0.8s\" begin=\"1.4s\" fill=\"freeze\"/></text><text x=\"460\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">中心（正）</text></g><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" opacity=\"0\">红花<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"前偏后正，修饰+中心，中心是后一部分","可变":{"偏的类型":["定语+名词（红花）","状语+动词（快跑）","定语用'的'（美丽的花）","状语用'地'（高兴地说）"],"中心词性":["名词（新书）","动词（小跑）","形容词（很好）"]},"边界":"中心在后：'红花'中心是花；与'的/地'配合：定语的、状语地；单音节形容词作定语可不加'的'（新书）","覆盖已确认":["中心词性"],"覆盖缺失":["偏的类型"]},"前置知识":["形容词","名词"]},{"name":"主谓式","例子":["祖国繁荣","他来了","天气晴朗","小鸟唱歌","花开了","天黑了","他笑了","心情好","成绩提高","春天来了","太阳升起来了","我们胜利了","学习语文很有意思。（主语是短语'学习语文'）","我们班获得了冠军。（主语是短语'我们班'）","今天星期一。（谓语是名词'星期一'）","他身体很好。（谓语是主谓短语'身体很好'）"],"口诀":"谁怎么样，主谓来讲","易错":"主谓短语可作主语、宾语、定语","讲解":"陈述关系，前后可加“是”","深讲":"主谓式是陈述关系的短语：前面说谁、什么，后面说他怎么样、是什么；前后中间常常能加“是”来检查，意思不变。","分类":[{"类":"动词谓语","说明":"谓语是动词，说明主语做什么。","代表":"小鸟唱歌、他来了","例子":["小鸟在枝头唱歌。"]},{"类":"形容词谓语","说明":"谓语是形容词，说明主语怎么样。","代表":"天气晴朗、祖国繁荣","例子":["今天天气晴朗。"]}],"怎么认":["能不能分成“谁”+“怎么样”两部分？能，多半是主谓。","中间加“是”意思变不变？不变，多半是主谓。","前面是不是在说后面那个动作、状态是谁做的？是的。"],"辨析":"主谓和动宾的区别：主谓是“谁怎么样”（小鸟唱歌：小鸟是主语），动宾是“动词+受动者”（唱歌：唱是动词，歌是宾语）。一个短语里“小鸟唱歌”是主谓，单看“唱歌”是动宾。","例句解析":[{"句":"小鸟在枝头唱歌。","析":"“小鸟”是主语，“唱歌”是谓语，说小鸟怎么样。"},{"句":"今天天气晴朗。","析":"“天气”是主语，“晴朗”是形容词谓语，说天气怎么样。"}],"练习":[{"q":"下面哪个是主谓式短语？","options":["学习语文","祖国繁荣","红旗","跑得快"],"answer":1,"解析":"祖国是主语，繁荣是谓语；其他是动宾、偏正、补充。","类":"形容词谓语"},{"q":"“他来了”中，“他”是？","options":["宾语","主语","定语","状语"],"answer":1,"解析":"他是陈述对象，是主语。","类":"动词谓语"},{"q":"“小鸟唱歌”中，“唱歌”是？","options":["主语","谓语","宾语","定语"],"answer":1,"解析":"唱歌说明小鸟怎么样，是谓语。","类":"动词谓语"}],"类比":"主谓式像<b>小句子的雏形</b>：太阳升起、我喜欢。陈述+被陈述，天生一对。","图示":"<svg viewBox=\"0 0 640 300\" id=\"svg\">  <!-- 句子 -->  <g font-size=\"26\" text-anchor=\"middle\">    <text x=\"140\" y=\"90\" fill=\"#2c3328\" id=\"s1\">小猫</text>    <text x=\"320\" y=\"90\" fill=\"#2c3328\" id=\"s2\">抓</text>    <text x=\"500\" y=\"90\" fill=\"#2c3328\" id=\"s3\">毛线球</text>  </g>  <!-- 第一步：找谓语（动词是骨架） -->  <text x=\"320\" y=\"40\" text-anchor=\"middle\" font-size=\"14\" fill=\"#6b7566\" opacity=\"0\">第1步：找动词（骨架）    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/>  </text>  <rect x=\"285\" y=\"60\" width=\"70\" height=\"45\" rx=\"8\" fill=\"none\" stroke=\"#b85a52\" stroke-width=\"3\" opacity=\"0\" id=\"boxV\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.8s\" fill=\"freeze\"/>  </rect>  <animate xlink:href=\"#s2\" attributeName=\"fill\" values=\"#2c3328;#b85a52\" dur=\"0.3s\" begin=\"0.8s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <!-- 第二步：问\"谁\"找主语 -->  <text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"14\" fill=\"#6b7566\" opacity=\"0\">第2步：问\"谁抓？\"→ 小猫    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.6s\" fill=\"freeze\"/>  </text>  <path d=\"M175,100 Q240,130 285,100\" fill=\"none\" stroke=\"#4a7a59\" stroke-width=\"3\"    stroke-dasharray=\"150\" stroke-dashoffset=\"150\">    <animate attributeName=\"stroke-dashoffset\" values=\"150;0\" dur=\"0.6s\" begin=\"1.8s\" fill=\"freeze\"/>  </path>  <animate xlink:href=\"#s1\" attributeName=\"fill\" values=\"#2c3328;#4a7a59\" dur=\"0.3s\" begin=\"1.8s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <!-- 第三步：问\"什么\"找宾语 -->  <text x=\"320\" y=\"170\" text-anchor=\"middle\" font-size=\"14\" fill=\"#6b7566\" opacity=\"0\">第3步：问\"抓什么？\"→ 毛线球    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.6s\" fill=\"freeze\"/>  </text>  <path d=\"M355,100 Q420,130 465,100\" fill=\"none\" stroke=\"#4a7a8c\" stroke-width=\"3\"    stroke-dasharray=\"150\" stroke-dashoffset=\"150\">    <animate attributeName=\"stroke-dashoffset\" values=\"150;0\" dur=\"0.6s\" begin=\"2.8s\" fill=\"freeze\"/>  </path>  <animate xlink:href=\"#s3\" attributeName=\"fill\" values=\"#2c3328;#4a7a8c\" dur=\"0.3s\" begin=\"2.8s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <!-- 骨架图 -->  <g opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3.6s\" fill=\"freeze\"/>    <line x1=\"140\" y1=\"220\" x2=\"500\" y2=\"220\" stroke=\"#d5dfd0\" stroke-width=\"4\" stroke-linecap=\"round\"/>    <circle cx=\"140\" cy=\"220\" r=\"10\" fill=\"#4a7a59\"/>    <circle cx=\"320\" cy=\"220\" r=\"10\" fill=\"#b85a52\"/>    <circle cx=\"500\" cy=\"220\" r=\"10\" fill=\"#4a7a8c\"/>    <text x=\"140\" y=\"250\" text-anchor=\"middle\" font-size=\"13\" fill=\"#4a7a59\">主语（谁）</text>    <text x=\"320\" y=\"250\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">谓语（干什么）</text>    <text x=\"500\" y=\"250\" text-anchor=\"middle\" font-size=\"13\" fill=\"#4a7a8c\">宾语（什么）</text>  </g>  <text x=\"320\" y=\"280\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">记住：动词是骨架，先找它，再问\"谁\"和\"什么\"    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"4.2s\" fill=\"freeze\"/>  </text></svg>","变式表":{"不变":"陈述+被陈述，主语+谓语，讲'谁怎么样'","可变":{"主语类型":["名词（他跑）","代词（我来）","短语（学习语文有意思）"],"谓语类型":["动词（吃饭）","形容词（花红）","名词（今天星期一）","主谓短语（他身体好）"]},"边界":"主谓短语作谓语是'大主谓'（他身体好）；'是'字句（他是老师）谓语是名词性，要认出","覆盖已确认":[],"覆盖缺失":["主语类型","谓语类型"]},"前置知识":["名词","动词"]},{"name":"动宾式","例子":["学习语文","打扫教室","热爱祖国","踢足球","读书","写字","吃饭","唱歌","画画","洗衣服","开门"],"口诀":"动词在前，宾语在后","易错":"不及物动词不能带宾语（如“出发”不能直接带宾语）","讲解":"支配关系，动词+受动者","深讲":"动宾式是支配关系的短语：前面是动词，后面是动词管着的人或事物；动词和宾语中间常常能加“什么”来提问，问的就是宾语。","分类":[{"类":"名词宾语","说明":"宾语是名词。","代表":"学习语文、踢足球","例子":["他打扫教室。"]},{"类":"代词宾语","说明":"宾语是代词。","代表":"帮助他、爱护它","例子":["老师帮助他。"]},{"类":"动词宾语","说明":"宾语是动词或动词短语。","代表":"喜欢游泳、开始跑步","例子":["我喜欢游泳。"]}],"怎么认":["前面是不是动词？后面是不是它管着的人或物？是的。","在动词后问“什么”，能问出后面的词吗？能，它就是宾语。","把动词和后面的词换个位置，意思变不变？变了，说明有支配关系，不是并列。"],"辨析":"动宾和主谓的区别：动宾是动词在前、宾语在后（打扫教室）；主谓是主语在前、谓语在后（教室干净）。“学习语文”学习是动词，语文是宾语；“语文难学”语文是主语，难学是谓语。","例句解析":[{"句":"他打扫教室。","析":"“打扫”是动词，“教室”是它管着的对象，是宾语。"},{"句":"我喜欢游泳。","析":"“喜欢”是动词，“游泳”是动词宾语，说明喜欢什么。"}],"练习":[{"q":"下面哪个是动宾式短语？","options":["祖国繁荣","学习语文","红旗","又高又大"],"answer":1,"解析":"学习是动词，语文是宾语；其他是主谓、偏正、并列。","类":"名词宾语"},{"q":"“帮助他”中，“他”是？","options":["主语","宾语","定语","谓语"],"answer":1,"解析":"他是帮助的对象，是代词宾语。","类":"代词宾语"},{"q":"“喜欢游泳”中，“游泳”是？","options":["名词宾语","动词宾语","主语","状语"],"answer":1,"解析":"游泳是动词，作喜欢的宾语。","类":"动词宾语"}],"类比":"动宾式像\"<b>动作+靶子</b>\"：吃饭、看书。动词发出动作，宾语承接动作。","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" id=\"fullChar\">吃饭<animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.4s\" begin=\"0.5s\" fill=\"freeze\"/></text><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">吃<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-140,0\" dur=\"0.8s\" begin=\"1s\" fill=\"freeze\"/></text><text x=\"180\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">动作（动）</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.4s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">饭<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;140,0\" dur=\"0.8s\" begin=\"1.4s\" fill=\"freeze\"/></text><text x=\"460\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">对象（宾）</text></g><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" opacity=\"0\">吃饭<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"动词+宾语，动作+对象，讲'做什么'","可变":{"宾语类型":["名词（吃饭）","代词（找他）","短语（学习语文）","双宾语（给我一本书）"],"动词类型":["及物动词（吃/看）"]},"边界":"不及物动词不能带宾语（✗睡觉床）；双宾语：间接（给谁）+直接（给什么），顺序不能反","覆盖已确认":["宾语类型","动词类型"],"覆盖缺失":[]},"前置知识":["动词","名词"]},{"name":"补充式","例子":["写得好","跑得快","热极了","笑得很开心","说清楚","洗干净","长高了","热得满头大汗","写完了","打破了","坐下"],"口诀":"补充说明在后头","易错":"常由“得”字连接","讲解":"后补前，补充说明动作结果/程度","深讲":"补充式是后补前、补充说明的短语：后面的词补充前面的动词或形容词，说明结果怎么样、程度怎么样、方向往哪去；补充部分常常由“得”连接，去掉它，动作还在，只是不具体了。","分类":[{"类":"结果补语","说明":"补充动作的结果。","代表":"写完了、洗干净","例子":["衣服洗干净了。"]},{"类":"程度补语","说明":"补充动作、状态的程度，常由“得”连接。","代表":"跑得快、笑得很开心","例子":["他跑得很快。"]},{"类":"趋向补语","说明":"补充动作的方向。","代表":"走进来、飞上去","例子":["小鸟飞上去了。"]}],"怎么认":["后面的词是不是在补充前面的动词、形容词？是的。","中间有没有“得”“极了”？有，多半是补充。","去掉后面的词，动作还成立吗？成立，只是结果、程度不清楚了。"],"辨析":"补充和偏正的区别：偏正是前面修饰后面（认真学习：认真在前），补充是后面补充前面（跑得快：快在后，补充跑）。看修饰在前还是补充在后。","例句解析":[{"句":"衣服洗干净了。","析":"“干净”补充“洗”的结果，说明洗成什么样。"},{"句":"他跑得很快。","析":"“快”由“得”连接，补充“跑”的程度。"}],"练习":[{"q":"下面哪个是补充式短语？","options":["红旗","学习语文","跑得快","老师和同学"],"answer":2,"解析":"快补充跑的程度；其他是偏正、动宾、并列。","类":"程度补语"},{"q":"“洗干净”中，“干净”是什么补语？","options":["结果补语","程度补语","趋向补语","定语"],"answer":0,"解析":"干净说明洗的结果。","类":"结果补语"},{"q":"“走进来”中，“进来”是什么补语？","options":["结果补语","程度补语","趋向补语","状语"],"answer":2,"解析":"进来说明走的方向。","类":"趋向补语"}],"类比":"补充式像给动作加<b>备注</b>：跑得快、写完了。动词在前，补充说明在后。","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" id=\"fullChar\">跑得快<animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.4s\" begin=\"0.5s\" fill=\"freeze\"/></text><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">跑<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-140,0\" dur=\"0.8s\" begin=\"1s\" fill=\"freeze\"/></text><text x=\"180\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">动作在前</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.4s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">得快<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;140,0\" dur=\"0.8s\" begin=\"1.4s\" fill=\"freeze\"/></text><text x=\"460\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">补充在后</text></g><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" opacity=\"0\">跑得快<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"动词/形容词+补语，补充说明结果、程度、趋向","可变":{"补语类型":["结果补语（写完）","程度补语（好得很）","趋向补语（走上来）","可能补语（看得见）","数量补语（说三遍）"],"连接":["直接（写完）","用'得'（跑得快）"]},"边界":"补语在后：'写完'补语是完；'得'字补语表程度（跑得快）vs'的'定语（跑的快✗）；可能补语用'得/不'（看得见/看不见）","覆盖已确认":["补语类型","连接"],"覆盖缺失":[]},"前置知识":["动词","形容词"]}],"name":"短语的结构（5种）"},{"id":"juzichengfen","items":[{"name":"主语","例子":["〔他〕来了","〔祖国的明天〕会更好","〔小明〕在踢球","我们班得了第一名。（我们班是主语）","小鸟在天上飞。（小鸟是主语）","春天来了。（春天是主语）","他认真地写作业。（他是主语）","鲜艳的红旗迎风飘扬。（红旗是主语）","勤劳的蜜蜂在花丛中飞舞。（蜜蜂是主语）","这本书很有趣。（书是主语）","外面下起了大雨。（雨是主语）","老师表扬了他。（老师是主语）","学习语文很有意思。（'学习语文'是短语，充当主语）","他身体好。（'他'是代词，充当主语）","我吃饭。（主语'我'在句首）","昨天他没来。（主语'他'在状语'昨天'后面、谓语前面）"],"口诀":"主语回答谁什么","易错":"主语多余或残缺是常见病句","讲解":"谓语陈述的对象，回答“谁/什么”","深讲":"主语是谓语陈述的对象，回答“谁”或“什么”；找主语先找谓语，再问“谁怎么样、什么怎么样”，答的就是主语；主语常常在句首。","分类":[{"类":"名词主语","说明":"主语是名词或名词短语。","代表":"小明、祖国","例子":["小明在踢球。"]},{"类":"代词主语","说明":"主语是代词。","代表":"他、我们","例子":["他来了。"]},{"类":"短语主语","说明":"主语是短语。","代表":"祖国的明天、读书","例子":["祖国的明天会更好。"]}],"怎么认":["先找谓语（说明怎么样的词），再问谁、什么。","主语多在句首。","去掉主语，句子就不知道说谁了。"],"辨析":"主语和宾语都回答谁、什么，区别在位置和关系：主语在谓语前，是陈述对象；宾语在动词后，是动作对象。“我爱妈妈”我主语，妈妈宾语。","例句解析":[{"句":"他来了。","析":"“他”是主语，“来了”是谓语，说他怎么样。"},{"句":"祖国的明天会更好。","析":"“祖国的明天”是主语，“会更好”是谓语，说它怎么样。"}],"练习":[{"q":"“小明在踢球”中，主语是？","options":["小明","在","踢球","球"],"answer":0,"解析":"小明是陈述对象，是名词主语。","类":"名词主语"},{"q":"“他来了”中，主语是？","options":["他","来了","了","来"],"answer":0,"解析":"他是陈述对象，是代词主语。","类":"代词主语"},{"q":"“祖国的明天会更好”中，主语是？","options":["祖国","明天","祖国的明天","更好"],"answer":2,"解析":"祖国的明天整体作主语，是短语主语。","类":"短语主语"}],"类比":"主语就像电影的\"主角\"：一句话讲谁，ta 就是主语。","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" id=\"fullChar\">小鸟在天上飞<animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.4s\" begin=\"0.5s\" fill=\"freeze\"/></text><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">小鸟<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-140,0\" dur=\"0.8s\" begin=\"1s\" fill=\"freeze\"/></text><text x=\"180\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">主语：讲谁</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.4s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#6b7566\">在天上飞<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;140,0\" dur=\"0.8s\" begin=\"1.4s\" fill=\"freeze\"/></text><text x=\"460\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">其余部分</text></g><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" opacity=\"0\">小鸟在天上飞<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"谓语陈述的对象，讲'谁/什么'","可变":{"充当":["名词（老师来了）","代词（他跑了）","短语（学习语文有意思）","主谓短语（他身体好）"],"位置":["句首（我吃饭）","谓语前"]},"边界":"主语不一定是施事（'饭吃完了'主语是饭）；无主句（'下雨了'）没有主语；'把'字句主语是处置者","覆盖已确认":[],"覆盖缺失":["充当","位置"]},"前置知识":["名词","代词","主谓式"]},{"name":"谓语","例子":["他〔来了〕","祖国〔是花园〕","小狗〔汪汪叫〕","我爱我的祖国。（爱是谓语）","小狗汪汪地叫。（叫是谓语）","他跑得很快。（跑是谓语）","妈妈在做饭。（做饭是谓语）","花儿开了。（开是谓语）","同学们认真听讲。（听讲是谓语）","太阳升起来了。（升是谓语）","我们胜利了。（胜利是谓语）","鸟儿在枝头唱歌。（唱歌是谓语）","花很红。（形容词'红'作谓语，不用'是'）","今天星期一。（名词'星期一'作谓语，表判断）"],"口诀":"谓语说明怎么样","易错":"谓语残缺会导致句子不完整","讲解":"陈述主语，回答“怎么样/是什么/做什么”","深讲":"谓语陈述主语，回答怎么样、是什么、做什么；谓语是句子的中心，没有谓语，句子就不完整；谓语可以是动词、形容词、名词短语。","分类":[{"类":"动词谓语","说明":"谓语是动词，说明主语做什么。","代表":"来了、踢球","例子":["他来了。"]},{"类":"形容词谓语","说明":"谓语是形容词，说明主语怎么样。","代表":"晴朗、美丽","例子":["天气晴朗。"]},{"类":"名词谓语","说明":"谓语是名词短语，说明主语是什么。","代表":"是花园、是老师","例子":["祖国是花园。"]}],"怎么认":["先找主语，再问它怎么样、是什么、做什么。","谓语多在主语后。","去掉谓语，只剩主语，句子说不完整。"],"辨析":"谓语和宾语：谓语说明主语，宾语是动词的对象。“他学习语文”学习是谓语，语文是宾语；不能把宾语当谓语。","例句解析":[{"句":"他来了。","析":"“来了”是谓语，说明他怎么样。"},{"句":"祖国是花园。","析":"“是花园”是谓语，说明祖国是什么。"}],"练习":[{"q":"“小狗汪汪叫”中，谓语是？","options":["小狗","汪汪叫","汪汪","叫"],"answer":1,"解析":"汪汪叫说明小狗怎么样，是动词谓语。","类":"动词谓语"},{"q":"“天气晴朗”中，谓语是？","options":["天气","晴朗","今天","很"],"answer":1,"解析":"晴朗说明天气怎么样，是形容词谓语。","类":"形容词谓语"},{"q":"“祖国是花园”中，谓语是？","options":["祖国","是花园","花园","是"],"answer":1,"解析":"是花园说明祖国是什么，是名词谓语。","类":"名词谓语"}],"类比":"谓语就像主角的\"动作戏\"：主角在干什么，谓语就讲什么。","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" id=\"fullChar\">小狗汪汪叫<animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.4s\" begin=\"0.5s\" fill=\"freeze\"/></text><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#6b7566\">小狗<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-140,0\" dur=\"0.8s\" begin=\"1s\" fill=\"freeze\"/></text><text x=\"180\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">主语</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.4s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#b85a52\">汪汪叫<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;140,0\" dur=\"0.8s\" begin=\"1.4s\" fill=\"freeze\"/></text><text x=\"460\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">谓语：动作戏</text></g><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" opacity=\"0\">小狗汪汪叫<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"陈述主语，讲'怎么样/是什么/做什么'","可变":{"充当":["动词（他跑）","形容词（花红）","名词（今天星期一）","主谓短语（他身体好）"],"类型":["动词谓语","形容词谓语","名词谓语"]},"边界":"形容词谓语不用'是'（✗花是红）；名词谓语表判断（今天星期一）；'是'后名词是宾语不是谓语（他是老师：谓语是'是'）","覆盖已确认":["充当"],"覆盖缺失":["类型"]},"前置知识":["动词","形容词","主谓式"]},{"name":"宾语","例子":["学习〔语文〕","热爱〔祖国〕","我爱〔妈妈〕","我喜欢读书。（书是宾语）","妈妈买了苹果。（苹果是宾语）","他踢足球。（足球是宾语）","我们参观了博物馆。（博物馆是宾语）","小明写完了作业。（作业是宾语）","老师表扬了他。（他是宾语）","我喝了一杯牛奶。（牛奶是宾语）","姐姐织毛衣。（毛衣是宾语）","他修好了自行车。（自行车是宾语）","我看书。（单宾语'书'）","老师给我一本书。（双宾语：'我'是间接宾语，'一本书'是直接宾语）"],"口诀":"动词之后找宾语","易错":"及物动词缺宾语是成分残缺","讲解":"动作的对象，回答“谁/什么”","深讲":"宾语是动作的对象，回答谁、什么；宾语在动词后面，动词问“什么”，答的就是宾语；不及物动词不能直接带宾语。","分类":[{"类":"名词宾语","说明":"宾语是名词。","代表":"语文、祖国","例子":["学习语文。"]},{"类":"代词宾语","说明":"宾语是代词。","代表":"他、它","例子":["我喜欢他。"]},{"类":"动词宾语","说明":"宾语是动词或动词短语。","代表":"游泳、跑步","例子":["我喜欢游泳。"]}],"怎么认":["先找动词，再问动词什么。","宾语多在动词后。","去掉宾语，动作就不知道对谁、做什么了。"],"辨析":"宾语和主语：都回答谁、什么，主语在前是陈述对象，宾语在后是动作对象。“妈妈爱我”妈妈主语，我宾语；换位置意思就变了。","例句解析":[{"句":"学习语文。","析":"“语文”是宾语，说明学习什么。"},{"句":"我爱妈妈。","析":"“妈妈”是宾语，说明爱谁。"}],"练习":[{"q":"“学习语文”中，宾语是？","options":["学习","语文","语","文"],"answer":1,"解析":"语文是学习的对象，是名词宾语。","类":"名词宾语"},{"q":"“我喜欢他”中，宾语是？","options":["我","喜欢","他","欢"],"answer":2,"解析":"他是喜欢的对象，是代词宾语。","类":"代词宾语"},{"q":"“我喜欢游泳”中，宾语是？","options":["我","喜欢","游泳","游"],"answer":2,"解析":"游泳是动词，作喜欢的宾语。","类":"动词宾语"}],"类比":"宾语就像动作的\"接球手\"：动词这个球扔出去，砸到谁，谁就是宾语。","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" id=\"fullChar\">我爱妈妈<animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.4s\" begin=\"0.5s\" fill=\"freeze\"/></text><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#6b7566\">我爱<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-140,0\" dur=\"0.8s\" begin=\"1s\" fill=\"freeze\"/></text><text x=\"180\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">主谓</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.4s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">妈妈<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;140,0\" dur=\"0.8s\" begin=\"1.4s\" fill=\"freeze\"/></text><text x=\"460\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">宾语：接球手</text></g><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" opacity=\"0\">我爱妈妈<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"动词支配的对象，讲'什么/谁'","可变":{"充当":["名词（吃饭）","代词（找他）","短语（学习语文）"],"类型":["单宾语（看书）","双宾语（给我书：间接+直接）"]},"边界":"宾语在动词后：'吃饭'宾语是饭；不及物动词无宾语；'把'字句宾语提前（我把饭吃了：宾语是饭）","覆盖已确认":["充当"],"覆盖缺失":["类型"]},"前置知识":["动词","名词","动宾式"]},{"name":"定语","例子":["（红色的）旗","（我）的书","（粉色的）铅笔盒","红红的苹果真好看。（红红的是定语）","勤劳的蜜蜂采蜜忙。（勤劳的是定语）","高高的山上有座庙。（高高的是定语）","聪明的孩子爱动脑。（聪明的是定语）","美丽的校园里花香扑鼻。（美丽的是定语）","洁白的雪覆盖了大地。（洁白的是定语）","勇敢的战士冲上前去。（勇敢的是定语）","新买的书包真漂亮。（新买的是定语）","慈祥的奶奶讲故事。（慈祥的是定语）","北京人爱吃烤鸭。（'北京'是名词，充当定语）","木头桌子很结实。（'木头'是名词，充当定语）","新买的书真好看。（'新买的'是短语，充当定语）","刚开的花真香。（'刚开的'是短语，充当定语）","我买了个新书包。（'新'作定语，不用'的'）","红旗飘扬。（'红'作定语，不用'的'）"],"口诀":"定语修饰名词，常带“的”字","易错":"多重定语语序：领属+数量+动词性+形容词性+名词","讲解":"修饰名词，回答“什么样的”","深讲":"定语修饰名词，回答什么样的、谁的、哪一个；定语在名词前面，常带“的”；定语去掉，名词还在，只是说得不具体。","分类":[{"类":"形容词定语","说明":"定语是形容词。","代表":"红色的、粉色的","例子":["红色的旗。"]},{"类":"名词定语","说明":"定语是名词，常表领属、材料。","代表":"我的、木头的","例子":["我的书。"]},{"类":"动词定语","说明":"定语是动词或动词短语。","代表":"刚买的、会唱歌的","例子":["刚买的书真好看。"]}],"怎么认":["看它修饰的是不是名词。","前面有没有“的”。","问“什么样的+名词”，答的就是定语。"],"辨析":"定语和状语：定语修饰名词（红色的旗），状语修饰动词、形容词（认真地学习）；看中心语是名词还是动词、形容词，再看“的”还是“地”。","例句解析":[{"句":"红色的旗。","析":"“红色的”修饰旗，是形容词定语。"},{"句":"我的书。","析":"“我的”修饰书，是名词定语。"}],"练习":[{"q":"“红色的旗”中，定语是？","options":["红色的","旗","飘扬","高"],"answer":0,"解析":"红色的修饰旗，是形容词定语。","类":"形容词定语"},{"q":"“我的书”中，定语是？","options":["我","我的","书","本"],"answer":1,"解析":"我的修饰书，是名词定语。","类":"名词定语"},{"q":"“刚买的书”中，定语是？","options":["刚","刚买的","书","买"],"answer":1,"解析":"刚买的修饰书，是动词定语。","类":"动词定语"}],"类比":"定语就像\"标签\"：贴在名词前面，告诉你这是哪一个。","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" id=\"fullChar\">红红的苹果<animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.4s\" begin=\"0.5s\" fill=\"freeze\"/></text><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#4a7a59\">红红的<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-140,0\" dur=\"0.8s\" begin=\"1s\" fill=\"freeze\"/></text><text x=\"180\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">定语：标签</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.4s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#6b7566\">苹果<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;140,0\" dur=\"0.8s\" begin=\"1.4s\" fill=\"freeze\"/></text><text x=\"460\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">中心名词</text></g><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" opacity=\"0\">红红的苹果<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"修饰名词，讲'什么样的'","可变":{"充当":["形容词（红花）","名词（北京人）","代词（我的书）","短语（新买的书）"],"标志":["用'的'（美丽的花）","不用'的'（新书）"]},"边界":"定语在名词前；'的'是定语标志（区别于'地/得'）；多定语顺序：领属+数量+动词性+形容词性+名词（我的三本新买的中文书）","覆盖已确认":["充当"],"覆盖缺失":["标志"]},"前置知识":["偏正式","形容词"]},{"name":"状语","例子":["〔认真地〕学习","〔在教室里〕读书","〔高兴地〕跳起来","他认真地听讲。（认真地是状语）","同学们在操场上跑步。（在操场上是状语）","妈妈高兴地笑了。（高兴地是状语）","我们明天去春游。（明天是状语）","小鸟快乐地唱歌。（快乐地是状语）","他飞快地跑回家。（飞快地是状语）","老师耐心地讲解。（耐心地是状语）","大家热烈地鼓掌。（热烈地是状语）","我昨天去了公园。（昨天是状语）","他高兴地说。（'高兴地'是形容词加'地'，充当状语）","他昨天来了。（'昨天'是时间名词，充当状语）","他在北京工作。（处所状语'在北京'）","他对我很好。（对象状语'对我'）"],"口诀":"状语修饰动形，常带“地”字","易错":"状语位置一般在谓语前","讲解":"修饰动词/形容词，回答“怎样/何时/何地”","深讲":"状语修饰动词、形容词，回答怎样、何时、何地；状语在谓语前面，常带“地”，也可以是时间、处所短语；去掉状语，句子主干还在，只是不具体。","分类":[{"类":"时间状语","说明":"说明动作的时间。","代表":"昨天、早上","例子":["昨天我们去春游。"]},{"类":"处所状语","说明":"说明动作的地点。","代表":"在教室里、在家里","例子":["在教室里读书。"]},{"类":"方式状语","说明":"说明动作的方式、样子，常带“地”。","代表":"认真地、高兴地","例子":["认真地学习。"]}],"怎么认":["看它修饰的是不是动词、形容词。","在谓语前，有没有“地”或时间、处所词。","问怎样、何时、何地，答的就是状语。"],"辨析":"状语和定语：状语修饰动词、形容词（认真地学习），定语修饰名词（认真的学生）；“地”前是状语，“的”前是定语。","例句解析":[{"句":"认真地学习。","析":"“认真地”修饰学习，是方式状语。"},{"句":"在教室里读书。","析":"“在教室里”修饰读书，说明地点，是处所状语。"}],"练习":[{"q":"“认真地学习”中，状语是？","options":["认真","认真地","学习","地"],"answer":1,"解析":"认真地修饰学习，是方式状语。","类":"方式状语"},{"q":"“在教室里读书”中，状语是？","options":["在","在教室里","读书","教室"],"answer":1,"解析":"在教室里修饰读书，说明地点，是处所状语。","类":"处所状语"},{"q":"“昨天我们去春游”中，状语是？","options":["昨天","我们","去","春游"],"answer":0,"解析":"昨天修饰去，说明时间，是时间状语。","类":"时间状语"}],"类比":"状语就像\"滤镜\"：加在动词/形容词前面，告诉你动作怎么发生的。","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" id=\"fullChar\">他认真地听讲<animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.4s\" begin=\"0.5s\" fill=\"freeze\"/></text><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#6b7566\">他<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-140,0\" dur=\"0.8s\" begin=\"1s\" fill=\"freeze\"/></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.4s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#b8892e\">认真地<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;0,0\" dur=\"0.8s\" begin=\"1.4s\" fill=\"freeze\"/></text><text x=\"320\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">状语：滤镜</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.8s\" fill=\"freeze\"/><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"36\" fill=\"#6b7566\">听讲<animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;140,0\" dur=\"0.8s\" begin=\"1.8s\" fill=\"freeze\"/></text></g><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"48\" fill=\"#2c3328\" opacity=\"0\">他认真地听讲<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3.4000000000000004s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"修饰动词、形容词，讲'怎么/何时/何地'","可变":{"充当":["副词（已经走）","形容词+地（高兴地说）","介宾短语（在北京住）","时间名词（昨天来）"],"类型":["时间/处所/方式/程度/对象"]},"边界":"状语在动词/形容词前；'地'是状语标志；'很'是状语不是补语（'很好'：很是状语）；多状语顺序：时间+处所+语气+范围+否定+程度+对象","覆盖已确认":[],"覆盖缺失":["充当","类型"]},"前置知识":["副词","介词"]},{"name":"补语","例子":["写得〔好〕","跑得〔快〕","写得〔很工整〕","他跑得很快。（很快是补语）","作业写完了。（完了是补语）","衣服洗干净了。（干净是补语）","她长高了许多。（许多是补语）","热得满头大汗。（满头大汗是补语）","说得清清楚楚。（清清楚楚是补语）","天黑下来了。（下来是补语）","花开得很美。（很美是补语）","他气得说不出话。（说不出话是补语）","他写完了作业。（结果补语'完'，在动词后面）","他走上来了。（趋向补语'上来'，在动词后面）"],"口诀":"补语补充在后头，常带“得”字","易错":"“得”后补语与“地”前状语不要混","讲解":"补充说明谓语，回答“到什么程度/结果”","深讲":"补语补充说明谓语，回答到什么程度、什么结果、往哪去；补语在谓语后面。“得”的存缺要看补语类型：程度补语和可能补语用“得”连接（他跑得很快、我听得懂），结果补语、趋向补语、数量补语前面不用“得”（衣服洗干净了、小鸟飞上去了、看了三遍）；一旦在结果/趋向补语前加了“得”，就变成可能补语（写得完、走得上去）。（来源：维基百科·述补短语）结果补语还分两种：自然结果（吃饱了、买累了：动作发生后自然出现的结果）和说话人的评价（买贵了、吃早了：说话人对结果的看法）。（来源：北大CCL）常用结果补语词汇表：晚（来晚了）、饱（吃饱了）、坏（玩坏了）、清楚（听清楚了）、干净（洗干净了）、破（撕破了）。（来源：AllSet Grammar Wiki）“好”表示动作做完、做好（写好了），“错”表示动作做错了（记错了）。（来源：AllSet Grammar Wiki）否定结果补语用“没”不用“不”：我没吃饱（不能说“我不吃饱”）。（来源：AllSet Grammar Wiki）少数单音节动词也能做结果补语：到（看到）、见（听见）、懂（看懂）、会（学会）、走（拿走）、掉（忘掉）。（来源：AllSet Grammar Wiki）结果/可能对照表：做完｜做得完｜做不完；听懂｜听得懂｜听不懂；看清楚｜看得清楚｜看不清楚。（来源：AllSet Grammar Wiki）去掉补语，动作还在，只是不具体。；结果补语爱把宾语提前当话题：这个字写错了（主语常省略，不说\"我把这个字写错了\"）（来源：AllSet Grammar Wiki）；趋向补语加\"得\"/\"不\"就变成可能补语：回去→回得去/回不去；过来→过得来/过不来；站起来→站得起来/站不起来（来源：AllSet Grammar Wiki）学术小注：程度补语、描写补语、状态补语三者的划分学界有争议（有的认为都是一类），不影响使用，关键是会用。（来源：AllSet Grammar Wiki）","分类":[{"类":"结果补语","说明":"补充动作的结果。结果补语后常跟\"了\"；\"好\"≈\"完\"，都表示\"做完、做好\"；单音节动词补语没几个（到/见/懂/会/走/掉），常被看成一个词。（来源：AllSet Grammar Wiki）","代表":"完、干净、好","例子":["衣服洗干净了。","我吃饱了。","他买错了东西。","你吃好了吗？","对不起，我记错了时间。","你来晚了，我们已经关门了。","他玩坏了哥哥的玩具。","他还没想好。","我们没听清楚，请再说一遍。","你们都听懂了吗？","你踩到我的脚了。","我不小心撞到墙了。","我女儿学会了数数。","我爸爸还没学会用智能手机。","老师拿走了我的iPad。","小偷偷走了我的钱包。","他不小心推倒了一个老人。","你撞倒了我的自行车。","谁扔掉了我的袜子？","我卖掉了我的旧手机。","这个字写错了。","杯子摔坏了。","房间打扫干净了吗？","我把杯子摔坏了。","他把我的电脑修好了。","小偷把我的钱包偷走了。","我们把房间打扫干净了。"]},{"类":"程度补语","说明":"补充动作、状态的程度，常由“得”连接。程度补语还能跟在形容词后面，不用\"得\"：极了（味道好极了）、死了（臭死了/可爱死了）、坏了（高兴坏了）；动词后不能又跟宾语又跟补语：要么重说动词（你说中文说得很好），要么宾语提前（你的中文说得很好）；\"很\"直接跟在\"得\"后的是程度补语（她说得很清楚），可能补语不能这样。（来源：AllSet Grammar Wiki）","代表":"快、很工整","例子":["他跑得很快。","累得很。","他高兴得跳了起来。","你做得不错。","孩子们学得挺快的。","我吃得太饱了。","你们谈得顺利吗？","她长得还可以。","你做菜做得很好。","你的菜做得很好。","你写字写得很漂亮。","你的字写得很漂亮。","味道好极了。","这里的天气舒服极了。","他的袜子臭死了。","小狗可爱死了。","我们都高兴坏了。","妈妈急坏了。"]},{"类":"趋向补语","说明":"补充动作的方向。关键看说话人在哪：动作朝说话人来用\"来\"，离说话人去用\"去\"；复合趋向补语：\"来\"字组（上来/下来/进来/出来/回来/过来/起来）、\"去\"字组（上去/下去/进去/出去/回去/过去）；一个动词后不能又跟补语又跟宾语：✗回来中国→✓回中国来。（来源：AllSet Grammar Wiki）自己移动时看语境：跟人约明天见，说\"我来找你\"（朝对方去也用\"来\"，跟英语\"I'll come see you\"一样）。（来源：AllSet Grammar Wiki）","代表":"进来、上去","例子":["小鸟飞上去了。","他走进来了。","请把书拿上来。","我在楼上，你上来。","出来玩吧，我们在酒吧等你。","我妈不让我出去。","这是我家，进来吧。","你下班了吗？几点回来吃饭？","请站起来。","不要让它跑出去。","从我家走过来要半个小时。","你包里的东西都拿出来了吗？","服务员，请再拿几个碗来。","快点送孩子去吧。","师傅，送两桶水来。","可以带朋友过来吗？","他们带了一些礼物回去。","把书拿出来。","把手举起来。","帮我把这个箱子搬过去。"]},{"类":"可能补语","说明":"表示动作能不能做到、做不做得到，用“得/不”连接。（来源：AllSet Grammar Wiki）可能补语从别的补语变来：动词＋见/懂/完/形容词/到/趋向，中间插\"得\"（肯定）或\"不\"（否定）；宾语可放补语后，也可提前到句首。（来源：AllSet Grammar Wiki）","代表":"听得懂、写得完","例子":["我听得懂。","这个字我写不出来。","你没戴眼镜，看得清楚吗？","他这么粗心，做得好吗？","你这么聪明，肯定学得会。","早上五点出发，孩子们起得来吗？","这么高的山，你爬得上去吗？","你的声音太小了，我们听不见。","这里太暗了，我看不清楚。","这个自行车太破了，谁都修不好。","她的腿受伤了，站不起来了。","包太小了，手机放不进去。","你听得懂上海话吗？","她这么小，看得懂这本书吗？","我怕我做不好这份工作。","这种手机现在买不到了。","这本书我一个星期肯定看得完。"]},{"类":"数量补语","说明":"补充动作的次数、持续的时间。（来源：维基百科·述补短语）动量词三兄弟：次（最常用）、遍、下；动词＋数＋量：看三次、读两遍、拍两下。（来源：AllSet Grammar Wiki）","代表":"三遍、一会儿","例子":["这本书我看了三遍。","他睡了一会儿。","再说一遍。","你能再读一遍吗？","这个电影我看过两遍。","这个故事我听她说过一百多遍了。","我们去过两次。","我问了他很多次。","这个问题我们讨论过几次。","那个红头发的男孩打了我三下。","他轻轻地拍了我两下。","你没听见吗？我敲了好几下。"]}],"怎么认":["看它是不是在谓语后面补充说明。","中间有没有“得”。","问程度、结果、方向，答的就是补语。"],"辨析":"补语和状语：补语在谓语后补充（跑得快：快在后），状语在谓语前修饰（快快跑：快快在前）；“得”后是补语，“地”前是状语。；补语和宾语：宾语是动作涉及的对象（吃什么→饭），补语回答动作“怎么样、到什么程度”（吃得怎么样→饱）。测试法：动词后面问“什么”，得到的是宾语；问“怎么样”，得到的是补语。（来源：视频讲课·沙叶《补语的难点讲解》）","例句解析":[{"句":"写得好。","析":"“好”补充写的程度，是程度补语。"},{"句":"衣服洗干净了。","析":"“干净”补充洗的结果，是结果补语。"}],"练习":[{"q":"“跑得快”中，补语是？","options":["跑","得","快","跑得"],"answer":2,"解析":"快补充跑的程度，是程度补语。","类":"程度补语"},{"q":"“衣服洗干净了”中，补语是？","options":["衣服","洗","干净","了"],"answer":2,"解析":"干净补充洗的结果，是结果补语。","类":"结果补语"},{"q":"“小鸟飞上去了”中，补语是？","options":["小鸟","飞","上去","了"],"answer":2,"解析":"上去补充飞的方向，是趋向补语。","类":"趋向补语"}],"类比":"补语就像\"赛后采访\"：动作结束了，补一句\"结果如何\"。","图示":"<svg viewBox=\"0 0 640 340\" id=\"svg\">  <!-- 动词：吃 -->  <text x=\"120\" y=\"80\" text-anchor=\"middle\" font-size=\"28\" fill=\"#2c3328\" id=\"verb\">吃</text>  <text x=\"120\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6b7566\">动词（没吃饱）</text>  <!-- 肚子空 -->  <ellipse cx=\"120\" cy=\"140\" rx=\"30\" ry=\"20\" fill=\"none\" stroke=\"#d5dfd0\" stroke-width=\"2\" id=\"belly\"/>    <!-- 5种补语依次喂 -->  <g font-size=\"18\" text-anchor=\"middle\" opacity=\"0\" id=\"b1\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.0s\" fill=\"freeze\"/>    <text x=\"320\" y=\"80\" fill=\"#4a7a59\" font-weight=\"bold\">完了</text>    <text x=\"320\" y=\"105\" font-size=\"12\" fill=\"#4a7a59\">结果补语：吃到什么程度</text>    <animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-120,40\" dur=\"0.8s\" begin=\"1.3s\" fill=\"freeze\"/>  </g>  <g font-size=\"18\" text-anchor=\"middle\" opacity=\"0\" id=\"b2\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5s\" fill=\"freeze\"/>    <text x=\"320\" y=\"150\" fill=\"#4a7a8c\" font-weight=\"bold\">得很快</text>    <text x=\"320\" y=\"175\" font-size=\"12\" fill=\"#4a7a8c\">状态补语：吃得怎么样</text>    <animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-120,-10\" dur=\"0.8s\" begin=\"2.8s\" fill=\"freeze\"/>  </g>  <g font-size=\"18\" text-anchor=\"middle\" opacity=\"0\" id=\"b3\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4.0s\" fill=\"freeze\"/>    <text x=\"320\" y=\"220\" fill=\"#b8892e\" font-weight=\"bold\">上去</text>    <text x=\"320\" y=\"245\" font-size=\"12\" fill=\"#b8892e\">趋向补语：吃到哪去</text>    <animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-120,-60\" dur=\"0.8s\" begin=\"4.3s\" fill=\"freeze\"/>  </g>    <!-- 肚子满 -->  <ellipse cx=\"120\" cy=\"140\" rx=\"30\" ry=\"20\" fill=\"#d3e5d6\" stroke=\"#4a7a59\" stroke-width=\"2\" opacity=\"0\" id=\"full\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"5.5s\" fill=\"freeze\"/>  </ellipse>    <!-- 总结 -->  <g opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"6.0s\" fill=\"freeze\"/>    <text x=\"320\" y=\"290\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\">补语=动词的\"饭\"：结果（完了）/ 状态（得很快）/ 趋向（上去）/ 程度（极了）/ 数量（三次）</text>    <text x=\"320\" y=\"315\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\">动词光秃秃没吃饱，加上补语才完整</text>  </g></svg>","变式表":{"不变":"补充说明动词、形容词的结果、程度、趋向等","可变":{"充当":["动词（写完）","形容词（好得很）","短语（走上来）"],"类型":["结果","程度","趋向","可能","数量"]},"边界":"补语在动词/形容词后；'得'是补语标志（跑得快）；区别于状语：状语在前（快跑），补语在后（跑得快）","覆盖已确认":["充当"],"覆盖缺失":["类型"]},"前置知识":["补充式","动词"]},{"name":"趋向补语引申义","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">天气热起来了。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“起来”不是方向，是“开始并持续”：天气开始热，而且越来越热。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">把玩具收起来。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“起来”表“完成、收拢”：把散着的玩具收好。不是往上收。</text></g></svg>","讲解":"“起来/下去/出来”不只表示方向，还引申出“开始、继续、有结果”的意思：天气热起来了（开始热），坚持下去（继续）。","深讲":"趋向补语本管方向（站起来=向上站），但常用出引申义：①起来=开始并持续（热起来了、胖起来了）；还表“完成、收拢”（收起来、藏起来）、表“估计”（看起来、听起来）；②下去=继续（说下去、坚持下去）；③出来=有了结果（想出来了、写出来了）；④下来=延续到现在或缓和（坚持下来、冷静下来）。判断方法：按方向讲不通，就是引申义（“热起来”不是往上热）。（来源：AllSet Chinese Grammar Wiki，CC BY-NC-SA 3.0）","类比":"趋向补语的引申义像方向盘打满：本来管方向（上下左右），打满了就拐出新意思（开始、继续）。","口诀":"起来是开始，下去是继续，出来见结果","例子":["天气热起来了。","说起来容易，做起来难。","把玩具收起来。","她看起来很健康。","听起来不错。","坚持下去！","这个故事太无聊，我听不下去了。","我想出来了！","他看起书来就忘了时间。"],"易错":"引申义时别再按方向理解（“热起来”不是往上热）；“下去”表继续时，主语多是人或事。","分类":[{"类":"表开始","说明":"起来：动作或状态开始并持续。","代表":"热起来、胖起来","例子":["天气热起来了。","说起来容易，做起来难。"]},{"类":"表继续","说明":"下去/下来：动作继续下去。","代表":"坚持下去","例子":["坚持下去！","这个故事太无聊，我听不下去了。"]},{"类":"表结果/估计","说明":"出来：有了结果；起来：估计推测。","代表":"想出来、看起来","例子":["我想出来了！","她看起来很健康。"]}],"怎么认":["动词后跟没跟“起来/下去/出来/下来”？跟了→可能是。","按方向讲通不通？“热起来”按方向讲不通→是引申义。","是不是表开始、继续、结果、估计？是→引申义。"],"辨析":"起来方向义 vs 引申义：看主语能不能“位移”。“站起来”（人能向上动）是方向；“热起来”（天气不能位移）是引申。能位移→方向，不能位移→引申。","例句解析":[{"句":"天气热起来了。","析":"“起来”不是方向，是“开始并持续”：天气开始热，而且越来越热。"},{"句":"把玩具收起来。","析":"“起来”表“完成、收拢”：把散着的玩具收好。不是往上收。"}],"练习":[{"q":"“天气热起来了”中“起来”表什么？","options":["方向向上","开始并持续","完成","估计"],"answer":1,"解析":"天气不能位移，“起来”是引申义：开始热并持续。","类":"辨析"},{"q":"哪句的“下去”表“继续”？","options":["走下去","坚持下去","跳下去","滑下去"],"answer":1,"解析":"“坚持下去”是继续坚持；其余是方向（向下）。","类":"辨析"},{"q":"“她看起来很健康”中“起来”表什么？","options":["开始","继续","估计推测","方向"],"answer":2,"解析":"“看起来”是固定搭配，表估计、推测。","类":"分类"},{"q":"“我想出来了”的“出来”表什么？","options":["方向向外","有了结果","开始","继续"],"answer":1,"解析":"“想出来”=想到了办法，“出来”表结果出现。","类":"分类"}],"前置知识":["补语","动词"]}],"name":"单句的成分（7种）"},{"id":"fuju","items":[{"name":"并列复句","例子":["他来了，我也来了","我写作业，弟弟看书","花儿红，草儿绿。","他会唱歌，也会跳舞。","天晴了，风停了。","小明爱读书，小红爱画画。","春天播种，秋天收获。","妈妈做饭，爸爸洗碗。","太阳升起，公鸡打鸣。","教室里安静，操场上热闹。","他个子高，她个子矮。","白天很热，夜里很凉。","他既会唱歌，又会跳舞。（'既…又…'）","她既聪明又勤奋。（'既…又…'）","他一边走路，一边听音乐。（'一边…一边…'）","妈妈一边做饭，一边打电话。（'一边…一边…'）"],"口诀":"关联词：既……又、也、还","易错":"","讲解":"分句间平等并列","深讲":"并列复句是两个或两个以上分句地位平等、并列在一起的复句；分句间没有主次，谁也不比谁更进一层；判断并列，先看意思是不是平行的，再看有没有既……又、也、还这类关联词。","分类":[{"类":"既……又……式","说明":"用既……又连接两个平行的方面。","代表":"既……又……","例子":["他既会唱歌，又会跳舞。"]},{"类":"也、还式","说明":"后分句用也、还表示同样、并列。","代表":"也、还","例子":["他来了，我也来了。"]},{"类":"一边……一边……式","说明":"两个动作同时进行。","代表":"一边……一边……","例子":["他一边走路，一边唱歌。"]}],"怎么认":["分句间是不是平行的，谁也不比谁更进一层？是的。","有没有既……又、也、还、一边……一边？有，多半是并列。","去掉一个分句，剩下的还能成话？能，说明地位平等。"],"辨析":"并列和递进的区别：并列是平行的（既会唱歌，又会跳舞），递进是后句更进一层（不但会唱歌，而且会作曲）。把“不但……而且”换成“既……又”，意思就变了味，说明不是并列。","例句解析":[{"句":"我写作业，弟弟看书。","析":"两个分句说两件事，地位平等，没有主次，是并列复句。"},{"句":"他既会唱歌，又会跳舞。","析":"既……又连接两个平行的本领，是并列复句。"}],"练习":[{"q":"下面哪个是并列复句？","options":["他不但会唱歌，而且会跳舞","他既会唱歌，又会跳舞","因为努力，所以成功","如果下雨，就不去了"],"answer":1,"解析":"既……又表示平行，是并列；其他是递进、因果、假设。","类":"既……又……式"},{"q":"“他来了，我也来了”中，“也”表示？","options":["递进","并列","转折","因果"],"answer":1,"解析":"也表示同样、并列。","类":"也、还式"},{"q":"“他一边走路，一边唱歌”属于？","options":["并列复句","递进复句","选择复句","条件复句"],"answer":0,"解析":"两个动作同时进行，地位平等，是并列。","类":"一边……一边……式"}],"类比":"并列复句像<b>两条平行线</b>：我唱歌，他跳舞。分句地位平等，谁也不从属于谁。","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他来了</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">分句一</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">我也来了</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">分句二：地位平等，不分主次</text></g><text x=\"320\" y=\"160\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">并列复句=两条平行线：我唱歌，他跳舞<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"1.9s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"分句平等并列，无主次，讲几件事或几方面","可变":{"关联词":["用（既…又…/一边…一边…）","不用（你来，我去）"],"内容":["同向并列（又唱又跳）","对照并列（你来我去）"]},"边界":"分句可互换（'又唱又跳'='又跳又唱'）；与递进区别：递进有轻重（'不但…而且…'），并列没有","覆盖已确认":[],"覆盖缺失":["关联词","内容"]},"前置知识":["主谓式","连词","并列式"]},{"name":"递进复句","例子":["他不但会唱歌，而且会跳舞","她不但画画好，而且字也写得漂亮","这本书不仅有趣，还很有道理。","小明不但聪明，而且勤奋。","她不但跑得快，而且跳得远。","这件事不但重要，而且紧急。","他不仅是学生，还是运动员。","教室不但干净，而且整齐。","妈妈不但会做饭，还会织毛衣。","这个问题不但难，而且很关键。","他不但答对了，而且全对。"],"口诀":"关联词：不但……而且、甚至","易错":"递进顺序不能颠倒","讲解":"后分句比前分句更进一层","深讲":"前句说一层意思，后句再进一层，顺序不能颠倒；常用不但……而且、不仅……还、甚至。","分类":[{"类":"不但……而且……式","说明":"最常用的递进搭配。","代表":"不但……而且……","例子":["他不但会唱歌，而且会跳舞。"]},{"类":"不仅……还……式","说明":"不仅引出前一层，还引出更进一层。","代表":"不仅……还……","例子":["她不仅画画好，还写得一手好字。"]},{"类":"甚至式","说明":"后句用甚至，表示进到出乎意料的一层。","代表":"甚至","例子":["他不但会唱歌，甚至会作曲。"]}],"怎么认":["后句是不是比前句更进一层？是的。","有没有不但……而且、不仅……还、甚至？有，多半是递进。","前后换个位置，意思还顺吗？不顺，说明顺序不能颠倒。"],"辨析":"递进和并列的区别：并列是平行的，递进是进一层的。“不但会唱歌，而且会跳舞”后句是新本领、更进一层；“既会唱歌，又会跳舞”只是平行列举。","例句解析":[{"句":"他不但会唱歌，而且会跳舞。","析":"后句跳舞比前句唱歌更进一层，是递进复句。"},{"句":"她不但画画好，而且字也写得漂亮。","析":"后句字漂亮比前句画画好更进一层，是递进复句。"}],"练习":[{"q":"下面哪个是递进复句？","options":["他既会唱歌，又会跳舞","他不但会唱歌，而且会跳舞","他来了，我也来了","你去还是留"],"answer":1,"解析":"不但……而且表示更进一层，是递进。","类":"不但……而且……式"},{"q":"递进复句前后顺序能颠倒吗？","options":["能","不能","有时能","看情况"],"answer":1,"解析":"递进是进一层的关系，顺序不能颠倒。","类":"不但……而且……式"},{"q":"“她不仅画画好，还写得一手好字”属于？","options":["并列复句","递进复句","转折复句","因果复句"],"answer":1,"解析":"不仅……还表示更进一层，是递进。","类":"不仅……还……式"}],"类比":"递进复句像<b>上台阶</b>：不但……而且……。后一层比前一层更进一层。","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">不但会唱歌</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">第一层</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">而且会跳舞</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">更进一层</text></g><text x=\"320\" y=\"160\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">递进复句=上台阶：后句比前句更进一步<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"1.9s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"后一分句比前一分句更进一层","可变":{"关联词":["不但…而且…","不仅…还…","甚至"],"程度":["轻→重（不但会唱，而且会跳）"]},"边界":"后重前轻是关键；'而且'后不能是否定（✗不但好，而且不好）；与并列区别：递进不可互换","覆盖已确认":["关联词","程度"],"覆盖缺失":[]},"前置知识":["主谓式","连词"]},{"name":"选择复句","例子":["是去还是留，你定吧","放学后去打球还是回家，你选吧","你是喝茶，还是喝咖啡？","与其在这里等，不如先回家。","宁可站着死，不肯跪着生。","他不是去北京，就是去上海。","与其抱怨，不如行动。","要么好好学，要么别学了。","你喜欢红色，还是喜欢蓝色？","不是你去，就是我去。","与其空想，不如实干。","他宁可走路，也不坐车。","你要么去，要么不去。（'要么…要么…'）","与其坐车，不如走路去。（'与其…不如…'）","你去还是不去？（'还是'用于疑问选择，任选其一）","或者你去，或者我去。（'或者…或者…'，陈述句中任选）"],"口诀":"关联词：或者……或者、是……还是","易错":"“或者”表选择，“还是”用于问句","讲解":"列出两种情况供选择","深讲":"选择复句是列出两种或两种以上情况，供人选择的复句；分句间是选择关系，不是并列，也不是转折；常用或者……或者、是……还是、要么……要么。","分类":[{"类":"或者……或者……式","说明":"在两种情况中选一种，常用于陈述。","代表":"或者……或者……","例子":["你或者去打球，或者回家。"]},{"类":"是……还是……式","说明":"用于问句，让对方选。","代表":"是……还是……","例子":["是去还是留，你定吧。"]},{"类":"要么……要么……式","说明":"在两种情况中选一种，语气较肯定。","代表":"要么……要么……","例子":["要么去，要么留，你定吧。"]}],"怎么认":["是不是在两种情况中选一种？是的。","有没有或者、还是、要么？有，多半是选择。","是不是在问对方选哪个？是的，多半是是……还是。"],"辨析":"选择和并列的区别：并列是两件事都发生（既唱歌又跳舞），选择是二选一（或者唱歌，或者跳舞）。“或者”表选择，“还是”用于问句，不要混。","例句解析":[{"句":"是去还是留，你定吧。","析":"是……还是让对方在去和留中选，是选择复句。"},{"句":"放学后去打球还是回家，你选吧。","析":"打球和回家二选一，是选择复句。"}],"练习":[{"q":"下面哪个是选择复句？","options":["他既会唱歌，又会跳舞","是去还是留，你定吧","因为努力，所以成功","虽然累，但是坚持"],"answer":1,"解析":"是……还是让对方选，是选择。","类":"是……还是……式"},{"q":"“或者”一般表？","options":["并列","选择","转折","因果"],"answer":1,"解析":"或者列出两种情况供选择。","类":"或者……或者……式"},{"q":"“要么去，要么留”属于？","options":["选择复句","并列复句","假设复句","条件复句"],"answer":0,"解析":"要么……要么是二选一，是选择。","类":"要么……要么……式"}],"类比":"选择复句像<b>岔路口</b>：要么……要么……。非此即彼，必须选一条。","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">要么去</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">选项A</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">要么不去</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">选项B：非此即彼</text></g><text x=\"320\" y=\"160\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">选择复句=岔路口：必须选一条<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"1.9s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"列出两种以上可能，选其一","可变":{"关联词":["或者…或者…","不是…就是…","与其…不如…"],"选择":["任选（去或不去）","取舍（与其…不如…）"]},"边界":"'还是'用于疑问选择（去还是不去？），'或者'用于陈述；'与其…不如…'表取舍，有褒贬","覆盖已确认":[],"覆盖缺失":["关联词","选择"]},"前置知识":["主谓式","连词"]},{"name":"转折复句","例子":["虽然下雨，但是没耽误","虽然我很累，但是我坚持跑完了","虽然下雨，但是运动会照常举行。","他虽然累，却很开心。","尽管困难很多，我们还是完成了。","虽然他年纪小，但是懂得很多。","这件衣服虽然贵，但是质量好。","虽然天黑了，但是路灯亮了。","他虽然失败了，却没有气馁。","尽管下着大雨，农民还在抢收。","这道题虽然难，但是我做出来了。","虽然他病了，但是坚持上课。","他尽管很累，还是坚持下来了。（'尽管…还是…'）","天气很冷，他却穿得很单薄。（'却'表转折）"],"口诀":"关联词：虽然……但是、尽管……还是","易错":"转折连词不能单独省略后半","讲解":"前后意思相反或相对","深讲":"转折复句是前后意思相反或相对的复句；前句先说一层意思，后句一转，说出相反或相对的意思；常用虽然……但是、尽管……还是。","分类":[{"类":"虽然……但是……式","说明":"最常用的转折搭配。","代表":"虽然……但是……","例子":["虽然下雨，但是没耽误。"]},{"类":"尽管……还是……式","说明":"尽管让步，还是表示转折的结果。","代表":"尽管……还是……","例子":["尽管很累，他还是坚持跑完了。"]},{"类":"转折词单独式","说明":"只用可是、但是、却表示转折。","代表":"可是、但是、却","例子":["他很累，可是还坚持着。"]}],"怎么认":["前后意思是不是相反或相对？是的。","有没有虽然……但是、尽管……还是、可是？有，多半是转折。","去掉后句，前句的意思还完整吗？不完整，说明转折在后句。"],"辨析":"转折和因果的区别：转折是前后相反（虽然下雨，但是没耽误），因果是前因后果（因为下雨，所以没去）。看前后是相反还是因果，不要只看有没有但是。","例句解析":[{"句":"虽然下雨，但是没耽误。","析":"前句下雨，后句没耽误，意思一转，是转折复句。"},{"句":"虽然我很累，但是我坚持跑完了。","析":"累和坚持跑完相对，是转折复句。"}],"练习":[{"q":"下面哪个是转折复句？","options":["因为努力，所以成功","虽然下雨，但是没耽误","如果下雨，就不去了","他既会唱歌，又会跳舞"],"answer":1,"解析":"虽然……但是表示转折。","类":"虽然……但是……式"},{"q":"“尽管很累，他还是坚持跑完了”属于？","options":["转折复句","因果复句","递进复句","并列复句"],"answer":0,"解析":"尽管……还是表示转折。","类":"尽管……还是……式"},{"q":"转折复句前后意思的关系是？","options":["平行","相反或相对","因果","选择"],"answer":1,"解析":"转折是前后相反或相对。","类":"虽然……但是……式"}],"类比":"转折就像\"先扬后抑\"：前面夸一句，后面\"但是\"一转才是真心话。","图示":"<svg viewBox=\"0 0 320 160\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">转折复句：意思拐了个弯</text><text x=\"12\" y=\"44\" font-size=\"15\" class=\"svg-ink\">虽然他生病了，</text><text x=\"117\" y=\"44\" font-size=\"15\" class=\"svg-red\">但是</text><text x=\"147\" y=\"44\" font-size=\"15\" class=\"svg-ink\">还是来了。</text><path d=\"M30,80 L170,80 Q200,80 200,110 L200,132\" stroke-width=\"12\" fill=\"none\" stroke-linecap=\"round\" opacity=\"0.3\" class=\"svg-muted-s\"/><circle r=\"6\" class=\"svg-accent\"><animateMotion dur=\"6s\"  path=\"M30,80 L170,80 Q200,80 200,110 L200,132\"/></circle><text x=\"212\" y=\"100\" font-size=\"12\" class=\"svg-red\">拐弯！</text><text x=\"12\" y=\"150\" font-size=\"12\" class=\"svg-muted\">\"虽然\"先让步，\"但是\"后面才是真正想说的</text></svg>","变式表":{"不变":"前后意思相反或相对，'虽然…但是…'","可变":{"关联词":["虽然…但是…","尽管…还是…","却"],"转折":["轻转（虽然累，但是开心）","重转（虽败犹荣）"]},"边界":"'但是'前可省略'虽然'；转折连词在主语后（'他虽然累，但是…'主语一致时'虽然'在主语后）；与让步区别：让步是'即使…也…'（未然），转折是已然","覆盖已确认":["转折"],"覆盖缺失":["关联词"]},"前置知识":["主谓式","连词"]},{"name":"因果复句","例子":["因为努力，所以成功","因为我生病了，所以没去上学","因为努力，所以他成功了。","由于下雨，比赛推迟了。","他之所以迟到，是因为堵车。","因为天气冷，所以多穿了衣服。","既然你来了，就一起吃饭吧。","因为坚持，他终于学会了游泳。","由于缺水，禾苗枯黄了。","他因为生病，所以请假了。","因为准备充分，考试很顺利。","之所以成功，是因为从不放弃。","由于下雨，运动会取消了。（'由于'）","既然来了，就多住几天。（'既然…就…'，表已然原因）","因为堵车，所以他迟到了。（口语：因为…所以…）","由于天气原因，航班延误。（书面：由于…）"],"口诀":"关联词：因为……所以、由于","易错":"因果倒置会造成逻辑错误","讲解":"前因后果","深讲":"因果复句是前因后果的复句；前句说原因，后句说结果，顺序一般是先因后果，也可以先果后因；常用因为……所以、由于……因此。","分类":[{"类":"因为……所以……式","说明":"最常用的因果搭配，先因后果。","代表":"因为……所以……","例子":["因为努力，所以成功。"]},{"类":"由于……因此……式","说明":"由于引出原因，因此引出结果。","代表":"由于……因此……","例子":["由于下雨，因此我们没去公园。"]},{"类":"先果后因式","说明":"先说结果，后说原因。","代表":"……，因为……","例子":["他没去上学，因为生病了。"]}],"怎么认":["前后是不是原因和结果？是的。","有没有因为……所以、由于……因此？有，多半是因果。","问“为什么”，能问出前句吗？能，说明前句是原因。"],"辨析":"因果和条件的区别：因果是原因已经发生、结果跟着来（因为生病，所以没去）；条件是条件还没发生、结果跟着条件来（只有努力，才能成功）。看原因是不是已经发生了。","例句解析":[{"句":"因为努力，所以成功。","析":"努力是原因，成功是结果，是因果复句。"},{"句":"因为我生病了，所以没去上学。","析":"生病是原因，没去上学是结果，是因果复句。"}],"练习":[{"q":"下面哪个是因果复句？","options":["虽然累，但是坚持","因为努力，所以成功","如果下雨，就不去了","他既会唱歌，又会跳舞"],"answer":1,"解析":"因为……所以表示因果。","类":"因为……所以……式"},{"q":"“他没去上学，因为生病了”中，原因是？","options":["没去上学","生病了","上学","他"],"answer":1,"解析":"生病了是原因，没去上学是结果，先果后因。","类":"先果后因式"},{"q":"因果倒置会造成？","options":["逻辑错误","语气变化","意思不变","变成并列"],"answer":0,"解析":"原因和结果颠倒，逻辑就错了。","类":"因为……所以……式"}],"类比":"因果就像\"多米诺\"：前一张牌倒了（因），后一张跟着倒（果）。","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">因果复句：原因 → 结果</text><rect x=\"12\" y=\"36\" width=\"120\" height=\"44\" rx=\"10\" fill=\"none\" stroke-width=\"2\" class=\"svg-accent-s\"><animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.45;0.5;0.95;1\" dur=\"8s\" /></rect><text x=\"72\" y=\"63\" font-size=\"15\" text-anchor=\"middle\" class=\"svg-ink\">因为下雨了</text><line x1=\"136\" y1=\"58\" x2=\"184\" y2=\"58\" stroke-width=\"2\" class=\"svg-muted-s\"/><circle r=\"5\" class=\"svg-accent\"><animateMotion dur=\"2s\"  path=\"M136,58 L184,58\"/></circle><polygon points=\"184,58 176,53 176,63\" class=\"svg-accent\"/><rect x=\"188\" y=\"36\" width=\"120\" height=\"44\" rx=\"10\" fill=\"none\" stroke-width=\"2\" class=\"svg-red-s\"><animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35\" keyTimes=\"0;0.45;0.5;0.95;1\" dur=\"8s\" /></rect><text x=\"248\" y=\"63\" font-size=\"15\" text-anchor=\"middle\" class=\"svg-ink\">所以没去踢球</text><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">金点从原因流向结果：\"因为\"和\"所以\"是固定搭档</text></svg>","变式表":{"不变":"前因后果，讲为什么","可变":{"关联词":["因为…所以…","由于…因此…","既然…就…"],"语体":["口语（因为…所以…）","书面（由于…因此…）"]},"边界":"'因为…所以…'不与'因此'混搭（✗因为…因此…）；'既然'表已然原因（既然来了，就住下）；因果可倒装（'因为累，所以睡'='睡，因为累'，强调不同）","覆盖已确认":[],"覆盖缺失":["关联词","语体"]},"前置知识":["主谓式","连词"]},{"name":"假设复句","例子":["如果下雨，就不去了","如果周末不下雨，我们就去爬山","如果下雨，我们就不去了。","假如我是鸟，就能自由飞翔。","要是早点出发，就不会迟到了。","如果努力，就一定有收获。","假如下雪，学校就放假了。","如果我是你，就会道歉。","要是没有水，植物会枯死。","假如时光倒流，我会更珍惜。","如果明天晴，就去爬山。","要是认真听，就能听懂。","假如我是鸟，就飞向蓝天。（'假如…就…'）","要是下雨，我们就不去了。（'要是…就…'）"],"口诀":"关联词：如果……就、假如","易错":"假设与条件的区别：假设多为未然","讲解":"假设条件下的结果","深讲":"假设复句是假设条件下的结果的复句；前句假设一种还没发生的情况，后句说在这种情况下会怎么样；常用如果……就、假如……就、要是……就。","分类":[{"类":"如果……就……式","说明":"最常用的假设搭配。","代表":"如果……就……","例子":["如果下雨，就不去了。"]},{"类":"假如……就……式","说明":"假如引出假设。","代表":"假如……就……","例子":["假如明天不下雨，我们就去爬山。"]},{"类":"要是……就……式","说明":"要是引出假设，口语常用。","代表":"要是……就……","例子":["要是努力，就会进步。"]}],"怎么认":["前句是不是在假设一种还没发生的情况？是的。","有没有如果、假如、要是？有，多半是假设。","后句是不是在说假设成立会怎么样？是的。"],"辨析":"假设和条件的区别：假设多为未然（如果下雨，就不去了：雨还没下）；条件多为必要或充分（只有努力，才能成功：努力是必要条件）。看前句是假设还是条件。","例句解析":[{"句":"如果下雨，就不去了。","析":"下雨是假设，还没发生；不去了是假设下的结果。"},{"句":"如果周末不下雨，我们就去爬山。","析":"周末不下雨是假设，去爬山是假设下的结果。"}],"练习":[{"q":"下面哪个是假设复句？","options":["因为努力，所以成功","虽然累，但是坚持","如果下雨，就不去了","只有努力，才能成功"],"answer":2,"解析":"如果……就表示假设。","类":"如果……就……式"},{"q":"假设复句前句的情况一般是？","options":["已经发生","还没发生","正在发生","不会发生"],"answer":1,"解析":"假设多为未然，还没发生。","类":"如果……就……式"},{"q":"“假如明天不下雨，我们就去爬山”属于？","options":["假设复句","条件复句","因果复句","选择复句"],"answer":0,"解析":"假如……就表示假设。","类":"假如……就……式"}],"类比":"假设复句像\"<b>如果</b>\"游戏：如果下雨，就不去。前面是假想条件，后面是结果。","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">如果下雨</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">假想条件</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">就不去了</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">可能的结果</text></g><text x=\"320\" y=\"160\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">假设复句=如果游戏：条件是假想的<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"1.9s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"假设一种情况，讲'如果…就…'（未然）","可变":{"关联词":["如果…就…","假如…就…","要是…就…"],"假设":["与事实相反（如果我是鸟）","可能实现（如果下雨）"]},"边界":"假设是未然（还没发生）；与条件区别：条件是已然/规律（'只有…才…'），假设是设想；'即使…也…'是让步假设","覆盖已确认":["假设"],"覆盖缺失":["关联词"]},"前置知识":["主谓式","连词"]},{"name":"条件复句","例子":["只有努力，才能成功","只有多练习，才能写好字","只要下雨，地就会湿。","无论多难，我们都不放弃。","不管刮风下雨，他都坚持跑步。","只有团结，才能战胜困难。","只要有信心，就没有办不成的事。","无论走到哪里，都要诚实。","不管多晚，妈妈都等我回家。","只有多读多写，作文才能进步。","只要肯动脑，就没有难题。","除非你去，否则我不去。（'除非…才…'）","无论多难，我们都要坚持。（'无论…都…'，无条件）","只有努力，才能成功。（'只有…才…'，唯一条件）","只要下雨，地就湿。（'只要…就…'，充分条件）"],"口诀":"关联词：只有……才、只要……就","易错":"“只有……才”表必要条件，“只要……就”表充分条件","讲解":"条件与结果","深讲":"条件复句是条件与结果的复句；前句说条件，后句说在这个条件下会怎么样；条件分必要条件和充分条件，还有无条件。","分类":[{"类":"只有……才……式","说明":"必要条件：缺了这个条件就不行。","代表":"只有……才……","例子":["只有努力，才能成功。"]},{"类":"只要……就……式","说明":"充分条件：有了这个条件就够了。","代表":"只要……就……","例子":["只要多练习，就能写好字。"]},{"类":"无论……都……式","说明":"无条件：不管什么条件，结果都一样。","代表":"无论……都……","例子":["无论多难，我们都要坚持。"]}],"怎么认":["前句是不是在说条件？是的。","有没有只有……才、只要……就、无论……都？有，多半是条件。","问“在什么条件下”，能问出前句吗？能，说明前句是条件。"],"辨析":"只有……才和只要……就的区别：只有……才是必要条件（缺了不行：只有努力，才能成功）；只要……就是充分条件（有了就够：只要多练习，就能写好字）。不要混。","例句解析":[{"句":"只有努力，才能成功。","析":"努力是必要条件，缺了不行，是条件复句。"},{"句":"只有多练习，才能写好字。","析":"多练习是必要条件，是条件复句。"}],"练习":[{"q":"下面哪个是条件复句？","options":["因为努力，所以成功","如果下雨，就不去了","只有努力，才能成功","虽然累，但是坚持"],"answer":2,"解析":"只有……才表示必要条件，是条件。","类":"只有……才……式"},{"q":"“只有……才”表？","options":["充分条件","必要条件","假设","因果"],"answer":1,"解析":"只有……才表示缺了这个条件就不行。","类":"只有……才……式"},{"q":"“只要多练习，就能写好字”中，“只要……就”表？","options":["必要条件","充分条件","假设","转折"],"answer":1,"解析":"只要……就表示有了这个条件就够了。","类":"只要……就……式"}],"类比":"条件复句像开门的<b>钥匙</b>：只有努力，才能成功。条件是门，结果是门后的房间。","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">只有努力</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">条件=钥匙</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">才能成功</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">结果=门后的房间</text></g><text x=\"320\" y=\"160\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">条件复句=钥匙开门：有条件才有结果<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"1.9s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"前一分句是后一分句的条件","可变":{"关联词":["只有…才…","只要…就…","无论…都…","除非…才…"],"条件":["唯一（只有…才…）","充分（只要…就…）","无条件（无论…都…）"]},"边界":"'只有…才…'表唯一条件（只有努力，才成功）；'只要…就…'表充分条件；与假设区别：条件多是规律/已然，假设是设想/未然","覆盖已确认":[],"覆盖缺失":["关联词","条件"]},"前置知识":["主谓式","连词"]}],"name":"复句的类型（7种）"},{"id":"guanlianci","name":"关联词（13组）","items":[{"name":"因为…所以…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">因为下雨，所以运动会取消了。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">下雨是原因，运动会取消是结果，是因果关系。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">因为他努力，所以考了第一。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">努力是原因，考第一是结果；前后主语不同，关联词在句首。</text></g></svg>","讲解":"表示因果关系：前因后果。","深讲":"因为……所以……表示因果关系：前句说原因，后句说结果；前后主语相同，关联词放主语后；主语不同，关联词放主语前；因为和但是不能配对，不能说“因为……但是……”。","分类":[{"类":"因为……所以……式","说明":"最常用的因果搭配，先因后果。","代表":"因为……所以……","例子":["因为下雨，所以运动会取消了。"]},{"类":"由于……因此……式","说明":"由于引出原因，因此引出结果。","代表":"由于……因此……","例子":["由于生病，因此他没去上学。"]},{"类":"先果后因式","说明":"先说结果，后说原因。","代表":"……，因为……","例子":["他没去上学，因为生病了。"]}],"怎么认":["前后是不是原因和结果？是的。","有没有因为、由于这类表原因的词？有。","问“为什么”，能问出前句吗？能，说明前句是原因。"],"辨析":"因为……所以……不能和但是配对。“因为下雨，但是没耽误”是错的：因为表原因，但是表转折，两者不能混用。想表转折，用虽然……但是。","例句解析":[{"句":"因为下雨，所以运动会取消了。","析":"下雨是原因，运动会取消是结果，是因果关系。"},{"句":"因为他努力，所以考了第一。","析":"努力是原因，考第一是结果；前后主语不同，关联词在句首。"}],"练习":[{"q":"下面哪个搭配是对的？","options":["因为……但是……","因为……所以……","因为……而且……","因为……还是……"],"answer":1,"解析":"因为配所以表因果，不能配但是。","类":"因为……所以……式"},{"q":"“他没去上学，因为生病了”属于？","options":["先因后果","先果后因","转折","假设"],"answer":1,"解析":"先说结果没去上学，后说原因生病了。","类":"先果后因式"},{"q":"“由于生病，因此他没去上学”中，原因是？","options":["没去上学","生病","他","因此"],"answer":1,"解析":"由于引出原因生病，因此引出结果。","类":"由于……因此……式"}],"例子":["因为下雨，所以运动会取消了","因为他努力，所以考了第一","因为下雨，所以地面湿了。","因为生病，所以他请假了。","因为坚持锻炼，所以身体很好。","因为粗心，所以他算错了题。","因为天黑，所以打开了路灯。","因为缺水，所以禾苗枯了。","因为准备充分，所以考得很好。","因为帮助别人，所以大家喜欢他。","因为起得早，所以赶上了火车。","因为爱读书，所以知识丰富。"],"口诀":"前因后果","易错":"不能说“因为…但是…”","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["因为…所以…","含义：表因果（原因→结果）；用法：前因后果连用；例句：因为下雨，所以运动会取消了；误用：❌“因为下雨，但是没耽误”（“因为”不能和“但是”配对）→ ✅“虽然下雨，但是没耽误”"],["虽然…但是…","含义：表转折（让步→转折）；用法：前让后转连用；例句：虽然下雨了，但是我们照常上课；误用：❌“因为……但是……”"]]},"前置知识":["因果复句"]},{"name":"如果…就…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">如果明天下雨，我们就不去春游了。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">明天下雨是假设，不去春游是假设下的结果。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">如果你来，我就告诉你。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">你来是假设，告诉你是假设下的结果；前后主语不同，关联词在主语前。</text></g></svg>","讲解":"表示假设：假设条件下的结果。","深讲":"如果……就……表示假设：前句假设一种还没发生的情况，后句说在这种情况下会怎么样；前后主语相同，关联词放主语后；不同，放主语前。","分类":[{"类":"如果……就……式","说明":"最常用的假设搭配。","代表":"如果……就……","例子":["如果明天下雨，我们就不去春游了。"]},{"类":"假如……就……式","说明":"假如引出假设。","代表":"假如……就……","例子":["假如你来，我就告诉你。"]},{"类":"要是……就……式","说明":"要是引出假设，口语常用。","代表":"要是……就……","例子":["要是努力，就会进步。"]}],"怎么认":["前句是不是在假设还没发生的情况？是的。","有没有如果、假如、要是？有。","后句是不是在说假设成立会怎么样？是的。"],"辨析":"如果……就……和只有……才……的区别：如果表假设（如果下雨，就不去了），只有表必要条件（只有努力，才能成功）。看前句是假设还是必要条件。","例句解析":[{"句":"如果明天下雨，我们就不去春游了。","析":"明天下雨是假设，不去春游是假设下的结果。"},{"句":"如果你来，我就告诉你。","析":"你来是假设，告诉你是假设下的结果；前后主语不同，关联词在主语前。"}],"练习":[{"q":"下面哪个是假设关系？","options":["因为努力，所以成功","如果下雨，就不去了","只有努力，才能成功","虽然累，但是坚持"],"answer":1,"解析":"如果……就表示假设。","类":"如果……就……式"},{"q":"“假如你来，我就告诉你”属于？","options":["假设","条件","因果","转折"],"answer":0,"解析":"假如……就表示假设。","类":"假如……就……式"},{"q":"假设的情况一般是？","options":["已经发生","还没发生","正在发生","不会发生"],"answer":1,"解析":"假设多为未然，还没发生。","类":"如果……就……式"}],"例子":["如果明天下雨，我们就不去春游了","如果你来，我就告诉你","如果明天下雨，我们就待在家里。","如果你有困难，就告诉我。","如果努力学习，就能取得好成绩。","如果他来了，就一起出发。","如果不抓紧，就来不及了。","如果你同意，我们就签约。","如果天晴，我们就去放风筝。","如果累了，就休息一会儿。","如果遇到难题，就问老师。","如果我是你，就会接受。"],"口诀":"假设条件","易错":"假设多为还没发生的事","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["如果…就…","含义：表假设；用法：假设成立，结果才来；例句：如果明天下雨，我们就不去春游了；误用：混淆假设与必要条件：看前句是假设还是必要条件"],["只有…才…","含义：表必要条件；用法：缺了不行；例句：只有努力，才能成功；误用：❌“如果努力，才能成功”"]]},"前置知识":["假设复句"]},{"name":"虽然…但是…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">虽然下雨了，但是我们照常上课。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">下雨和照常上课相对，是转折关系。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">虽然他很累，但是坚持跑完了。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">累和坚持跑完相对，是转折关系；前后主语相同，关联词在主语后。</text></g></svg>","讲解":"表示转折：前后意思相反或相对。","深讲":"虽然……但是……表示转折：前句先让一步，后句一转，说出相反或相对的意思；前后主语相同，关联词放主语后；不同，放主语前；转折的后句不能省。","分类":[{"类":"虽然……但是……式","说明":"最常用的转折搭配。","代表":"虽然……但是……","例子":["虽然下雨了，但是我们照常上课。"]},{"类":"尽管……还是……式","说明":"尽管让步，还是表示转折的结果。","代表":"尽管……还是……","例子":["尽管他很累，还是坚持跑完了。"]},{"类":"虽然……，……式","说明":"后句转折词省略，但意思仍是转折。","代表":"虽然……，……","例子":["虽然下雨，我们照常上课。"]}],"怎么认":["前后意思是不是相反或相对？是的。","有没有虽然、尽管这类让步词？有。","去掉后句，前句的意思还完整吗？不完整，说明转折在后句。"],"辨析":"虽然……但是……和因为……所以……的区别：虽然表转折（虽然下雨，但是照常上课），因为表因果（因为下雨，所以取消）。不能说“因为……但是……”。","例句解析":[{"句":"虽然下雨了，但是我们照常上课。","析":"下雨和照常上课相对，是转折关系。"},{"句":"虽然他很累，但是坚持跑完了。","析":"累和坚持跑完相对，是转折关系；前后主语相同，关联词在主语后。"}],"练习":[{"q":"下面哪个是转折关系？","options":["因为努力，所以成功","虽然下雨，但是照常上课","如果下雨，就不去了","只有努力，才能成功"],"answer":1,"解析":"虽然……但是表示转折。","类":"虽然……但是……式"},{"q":"“尽管他很累，还是坚持跑完了”属于？","options":["转折","因果","递进","并列"],"answer":0,"解析":"尽管……还是表示转折。","类":"尽管……还是……式"},{"q":"“因为……但是……”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"因为表原因，但是表转折，不能配对。","类":"虽然……但是……式"}],"例子":["虽然下雨了，但是我们照常上课","虽然他很累，但是坚持跑完了","虽然天气很冷，但是他坚持跑步。","虽然作业很多，但是他很快写完了。","虽然失败了，但是他不灰心。","虽然年纪小，但是他很懂事。","虽然路很远，但是我们走到了。","虽然很累，但是妈妈还在做饭。","虽然下雨，但是比赛继续进行。","虽然他病了，但是坚持上学。","虽然时间紧，但是任务完成了。","虽然贵了点，但是很实用。"],"口诀":"先让后转","易错":"前后意思要相反或相对","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["虽然…但是…","含义：表转折；用法：前让后转连用；例句：虽然下雨了，但是我们照常上课；误用：❌“因为……但是……”"],["因为…所以…","含义：表因果；用法：前因后果连用；例句：因为下雨，所以运动会取消了；误用：❌“虽然……所以……”"]]},"前置知识":["转折复句"]},{"name":"不但…而且…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他不但学习好，而且爱运动。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">爱运动比学习好更进一层，是递进关系。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">她不但画画好，而且字也写得漂亮。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">字漂亮比画画好更进一层，是递进关系。</text></g></svg>","讲解":"表示递进：后分句比前分句更进一层。","深讲":"不但……而且……表示递进：后句比前句更进一层，顺序不能颠倒；前后主语相同，关联词放主语后；不同，放主语前。","分类":[{"类":"不但……而且……式","说明":"最常用的递进搭配。","代表":"不但……而且……","例子":["他不但学习好，而且爱运动。"]},{"类":"不仅……还……式","说明":"不仅引出前一层，还引出更进一层。","代表":"不仅……还……","例子":["她不仅画画好，还写得一手好字。"]},{"类":"不但……，甚至……式","说明":"后句用甚至，表示进到出乎意料的一层。","代表":"不但……，甚至……","例子":["他不但会唱歌，甚至会作曲。"]}],"怎么认":["后句是不是比前句更进一层？是的。","有没有不但、不仅、甚至？有。","前后换个位置，意思还顺吗？不顺，说明顺序不能颠倒。"],"辨析":"不但……而且……和既……又……的区别：不但表递进（更进一层），既表并列（平行）。“不但学习好，而且爱运动”是递进；“既聪明又勤奋”是并列。","例句解析":[{"句":"他不但学习好，而且爱运动。","析":"爱运动比学习好更进一层，是递进关系。"},{"句":"她不但画画好，而且字也写得漂亮。","析":"字漂亮比画画好更进一层，是递进关系。"}],"练习":[{"q":"下面哪个是递进关系？","options":["他既聪明又勤奋","他不但学习好，而且爱运动","他来了，我也来了","因为努力，所以成功"],"answer":1,"解析":"不但……而且表示更进一层。","类":"不但……而且……式"},{"q":"递进关系前后顺序能颠倒吗？","options":["能","不能","有时能","看情况"],"answer":1,"解析":"递进是进一层的关系，顺序不能颠倒。","类":"不但……而且……式"},{"q":"“她不仅画画好，还写得一手好字”属于？","options":["并列","递进","转折","因果"],"answer":1,"解析":"不仅……还表示更进一层。","类":"不仅……还……式"}],"例子":["他不但学习好，而且爱运动","她不但画画好，而且字也写得漂亮","他不但学习好，而且体育好。","这家店不但便宜，而且质量好。","小明不但聪明，而且勤奋。","春天不但温暖，而且多彩。","她不但会唱歌，而且会弹琴。","这本书不但有趣，而且有用。","他不但跑得快，而且跳得高。","妈妈不但会做饭，而且会织毛衣。","这个问题不但重要，而且紧急。","教室不但干净，而且明亮。"],"口诀":"层层递进","易错":"递进顺序不能颠倒","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["不但…而且…","含义：表递进（更进一层）；用法：后句比前句更进一层；例句：他不但学习好，而且爱运动；误用：❌“他既学习好，而且爱运动”（混用）"],["既…又…","含义：表并列（平行）；用法：前后平行；例句：他既聪明又勤奋；误用：❌“他不但聪明，又勤奋”"]]},"前置知识":["递进复句"]},{"name":"只有…才…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">只有努力，才能成功。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">努力是必要条件，缺了不行，是条件关系。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">只有多练习，才能写好字。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">多练习是必要条件，是条件关系。</text></g></svg>","讲解":"表示必要条件：缺了这个条件就不行。","深讲":"只有……才……表示必要条件：缺了这个条件就不行；别和只要……就……搞混，那是充分条件，有了就够了。","分类":[{"类":"只有……才……式","说明":"最常用的必要条件搭配。","代表":"只有……才……","例子":["只有努力，才能成功。"]},{"类":"唯有……才……式","说明":"唯有和只有意思一样，语气较正式。","代表":"唯有……才……","例子":["唯有努力，才有收获。"]},{"类":"除非……才……式","说明":"除非引出必要条件，意思和只有一样。","代表":"除非……才……","例子":["除非努力，才会成功。"]}],"怎么认":["前句是不是缺了就不行的条件？是的。","有没有只有、唯有、除非？有。","把前句去掉，后句还能成立吗？不能，说明前句是必要条件。"],"辨析":"只有……才……和只要……就……的区别：只有是必要条件（缺了不行：只有努力，才能成功），只要是充分条件（有了就够：只要多练习，就能写好字）。","例句解析":[{"句":"只有努力，才能成功。","析":"努力是必要条件，缺了不行，是条件关系。"},{"句":"只有多练习，才能写好字。","析":"多练习是必要条件，是条件关系。"}],"练习":[{"q":"下面哪个是必要条件？","options":["只要多练习，就能写好字","只有努力，才能成功","如果下雨，就不去了","因为努力，所以成功"],"answer":1,"解析":"只有……才表示缺了不行。","类":"只有……才……式"},{"q":"“除非努力，才会成功”属于？","options":["必要条件","充分条件","假设","因果"],"answer":0,"解析":"除非……才和只有……才一样，表必要条件。","类":"除非……才……式"},{"q":"“唯有努力，才有收获”中，“唯有”的意思是？","options":["只要","只有","如果","因为"],"answer":1,"解析":"唯有和只有意思一样，表必要条件。","类":"唯有……才……式"}],"例子":["只有努力，才能成功","只有多练习，才能写好字","只有努力学习，才能考上好学校。","只有团结一心，才能战胜困难。","只有诚实，才能赢得信任。","只有坚持，梦想才能实现。","只有爱护环境，家园才更美丽。","只有认真听讲，才能真正学会。","只有付出，才有回报。","只有经历风雨，才能见彩虹。","只有打好基础，才能走得更远。"],"口诀":"必要条件","易错":"别和“只要…就…”搞混（那是充分条件）","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["只有…才…","含义：表必要条件（缺了不行）；用法：只有+条件，才+结果；例句：只有努力，才能成功；误用：❌“只要努力，才能成功”（前后不配套）"],["只要…就…","含义：表充分条件（有了就够）；用法：只要+条件，就+结果；例句：只要多练习，就能写好字；误用：❌“只有多练习，就能写好字”"]]},"前置知识":["条件复句"]},{"name":"无论…都…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">无论刮风下雨，他都按时到校。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">刮风下雨与否，结果都一样按时到校，是无条件。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">无论谁问，他都不说。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">谁问都一样不说，是无条件；无论后跟疑问词谁。</text></g></svg>","讲解":"表示无条件：不管什么情况，结果都一样。","深讲":"无论……都……表示无条件：不管什么情况，结果都一样；无论后面常跟疑问词，如谁、哪儿、什么。","分类":[{"类":"无论……都……式","说明":"最常用的无条件搭配。","代表":"无论……都……","例子":["无论刮风下雨，他都按时到校。"]},{"类":"不管……都……式","说明":"不管和无论意思一样，口语常用。","代表":"不管……都……","例子":["不管多难，我们都要坚持。"]},{"类":"无论+疑问词式","说明":"无论后跟疑问词，表示任何情况都一样。","代表":"无论谁、哪儿、什么……都……","例子":["无论谁问，他都不说。"]}],"怎么认":["不管什么情况，结果是不是都一样？是的。","有没有无论、不管？有。","无论后是不是跟了疑问词（谁、哪儿、什么）？是的，多半是无条件。"],"辨析":"无论……都……和如果……就……的区别：无论表无条件（不管怎样结果都一样），如果表假设（假设成立结果才来）。看结果是不是不依赖条件。","例句解析":[{"句":"无论刮风下雨，他都按时到校。","析":"刮风下雨与否，结果都一样按时到校，是无条件。"},{"句":"无论谁问，他都不说。","析":"谁问都一样不说，是无条件；无论后跟疑问词谁。"}],"练习":[{"q":"下面哪个是无条件关系？","options":["如果下雨，就不去了","无论刮风下雨，他都按时到校","只有努力，才能成功","因为努力，所以成功"],"answer":1,"解析":"无论……都表示不管怎样结果都一样。","类":"无论……都……式"},{"q":"“无论谁问，他都不说”中，“无论”后跟的是？","options":["名词","疑问词","动词","形容词"],"answer":1,"解析":"无论后可跟疑问词谁。","类":"无论+疑问词式"},{"q":"“不管多难，我们都要坚持”属于？","options":["无条件","假设","必要条件","因果"],"answer":0,"解析":"不管……都和无论……都一样，表无条件。","类":"不管……都……式"}],"例子":["无论刮风下雨，他都按时到校","无论谁问，他都不说","无论多么困难，我们都不放弃。","无论走到哪里，我都想念家乡。","无论多忙，妈妈都记得我的生日。","无论结果如何，我们都尽力了。","无论多晚，他都坚持把作业写完。","无论谁问起，他都实话实说。","无论天气怎样，运动会都照常举行。","无论多累，战士们都不停下脚步。","无论遇到什么，都要勇敢面对。"],"口诀":"条件再多都不怕","易错":"“无论”后可跟疑问词：无论谁/哪儿/什么","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["无论…都…","含义：表无条件（不管怎样结果都一样）；用法：结果不依赖条件；例句：无论刮风下雨，他都按时到校；误用：❌“无论下雨，我们就不去了”（“无论”后不能接单一假设结果）"],["如果…就…","含义：表假设；用法：假设成立结果才来；例句：如果明天下雨，我们就不去春游了；误用：看结果是不是不依赖条件：是→用“无论”，否→用“如果”"]]},"前置知识":["条件复句"]},{"name":"既…又…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他既聪明又勤奋。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">聪明和勤奋同时成立、地位平等，是并列关系。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">这件衣服既好看又便宜。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">好看和便宜都是这件衣服的特点，地位平等，是并列关系。</text></g></svg>","讲解":"表示并列：两个方面同时成立。","深讲":"既……又……表示并列：两个方面同时成立，地位平等；前后感情色彩要一致，不能既好又坏。","分类":[{"类":"品格并列式","说明":"并列的两个方面都是人的品格、优点。","代表":"既……又……","例子":["他既聪明又勤奋。"]},{"类":"特点并列式","说明":"并列的两个方面都是事物的特点。","代表":"既……又……","例子":["这件衣服既好看又便宜。"]}],"怎么认":["两个方面是不是同时成立、地位平等？是的。","有没有既……又……？有。","前后感情色彩一致吗？一致，才是规范的既……又……。"],"辨析":"既……又……和不但……而且……的区别：既表并列（平行：既聪明又勤奋），不但表递进（更进一层：不但聪明，而且勤奋得出了名）。看后句是不是更进一层。","例句解析":[{"句":"他既聪明又勤奋。","析":"聪明和勤奋同时成立、地位平等，是并列关系。"},{"句":"这件衣服既好看又便宜。","析":"好看和便宜都是这件衣服的特点，地位平等，是并列关系。"}],"练习":[{"q":"下面哪个是并列关系？","options":["他不但聪明，而且勤奋","他既聪明又勤奋","因为聪明，所以成功","如果聪明，就成功"],"answer":1,"解析":"既……又表示平行并列。","类":"品格并列式"},{"q":"“既……又……”前后感情色彩要？","options":["相反","一致","无关","递进"],"answer":1,"解析":"前后感情色彩要一致，不能既好又坏。","类":"品格并列式"},{"q":"“这件衣服既好看又便宜”属于？","options":["并列","递进","转折","因果"],"answer":0,"解析":"好看和便宜平行，是并列。","类":"特点并列式"}],"例子":["他既聪明又勤奋","这件衣服既好看又便宜","这苹果既大又甜。","教室里既干净又安静。","她既会唱歌又会跳舞。","小狗既可爱又听话。","秋天既凉爽又美丽。","他既是班长又是课代表。","这个问题既有趣又有意义。","湖水既清又静。"],"口诀":"两个优点一起夸","易错":"前后感情色彩要一致（不能既好又坏）","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["既…又…","含义：表并列（平行）；用法：前后平行；例句：他既聪明又勤奋；误用：❌“他既学习好，而且爱运动”"],["不但…而且…","含义：表递进（更进一层）；用法：后句更进一层；例句：他不但学习好，而且爱运动；误用：看后句是不是更进一层：是→用“不但”，否→用“既”"]]},"前置知识":["并列复句"]},{"name":"不是…而是…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他不是不认真，而是方法不对。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">否定不认真，肯定方法不对，是选择关系。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">我不是不想去，而是有事。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">否定不想去，肯定有事，是选择关系。</text></g></svg>","讲解":"表示选择：否定前者，肯定后者。","深讲":"不是……而是……表示选择：否定前者，肯定后者；前后要是同一类事物才能这样选，不能拿不同类的东西比。","分类":[{"类":"否定原因式","说明":"否定一个原因，肯定另一个原因。","代表":"不是……而是……","例子":["他不是不认真，而是方法不对。"]},{"类":"否定事物式","说明":"否定一个事物，肯定另一个事物。","代表":"不是……而是……","例子":["这不是苹果，而是梨子。"]}],"怎么认":["是不是先否定一个，再肯定一个？是的。","有没有不是……而是……？有。","前后是不是同一类事物？是的，才能这样选。"],"辨析":"不是……而是……和是……还是……的区别：不是……而是……是说话人自己选定后者（不是苹果，而是梨子）；是……还是……是让对方选（是苹果还是梨子）。","例句解析":[{"句":"他不是不认真，而是方法不对。","析":"否定不认真，肯定方法不对，是选择关系。"},{"句":"我不是不想去，而是有事。","析":"否定不想去，肯定有事，是选择关系。"}],"练习":[{"q":"下面哪个是“不是……而是……”关系？","options":["是去还是留","他不是不认真，而是方法不对","因为认真，所以成功","虽然累，但是坚持"],"answer":1,"解析":"先否定不认真，再肯定方法不对。","类":"否定原因式"},{"q":"“这不是苹果，而是梨子”属于？","options":["选择","并列","因果","转折"],"answer":0,"解析":"否定苹果，肯定梨子，是选择。","类":"否定事物式"},{"q":"“不是……而是……”前后要是？","options":["不同类事物","同一类事物","无关事物","相反事物"],"answer":1,"解析":"前后要是同一类事物才能这样选。","类":"否定事物式"}],"例子":["他不是不认真，而是方法不对","我不是不想去，而是有事","他不是不努力，而是方法不对。","这不是失败，而是新的开始。","成功不是偶然，而是坚持的结果。","他不是生病，而是有事出去了。","这不是批评，而是真诚的建议。","爱不是占有，而是付出。","他不是不想去，而是没时间。","这道题不是不会，而是有点难。","真正的朋友不是锦上添花，而是雪中送炭。","学习不是为了分数，而是为了成长。"],"口诀":"否定一个，肯定一个","易错":"前后要是同一类事物才能这样选","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["不是…而是…","含义：说话人自己选定后者；用法：否定前者、肯定后者；例句：他不是不认真，而是方法不对；误用：❌“他是认真还是不认真？”（想表达选定后者时不用“还是”）"],["是…还是…","含义：让对方选；用法：提出选项问对方；例句：你喝水还是喝牛奶？；误用：自己已选定时不用“还是”"]]},"前置知识":["并列复句"]},{"name":"先…然后…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">先洗手，然后吃饭。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">洗手在前，吃饭在后，按顺序做，是承接关系。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">先写作业，然后才能看电视。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">写作业在前，看电视在后，是承接关系。</text></g></svg>","讲解":"表示承接：按顺序做事情。","深讲":"先……然后……表示承接：按顺序做事情，先做的放前面，后做的放后面，顺序不能乱；这是承接关系，在复句7种里没有单列，在关联词里学。","分类":[{"类":"先……然后……式","说明":"最常用的承接搭配。","代表":"先……然后……","例子":["先洗手，然后吃饭。"]},{"类":"先……，再……式","说明":"再和然后意思一样，表接着做。","代表":"先……，再……","例子":["先洗手，再吃饭。"]},{"类":"先……，接着……式","说明":"接着表示紧接着做下一步。","代表":"先……，接着……","例子":["先写作业，接着看电视。"]}],"怎么认":["是不是按顺序做事情？是的。","有没有先……然后、先……再？有。","前后换个位置，顺序还对吗？不对，说明顺序不能乱。"],"辨析":"先……然后……和一……就……的区别：先然后表顺序（先洗手，然后吃饭：两件事有先后），一就表紧接（我一回家就写作业：两件事挨得很紧）。","例句解析":[{"句":"先洗手，然后吃饭。","析":"洗手在前，吃饭在后，按顺序做，是承接关系。"},{"句":"先写作业，然后才能看电视。","析":"写作业在前，看电视在后，是承接关系。"}],"练习":[{"q":"下面哪个是承接关系？","options":["我一回家就写作业","先洗手，然后吃饭","因为累，所以休息","虽然累，但是坚持"],"answer":1,"解析":"先……然后表示按顺序做事情。","类":"先……然后……式"},{"q":"承接关系前后顺序能乱吗？","options":["能","不能","有时能","看情况"],"answer":1,"解析":"先做的放前面，顺序不能乱。","类":"先……然后……式"},{"q":"“先洗手，再吃饭”属于？","options":["承接","紧接","因果","并列"],"answer":0,"解析":"先……再……和先……然后……一样，表承接。","类":"先……，再……式"}],"例子":["先洗手，然后吃饭","先写作业，然后才能看电视","先读题目，然后再下笔。","先穿上外套，然后再出门。","做数学题要先审题，然后计算。","先把桌子擦干净，然后摆好书本。","他先跑完步，然后去洗澡。","先听老师讲，然后自己练习。","做饭要先洗菜，然后切菜。","先完成作业，然后才能玩。","他先道歉，然后解释了原因。"],"口诀":"事情有先后","易错":"顺序不能乱，先做的放前面","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["先…然后…","含义：表顺序（有先后）；用法：两件事有先后，不一定紧接；例句：先洗手，然后吃饭；误用：❌“我先回家然后就写作业”（混用两种格式）"],["一…就…","含义：表紧接（挨得很紧）；用法：两件事挨得很紧；例句：我一回家就写作业；误用：❌“先回家就写作业”"]]},"前置知识":["并列复句"]},{"name":"一…就…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我一回家就写作业。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">回家一发生，写作业马上跟着，是紧接关系。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">他一听音乐就开心。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">一听音乐，开心马上来，是紧接关系。</text></g></svg>","讲解":"表示紧接：两个动作挨得很紧。","深讲":"一……就……表示紧接：两个动作挨得很紧，前一个动作一发生，后一个动作马上跟着发生；一……就……中间别加太多字。","分类":[{"类":"一……就……式","说明":"最常用的紧接搭配。","代表":"一……就……","例子":["我一回家就写作业。"]},{"类":"刚……就……式","说明":"刚表示刚刚发生，就表示马上跟着。","代表":"刚……就……","例子":["他刚回家就写作业。"]},{"类":"一听一看就……式","说明":"一听、一看这类感官动作一发生，反应马上来。","代表":"一……就……","例子":["他一听音乐就开心。"]}],"怎么认":["两个动作是不是挨得很紧？是的。","有没有一……就、刚……就？有。","前一个动作一发生，后一个是不是马上跟着？是的。"],"辨析":"一……就……和先……然后……的区别：一就表紧接（我一回家就写作业：挨得很紧），先然后表顺序（先洗手，然后吃饭：有先后，不一定紧接）。","例句解析":[{"句":"我一回家就写作业。","析":"回家一发生，写作业马上跟着，是紧接关系。"},{"句":"他一听音乐就开心。","析":"一听音乐，开心马上来，是紧接关系。"}],"练习":[{"q":"下面哪个是紧接关系？","options":["先洗手，然后吃饭","我一回家就写作业","因为累，所以休息","虽然累，但是坚持"],"answer":1,"解析":"一……就表示两个动作挨得很紧。","类":"一……就……式"},{"q":"“他刚回家就写作业”属于？","options":["紧接","承接","因果","并列"],"answer":0,"解析":"刚……就和一……就一样，表紧接。","类":"刚……就……式"},{"q":"“一……就……”中间别加？","options":["太多字","关联词","主语","谓语"],"answer":0,"解析":"一……就……中间别加太多字。","类":"一……就……式"}],"例子":["我一回家就写作业","他一听音乐就开心","他一看到我就笑了。","天一黑，路灯就亮了。","妈妈一回来，小狗就摇尾巴。","他一上车就睡着了。","春天一到，花儿就开了。","铃声一响，同学们就进教室了。","我一打开书，就被吸引住了。","他一听说，就赶来了。","雨一停，孩子们就跑出去玩了。"],"口诀":"紧接着发生","易错":"“一…就…”中间别加太多字","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["一…就…","含义：表紧接（挨得很紧）；用法：两件事挨得很紧；例句：我一回家就写作业；误用：❌“先回家就写作业”"],["先…然后…","含义：表顺序（有先后）；用法：有先后，不一定紧接；例句：先洗手，然后吃饭；误用：❌“我一洗手然后吃饭”"]]},"前置知识":["条件复句"]},{"name":"既然…就…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">既然来了，就一起吃饭吧！</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“来了”是已知事实，“一起吃饭吧”是建议。不是结果，是“那就这么办”。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">你既然不想说，那就别说了。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">前后主语都是“你”，“既然”放在主语后更自然。后句“那就别说了”是建议。</text></g></svg>","讲解":"表示“既然事实是这样，那就…”：前句摆一个已知的事实，后句给出建议或推断。","深讲":"结构：既然 + 事实，（那/就/那就）+ 建议或推断。比如“既然来了，就一起吃饭吧”：来是事实，一起吃饭是建议。注意三点：①前句必须是已知事实（假设用“如果”）；②后句不说结果，说“该怎么办”或“能推出什么”；③前后主语相同时，“既然”多放在主语后（“你既然不想说，那就别说了”）。后句也可以是反问（“你既然不喜欢他，为什么还想跟他出去？”）。（来源：AllSet Chinese Grammar Wiki，CC BY-NC-SA 3.0）","类比":"“既然”像顺水推舟：水（事实）已经在那儿了，顺着推一把（建议），船就走了。","口诀":"既然摆事实，就来给建议","例子":["既然来了，就一起吃饭吧！","既然你不舒服，就回家休息吧。","你既然不想说，那就别说了。","既然你那么喜欢，那就买吧。","她既然刚分手，那现在应该是单身吧。","你既然不喜欢他，为什么还想跟他出去？","既然下雨了，我们就在家看电影吧。"],"易错":"✗“既然…所以…”（后句用“就/那”，不用“所以”）；“既然”是已知事实，“如果”是假设，别混。","分类":[{"类":"表建议","说明":"由事实推出该怎么做。","代表":"既然来了就吃吧","例子":["既然来了，就一起吃饭吧！","既然下雨了，我们就在家看电影吧。"]},{"类":"表推断","说明":"由事实推出是什么情况。","代表":"既然分手那就是单身","例子":["她既然刚分手，那现在应该是单身吧。"]},{"类":"带反问","说明":"后句用反问表建议，“那”可省。","代表":"既然不喜欢为什么还去","例子":["你既然不喜欢他，为什么还想跟他出去？"]}],"怎么认":["前句是不是已知事实？是→可能是既然。","后句是不是“该怎么办/能推出什么”？是→更像既然。","能不能换成“如果”？能换→是假设不是既然。"],"辨析":"既然 vs 因为：因为解释“为什么会这样”（因为下雨，比赛取消了）；既然由已知事实推出“该怎么办”（既然下雨了，我们就在家看电影吧）。一个讲原因，一个给建议。既然 vs 如果：如果表还没发生的假设，既然表已发生的事实。","例句解析":[{"句":"既然来了，就一起吃饭吧！","析":"“来了”是已知事实，“一起吃饭吧”是建议。不是结果，是“那就这么办”。"},{"句":"你既然不想说，那就别说了。","析":"前后主语都是“你”，“既然”放在主语后更自然。后句“那就别说了”是建议。"}],"练习":[{"q":"“既然下雨了，我们____在家看电影吧”填哪个？","options":["所以","就","但是","而且"],"answer":1,"解析":"既然后句用“就/那”，不用“所以”。","类":"搭配"},{"q":"哪句的“既然”用对了？","options":["既然明天下雨，我们就去","既然你来了，就一起吃吧","既然他会来，所以我等","既然下雨，但是去"],"answer":1,"解析":"“你来了”是已知事实，后句是建议。用“如果”表假设，用“所以/但是”搭配错。","类":"辨析"},{"q":"“既然”和“如果”最大的区别是？","options":["没区别","既然表已知事实，如果表假设","既然表假设，如果表事实","既然只能书面"],"answer":1,"解析":"既然的前提是已发生的事实，如果的前提是还没发生的假设。","类":"辨析"},{"q":"“你既然不想说，那就别说了”中“既然”放哪？","options":["句首","主语后","句末","动词后"],"answer":1,"解析":"前后主语相同时，“既然”多放在主语后面。","类":"位置"}],"前置知识":["因果复句","条件复句"]},{"name":"即使…也…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">即使下雨，我们也去。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“下雨”是假设，“也去”表决心不变。不能换成“虽然”，因为雨还没下。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">现在即使很忙，我们也抽时间陪孩子。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">这句是错的：“现在很忙”是事实，该用“虽然”：现在虽然很忙，我们也抽时间陪孩子。</text></g></svg>","讲解":"表示让步：“哪怕…，也…”：前句先假设一个情况，后句说“即使这样，结果仍然不变”。","深讲":"结构：即使 + 假设，也 + 结果。比如“即使下雨，我们也去”：下雨是假设（不一定真下），去是决心。注意三点：①前句必须是假设（事实用“虽然”）；②后句的“也”放在主语后（“我也要去”✓，“也要我去”✗）；③搭“也”，不搭“但是”（✗即使…但是…）。近义词：就算、哪怕、就是…也。（来源：AllSet Chinese Grammar Wiki，CC BY-NC-SA 3.0）","类比":"“即使”像打预防针：先假设最坏的情况（下雨），再说针照打（也去）——结果不改。","口诀":"即使摆假设，也字表仍然","例子":["即使下雨，我们也去。","即使你不想让我去，我也要去。","即使冬天很冷，杰克也不穿外套。","即使他没钱，我也要嫁给他。","即使明天下雨，我们也要训练。","即使很贵，我也要买。","即使你不说，我也知道。"],"易错":"前句是事实时用“虽然”（✗“现在即使很忙”→“现在虽然很忙”）；✗“即使…但是…”（→“即使…也…”）。","分类":[{"类":"表决心","说明":"让步之后，决心不变。","代表":"即使…也要","例子":["即使下雨，我们也去。","即使很贵，我也要买。"]},{"类":"表反差","说明":"假设与结果形成反差。","代表":"即使…也不","例子":["即使冬天很冷，杰克也不穿外套。","即使他没钱，我也要嫁给他。"]}],"怎么认":["前句是不是“万一、哪怕”？是→可能是即使。","后句有没有“也/还”表“仍然”？有→更像即使。","前句是事实还是假设？事实→用虽然，假设→用即使。"],"辨析":"即使 vs 虽然：虽然 + 事实（“虽然下雨了，我们还是去了”——雨真的下了）；即使 + 假设（“即使下雨，我们也去”——不一定下）。看前句真假。即使 vs 如果：如果只表假设，即使还多一层“让步、转折”的味道。","例句解析":[{"句":"即使下雨，我们也去。","析":"“下雨”是假设（还没下），“也去”表决心不变。不能换成“虽然”，因为雨还没下。"},{"句":"现在即使很忙，我们也抽时间陪孩子。","析":"这句是错的：“现在很忙”是事实，该用“虽然”：现在虽然很忙，我们也抽时间陪孩子。"}],"练习":[{"q":"“即使明天下雨，我们____要训练”填哪个？","options":["但是","也","所以","而且"],"answer":1,"解析":"即使搭“也”，不搭“但是”。","类":"搭配"},{"q":"哪句该用“虽然”而不是“即使”？","options":["即使下雨，我们也去","现在很忙，我们也陪孩子","即使很贵，我也要买","即使他不来，我也去"],"answer":1,"解析":"“现在很忙”是事实，让步事实用“虽然”。","类":"辨析"},{"q":"“即使你不想让我去，我____要去”中“也”放哪？","options":["我前面","我后面","句首","句末"],"answer":1,"解析":"“也”放在后句主语后面：我也要去。","类":"位置"},{"q":"“即使”的近义词不包括？","options":["就算","哪怕","如果","就是"],"answer":2,"解析":"就算、哪怕、就是…也都表让步；“如果”只表假设，没有让步味。","类":"辨析"}],"前置知识":["假设复句","转折复句"]},{"name":"除非…才…","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">除非你去，他才会去。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“你去”是唯一条件，“他才去”是结果。= 只有你去，他才会去。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">除非下大雨，否则比赛照常进行。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“下大雨”是条件，“否则”引出不满足条件的结果：不下大雨→照常进行。</text></g></svg>","讲解":"表示“唯一条件”：除非A，才B = 只有A，B才成立。A是唯一的门槛。","深讲":"“除非”有三式：①除非A，才B（唯一条件：“除非你去，他才会去”）；②除非A，否则/不然B（“除非你是会员，否则不能进去”——否则=不这样就…）；③结果，除非A（倒装强调：“我不去，除非你也去”）。注意别和“除了”搞混：除了=除开（除了他，都来了），除非=条件。（来源：AllSet Chinese Grammar Wiki，CC BY-NC-SA 3.0）","类比":"“除非”像门禁卡：没刷卡（条件），门（结果）就不开——唯一的钥匙。","口诀":"除非定条件，才字锁结果","例子":["除非你去，他才会去。","除非你有员工卡，才能用这台打印机。","除非你是会员，否则不能进去。","除非下大雨，否则比赛照常进行。","我不去，除非你也去。","你不会这么快升职，除非你表现很好。"],"易错":"✗“除非…所以…”；“除非”是条件，“除了”是除外，别混（“除了他都来了”≠“除非他都来了”）。","分类":[{"类":"唯一条件式","说明":"除非A，才B：B只在A成立时成立。","代表":"除非你去我才去","例子":["除非你去，他才会去。","除非你有员工卡，才能用这台打印机。"]},{"类":"除非否则式","说明":"除非A，否则B：不满足A就会B。","代表":"除非会员否则不进","例子":["除非你是会员，否则不能进去。","除非下大雨，否则比赛照常进行。"]},{"类":"倒装强调式","说明":"先说结果，再用除非补条件。","代表":"我不去除非你去","例子":["我不去，除非你也去。"]}],"怎么认":["是不是“只有…才”的意思？是→可能是除非。","后句有没有“才/否则/不然”？有→更像除非。","能不能换成“除了”？能换→是除外不是条件。"],"辨析":"除非 vs 只有：意思接近（“只有你去，我才去”），除非更口语、更强调“排他、唯一”。除非 vs 除了：除了表“除外”（除了他，大家都来了）；除非表“条件”（除非他来，我才去）。看后面跟的是名词还是条件句。","例句解析":[{"句":"除非你去，他才会去。","析":"“你去”是唯一条件，“他才去”是结果。= 只有你去，他才会去。"},{"句":"除非下大雨，否则比赛照常进行。","析":"“下大雨”是条件，“否则”引出不满足条件的结果：不下大雨→照常进行。"}],"练习":[{"q":"“除非你是会员，____不能进去”填哪个？","options":["所以","否则","但是","而且"],"answer":1,"解析":"除非A，否则B：不满足条件就会B。","类":"搭配"},{"q":"“除非”最接近哪个词的意思？","options":["除了","只有","如果","虽然"],"answer":1,"解析":"除非A才B = 只有A才B，表唯一条件。","类":"辨析"},{"q":"哪句的“除非”用错了？","options":["除非你去，我才去","除了他，大家都来了","除非下雨，否则取消","除非他来，所以我去"],"answer":3,"解析":"“除非…所以…”搭配错，该用“才/否则”。注意第2句是“除了”，表除外，用对了。","类":"易错"},{"q":"“我不去，除非你也去”是哪种句式？","options":["正常语序","倒装强调","疑问句","感叹句"],"answer":1,"解析":"先说结果“我不去”，再用“除非”补条件，是倒装强调式。","类":"结构"}],"前置知识":["条件复句"]}]},{"id":"xiuci","items":[{"name":"比喻","例子":["他像豹子一样快","天上的云像棉花糖","天上的云像棉花糖一样白。","他跑得像豹子一样快。","月亮像玉盘挂在天上。","老师的爱像春雨滋润心田。","西湖像一面明镜。","她的脸红得像苹果。","时间像流水一去不回。","柳条像姑娘的长发随风飘。","雪花像鹅毛纷纷落下。","他高兴得像吃了蜜一样甜。","云像棉花糖。（本体'云'具体，喻体'棉花糖'具体）","时间像流水。（本体'时间'抽象，喻体'流水'具体）"],"口诀":"生动形象","易错":"有“像”不一定是比喻（如表示举例）","讲解":"打比方，生动形象","深讲":"比喻是打比方：把一个事物比作另一个事物，让人一听就明白、一想就形象；本体和喻体必须是不同类的事物，否则就不是比喻，只是比较。","分类":[{"类":"明喻","说明":"有像、如、似这类喻词，本体、喻体都出现。","代表":"像、如、似","例子":["天上的云像棉花糖。"]},{"类":"暗喻","说明":"用是、变成连接，本体、喻体都出现，没有像。","代表":"是、变成","例子":["老师是辛勤的园丁。"]},{"类":"借喻","说明":"只出现喻体，本体不出现，借喻体来说本体。","代表":"只说喻体","例子":["一群花朵走进了教室。"]}],"怎么认":["句子里有没有把甲说成乙？有。","甲和乙是不是不同类的事物？是的，才是比喻。","有没有像、是这类喻词？有，帮助判断是明喻还是暗喻。"],"辨析":"有“像”不一定是比喻。表示举例、比较的“像”不是比喻：他像他爸爸一样高，是比较（人和人同类），不是比喻；天上的云像棉花糖，是比喻（云和棉花糖不同类）。","例句解析":[{"句":"天上的云像棉花糖。","析":"云是本体，棉花糖是喻体，像是喻词，是明喻。"},{"句":"他像豹子一样快。","析":"他是本体，豹子是喻体，像是喻词，是明喻。"}],"练习":[{"q":"下面哪个是比喻？","options":["他像他爸爸一样高","天上的云像棉花糖","他比我高","他和我一样大"],"answer":1,"解析":"云和棉花糖不同类，是比喻；他和爸爸同类，是比较。","类":"明喻"},{"q":"“老师是辛勤的园丁”属于？","options":["明喻","暗喻","借喻","拟人"],"answer":1,"解析":"用是连接，没有像，是暗喻。","类":"暗喻"},{"q":"“一群花朵走进了教室”属于？","options":["明喻","暗喻","借喻","夸张"],"answer":2,"解析":"只出现喻体花朵，本体孩子不出现，是借喻。","类":"借喻"}],"图示":"<svg viewBox=\"0 0 640 360\" id=\"svg\">  <!-- 因果 -->  <g opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/>    <text x=\"80\" y=\"40\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">因果</text>    <rect x=\"30\" y=\"60\" width=\"80\" height=\"36\" rx=\"6\" fill=\"#d3e5d6\"/>    <text x=\"70\" y=\"84\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2c3328\">因为下雨</text>    <rect x=\"170\" y=\"60\" width=\"80\" height=\"36\" rx=\"6\" fill=\"#d3e5d6\"/>    <text x=\"210\" y=\"84\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2c3328\">所以没去</text>    <path d=\"M115,78 L165,78\" stroke=\"#4a7a59\" stroke-width=\"3\" stroke-linecap=\"round\">      <animate attributeName=\"stroke-dashoffset\" values=\"50;0\" dur=\"0.5s\" begin=\"0.8s\" fill=\"freeze\" stroke-dasharray=\"50\"/>    </path>    <polygon points=\"165,72 175,78 165,84\" fill=\"#4a7a59\" opacity=\"0\">      <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.2s\" begin=\"1.2s\" fill=\"freeze\"/>    </polygon>    <text x=\"140\" y=\"110\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6b7566\">因为…所以…</text>  </g>    <!-- 转折 -->  <g opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.8s\" fill=\"freeze\"/>    <text x=\"400\" y=\"40\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">转折</text>    <rect x=\"350\" y=\"60\" width=\"80\" height=\"36\" rx=\"6\" fill=\"#f5d5d0\"/>    <text x=\"390\" y=\"84\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2c3328\">虽然想去</text>    <rect x=\"350\" y=\"60\" width=\"12\" height=\"36\" fill=\"#b85a52\" opacity=\"0.3\"/>    <rect x=\"490\" y=\"60\" width=\"80\" height=\"36\" rx=\"6\" fill=\"#f5d5d0\"/>    <text x=\"530\" y=\"84\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2c3328\">但是没去</text>    <text x=\"460\" y=\"110\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6b7566\">虽然…但是…（一堵墙）</text>  </g>    <!-- 并列 -->  <g opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.0s\" fill=\"freeze\"/>    <text x=\"80\" y=\"170\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">并列</text>    <rect x=\"30\" y=\"190\" width=\"60\" height=\"36\" rx=\"6\" fill=\"#d3e8f0\"/>    <text x=\"60\" y=\"214\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2c3328\">唱歌</text>    <rect x=\"110\" y=\"190\" width=\"60\" height=\"36\" rx=\"6\" fill=\"#d3e8f0\"/>    <text x=\"140\" y=\"214\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2c3328\">跳舞</text>    <text x=\"190\" y=\"214\" font-size=\"13\" fill=\"#4a7a8c\">和</text>    <text x=\"100\" y=\"250\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6b7566\">…和…（并排站）</text>  </g>    <!-- 递进 -->  <g opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4.0s\" fill=\"freeze\"/>    <text x=\"400\" y=\"170\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">递进</text>    <rect x=\"350\" y=\"210\" width=\"70\" height=\"24\" rx=\"4\" fill=\"#f0e6d3\"/>    <text x=\"385\" y=\"227\" text-anchor=\"middle\" font-size=\"12\" fill=\"#2c3328\">会跑</text>    <rect x=\"430\" y=\"190\" width=\"70\" height=\"24\" rx=\"4\" fill=\"#f0e6d3\"/>    <text x=\"465\" y=\"207\" text-anchor=\"middle\" font-size=\"12\" fill=\"#2c3328\">而且会飞</text>    <text x=\"425\" y=\"250\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6b7566\">不但…而且…（上楼梯）</text>  </g>    <text x=\"320\" y=\"300\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">记住形状：箭头=因果，墙=转折，并排=并列，楼梯=递进    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"5.0s\" fill=\"freeze\"/>  </text>  <text x=\"320\" y=\"325\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">13组关联词都是这4种逻辑的变体    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"5.4s\" fill=\"freeze\"/>  </text></svg>","类比":"比喻像给事物<b>穿上别人的衣服</b>：月亮像玉盘。用熟悉的东西解释陌生的东西，一下就懂了。","变式表":{"不变":"打比方，用甲事物说明乙事物，生动形象","可变":{"类型":["明喻（像/如：云像棉花糖）","暗喻（是：他是小老虎）","借喻（不出现本体：棉花糖飘来了）"],"本体喻体":["具体（云→棉花糖）","抽象（时间→流水）"]},"边界":"有'像'不一定是比喻：表举例（像苹果、香蕉）不是；同类比较（他像他爸）不是；本体喻体须不同类","覆盖已确认":["类型"],"覆盖缺失":["本体喻体"]},"前置知识":["名词"]},{"name":"拟人","例子":["小草向我点头","风儿轻轻地抚摸着我的脸","小鸟在枝头唱歌跳舞。","花儿向我们点头微笑。","小溪唱着歌流向远方。","月亮悄悄地爬上了树梢。","柳树姑娘甩着长辫子。","太阳公公露出了笑脸。","小草从土里探出头来。","星星眨着眼睛看我们。","秋风温柔地拥抱着大地。","柳枝在风中跳舞。（直接拟人：'跳舞'是人的动作）","春风又绿江南岸。（间接拟人：'绿'字有人情味）"],"口诀":"赋予情感","易错":"拟人与比喻可兼用","讲解":"把物当人写","深讲":"拟人是把物当人写：让花草、风雨、小动物像人一样动作、说话、有感情；拟人让没有生命的东西活起来，读起来亲切。","分类":[{"类":"动作拟人","说明":"让物像人一样做动作。","代表":"点头、跑、跳","例子":["小草向我点头。"]},{"类":"情感拟人","说明":"让物像人一样有感情。","代表":"笑、哭、高兴","例子":["花儿笑了。"]},{"类":"语言拟人","说明":"让物像人一样说话。","代表":"说、唱、叫","例子":["小鸟对我说：“早上好。”"]}],"怎么认":["主语是不是没有生命的东西？是的。","它做的是不是只有人才做的事（说话、点头、笑）？是的。","把主语换成人，句子还通吗？通，说明是拟人。"],"辨析":"拟人和比喻可兼用，但不一样：拟人是把物当人（小草点头），比喻是把甲比作乙（云像棉花糖）。“风儿抚摸着我的脸”是拟人，不是比喻，因为没有比作什么。","例句解析":[{"句":"小草向我点头。","析":"小草不会点头，点头是人的动作，是拟人。"},{"句":"风儿轻轻地抚摸着我的脸。","析":"抚摸是人的动作，风儿被当成人写，是拟人。"}],"练习":[{"q":"下面哪个是拟人？","options":["天上的云像棉花糖","小草向我点头","他跑得很快","白发三千丈"],"answer":1,"解析":"小草点头是人的动作，是拟人。","类":"动作拟人"},{"q":"“花儿笑了”属于？","options":["动作拟人","情感拟人","语言拟人","比喻"],"answer":1,"解析":"笑是感情，花儿被写出了感情。","类":"情感拟人"},{"q":"“小鸟对我说：早上好”属于？","options":["动作拟人","情感拟人","语言拟人","夸张"],"answer":2,"解析":"小鸟说话，是语言拟人。","类":"语言拟人"}],"类比":"拟人像给万物<b>装上人心</b>：小草在微笑。把人的动作表情借给不会说话的东西。","图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">小草向我点头</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\"点头\"是人的动作</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">柳树姑娘甩长辫子</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">把柳枝当成姑娘</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">星星眨着眼睛</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\"眨眼\"是人的表情</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">拟人=给万物装上人心<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"把物当人写，赋予人的动作/情感","可变":{"拟":["拟人（花儿笑了）","拟物（把人当物，较少）"],"方式":["直接（柳枝跳舞）","间接（春风又绿江南岸的'绿'有人味）"]},"边界":"须有人的特征（笑/哭/说话）；'像人一样'是比喻不是拟人；拟人+比喻可兼格（'他像小老虎一样扑来'）","覆盖已确认":["拟"],"覆盖缺失":["方式"]},"前置知识":["名词","动词"]},{"name":"夸张","例子":["白发三千丈","教室里安静得连针掉地上都听得见","他跑得比风还快。","这间屋子大得能装下一头大象。","我饿得能吃下一头牛。","教室里静得连针掉在地上都听得见。","他高兴得一蹦三尺高。","飞流直下三千尺，疑是银河落九天。","白发三千丈，缘愁似个长。","这道题难得比登天还难。","他气得火冒三丈。","操场上的人山人海一眼望不到边。","教室里静得连针掉地上都听得见。（合理夸张，突出安静）","他一顿能吃三百个馒头。（过度夸张，失真）"],"口诀":"突出强调","易错":"夸张要合理，不能失真","讲解":"故意夸大或缩小","深讲":"夸张是故意夸大或缩小：把事物说得比实际更大、更小、更多、更少，用来突出强调；夸张要合理，不能失真，让人一听就知道是夸张，不是真的。","分类":[{"类":"扩大夸张","说明":"把事物说得比实际大得多。","代表":"三千丈、飞流直下","例子":["白发三千丈。"]},{"类":"缩小夸张","说明":"把事物说得比实际小得多。","代表":"巴掌大、一根针","例子":["教室只有巴掌大。"]}],"怎么认":["句子里的数目、程度是不是大得或小得不可能？是的。","去掉夸张，事物本身还成立吗？成立，只是没那么突出。","作者是不是在强调、突出？是的。"],"辨析":"夸张和说谎不一样：夸张是故意夸大、让人一听就知道是夸张（白发三千丈）；说谎是想让人当真。夸张要合理，不能失真。","例句解析":[{"句":"白发三千丈。","析":"白发不可能真有三千丈，是扩大夸张，突出愁得多。"},{"句":"教室里安静得连针掉地上都听得见。","析":"安静被夸大到针掉地上都听得见，是扩大夸张。"}],"练习":[{"q":"下面哪个是夸张？","options":["天上的云像棉花糖","白发三千丈","小草向我点头","他跑得很快"],"answer":1,"解析":"白发不可能真有三千丈，是夸张。","类":"扩大夸张"},{"q":"“教室只有巴掌大”属于？","options":["扩大夸张","缩小夸张","比喻","拟人"],"answer":1,"解析":"教室被说得比实际小得多，是缩小夸张。","类":"缩小夸张"},{"q":"夸张要？","options":["让人当真","合理，不能失真","越大越好","越小越好"],"answer":1,"解析":"夸张要合理，不能失真。","类":"扩大夸张"}],"类比":"夸张像拿<b>放大镜</b>看东西：白发三千丈。故意说大说小，让印象更深刻。","图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">白发三千丈</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">说大：头发哪有三千丈</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">静得针掉都听见</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">说小：突出安静</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">飞流直下三千尺</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">李白：瀑布夸成银河</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">夸张=放大镜：故意说大说小，印象深刻<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"故意夸大或缩小，突出特征","可变":{"方向":["夸大（飞流直下三千尺）","缩小（针尖大的地方）","超前（未饮先醉）"],"程度":["合理夸张（突出）","过度（失真就成病句）"]},"边界":"夸张须有度（'三千尺'是夸张，'三万尺'就离谱）；与比喻区别：夸张是数量/程度，喻是类比；'非常/极'是程度副词不是夸张","覆盖已确认":["方向"],"覆盖缺失":["程度"]},"前置知识":[]},{"name":"排比","例子":["爱心是春风，是夏雨，是秋月","春天是花朵，是绿叶，是暖阳","读书使人充实，讨论使人机智，写作使人精确。","爱心是一盏灯，照亮别人，也温暖自己；爱心是一首歌，唱出希望，也带来快乐。","春天来了，花儿开了，草儿绿了，鸟儿叫了。","他爱学习，爱劳动，爱帮助人。","我们要讲文明，讲礼貌，讲卫生。","海是蓝的，天是蓝的，人的心也应该是蓝的。","理想是灯，照亮夜行的路；理想是火，点燃熄灭的灯。","红的花，绿的草，高大的树，构成了一幅美景。","学习要专心，吃饭要专心，做事要专心。","燕子去了，有再来的时候；杨柳枯了，有再青的时候。","我爱祖国，我爱人民，我爱家乡。（句排比）","盼望着，盼望着，东风来了，春天的脚步近了。（段排比）","爱学习，爱劳动，爱运动。（结构相同）","他性格开朗，她待人热情，他做事认真。（结构相似）"],"口诀":"增强气势","易错":"排比项数一般三项以上","讲解":"三个以上结构相似的句子","深讲":"排比是由三个或三个以上结构相同或相似、语气一致的短语或句子排列在一起，用来增强气势；排比项一般三项以上，少了就不成排比。","分类":[{"类":"句子排比","说明":"由三个以上结构相同的句子组成。","代表":"是……，是……，是……","例子":["爱心是春风，是夏雨，是秋月。"]},{"类":"短语排比","说明":"由三个以上结构相同的短语组成。","代表":"又高、又壮、又结实","例子":["他长得又高、又壮、又结实。"]}],"怎么认":["有没有三个以上结构相同的短语或句子？有。","它们的语气是不是一致的？是的。","读起来是不是气势越来越强？是的。"],"辨析":"排比和反复的区别：排比是结构相同、内容不同（春风、夏雨、秋月）；反复是同一内容重复（盼望着，盼望着）。看内容是不是换了。","例句解析":[{"句":"爱心是春风，是夏雨，是秋月。","析":"三个句子结构相同，语气一致，是句子排比。"},{"句":"春天是花朵，是绿叶，是暖阳。","析":"三个句子结构相同，是句子排比。"}],"练习":[{"q":"下面哪个是排比？","options":["盼望着，盼望着，春天来了","爱心是春风，是夏雨，是秋月","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"三个句子结构相同，是排比；盼望着是反复。","类":"句子排比"},{"q":"排比项数一般？","options":["一项","两项","三项以上","不限"],"answer":2,"解析":"排比项数一般三项以上。","类":"句子排比"},{"q":"“他长得又高、又壮、又结实”属于？","options":["句子排比","短语排比","反复","对偶"],"answer":1,"解析":"三个结构相同的短语排列，是短语排比。","类":"短语排比"}],"类比":"排比像<b>台阶一级一级往上</b>：山是高大的，水是清澈的，天是蔚蓝的。结构相同，气势叠加。","图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">爱心是春风</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">第一级台阶</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">爱心是夏雨</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">第二级台阶</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">爱心是秋月</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">第三级台阶</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">排比=台阶一级级往上：结构相同，气势叠加<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"三个以上结构相同/相似的句子并列，气势强","可变":{"类型":["句排比（爱…爱…爱…）","段排比"],"结构":["相同（我爱…我爱…）","相似（有人…有人…）"]},"边界":"须三项以上（两项是对偶）；结构须一致（'爱祖国、爱人民、爱劳动'✓）；与反复区别：反复是同一词语重复，排比是结构重复","覆盖已确认":[],"覆盖缺失":["类型","结构"]},"前置知识":["主谓式"]},{"name":"对偶","例子":["横眉冷对千夫指，俯首甘为孺子牛","书山有路勤为径，学海无涯苦作舟","明月松间照，清泉石上流。","两个黄鹂鸣翠柳，一行白鹭上青天。","海内存知己，天涯若比邻。","感时花溅泪，恨别鸟惊心。","春种一粒粟，秋收万颗子。","大漠孤烟直，长河落日圆。","几处早莺争暖树，谁家新燕啄春泥。","白日依山尽，黄河入海流。","野火烧不尽，春风吹又生。","举头望明月，低头思故乡。","海内存知己，天涯若比邻。（工对：词性相对工整）","春种一粒粟，秋收万颗子。（宽对：大意相对）"],"口诀":"整齐凝练","易错":"对偶要求平仄相对（宽对可放宽）","讲解":"字数相等、结构相同、意义相关","深讲":"用来显得整齐凝练；对偶是两句，排比是三句以上，不要混。","分类":[{"类":"正对","说明":"上下句意思相近、互补。","代表":"书山有路勤为径，学海无涯苦作舟","例子":["书山有路勤为径，学海无涯苦作舟。"]},{"类":"反对","说明":"上下句意思相反、相对。","代表":"横眉冷对千夫指，俯首甘为孺子牛","例子":["横眉冷对千夫指，俯首甘为孺子牛。"]},{"类":"流水对","说明":"上下句意思连贯、承接，像流水一样。","代表":"欲穷千里目，更上一层楼","例子":["欲穷千里目，更上一层楼。"]}],"怎么认":["是不是两个句子？是的。","字数是不是相等、结构是不是相同？是的。","上下句意思是不是相关（相近、相反或承接）？是的。"],"辨析":"对偶和排比的区别：对偶是两句，字数相等、结构相同；排比是三句以上，结构相同、语气一致。数一数有几句，再看字数是不是相等。","例句解析":[{"句":"横眉冷对千夫指，俯首甘为孺子牛。","析":"两句字数相等、结构相同，意思相反，是反对。"},{"句":"书山有路勤为径，学海无涯苦作舟。","析":"两句字数相等、结构相同，意思相近互补，是正对。"}],"练习":[{"q":"下面哪个是对偶？","options":["爱心是春风，是夏雨，是秋月","横眉冷对千夫指，俯首甘为孺子牛","盼望着，盼望着，春天来了","天上的云像棉花糖"],"answer":1,"解析":"两句字数相等、结构相同、意思相反，是对偶。","类":"反对"},{"q":"对偶是几句？","options":["一句","两句","三句以上","不限"],"answer":1,"解析":"对偶是两个句子相对成文。","类":"正对"},{"q":"“欲穷千里目，更上一层楼”属于？","options":["正对","反对","流水对","排比"],"answer":2,"解析":"上下句意思连贯承接，是流水对。","类":"流水对"}],"类比":"对偶像<b>对联的两边</b>：明月松间照，清泉石上流。字数相等，意思相对，工工整整。","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">明月松间照</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">上联</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">清泉石上流</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">下联：字数相等，意思相对</text></g><text x=\"320\" y=\"160\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">对偶=对联两边：工工整整<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"1.9s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"两句字数相等、结构相同、意思相关","可变":{"类型":["正对（意思相近：海内存知己，天涯若比邻）","反对（意思相反：横眉冷对千夫指，俯首甘为孺子牛）","串对（承接：才饮长江水，又食武昌鱼）"],"工整":["工对（词性相对）","宽对（大意相对）"]},"边界":"须两句（多句是排比）；字数须相等；与对联区别：对联是应用，对偶是修辞；'对仗'是格律术语，指律诗中的对偶","覆盖已确认":["类型"],"覆盖缺失":["工整"]},"前置知识":["名词","动词","形容词"]},{"name":"反复","例子":["盼望着，盼望着，春天来了","加油，加油，我们一定能赢！","盼望着，盼望着，东风来了，春天的脚步近了。","大山无言，小草无言，土地无言。","他说好，好，好，就这么办。","沉默啊，沉默啊，不在沉默中爆发，就在沉默中灭亡。","我们是光荣的少先队员，我们是祖国的未来。","学，学，再学；练，练，再练。","风啊，你轻轻地吹吧，吹吧。","走啊走啊，终于走到了山顶。","他笑了，笑了，开心地笑了。","雨，下吧，下吧，滋润干渴的大地吧。","盼望着，盼望着，春天来了。（词语反复：'盼望着'）","他说得对，他说得对极了。（句子反复）"],"口诀":"强调加深","易错":"与排比区别：反复是重复同一内容","讲解":"重复词语/句子强调","深讲":"反复是重复词语或句子，用来强调、加深印象；反复重复的是同一内容，排比换的是内容，不要混。","分类":[{"类":"词语反复","说明":"重复同一个词语。","代表":"盼望着，盼望着","例子":["盼望着，盼望着，春天来了。"]},{"类":"句子反复","说明":"重复同一个句子。","代表":"春天来了！春天来了！","例子":["春天来了！春天来了！花儿都开了。"]}],"怎么认":["有没有同一个词语或句子重复出现？有。","重复是不是为了强调？是的。","去掉重复，意思还在吗？在，只是强调弱了。"],"辨析":"反复和排比的区别：反复是同一内容重复（盼望着，盼望着），排比是结构相同、内容不同（春风、夏雨、秋月）。看重复的是不是同一个内容。","例句解析":[{"句":"盼望着，盼望着，春天来了。","析":"盼望着重复出现，是词语反复，用来强调盼望。"},{"句":"加油，加油，我们一定能赢！","析":"加油重复出现，是词语反复，用来强调鼓励。"}],"练习":[{"q":"下面哪个是反复？","options":["爱心是春风，是夏雨，是秋月","盼望着，盼望着，春天来了","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"盼望着重复，是反复；春风夏雨秋月是排比。","类":"词语反复"},{"q":"反复和排比的区别是？","options":["反复换内容，排比重复内容","反复重复同一内容，排比换内容","没有区别","反复是两句"],"answer":1,"解析":"反复重复同一内容，排比结构相同、内容不同。","类":"词语反复"},{"q":"“春天来了！春天来了！花儿都开了”属于？","options":["词语反复","句子反复","排比","对偶"],"answer":1,"解析":"同一个句子重复出现，是句子反复。","类":"句子反复"}],"类比":"反复像<b>敲鼓重击</b>：盼望着，盼望着。重要的话说两遍，感情更浓。","图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">盼望着</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">第一遍</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">盼望着</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">第二遍：重要的说两遍</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">春天来了</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">感情更浓</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">反复=敲鼓重击：重要的话说两遍<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"同一词语/句子重复出现，强调感情","可变":{"类型":["连续反复（盼望着，盼望着）","间隔反复（……啊，……啊）"],"重复":["词语（大山啊，大山啊）","句子"]},"边界":"须有强调意图（无意的重复是啰嗦）；与排比区别：反复是词语重复，排比是结构重复；与叠词区别：叠词是构词（红红的），反复是修辞","覆盖已确认":["类型"],"覆盖缺失":["重复"]},"前置知识":[]},{"name":"设问","例子":["是谁创造了世界？是我们劳动群众","谁是班上跑得最快的？是小明","是谁创造了人类世界？是我们劳动群众。","什么叫自律？自律就是自我约束、自我管理。","幸福是什么？幸福是帮助别人后的快乐。","谁是最可爱的人？是我们的战士。","怎样才能学好语文？多读、多写、多思考。","什么是勇敢？勇敢不是不害怕，而是害怕也向前。","春天在哪里？春天在枝头，在花间，在人们的心里。","为什么要读书？因为书是进步的阶梯。","谁言寸草心，报得三春晖？是说子女难报父母恩。","学而不思则罔，思而不学则殆，是什么意思？是说只学不想、只想不学都不行。","什么是幸福？是清晨的一缕阳光，是家人的一句问候，是朋友的一个微笑。（问一句，答多句）","谁是最可爱的人？是医生，是老师，是每一个平凡岗位上的劳动者。（问一句，答多句）"],"口诀":"引起注意","易错":"设问后一定要回答","讲解":"自问自答","深讲":"设问是自问自答：先提出问题，再自己回答，用来引起注意、引出下文；设问后一定要回答，不回答就不是设问。","分类":[{"类":"句首设问","说明":"在开头提问，引起注意。","代表":"是谁……？是……","例子":["是谁创造了世界？是我们劳动群众。"]},{"类":"句中设问","说明":"在中间提问，引出下文。","代表":"……是什么？……是……","例子":["祖国是什么？祖国是我们的家。"]}],"怎么认":["是不是先问后答？是的。","问句后面有没有回答？有，才是设问。","提问是不是为了引起注意、引出下文？是的。"],"辨析":"设问和反问的区别：设问自问自答（是谁创造了世界？是我们劳动群众）；反问不回答，答案隐含在问句里（这不是很清楚吗？）。看后面有没有回答。","例句解析":[{"句":"是谁创造了世界？是我们劳动群众。","析":"先问是谁创造了世界，再回答是劳动群众，是设问。"},{"句":"谁是班上跑得最快的？是小明。","析":"先问谁最快，再回答是小明，是设问。"}],"练习":[{"q":"下面哪个是设问？","options":["这不是很清楚吗？","是谁创造了世界？是我们劳动群众","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"自问自答，是设问；这不是很清楚吗是反问。","类":"句首设问"},{"q":"设问后一定要？","options":["不回答","回答","再问一次","换话题"],"answer":1,"解析":"设问后一定要回答。","类":"句首设问"},{"q":"“祖国是什么？祖国是我们的家”属于？","options":["句首设问","句中设问","反问","排比"],"answer":1,"解析":"在中间提问引出下文，是句中设问。","类":"句中设问"}],"类比":"设问像<b>自问自答</b>：是谁创造了人类世界？是我们劳动群众。先抛问题，再给答案，引起注意。","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">是谁创造了世界？</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">先抛问题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">是我们劳动群众</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">再给答案</text></g><text x=\"320\" y=\"160\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">设问=自问自答：引起注意<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"1.9s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"自问自答，引起注意","可变":{"形式":["问一句答一句（谁是最可爱的人？是战士）","问多句答一句"],"作用":["引起注意","突出强调","承上启下"]},"边界":"须自问自答（只问不答是疑问句）；与反问区别：设问有答案，反问答案在问中（'难道不是吗？'=是的）；问号后须有答句","覆盖已确认":[],"覆盖缺失":["形式","作用"]},"前置知识":[]},{"name":"反问","例子":["这不是很清楚吗？","这么简单的题，你不会做吗？","难道我们不该好好学习吗？","这么冷的天，你怎么能穿这么少？","这件事难道不是他做的吗？","浪费粮食，难道不觉得可惜吗？","这么好的机会，怎能错过？","诚信是做人之本，难道不应该坚守吗？","你自己不努力，难道还怪别人？","这么简单的题，难道你不会做？","父母为我们付出这么多，难道不值得感恩吗？","现在不努力，更待何时？","难道他不知道吗？（形式：'难道…吗'）","你怎能半途而废？（形式：'怎能'）","这难道不是你的错吗？（表肯定：是你的错）","我怎么会骗你呢？（表否定：不会骗你）"],"口诀":"加强语气","易错":"反问后不回答，答案隐含其中","讲解":"用问句表肯定/否定，加强语气","深讲":"反问是用问句表示肯定或否定，用来加强语气；反问后不回答，答案隐含在问句里，听的人一听就明白。","分类":[{"类":"肯定式反问","说明":"用否定问句表示肯定。","代表":"不是……吗？","例子":["这不是很清楚吗？"]},{"类":"否定式反问","说明":"用肯定问句表示否定。","代表":"……吗？（表否定）","例子":["这么简单的题，你不会做吗？"]}],"怎么认":["是不是问句形式，但意思不是真的在问？是的。","问句后面有没有回答？没有，答案隐含其中。","把问句换成陈述句，意思是不是更直接？是的，说明是反问。"],"辨析":"反问和设问的区别：反问不回答（这不是很清楚吗？答案就是很清楚），设问自问自答（是谁创造了世界？是我们劳动群众）。看后面有没有回答。","例句解析":[{"句":"这不是很清楚吗？","析":"用否定问句表示肯定：很清楚，是反问。"},{"句":"这么简单的题，你不会做吗？","析":"用肯定问句表示否定：你应该会做，是反问。"}],"练习":[{"q":"下面哪个是反问？","options":["是谁创造了世界？是我们劳动群众","这不是很清楚吗？","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"不回答，答案隐含其中，是反问。","类":"肯定式反问"},{"q":"“这么简单的题，你不会做吗？”的意思是？","options":["你不会做","你应该会做","题很难","不知道"],"answer":1,"解析":"用肯定问句表示否定：你应该会做。","类":"否定式反问"},{"q":"反问后要不要回答？","options":["要","不要，答案隐含其中","有时要","看情况"],"answer":1,"解析":"反问后不回答，答案隐含在问句里。","类":"肯定式反问"}],"类比":"反问像<b>明知故问</b>：难道这不是奇迹吗？用问句表达肯定的意思，语气更强烈。","图示":"<svg viewBox=\"0 0 640 280\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g id=\"wrongG\"><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"20\" fill=\"#b85a52\">这么简单的题你不会做。</text><text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">✘ 陈述句：语气平淡</text><animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-5,0;5,0;-5,0;0,0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/><animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.5s\" begin=\"1.5s\" fill=\"freeze\"/></g><text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"32\" fill=\"#4a7a59\" opacity=\"0\">✓<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/></text><text x=\"320\" y=\"200\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">这么简单的题，你不会做吗？<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.2s\" fill=\"freeze\"/></text><text x=\"320\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">反问=明知故问，用问句表肯定，语气更强烈<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.6s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"用疑问形式表肯定/否定，答案在问中，语气强","可变":{"形式":["用'难道/岂'（难道这不是吗？）","用'怎么/怎能'（怎能忘记？）"],"表意":["肯定（难道不是=是）","否定（怎能=不能）"]},"边界":"答案自明，不需回答；与设问区别：反问无答句，设问有答句；'吗'结尾多是真疑问（'好吗？'），反问多用'呢/吧/难道'","覆盖已确认":[],"覆盖缺失":["形式","表意"]},"前置知识":["设问"]}],"name":"常见修辞格（8种）"},{"id":"bingju","items":[{"name":"语序不当","图示":"<svg viewBox=\"0 0 640 280\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g id=\"wrongG\"><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"20\" fill=\"#b85a52\">一位优秀的我们班的学生</text><text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">✘ 病句</text><animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-5,0;5,0;-5,0;0,0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/><animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.5s\" begin=\"1.5s\" fill=\"freeze\"/></g><text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"32\" fill=\"#4a7a59\" opacity=\"0\">✓<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/></text><text x=\"320\" y=\"200\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">我们班的一位优秀的学生<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.2s\" fill=\"freeze\"/></text><text x=\"320\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">词语或分句顺序颠倒<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.6s\" fill=\"freeze\"/></text></svg>","例子":["病：他把教室打扫得干干净净、整整齐齐→改：把“整整齐齐”删去或调整","病：我昨天晚上把作业认真地写完了 → 改：我昨天晚上认真地把作业写完了","病：他把教室打扫得干干净净、整整齐齐→改：删去“整整齐齐”或改为“把教室打扫得干干净净”","病：一位优秀的我们班的学生→改：我们班的一位优秀的学生","病：他经常回忆起过去的往事→改：删去“过去”，“往事”已含过去义","病：我们要认真克服并发现缺点→改：我们要发现并认真克服缺点","病：他把一封信寄给我妈妈的→改：他把一封信寄给了我妈妈","病：同学们把校园打扫得整整齐齐、干干净净→改：删去重复义词语，留“干干净净”","病：他先把门关上，然后轻轻地→改：他轻轻地把门关上，然后离开"],"口诀":"先找主干，再看修饰","易错":"多重定语/状语语序是重灾区","讲解":"词语或分句顺序颠倒","深讲":"语序不当是词语或分句顺序颠倒：先找主干，再看修饰；多重定语、状语是重灾区。改法是：一读句子，二找主干，三看修饰语顺序，四调换位置。","分类":[{"类":"定语语序不当","说明":"多重定语排列顺序错了。","代表":"领属＋数量＋形容词＋名词","例子":["一位优秀的我们班的学生。"]},{"类":"状语语序不当","说明":"状语放错了位置。","代表":"时间＋认真地＋把＋作业","例子":["我昨天晚上把作业认真地写完了。"]}],"怎么认":["先压缩主干，看主谓宾齐不齐？齐。","再看修饰语：定语、状语的顺序对不对？不对。","调换修饰语位置，句子是不是顺了？顺了，说明是语序不当。"],"辨析":"语序不当和结构混乱的区别：语序不当是顺序颠倒，调换位置就顺了；结构混乱是两种句式纠缠，要删掉一种句式。看调换位置能不能修好。","例句解析":[{"句":"一位优秀的我们班的学生。","析":"领属定语我们班应在最前，改为：我们班的一位优秀的学生。"},{"句":"我昨天晚上把作业认真地写完了。","析":"状语认真地应在把字前，改为：我昨天晚上认真地把作业写完了。"}],"练习":[{"q":"“一位优秀的我们班的学生”错在哪？","options":["缺主语","定语语序不当","搭配不当","表意不明"],"answer":1,"解析":"领属定语我们班应在最前。","类":"定语语序不当"},{"q":"“我昨天晚上把作业认真地写完了”怎么改？","options":["我昨天晚上把作业写完了认真地","我昨天晚上认真地把作业写完了","我把作业昨天晚上认真地写完了","我昨天晚上把认真地作业写完了"],"answer":1,"解析":"状语认真地应在把字前。","类":"状语语序不当"},{"q":"多重定语的正确顺序是？","options":["形容词＋领属＋数量＋名词","领属＋数量＋形容词＋名词","数量＋形容词＋领属＋名词","名词＋领属＋数量＋形容词"],"answer":1,"解析":"领属在最前，再是数量、形容词，最后是名词。","类":"定语语序不当"}],"类比":"语序不当就像\"穿反了衣服\"：每件都在，但位置错了。","决策树":"①压缩主干：主谓宾齐吗？→不齐：不是语序问题，转查成分残缺→②齐：看修饰语——定语在名词前吗？→不在：移到名词前，顺了吗？→顺了：定语语序不当→③状语在动词前吗？→不在：移到动词前→顺了：状语语序不当→④分句顺序符合逻辑先后吗？→否：调换分句","前置知识":["定语","状语"]},{"name":"搭配不当","图示":"<svg viewBox=\"0 0 640 280\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g id=\"wrongG\"><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"20\" fill=\"#b85a52\">他怀着崇高的心情</text><text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">✘ 病句</text><animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-5,0;5,0;-5,0;0,0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/><animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.5s\" begin=\"1.5s\" fill=\"freeze\"/></g><text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"32\" fill=\"#4a7a59\" opacity=\"0\">✓<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/></text><text x=\"320\" y=\"200\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">怀着激动的心情<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.2s\" fill=\"freeze\"/></text><text x=\"320\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">崇高不配心情，改激动<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.6s\" fill=\"freeze\"/></text></svg>","例子":["病：他怀着崇高的心情→改：怀着激动的心情","病：同学们都很爱护 → 改：同学们都很爱护公物","病：他的普通话说得很标准→改：他的普通话说得很流利（标准与“说”不搭配）","病：我们要养成良好的学习态度→改：养成良好的学习习惯（养成与习惯搭配）","病：他对自己很有信心，学习成绩很优异→改：删去“很优异”或改为“学习成绩优异”","病：经过努力，他的错别字大大进步了→改：错别字大大减少了（进步与减少搭配）","病：我们要端正学习目的→改：端正学习态度（端正与态度搭配）","病：他的写作水平有了很大的提高→改：正确（示例：提高与水平搭配恰当）","病：同学们都认真地完成了作业→改：正确（完成与作业搭配恰当）","病：他发扬了艰苦奋斗的精神→改：正确（发扬与精神搭配恰当）"],"口诀":"主谓动宾，一一对应","易错":"“怀着……心情”不能配“崇高”","讲解":"主谓、动宾、修饰语与中心词不搭配","深讲":"搭配不当是主谓、动宾、修饰语与中心词对不上号：主谓动宾一一对应，修饰语也要配中心词。改法是：压缩主干，检查每一对搭配。","分类":[{"类":"主谓搭配不当","说明":"主语和谓语对不上号。","代表":"人口是国家","例子":["我国的人口是世界上最多的国家。"]},{"类":"动宾搭配不当","说明":"动词和宾语对不上号。","代表":"端正学习","例子":["我们要端正学习。"]},{"类":"修饰搭配不当","说明":"修饰语和中心词对不上号。","代表":"怀着崇高的心情","例子":["他怀着崇高的心情。"]}],"怎么认":["压缩主干，主谓宾齐不齐？齐。","主语配谓语、动词配宾语、修饰语配中心词，一一检查。","有一对对不上，就是搭配不当。"],"辨析":"搭配不当和成分残缺的区别：搭配不当是成分齐了但配错了（端正学习）；成分残缺是成分缺了（同学们都很爱护，缺宾语）。看成分齐不齐。","例句解析":[{"句":"他怀着崇高的心情。","析":"崇高配精神、理想，不配心情，改为：怀着激动的心情。"},{"句":"我国的人口是世界上最多的国家。","析":"人口不能是国家，改为：我国是世界上人口最多的国家。"}],"练习":[{"q":"“他怀着崇高的心情”错在哪？","options":["缺宾语","修饰搭配不当","语序不当","表意不明"],"answer":1,"解析":"崇高不配心情，应配激动的心情。","类":"修饰搭配不当"},{"q":"“我们要端正学习”怎么改？","options":["我们要端正学习态度","我们要学习端正","我们要端正地学习","我们要学习"],"answer":0,"解析":"端正配态度，不配学习。","类":"动宾搭配不当"},{"q":"“我国的人口是世界上最多的国家”错在哪？","options":["动宾搭配不当","主谓搭配不当","语序不当","结构混乱"],"answer":1,"解析":"人口不能是国家，改为：我国是世界上人口最多的国家。","类":"主谓搭配不当"}],"类比":"搭配不当就像\"左脚穿右脚的鞋\"：单个看都对，放一起别扭。","决策树":"①压缩主干：主谓宾齐吗？→不齐：先查残缺→②齐：一一配对——主语配谓语，语义通吗？→不通：主谓搭配不当，换谓语→③动词配宾语，语义通吗？→不通：动宾搭配不当，换动词或宾语→④修饰语配中心词，通吗？→不通：修饰搭配不当→⑤全通：不是搭配问题","前置知识":["主语","谓语","宾语","定语"]},{"name":"成分残缺或赘余","图示":"<svg viewBox=\"0 0 640 280\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g id=\"wrongG\"><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"20\" fill=\"#b85a52\">看了这部电影，受到了深刻的教育</text><text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">✘ 病句</text><animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-5,0;5,0;-5,0;0,0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/><animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.5s\" begin=\"1.5s\" fill=\"freeze\"/></g><text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"32\" fill=\"#4a7a59\" opacity=\"0\">✓<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/></text><text x=\"320\" y=\"200\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">我看了这部电影，受到了深刻的教育<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.2s\" fill=\"freeze\"/></text><text x=\"320\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">缺主/谓/宾，或词语重复多余<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.6s\" fill=\"freeze\"/></text></svg>","例子":["病：通过学习，使我进步（缺主语）→删“使”","病：不约而同异口同声（赘余）","病：通过努力，取得了进步 → 改：通过努力，我取得了进步","病：看了这部电影，受到了深刻的教育→改：我看了这部电影，受到了深刻的教育（缺主语）","病：通过这次活动，使我明白了道理→改：这次活动使我明白了道理（删“通过”或“使”）","病：他把今天的任务→改：他把今天的任务完成了（缺谓语）","病：我们要学习雷锋同志全心全意为人民服务的→改：我们要学习雷锋同志全心全意为人民服务的精神（缺宾语）","病：他非常非常特别的高兴→改：他非常高兴（“非常非常特别”赘余）","病：大约有三百多人参加了会议→改：有三百多人参加了会议（“大约”与“多”重复）","病：他亲眼目睹了这件事的经过→改：他目睹了这件事的经过（“亲眼”与“目睹”重复）"],"口诀":"压缩主干，残缺立现","易错":"“通过……使”句式最易缺主语","讲解":"缺主/谓/宾，或词语重复多余","深讲":"成分残缺或赘余是缺主、谓、宾，或词语重复多余：压缩主干，残缺立现；意思重复，赘余立现。改法是：缺了补上，多了删去。","分类":[{"类":"主语残缺式","说明":"缺主语，话没了头。","代表":"通过……使……","例子":["通过学习，使我进步。"]},{"类":"宾语残缺式","说明":"缺宾语，动作没着落。","代表":"爱护后空着","例子":["同学们都很爱护。"]},{"类":"成分赘余式","说明":"词语意思重复，多余。","代表":"不约而同异口同声","例子":["不约而同异口同声。"]}],"怎么认":["压缩主干，主谓宾齐不齐？不齐，就是残缺。","有没有意思重复的词？有，就是赘余。","“通过……使……”句式最易缺主语，重点查。"],"辨析":"成分残缺和搭配不当的区别：残缺是缺了成分（通过学习，使我进步，缺主语）；搭配不当是成分齐了但配错了（端正学习）。看成分齐不齐。","例句解析":[{"句":"通过学习，使我进步。","析":"通过和使同时出现，主语被吃掉，删去使。"},{"句":"不约而同异口同声。","析":"不约而同和异口同声意思重复，删去一个。"}],"练习":[{"q":"“通过学习，使我进步”错在哪？","options":["搭配不当","主语残缺","语序不当","表意不明"],"answer":1,"解析":"通过和使同时出现，主语被吃掉。","类":"主语残缺式"},{"q":"“不约而同异口同声”错在哪？","options":["缺主语","缺宾语","成分赘余","结构混乱"],"answer":2,"解析":"两个词意思重复，多余。","类":"成分赘余式"},{"q":"“通过努力，取得了进步”怎么改？","options":["通过努力，使取得了进步","通过努力，我取得了进步","努力，取得了进步","通过努力，进步取得了"],"answer":1,"解析":"补上主语我。","类":"主语残缺式"}],"决策树":"①压缩主干：主/谓/宾缺吗？→缺：成分残缺，补上所缺→②齐：看句式——有\"通过/经过/由于……使/让\"吗？→有：删\"使/让\"或补主语→③有意思重复的词吗？→有：成分赘余，删一留一→④无：成分完整，查别类","前置知识":["主语","谓语","宾语"]},{"name":"结构混乱","图示":"<svg viewBox=\"0 0 640 280\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g id=\"wrongG\"><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"20\" fill=\"#b85a52\">原因是由于他努力</text><text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">✘ 病句</text><animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-5,0;5,0;-5,0;0,0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/><animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.5s\" begin=\"1.5s\" fill=\"freeze\"/></g><text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"32\" fill=\"#4a7a59\" opacity=\"0\">✓<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/></text><text x=\"320\" y=\"200\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">原因是他努力<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.2s\" fill=\"freeze\"/></text><text x=\"320\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">原因和由于重复，删一个<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.6s\" fill=\"freeze\"/></text></svg>","例子":["病：原因是由于他努力→改：原因是他努力","病：这次活动是受到了大家的欢迎造成的 → 改：这次活动受到了大家的欢迎","病：我们来到山间，听见鸟叫，看见花开，感到心旷神怡的原因是景色太美了→改：我们来到山间，听见鸟叫，看见花开，感到心旷神怡（删“的原因是…”）","病：他的写作水平有了很大的提高是勤奋的结果→改：他的写作水平有了很大提高，这是勤奋的结果","病：这部电影，我看了三遍，很受感动的原因是剧情真实→改：这部电影我看了三遍，很受感动，因为剧情真实","病：老师对我们要求很严格是希望我们成才→改：老师对我们要求很严格，是希望我们成才","病：他之所以成功，是因为努力的结果→改：他之所以成功，是因为努力（删“的结果”）","病：问题的关键在于态度是否端正上→改：问题的关键在于态度是否端正（删“上”）","病：这件事的成败，在于大家齐心协力与否是关键→改：这件事的成败，在于大家是否齐心协力","病：关于这个问题，我的看法是认为应该慎重→改：关于这个问题，我认为应该慎重（删“的看法是”）"],"口诀":"两种句式，留一去一","易错":"“原因是由于”“是由于……造成的”典型杂糅","讲解":"句式杂糅，两种结构纠缠","深讲":"结构混乱是句式杂糅：两种结构纠缠在一起。改法是：两种句式，留一去一，认清一句话只能用一种结构。","分类":[{"类":"原因是由于式","说明":"原因和由于重复用了。","代表":"原因是由于……","例子":["原因是由于他努力。"]},{"类":"是……造成的式","说明":"是和受到……造成的纠缠。","代表":"是受到了……造成的","例子":["这次活动是受到了大家的欢迎造成的。"]}],"怎么认":["一句话里有没有两种句式？有。","删掉一种，句子是不是顺了？顺了。","“原因是由于”“是由于……造成的”是典型杂糅，重点查。"],"辨析":"结构混乱和语序不当的区别：结构混乱是两种句式纠缠，要删一种；语序不当是顺序颠倒，调换位置就好。看删能不能修好。","例句解析":[{"句":"原因是由于他努力。","析":"原因和由于重复，改为：原因是他努力。"},{"句":"这次活动是受到了大家的欢迎造成的。","析":"是……造成的和受到了……纠缠，改为：这次活动受到了大家的欢迎。"}],"练习":[{"q":"“原因是由于他努力”怎么改？","options":["原因是由于他努力的","原因是他努力","由于是他努力","原因是他努力的由于"],"answer":1,"解析":"原因和由于留一个。","类":"原因是由于式"},{"q":"“这次活动是受到了大家的欢迎造成的”错在哪？","options":["语序不当","结构混乱","搭配不当","表意不明"],"answer":1,"解析":"两种句式纠缠，删一种。","类":"是……造成的式"},{"q":"句式杂糅的改法是？","options":["调换位置","留一去一","补上成分","换关联词"],"answer":1,"解析":"两种句式，留一去一。","类":"原因是由于式"}],"决策树":"①一句中有两套主谓吗？→有：句式杂糅，拆成两句或删一套→②前半说A、后半说B（中途易辙）吗？→是：前后分开各成一句→③暗换主语了吗？→是：补出后句主语或拆句→④否：结构没问题，查别类","前置知识":["主语","谓语","并列复句"]},{"name":"表意不明","图示":"<svg viewBox=\"0 0 640 280\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g id=\"wrongG\"><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"20\" fill=\"#b85a52\">数理化学习经验</text><text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">✘ 病句</text><animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-5,0;5,0;-5,0;0,0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/><animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.5s\" begin=\"1.5s\" fill=\"freeze\"/></g><text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"32\" fill=\"#4a7a59\" opacity=\"0\">✓<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/></text><text x=\"320\" y=\"200\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">数理化的学习经验<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.2s\" fill=\"freeze\"/></text><text x=\"320\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">歧义或指代不清<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.6s\" fill=\"freeze\"/></text></svg>","例子":["病：他背着总经理和副总喝酒（谁喝？）","病：小红的妈妈说她病了（谁病了？）","病：他背着总经理去开会→改：总经理背着他去开会（或：他陪总经理去开会），消除歧义","病：数理化学习经验→改：数理化的学习经验（加“的”消除歧义）","病：鸡不吃了→改：鸡不吃食了（或：这只鸡不吃了），说清主语","病：我想起来了→改：我想起这件事了（说清宾语）","病：开刀的是他父亲→改：给他开刀的是他父亲的同事（说清施事）","病：这辆车没有锁→改：这辆车没有上锁（说清“锁”的含义）","病：他在火车上写字→改：他在火车上写了一封信（补宾语）","病：雨天没有晴天多→改：下雨天没有晴天多（说清比较对象）"],"口诀":"代词指代要明确","易错":"多重定语易生歧义","讲解":"歧义或指代不清","深讲":"表意不明是歧义或指代不清：代词指代要明确，多重定语易生歧义。改法是：代词换成名字，歧义的句子拆开说。","分类":[{"类":"代词指代不明","说明":"代词不知道指谁。","代表":"她病了（谁？）","例子":["小红的妈妈说她病了。"]},{"类":"句子歧义","说明":"一句话有两种理解。","代表":"背着……喝酒（谁喝？）","例子":["他背着总经理和副总喝酒。"]}],"怎么认":["句子里的代词（他、她、它）指谁？说不清，就是指代不明。","一句话能不能有两种理解？能，就是歧义。","两个人以上时，少用他，直接叫名字。"],"辨析":"表意不明和不合逻辑的区别：表意不明是意思说不清（谁病了？）；不合逻辑是意思说得清但不合理（七点起床，六点半出门）。看意思清不清。","例句解析":[{"句":"他背着总经理和副总喝酒。","析":"不知道是谁喝酒，是和副总一起喝，还是背着他们喝，有歧义。"},{"句":"小红的妈妈说她病了。","析":"她不知道指小红还是妈妈，指代不明。"}],"练习":[{"q":"“小红的妈妈说她病了”错在哪？","options":["搭配不当","代词指代不明","语序不当","结构混乱"],"answer":1,"解析":"她不知道指小红还是妈妈。","类":"代词指代不明"},{"q":"“他背着总经理和副总喝酒”错在哪？","options":["缺主语","句子歧义","搭配不当","不合逻辑"],"answer":1,"解析":"不知道是谁喝酒，有两种理解。","类":"句子歧义"},{"q":"“小明和小刚说，他赢了”怎么改最清楚？","options":["小明和小刚说，他赢了","小明对小刚说：“我赢了”","他们说，他赢了","小明说，他赢了"],"answer":1,"解析":"直接叫名字、用第一人称，指代就清楚了。","类":"代词指代不明"}],"决策树":"①有代词（他/这/那）吗？→有：上文可指对象唯一吗？→不唯一：指代不明，改用具体名词→②有歧义停顿吗？→有：加标点或改句式断开→③一句话有两种理解吗？→有：换一种说法→④否：表意明确","前置知识":["歧义句"]},{"name":"不合逻辑","图示":"<svg viewBox=\"0 0 640 280\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g id=\"wrongG\"><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"20\" fill=\"#b85a52\">他是众多死难者中幸免的一个</text><text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">✘ 病句</text><animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-5,0;5,0;-5,0;0,0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/><animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.5s\" begin=\"1.5s\" fill=\"freeze\"/></g><text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"32\" fill=\"#4a7a59\" opacity=\"0\">✓<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/></text><text x=\"320\" y=\"200\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">他是众多遇难者中幸免的一个<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.2s\" fill=\"freeze\"/></text><text x=\"320\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">自相矛盾、概念并列不当等<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.6s\" fill=\"freeze\"/></text></svg>","例子":["病：三月的南京是美丽的季节（主谓不合逻辑）","病：他七点起床洗漱，然后六点半出门（时间倒流了！）","病：他是众多死难者中幸免的一个→改：他是众多遇难者中幸免的一个（死难者不能幸免）","病：我断定他大概是生病了→改：我断定他是生病了（断定与大概矛盾）","病：全体同学都参加了，只有小明没来→改：除小明外，全体同学都参加了","病：他是唯一一个女同学→改：她是唯一的女同学（唯一与一个重复且搭配不当）","病：这道题我做了三遍，终于做对了一半→改：这道题我做了三遍，终于做对了","病：他的年龄大约十六七岁左右→改：他的年龄十六七岁（约数矛盾）","病：我们一定要发扬光大革命传统→改：我们一定要发扬革命传统（删“光大”或改为“把…发扬光大”）","病：这家店的商品物美价廉，服务态度好→改：正确（并列得当）"],"口诀":"概念关系要理清","易错":"“美”和“季节”不能搭配","讲解":"自相矛盾、概念并列不当等","深讲":"改法是：一读前后，二查概念，三改说法。","分类":[{"类":"前后矛盾式","说明":"前后说法自己打自己。","代表":"七点起床，六点半出门","例子":["他七点起床洗漱，然后六点半出门。"]},{"类":"并列概念不当式","说明":"并列的概念有交叉或包含。","代表":"水果、苹果和香蕉","例子":["水果、苹果和香蕉都很好吃。"]},{"类":"主谓不合逻辑式","说明":"主语和谓语在逻辑上对不上。","代表":"南京是季节","例子":["三月的南京是美丽的季节。"]}],"怎么认":["前后说法打不打架？打架，就是前后矛盾。","并列的词有没有包含关系？有，就是并列不当。","主语和谓语在逻辑上配不配？不配，就是主谓不合逻辑。"],"辨析":"不合逻辑和表意不明的区别：不合逻辑是意思清楚但不合理（时间倒流）；表意不明是意思说不清（谁病了？）。看意思清不清、合理不合理。","例句解析":[{"句":"三月的南京是美丽的季节。","析":"南京是城市，不能是季节，主谓不合逻辑。"},{"句":"他七点起床洗漱，然后六点半出门。","析":"六点半比七点早，时间倒流了，前后矛盾。"}],"练习":[{"q":"“他七点起床洗漱，然后六点半出门”错在哪？","options":["语序不当","前后矛盾","搭配不当","表意不明"],"answer":1,"解析":"六点半比七点早，时间倒流了。","类":"前后矛盾式"},{"q":"“水果、苹果和香蕉都很好吃”错在哪？","options":["并列概念不当","语序不当","缺宾语","结构混乱"],"answer":0,"解析":"水果包含了苹果，不能并列。","类":"并列概念不当式"},{"q":"“三月的南京是美丽的季节”错在哪？","options":["主谓不合逻辑","缺主语","语序不当","搭配不当"],"answer":0,"解析":"南京是城市，不能是季节。","类":"主谓不合逻辑式"}],"决策树":"①有并列词语吗？→有：概念交叉或从属吗？→是：删交叉项或改并列为包含→②有数量词吗？→有：约数词+确数并存吗？→是：删约数词或确数→③有否定词吗？→是：语义反了吗？→反了：删多余否定→④有\"大约/左右\"+确数吗？→有：删一→⑤否：逻辑没问题","前置知识":["概念：定义与划分"]},{"name":"主语残缺","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">通过这次春游，使我增长了见识。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">通过和使同时出现，删去使：通过这次春游，我增长了见识。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">看了这部电影，受到了教育。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">主语被介词吃掉，补上主语：我受到了教育。</text></g></svg>","讲解":"滥用介词（通过/使/令）导致主语丢失，话没了“头”。","深讲":"主语残缺是滥用介词（通过、使、令）导致主语丢失，话没了头。改法是：通过、使、令，删一留一，把主语留下来。","分类":[{"类":"通过使式","说明":"通过和使同时出现，主语被吃掉。","代表":"通过……使……","例子":["通过这次春游，使我增长了见识。"]},{"类":"介词开头式","说明":"介词开头，主语被介词吃掉。","代表":"看了……，受到了……","例子":["看了这部电影，受到了教育。"]}],"怎么认":["句子开头是不是通过、使、令这类介词？是的。","压缩主干，有没有主语？没有，就是主语残缺。","删掉通过或使，主语是不是回来了？回来了。"],"辨析":"主语残缺和谓语残缺的区别：主语残缺是缺头（通过学习，使我进步）；谓语残缺是缺动作（他昨天）。看缺的是头还是动作。","例句解析":[{"句":"通过这次春游，使我增长了见识。","析":"通过和使同时出现，删去使：通过这次春游，我增长了见识。"},{"句":"看了这部电影，受到了教育。","析":"主语被介词吃掉，补上主语：我受到了教育。"}],"练习":[{"q":"“通过这次春游，使我增长了见识”怎么改？","options":["通过这次春游，使我增长了见识了","通过这次春游，我增长了见识","这次春游，使我增长了见识","通过春游，使我增长见识"],"answer":1,"解析":"删去使，主语我就回来了。","类":"通过使式"},{"q":"“看了这部电影，受到了教育”错在哪？","options":["缺谓语","主语残缺","缺宾语","语序不当"],"answer":1,"解析":"主语被介词吃掉了。","类":"介词开头式"},{"q":"“通过……使……”是哪个病句的重灾区？","options":["谓语残缺","主语残缺","宾语残缺","搭配不当"],"answer":1,"解析":"通过和使同时出现，最易缺主语。","类":"通过使式"}],"例子":["病：通过这次春游，使我增长了见识 → 改：删去“使”","病：看了这部电影，受到了教育 → 改：我受到了教育","病：通过这次春游，使我增长了见识→改：通过这次春游，我增长了见识（删“使”）","病：看了这部电影，受到了教育→改：我看了这部电影，受到了教育（补主语“我”）","病：由于他努力学习，因而取得了好成绩→改：由于他努力学习，他取得了好成绩（删“因而”或补主语）","病：经过老师的教育，让我明白了道理→改：经过老师的教育，我明白了道理（删“让”）","病：从这件事中，懂得了诚实的重要→改：从这件事中，我懂得了诚实的重要（补“我”）","病：在老师的帮助下，他的成绩有了提高→改：正确（“他的成绩”作主语）","病：听了这个故事，受到很大启发→改：我听了这个故事，受到很大启发","病：通过讨论，使我们的认识提高了→改：通过讨论，我们的认识提高了"],"口诀":"通过使令，删一留一","易错":"“通过……使……”是重灾区","类比":"主语残缺就像“没头的话”：说了半天，不知道谁干的。","决策树":"①找主语：有吗？→有：不是主语残缺→②无：看句式——\"通过/由于/经过……使/让\"型吗？→是：删\"使/让\"，原宾语升为主语，或补主语→③介词开头（在/对/对于/通过）吗？→是：删介词，主语自然出现，或补主语→④否：另找缺主原因","前置知识":["主语"]},{"name":"谓语残缺","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他昨天。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">只有主语和时间，缺谓语，改为：他昨天来了。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">我们班的同学都很。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">都很后面缺形容词，改为：我们班的同学都很好学。</text></g></svg>","讲解":"只有主语没有谓语，话没说完。","深讲":"改法是：主语有了，动作要有，补上谓语。","分类":[{"类":"主语独存式","说明":"只有主语，谓语全缺。","代表":"他昨天","例子":["他昨天。"]},{"类":"谓语不全式","说明":"谓语说了半截，没说完。","代表":"同学都很","例子":["我们班的同学都很。"]}],"怎么认":["压缩句子后只剩主语吗？是的，就是谓语残缺。","主语后面有没有动作或状态？没有，就是缺谓语。","补上动作，句子是不是完整了？完整了。"],"辨析":"谓语残缺和主语残缺的区别：谓语残缺是缺动作（他昨天）；主语残缺是缺头（通过学习，使我进步）。看缺的是头还是动作。","例句解析":[{"句":"他昨天。","析":"只有主语和时间，缺谓语，改为：他昨天来了。"},{"句":"我们班的同学都很。","析":"都很后面缺形容词，改为：我们班的同学都很好学。"}],"练习":[{"q":"“他昨天”错在哪？","options":["主语残缺","谓语残缺","宾语残缺","语序不当"],"answer":1,"解析":"只有主语，缺谓语。","类":"主语独存式"},{"q":"“我们班的同学都很”怎么改？","options":["我们班的同学都很学","我们班的同学都很好学","我们班的同学很","我们班的同学都"],"answer":1,"解析":"补上谓语好学。","类":"谓语不全式"},{"q":"压缩句子后只剩主语，说明？","options":["主语残缺","谓语残缺","宾语残缺","搭配不当"],"answer":1,"解析":"只剩主语，就是谓语残缺。","类":"主语独存式"}],"例子":["病：他昨天 → 改：他昨天来了","病：我们班的同学都很 → 改：我们班的同学都很好学","病：他把今天的任务→改：他把今天的任务完成了（补谓语“完成”）","病：我们正在努力→改：我们正在努力学习（补宾语/谓语中心）","病：小明把门→改：小明把门关上了（补谓语“关上”）","病：他对这件事的关心→改：他对这件事很关心（补谓语“关心”）","病：妈妈把饭→改：妈妈把饭做好了（补谓语“做好”）","病：我们要学习雷锋的→改：我们要学习雷锋的精神（补宾语）","病：老师要求我们→改：老师要求我们认真读书（补谓语）","病：他把球→改：他把球踢进了球门（补谓语）"],"口诀":"主语有了，动作要有","易错":"压缩句子后只剩主语，就是谓语残缺","决策树":"①找谓语：有吗？→有：不是谓语残缺→②无：主语后直接跟宾语吗？→是：按宾语语义补谓语→③\"是\"字句缺\"是\"吗？→是：补\"是\"→④长定语后缺谓语吗？→是：补谓语→⑤否：不是谓语残缺","前置知识":["谓语"]},{"name":"宾语残缺","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我们要养成的好习惯。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">养成后缺完整的宾语，改为：养成讲卫生的好习惯。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">大家都喜欢。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">喜欢后空着，改为：大家都喜欢这本书。</text></g></svg>","讲解":"及物动词后缺宾语，动作没“着落”。","深讲":"宾语残缺是及物动词后缺宾语，动作没着落。改法是：动词之后，宾语莫丢，补上宾语。","分类":[{"类":"宾语空缺式","说明":"动词后宾语全空着。","代表":"大家都喜欢","例子":["大家都喜欢。"]},{"类":"宾语不全式","说明":"宾语说了半截，不完整。","代表":"养成的好习惯","例子":["我们要养成的好习惯。"]}],"怎么认":["动词后面有没有宾语？没有，就是宾语残缺。","“养成”“喜欢”后不能空着，重点查。","补上宾语，句子是不是完整了？完整了。"],"辨析":"宾语残缺和主语残缺的区别：宾语残缺是动作没着落（大家都喜欢）；主语残缺是话没头（通过学习，使我进步）。看缺的是头还是尾。","例句解析":[{"句":"我们要养成的好习惯。","析":"养成后缺完整的宾语，改为：养成讲卫生的好习惯。"},{"句":"大家都喜欢。","析":"喜欢后空着，改为：大家都喜欢这本书。"}],"练习":[{"q":"“大家都喜欢”错在哪？","options":["主语残缺","谓语残缺","宾语残缺","语序不当"],"answer":2,"解析":"喜欢后缺宾语。","类":"宾语空缺式"},{"q":"“我们要养成的好习惯”怎么改？","options":["我们要养成好习惯","我们要养成讲卫生的好习惯","我们要好习惯养成","我们要养成习惯"],"answer":1,"解析":"补上讲卫生，宾语就完整了。","类":"宾语不全式"},{"q":"“养成”“喜欢”后不能？","options":["加宾语","空着","加定语","加状语"],"answer":1,"解析":"及物动词后不能空着。","类":"宾语空缺式"}],"例子":["病：我们要养成的好习惯 → 改：养成讲卫生的好习惯","病：大家都喜欢 → 改：大家都喜欢这本书","病：我们要学习雷锋同志全心全意为人民服务的→改：…服务的精神（补宾语“精神”）","病：他正在看→改：他正在看书（补宾语“书”）","病：妈妈在洗→改：妈妈在洗衣服（补宾语“衣服”）","病：老师表扬了→改：老师表扬了他（补宾语“他”）","病：我喜欢→改：我喜欢画画（补宾语“画画”）","病：他把作业→改：他把作业写完了（补谓语和宾语完整）","病：我们参观了→改：我们参观了博物馆（补宾语）","病：小明正在写→改：小明正在写作文（补宾语）"],"口诀":"动词之后，宾语莫丢","易错":"“养成”“喜欢”后不能空着","决策树":"①动词后有宾语吗？→有：不是宾语残缺→②无：动词是及物动词吗？→是：按语境补宾语→③\"把\"字句缺中心词吗？→是：补中心词→④不及物动词误带宾语吗？→是：删宾语→⑤否：查别类","前置知识":["宾语","动词"]},{"name":"定语语序不当","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">一位优秀的我们班的学生。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">领属我们班应在最前，改为：我们班的一位优秀的学生。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">优秀的我们班的一位学生。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">按领属、数量、形容词排，改为：我们班的一位优秀的学生。</text></g></svg>","讲解":"多重定语排列顺序错误。","深讲":"顺序是：领属＋数量＋动词性＋形容词性＋名词，依次排好，不能乱。","分类":[{"类":"领属错位式","说明":"领属定语没放在最前。","代表":"一位优秀的我们班的学生","例子":["一位优秀的我们班的学生。"]},{"类":"多重定语错位式","说明":"多个定语顺序全乱了。","代表":"优秀的我们班的一位学生","例子":["优秀的我们班的一位学生。"]}],"怎么认":["定语有几个？多个，就要查顺序。","按领属、数量、动词性、形容词性、名词排一排。","排好后句子是不是顺了？顺了。"],"辨析":"定语语序不当和状语语序不当的区别：定语错位是名词前的修饰语排错了（我们班的一位优秀的学生）；状语错位是动词前的修饰语放错了（认真地把作业写完了）。看修饰的是名词还是动词。","例句解析":[{"句":"一位优秀的我们班的学生。","析":"领属我们班应在最前，改为：我们班的一位优秀的学生。"},{"句":"优秀的我们班的一位学生。","析":"按领属、数量、形容词排，改为：我们班的一位优秀的学生。"}],"练习":[{"q":"“一位优秀的我们班的学生”怎么改？","options":["一位我们班的优秀的学生","我们班的一位优秀的学生","优秀的我们班的一位学生","我们班优秀的一位学生"],"answer":1,"解析":"领属我们班在最前。","类":"领属错位式"},{"q":"多重定语的正确顺序是？","options":["形容词＋领属＋数量＋名词","领属＋数量＋动词性＋形容词性＋名词","数量＋领属＋形容词性＋名词","名词＋领属＋数量＋形容词"],"answer":1,"解析":"领属、数量、动词性、形容词性、名词依次排。","类":"多重定语错位式"},{"q":"“我们班的一位优秀的学生”中，领属定语是？","options":["一位","优秀的","我们班的","学生"],"answer":2,"解析":"我们班的是领属定语，在最前。","类":"领属错位式"}],"例子":["病：一位优秀的我们班的学生 → 改：我们班的一位优秀的学生","病：一位优秀的我们班的学生→改：我们班的一位优秀的学生（领属在前）","病：红的我的书包→改：我的红书包（领属+颜色顺序）","病：三本他的新书→改：他的三本新书（领属+数量+形容）","病：美丽的祖国的花朵→改：祖国美丽的花朵（领属在前）","病：两个可爱的小明的弟弟→改：小明的两个可爱的弟弟","病：昨天的一场大雨→改：正确（时间定语在前）","病：学校的我们的老师→改：我们学校的老师","病：高兴的他的消息→改：他的好消息（或：令他高兴的消息）","病：五个班里的同学→改：班里的五个同学"],"口诀":"谁的、多少、干啥、啥样，依次排好","易错":"顺序：领属＋数量＋动词性＋形容词性＋名词","决策树":"①找定语：在中心词前吗？→不在：移到中心词前→②多个定语：按\"领属→数量→动词性→形容词性→名词性\"排，顺序对吗？→不对：按序重排→③定语+中心语语义通吗？→不通：调换或改定语→④通：不是定语语序问题","前置知识":["定语","语序不当"]},{"name":"关联词误用","讲解":"关联词前后不搭配，张冠李戴。","深讲":"改法是：因果转折，配对要准，因为配所以，虽然配但是，别串门。","分类":[{"类":"因果误配转折式","说明":"因果词配了转折词。","代表":"因为……但是……","例子":["因为他很努力，但是没考好。"]},{"类":"条件误配式","说明":"条件词配错了。","代表":"只有……就……","例子":["只有下雨，就不去。"]}],"怎么认":["前后分句是什么关系？先定关系。","关联词配不配这个关系？不配，就是误用。","因为配所以，虽然配但是，查一查配对表。"],"辨析":"关联词误用和关联词残缺的区别：误用是配错了（因为……但是……）；残缺是只说一半（一边跑步，听音乐）。看是配错还是缺一半。","例句解析":[{"句":"因为他很努力，但是没考好。","析":"因为配但是是错的，改为：虽然他很努力，但是没考好。"},{"句":"只有下雨，就不去。","析":"只有是必要条件，就不去是充分结果，配错了，改为：只要下雨，就不去。"}],"练习":[{"q":"“因为他很努力，但是没考好”怎么改？","options":["因为他很努力，所以没考好","虽然他很努力，但是没考好","因为他很努力，而且没考好","如果他很努力，但是没考好"],"answer":1,"解析":"转折关系用虽然配但是。","类":"因果误配转折式"},{"q":"“只有下雨，就不去”怎么改？","options":["只有下雨，才不去","只要下雨，就不去","如果下雨，才不去","因为下雨，就不去"],"answer":1,"解析":"只要配就，表充分条件。","类":"条件误配式"},{"q":"“因为”配？","options":["但是","所以","而且","还是"],"answer":1,"解析":"因为配所以，别串门。","类":"因果误配转折式"}],"例子":["病：因为他很努力，但是没考好 → 改：虽然他很努力，但是没考好","病：只有下雨，就不去 → 改：只要下雨，就不去","病：因为他努力，所以他虽然成功了→改：因为他努力，所以他成功了（删“虽然”）","病：即使困难再大，我们也要不但完成→改：即使困难再大，我们也要完成（删“不但”）","病：他不但学习好，但是体育不好→改：他不但学习好，而且体育也好（“不但”配“而且”）","病：虽然他病了，所以没来上课→改：因为他病了，所以没来上课（因果用“因为…所以”）","病：如果努力，就不但能成功→改：如果努力，就能成功（删“不但”）","病：不是他不努力，而是因为方法不对→改：他不是不努力，而是方法不对（“不是…而是”位置）","病：只有你来，我才不去→改：如果你来，我就不去（条件关系用“如果…就”）","病：尽管下雨，但是却照常进行→改：尽管下雨，但是照常进行（删“却”）"],"口诀":"因果转折，配对要准","易错":"“因为”配“所以”，“虽然”配“但是”，别串门","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">关联词误用：\"因为\"不能配\"但是\"</text><g opacity=\"1\"><animate attributeName=\"opacity\" values=\"1;1;0;0;1;1\" keyTimes=\"0;0.4;0.5;0.9;0.95;1\" dur=\"8s\" /><text x=\"12\" y=\"64\" font-size=\"16\" class=\"svg-ink\">因为下雨，</text><text x=\"92\" y=\"64\" font-size=\"16\" class=\"svg-red\">但是</text><text x=\"124\" y=\"64\" font-size=\"16\" class=\"svg-ink\">没带伞。</text><text x=\"280\" y=\"64\" font-size=\"20\" class=\"svg-red\">✗</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;0;1;1;0;0\" keyTimes=\"0;0.4;0.5;0.9;0.95;1\" dur=\"8s\" /><text x=\"12\" y=\"64\" font-size=\"16\" class=\"svg-ink\">因为下雨，</text><text x=\"92\" y=\"64\" font-size=\"16\" class=\"svg-accent\">所以</text><text x=\"124\" y=\"64\" font-size=\"16\" class=\"svg-ink\">没带伞。</text><text x=\"280\" y=\"64\" font-size=\"20\" class=\"svg-accent\">✓</text></g><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">因为…所以…／虽然…但是…，前后要配套</text></svg>","决策树":"①有复句吗？→单句：不用关联词，删→②有关联词吗？→无：该用未用，补→③判断分句关系（因果/转折/递进/假设/条件）：关联词表意对吗？→不对：换表意相符的→④位置对吗（前后主语相同放后、不同放前）？→不对：调位置→⑤对：关联词没问题","前置知识":["转折复句","因果复句"]},{"name":"关联词残缺","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他一边跑步，听音乐。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">一边只说了一半，改为：他一边跑步，一边听音乐。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">虽然天气冷，坚持锻炼。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">虽然后缺但是，改为：虽然天气冷，但是坚持锻炼。</text></g></svg>","讲解":"关联词只说一半，另一半丢了。","深讲":"改法是：关联成双，缺一不可，把另一半补上。","分类":[{"类":"一边残缺式","说明":"一边……一边……只说了一边。","代表":"一边跑步，听音乐","例子":["他一边跑步，听音乐。"]},{"类":"虽然残缺式","说明":"虽然……但是……只说了虽然。","代表":"虽然天气冷，坚持锻炼","例子":["虽然天气冷，坚持锻炼。"]}],"怎么认":["关联词是不是成双的？只说一半，就是残缺。","一边、虽然、因为这类词，后面有没有另一半？没有，就是残缺。","补上另一半，句子是不是完整了？完整了。"],"辨析":"关联词残缺和关联词误用的区别：残缺是缺一半（一边跑步，听音乐）；误用是配错了（因为……但是……）。看是缺了还是配错了。","例句解析":[{"句":"他一边跑步，听音乐。","析":"一边只说了一半，改为：他一边跑步，一边听音乐。"},{"句":"虽然天气冷，坚持锻炼。","析":"虽然后缺但是，改为：虽然天气冷，但是坚持锻炼。"}],"练习":[{"q":"“他一边跑步，听音乐”怎么改？","options":["他一边跑步，一边听音乐","他跑步，听音乐","他一边跑步，听着音乐","他跑步一边，听音乐一边"],"answer":0,"解析":"一边要成双。","类":"一边残缺式"},{"q":"“虽然天气冷，坚持锻炼”缺什么？","options":["一边","但是","所以","而且"],"answer":1,"解析":"虽然配但是，缺了但是。","类":"虽然残缺式"},{"q":"关联词的改法是？","options":["留一去一","关联成双，缺一不可","调换位置","删去一个"],"answer":1,"解析":"关联成双，缺一不可。","类":"一边残缺式"}],"例子":["病：他一边跑步，听音乐 → 改：他一边跑步，一边听音乐","病：虽然天气冷，坚持锻炼 → 改：虽然天气冷，但是坚持锻炼","病：他努力学习，取得了好成绩→改：因为他努力学习，所以取得了好成绩（补关联词）","病：下雨，运动会取消→改：因为下雨，所以运动会取消了","病：你去，我去→改：你去，我就去（补“就”）","病：困难再大，我们克服→改：即使困难再大，我们也要克服","病：他学习好，体育好→改：他不但学习好，而且体育好","病：天黑，我们回家→改：天黑了，我们就回家","病：你不说，我怎么知道→改：如果你不说，我怎么知道","病：努力，就有收获→改：只要努力，就有收获"],"口诀":"关联成双，缺一不可","易错":"“一边…一边…”“虽然…但是…”都要说全","决策树":"①是复句吗？→否：不用关联词→②有关联词吗？→无：分句关系需关联词点明吗？→需：补→③成对关联词（因为…所以/虽然…但是）缺一半吗？→缺：补全→④齐：不是残缺，查误用","前置知识":["因果复句","假设复句"]},{"name":"指代不明","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">小明和小刚说，他赢了。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他不知道指小明还是小刚，改为：小明对小刚说：“我赢了”。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">他把书放在桌子上，它不见了。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">它指代不清，改为：书不见了。</text></g></svg>","讲解":"代词指代对象不明确，不知道说的是谁。","深讲":"改法是：两个人以上时，少用他，直接叫名字。","分类":[{"类":"人物指代不明","说明":"代词不知道指哪个人。","代表":"他赢了（谁？）","例子":["小明和小刚说，他赢了。"]},{"类":"事物指代不明","说明":"代词不知道指哪个事物。","代表":"它不见了（什么？）","例子":["他把书放在桌子上，它不见了。"]}],"怎么认":["句子里有几个人、几个物？两个以上，就要查代词。","代词（他、她、它）指谁？说不清，就是指代不明。","换成名字，句子是不是清楚了？清楚了。"],"辨析":"指代不明和句子歧义的区别：指代不明是代词不知道指谁（她病了）；句子歧义是一句话有两种理解（背着……喝酒）。看问题在代词还是整句话。","例句解析":[{"句":"小明和小刚说，他赢了。","析":"他不知道指小明还是小刚，改为：小明对小刚说：“我赢了”。"},{"句":"他把书放在桌子上，它不见了。","析":"它指代不清，改为：书不见了。"}],"练习":[{"q":"“小明和小刚说，他赢了”错在哪？","options":["语序不当","人物指代不明","搭配不当","结构混乱"],"answer":1,"解析":"他不知道指小明还是小刚。","类":"人物指代不明"},{"q":"“他把书放在桌子上，它不见了”怎么改最清楚？","options":["他把书放在桌子上，它不见了","书不见了","他把书放在桌子上，书不见了","它把书放在桌子上，不见了"],"answer":1,"解析":"直接说书不见了，指代就清楚了。","类":"事物指代不明"},{"q":"两个人以上时，代词的改法是？","options":["多用他","少用他，直接叫名字","删去代词","换成它"],"answer":1,"解析":"少用他，直接叫名字。","类":"人物指代不明"}],"例子":["病：小明和小刚说，他赢了 → 改：小明对小刚说：“我赢了”","病：他把书放在桌子上，它不见了 → 改：书不见了","病：小明对小红说，他明天要去北京→改：小明对小红说：“我明天要去北京”（说清“他”指谁）","病：老师把书给了他，他很高兴→改：老师把书给了小明，小明很高兴","病：妈妈叫姐姐，她答应了→改：妈妈叫姐姐，姐姐答应了","病：他把这件事告诉了他→改：他把这件事告诉了小刚","病：老师批评了他，他很不服气→改：老师批评了小明，小明很不服气","病：小红和小丽是好朋友，她学习很好→改：小红和小丽是好朋友，小红学习很好","病：爸爸对儿子说，你要好好学习→改：爸爸对儿子说：“你要好好学习”（加引号明确）","病：他把自行车借给了他→改：他把自行车借给了弟弟"],"口诀":"他她它，谁是谁","易错":"两个人以上时，少用“他”，直接叫名字","决策树":"①有\"他/她/它/这/那/其\"吗？→无：不是指代问题→②有：上文有几个可指对象？→多个：指代不明，改用具体名词点明→③一个：指代唯一，OK→④\"这/那\"指代事件还是词语？→模糊：改写点明","前置知识":["代词"]},{"name":"前后矛盾","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他断定这次大概能考第一。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">断定和大概打架，改为：他估计这次能考第一。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">昨天上午，我亲眼看见他下午在打球。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">上午和下午打架，时间矛盾。</text></g></svg>","讲解":"前后说法自相矛盾，自己打自己。","深讲":"改法是：断定别大概，前后别打架，语气、时间都要一致。","分类":[{"类":"语气矛盾式","说明":"断定词和大概词打架。","代表":"断定……大概……","例子":["他断定这次大概能考第一。"]},{"类":"时间矛盾式","说明":"时间前后打架。","代表":"昨天上午……下午……","例子":["昨天上午，我亲眼看见他下午在打球。"]}],"怎么认":["前后说法打不打架？打架，就是前后矛盾。","断定、肯定后有没有大概、可能？有，就是语气矛盾。","时间顺序对不对？不对，就是时间矛盾。"],"辨析":"前后矛盾和并列概念不当的区别：前后矛盾是说法打架（断定大概）；并列概念不当是词并列错了（水果、苹果）。看是说法打架还是词并列错了。","例句解析":[{"句":"他断定这次大概能考第一。","析":"断定和大概打架，改为：他估计这次能考第一。"},{"句":"昨天上午，我亲眼看见他下午在打球。","析":"上午和下午打架，时间矛盾。"}],"练习":[{"q":"“他断定这次大概能考第一”错在哪？","options":["语序不当","语气矛盾","搭配不当","表意不明"],"answer":1,"解析":"断定后不能跟大概。","类":"语气矛盾式"},{"q":"“昨天上午，我亲眼看见他下午在打球”错在哪？","options":["时间矛盾","语序不当","缺主语","搭配不当"],"answer":0,"解析":"上午和下午时间打架了。","类":"时间矛盾式"},{"q":"“断定”“肯定”后不能跟？","options":["一定","大概、可能","确实","真的"],"answer":1,"解析":"断定别大概。","类":"语气矛盾式"}],"例子":["病：他断定这次大概能考第一 → 改：他估计这次能考第一","病：昨天上午，我亲眼看见他下午在打球（时间打架了！）","病：他大约十六七岁左右→改：他十六七岁（删“大约”“左右”）","病：这道题我断定大概做对了→改：这道题我断定做对了（删“大概”）","病：全体同学都到了，只有小明没来→改：除了小明，全体同学都到了","病：他是唯一的三个获奖者之一→改：他是三个获奖者之一（删“唯一的”）","病：我亲眼目睹了他亲手做这件事→改：我目睹了他做这件事（删重复强调）","病：这个星期天，我肯定一定去→改：这个星期天，我一定去（删“肯定”）","病：他差不多把作业全部做完了→改：他把作业全部做完了（删“差不多”）","病：大约有三百多人参加→改：有三百多人参加（删“大约”）"],"口诀":"断定别大概，前后别打架","易错":"“断定”“肯定”后不能跟“大概”“可能”","决策树":"①找时间词：前后一致吗？→不一致：删改统一→②找数量词：约数+确数并存吗？→是：删一→③找判断词（是/不是、能/不能）：前后打架吗？→打架：统一说法→④找\"都/全\"+\"部分\"：冲突吗？→冲突：改→⑤否：前后一致","前置知识":["转折复句","概念：定义与划分"]},{"name":"并列概念交叉","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">水果、苹果和香蕉都很好吃。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">水果包含了苹果，改为：苹果和香蕉都很好吃。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">他喜欢球类、足球和音乐。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">球类包含了足球，改为：他喜欢足球和音乐。</text></g></svg>","讲解":"并列的概念有交叉或包含关系，不能放一排。","深讲":"改法是：大概念小概念，别放一排，去掉大概念或小概念。","分类":[{"类":"包含并列式","说明":"大概念包含了小概念，还并列。","代表":"水果、苹果和香蕉","例子":["水果、苹果和香蕉都很好吃。"]},{"类":"类别交叉式","说明":"类别词和小类词并列。","代表":"球类、足球和音乐","例子":["他喜欢球类、足球和音乐。"]}],"怎么认":["并列的词有没有包含关系？有，就是并列不当。","大概念和小概念放一排了吗？放了，就是错的。","去掉大概念，句子是不是顺了？顺了。"],"辨析":"并列概念交叉和前后矛盾的区别：并列不当是词并列错了（水果、苹果）；前后矛盾是说法打架（断定大概）。看是词并列还是说法打架。","例句解析":[{"句":"水果、苹果和香蕉都很好吃。","析":"水果包含了苹果，改为：苹果和香蕉都很好吃。"},{"句":"他喜欢球类、足球和音乐。","析":"球类包含了足球，改为：他喜欢足球和音乐。"}],"练习":[{"q":"“水果、苹果和香蕉都很好吃”怎么改？","options":["水果、苹果和香蕉都好吃","苹果和香蕉都很好吃","水果和苹果都很好吃","水果、香蕉都很好吃"],"answer":1,"解析":"去掉大概念水果。","类":"包含并列式"},{"q":"“他喜欢球类、足球和音乐”错在哪？","options":["语序不当","类别交叉并列","缺宾语","结构混乱"],"answer":1,"解析":"球类包含了足球，不能并列。","类":"类别交叉式"},{"q":"“水果”包含了“苹果”，所以不能？","options":["并列","分开说","一起吃","比较"],"answer":0,"解析":"大概念小概念，别放一排。","类":"包含并列式"}],"例子":["病：水果、苹果和香蕉都很好吃 → 改：苹果和香蕉都很好吃","病：他喜欢球类、足球和音乐 → 改：他喜欢足球和音乐","病：我国的粮食、棉花、油料都增产了→改：我国的粮食作物、棉花、油料作物都增产了（并列得当）","病：他喜欢唱歌、跳舞和文艺→改：他喜欢唱歌、跳舞（删“文艺”，概念包含）","病：商店里有水果、苹果、香蕉→改：商店里有苹果、香蕉等水果（苹果香蕉属水果）","病：他爱好体育、篮球、足球→改：他爱好篮球、足球等体育项目","病：我们参观了工厂、学校和教育→改：我们参观了工厂、学校（删“教育”）","病：动物园里有老虎、狮子和动物→改：动物园里有老虎、狮子等动物","病：他买了文具、铅笔和橡皮→改：他买了铅笔、橡皮等文具","病：会上讨论了学习、纪律和思想问题→改：正确（并列得当）"],"口诀":"大概念小概念，别放一排","易错":"“水果”包含了“苹果”，不能并列","决策树":"①有顿号/和/与/及/以及吗？→无：不是并列问题→②有：并列项概念交叉吗？→交叉：删交叉项→③有从属关系吗？（如\"水果和苹果\"）→有：改并列为包含（\"水果，如苹果\"）或删从属项→④词性/类别一致吗？→不一致：改一致→⑤OK","前置知识":["并列式","概念：定义与划分"]},{"name":"重复啰嗦","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他凯旋归来了。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">旋就是归来，改为：他凯旋了。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">非常十分开心。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">非常和十分叠用，改为：非常开心。</text></g></svg>","讲解":"词语意思重复，多余。","深讲":"改法是：意思重复，删去一个。","分类":[{"类":"意思重复式","说明":"两个词意思一样，重复了。","代表":"凯旋归来","例子":["他凯旋归来了。"]},{"类":"程度叠用式","说明":"程度词叠用，多余。","代表":"非常十分开心","例子":["非常十分开心。"]}],"怎么认":["有没有意思一样的词？有，就是重复。","程度词（非常、十分）叠用了吗？叠用了，就是多余。","删去一个，意思变不变？不变，就是啰嗦。"],"辨析":"重复啰嗦和成分赘余的区别：其实是一回事，重复啰嗦是成分赘余的一种；成分赘余还包括不约而同异口同声这类。看重复的是词还是成分。","例句解析":[{"句":"他凯旋归来了。","析":"旋就是归来，改为：他凯旋了。"},{"句":"非常十分开心。","析":"非常和十分叠用，改为：非常开心。"}],"练习":[{"q":"“他凯旋归来了”怎么改？","options":["他凯旋归来","他凯旋了","他归来了","他凯旋归来了啊"],"answer":1,"解析":"旋就是归来，删去归来。","类":"意思重复式"},{"q":"“非常十分开心”怎么改？","options":["十分开心","非常开心","非常十分地开心","开心"],"answer":1,"解析":"程度词留一个就够。","类":"程度叠用式"},{"q":"“凯旋”本身就含什么意？","options":["胜利","归来","开心","回来"],"answer":1,"解析":"旋就是归来。","类":"意思重复式"}],"例子":["病：他凯旋归来了 → 改：他凯旋了（“旋”就是归来）","病：非常十分开心 → 改：非常开心","病：他亲眼目睹了这件事→改：他目睹了这件事（亲眼与目睹重复）","病：这件事的经过大概→改：这件事的经过（删“大概”或保留一处）","病：他非常非常高兴→改：他非常高兴（删重复）","病：大约三百多人左右→改：三百多人（删“大约”“左右”）","病：他回到了他的家乡→改：他回到了家乡（删“他的”）","病：这是一个非常极好的消息→改：这是一个极好的消息（删“非常”）","病：他首先第一个发言→改：他第一个发言（首先与第一重复）","病：我们共同一起努力→改：我们共同努力（删“一起”）"],"口诀":"意思重复，删去一个","易错":"“凯旋”本身就含“归来”意","决策树":"①有意思相近的词并存吗？→有：删一留一→②有\"的原因是因为/目的是为了\"类杂糅吗？→有：删杂糅部分→③有\"十分非常/大约左右\"类同义叠加吗？→有：留一个→④有\"凯旋归来/亲眼目睹\"类语义重复吗？→有：删重复义素→⑤无：不啰嗦","前置知识":[]},{"name":"约数矛盾","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">大约有30人左右。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">大约和左右都是约数，改为：大约有30人。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">最少也有10多个。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">最少和多个叠用，改为：有10多个。</text></g></svg>","讲解":"约数词叠用，自相矛盾。","深讲":"改法是：大约、左右、上下、多都是约数，别叠用，留一个就够。","分类":[{"类":"大约左右式","说明":"大约和左右叠用。","代表":"大约有30人左右","例子":["大约有30人左右。"]},{"类":"最少多个式","说明":"最少和多个叠用。","代表":"最少也有10多个","例子":["最少也有10多个。"]}],"怎么认":["约数词有几个？两个以上，就是叠用。","大约、左右、上下、多，数一数。","留一个，句子是不是顺了？顺了。"],"辨析":"约数矛盾和重复啰嗦的区别：约数矛盾是约数词叠用（大约左右）；重复啰嗦是意思重复（凯旋归来）。看叠用的是不是约数词。","例句解析":[{"句":"大约有30人左右。","析":"大约和左右都是约数，改为：大约有30人。"},{"句":"最少也有10多个。","析":"最少和多个叠用，改为：有10多个。"}],"练习":[{"q":"“大约有30人左右”怎么改？","options":["大约有30人左右啊","大约有30人","有30人左右","大约左右有30人"],"answer":1,"解析":"约数留一个就够。","类":"大约左右式"},{"q":"“最少也有10多个”怎么改？","options":["最少有10多个","有10多个","最少也有10个多","最少10多个"],"answer":1,"解析":"删去最少也有，留多个。","类":"最少多个式"},{"q":"下面哪个是约数词？","options":["一定","大约","确实","真的"],"answer":1,"解析":"大约是约数词。","类":"大约左右式"}],"例子":["病：大约有30人左右 → 改：大约有30人","病：最少也有10多个 → 改：有10多个","病：大约有三百多人参加→改：有三百多人参加","病：他的年龄十六七岁左右→改：他的年龄十六七岁","病：这条路大约长约五公里→改：这条路长约五公里","病：大约一百多名同学→改：一百多名同学","病：他走了大约半个多小时→改：他走了半个多小时","病：这个水池大约深两米左右→改：这个水池深约两米","病：大约有五六十人上下→改：有五六十人","病：他大概八九岁上下→改：他八九岁"],"口诀":"大约左右，留一个就够","易错":"“大约”“左右”“上下”“多”都是约数，别叠用","决策树":"①有约数词（大约/左右/上下/多/近/余）吗？→无：不是约数问题→②有：后面还有确数吗？→有：约数矛盾，删确数或删约数词→③两个约数词叠加吗？→是：留一个→④无：OK","前置知识":["数词"]},{"name":"否定失当","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">为了避免不再犯错，我们要认真。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">避免后不再加不，改为：为了避免犯错。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">切忌不要骄傲。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">切忌后不再加不，改为：切忌骄傲。</text></g></svg>","讲解":"多重否定算错了账，表意正好相反。","深讲":"改法是：否定加否定，意思要算清；避免、切忌、防止后不再加不。","分类":[{"类":"避免否定式","说明":"避免后又加不，意思反了。","代表":"避免不再犯错","例子":["为了避免不再犯错，我们要认真。"]},{"类":"切忌否定式","说明":"切忌后又加不，意思反了。","代表":"切忌不要骄傲","例子":["切忌不要骄傲。"]}],"怎么认":["否定词有几个？数一数。","避免、切忌、防止后有没有不？有，就是多余否定。","算一算否定，意思是不是反了？反了，就是否定失当。"],"辨析":"否定失当和前后矛盾的区别：否定失当是否定算错了账（避免不再犯错）；前后矛盾是说法打架（断定大概）。看问题在否定还是说法。","例句解析":[{"句":"为了避免不再犯错，我们要认真。","析":"避免后不再加不，改为：为了避免犯错。"},{"句":"切忌不要骄傲。","析":"切忌后不再加不，改为：切忌骄傲。"}],"练习":[{"q":"“为了避免不再犯错，我们要认真”怎么改？","options":["为了避免不再犯错","为了避免犯错","为了不再犯错","为了避免不犯错"],"answer":1,"解析":"避免后不再加不。","类":"避免否定式"},{"q":"“切忌不要骄傲”怎么改？","options":["切忌要骄傲","切忌骄傲","不要切忌骄傲","切忌不要不骄傲"],"answer":1,"解析":"切忌后不再加不。","类":"切忌否定式"},{"q":"“避免”“切忌”“防止”后不再加？","options":["不","要","会","能"],"answer":0,"解析":"避免、切忌、防止后不再加不。","类":"避免否定式"}],"例子":["病：为了避免不再犯错，我们要认真 → 改：为了避免犯错","病：切忌不要骄傲 → 改：切忌骄傲","病：我们要防止不再犯错→改：我们要防止犯错（删“不”）","病：他无时无刻不忘学习→改：正确（双重否定表肯定）","病：没有人不说他不好→改：没有人不说他好（删多余否定）","病：难道他不想不去吗→改：难道他不想去吗（删多余否定）","病：我们切忌不要骄傲→改：我们切忌骄傲（删“不要”）","病：他不禁忍不住笑了→改：他忍不住笑了（删“不禁”）","病：避免不发生事故→改：避免发生事故","病：我不会不帮你→改：正确（双重否定表一定帮）"],"口诀":"否定加否定，意思要算清","易错":"“避免”“切忌”“防止”后不再加“不”","决策树":"①数否定词：几个？→0-1个：一般没问题→②≥2个：连起来读，语义反了吗？→反了：删多余否定→③有\"避免/防止/忌/以免\"后加否定吗？→有：删否定（本身已含否定义）→④有\"无时无刻不\"类双重否定表肯定吗？→语义需要：保留→⑤否：否定没问题","前置知识":["副词","双重否定"]},{"name":"主谓搭配不当","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我国的人口是世界上最多的国家。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">人口不能是国家，改为：我国是世界上人口最多的国家。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">三月的南京是美丽的季节。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">南京不能是季节，主谓不合逻辑，也是主谓搭配不当。</text></g></svg>","讲解":"主语和谓语搭配不起来，对不上号。","深讲":"改法是：谁是什么，对号入座，人口不能是国家。","分类":[{"类":"主语谓语错位式","说明":"主语和谓语在概念上错位。","代表":"人口是国家","例子":["我国的人口是世界上最多的国家。"]},{"类":"概念错配式","说明":"主语概念和谓语概念不配。","代表":"南京是季节","例子":["三月的南京是美丽的季节。"]}],"怎么认":["压缩主干，主语是谁？谓语是什么？","主语和谓语配不配？不配，就是主谓搭配不当。","人口不能是国家，城市不能是季节，查概念。"],"辨析":"主谓搭配不当和动宾搭配不当的区别：主谓不当是主语配谓语错了（人口是国家）；动宾不当是动词配宾语错了（端正学习）。看错的是主谓还是动宾。","例句解析":[{"句":"我国的人口是世界上最多的国家。","析":"人口不能是国家，改为：我国是世界上人口最多的国家。"},{"句":"三月的南京是美丽的季节。","析":"南京不能是季节，主谓不合逻辑，也是主谓搭配不当。"}],"练习":[{"q":"“我国的人口是世界上最多的国家”怎么改？","options":["我国的人口是世界上最多的","我国是世界上人口最多的国家","我国的人口是最多的国家","我国是人口最多的国家"],"answer":1,"解析":"主语换成我国，人口作定语。","类":"主语谓语错位式"},{"q":"“三月的南京是美丽的季节”错在哪？","options":["缺宾语","主谓搭配不当","语序不当","结构混乱"],"answer":1,"解析":"南京不能是季节。","类":"概念错配式"},{"q":"主谓搭配的口诀是？","options":["动词宾语，手拉手配对","谁是什么，对号入座","通过使令，删一留一","关联成双，缺一不可"],"answer":1,"解析":"谁是什么，对号入座。","类":"主语谓语错位式"}],"例子":["病：我国的人口是世界上最多的国家 → 改：我国是世界上人口最多的国家","病：他的写作水平有了很大提高→改：正确（水平与提高搭配）","病：他的普通话说得很标准→改：他的普通话说得很流利","病：同学们都认真地完成了作业→改：正确（完成与作业搭配）","病：他的学习成绩很优异→改：他的学习成绩优异（删“很”）","病：我们要发扬光大革命传统→改：我们要发扬革命传统","病：他的声音很宏亮→改：正确（声音与宏亮搭配）","病：这场雨下得很及时→改：正确（雨与及时搭配）","病：他的态度很端正→改：正确（态度与端正搭配）","病：我们要养成良好的学习态度→改：我们要养成良好的学习习惯"],"口诀":"谁是什么，对号入座","易错":"“人口”不能是“国家”，主语谓语要门当户对","决策树":"①抽主语+谓语：语义通吗？→通：不是主谓搭配问题→②不通：主语是事物、谓语是动作吗？→是：换能发此动作的主语，或换谓语→③主谓褒贬/大小/范围一致吗？→不一致：换一端→④\"是\"字句两边等值吗？→不等：改","前置知识":["主语","谓语","搭配不当"]},{"name":"动宾搭配不当","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我们要端正学习。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">端正配态度，改为：端正学习态度。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">他发扬了球技。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">发扬配精神，球技配提高，改为：他提高了球技。</text></g></svg>","讲解":"动词和宾语不搭配。","深讲":"动宾搭配不当是动词和宾语不搭配。改法是：动词宾语，手拉手配对，端正配态度，提高配水平，别拉错手。","分类":[{"类":"端正配态度式","说明":"端正要配态度，不配学习。","代表":"端正学习","例子":["我们要端正学习。"]},{"类":"提高配水平式","说明":"提高要配水平、球技，不配发扬。","代表":"发扬了球技","例子":["他发扬了球技。"]}],"怎么认":["动词后面跟的是什么宾语？","动词和宾语配不配？不配，就是动宾搭配不当。","端正配态度，提高配水平，查一查固定搭配。"],"辨析":"动宾搭配不当和主谓搭配不当的区别：动宾不当是动词配宾语错了（端正学习）；主谓不当是主语配谓语错了（人口是国家）。看错的是动宾还是主谓。","例句解析":[{"句":"我们要端正学习。","析":"端正配态度，改为：端正学习态度。"},{"句":"他发扬了球技。","析":"发扬配精神，球技配提高，改为：他提高了球技。"}],"练习":[{"q":"“我们要端正学习”怎么改？","options":["我们要端正学习态度","我们要学习端正","我们要端正地学习","我们要学习"],"answer":0,"解析":"端正配态度。","类":"端正配态度式"},{"q":"“他发扬了球技”怎么改？","options":["他发扬了球技水平","他提高了球技","他发扬球技","他提高发扬球技"],"answer":1,"解析":"球技配提高，不配发扬。","类":"提高配水平式"},{"q":"“提高”配？","options":["态度","水平","精神","学习"],"answer":1,"解析":"提高配水平。","类":"提高配水平式"}],"例子":["病：我们要端正学习 → 改：端正学习态度","病：他发扬了球技 → 改：他提高了球技","病：我们要端正学习目的→改：我们要端正学习态度","病：他打碎了信心→改：他失去了信心（打碎与信心不搭配）","病：同学们完成了任务→改：正确（完成与任务搭配）","病：我们要提高学习→改：我们要提高学习成绩（补宾语中心）","病：他改正了缺点→改：正确（改正与缺点搭配）","病：老师提出了希望→改：正确（提出与希望搭配）","病：我们要爱护时间→改：我们要珍惜时间（爱护与时间不搭配）","病：他发挥了水平→改：正确（发挥与水平搭配）"],"口诀":"动词宾语，手拉手配对","易错":"“端正”配“态度”，“提高”配“水平”，别拉错手","决策树":"①抽动词+宾语：能搭配吗？→能：不是动宾搭配问题→②不能：看宾语语义，换能带此宾语的动词→③一动多宾：动词能管住每个宾语吗？→不能：拆开各配动词→④\"进行/加以\"+动词宾语赘余吗？→是：删\"进行\"","前置知识":["宾语","动词","搭配不当"]}],"name":"常见病句类型（20种）"},{"id":"gaoji","name":"高级句式（10种）","items":[{"name":"把字句","类比":"把字句就像\"抓娃娃机\"：先\"把\"娃娃抓住（提起宾语），再决定怎么处置它。","图示":"<svg viewBox=\"0 0 640 300\" id=\"svg\">  <!-- 原句：我吃完了苹果 -->  <g font-size=\"24\" text-anchor=\"middle\" id=\"orig\">    <text x=\"100\" y=\"80\" fill=\"#2c3328\">我</text>    <text x=\"220\" y=\"80\" fill=\"#2c3328\" id=\"chiwan\">吃完了</text>    <text x=\"360\" y=\"80\" fill=\"#2c3328\" id=\"apple1\">苹果</text>  </g>  <text x=\"320\" y=\"40\" text-anchor=\"middle\" font-size=\"14\" fill=\"#6b7566\" opacity=\"0\">普通说法：我吃完了苹果    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"0.3s\" fill=\"freeze\"/>  </text>  <!-- 手出现 -->  <g opacity=\"0\" id=\"hand\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.5s\" fill=\"freeze\"/>    <!-- 简笔画手 -->    <ellipse cx=\"360\" cy=\"130\" rx=\"25\" ry=\"20\" fill=\"none\" stroke=\"#b85a52\" stroke-width=\"3\"/>    <path d=\"M340,130 L340,110 M350,130 L350,108 M360,130 L360,108 M370,130 L370,110\" stroke=\"#b85a52\" stroke-width=\"3\" stroke-linecap=\"round\"/>    <text x=\"360\" y=\"170\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">把</text>  </g>  <!-- 手抓住苹果，移动到动词前 -->  <g id=\"moveGroup\" opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.2s\" begin=\"2.2s\" fill=\"freeze\"/>    <animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-140,-10\" dur=\"1.2s\" begin=\"2.2s\" fill=\"freeze\"/>    <text x=\"360\" y=\"80\" text-anchor=\"middle\" font-size=\"24\" fill=\"#b85a52\" font-weight=\"bold\">苹果</text>    <ellipse cx=\"360\" cy=\"130\" rx=\"25\" ry=\"20\" fill=\"none\" stroke=\"#b85a52\" stroke-width=\"3\"/>    <path d=\"M340,130 L340,110 M350,130 L350,108 M360,130 L360,108 M370,130 L370,110\" stroke=\"#b85a52\" stroke-width=\"3\" stroke-linecap=\"round\"/>  </g>  <!-- 原苹果淡出 -->  <animate xlink:href=\"#apple1\" attributeName=\"opacity\" values=\"1;0\" dur=\"0.3s\" begin=\"2.2s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <!-- 原手淡出 -->  <animate xlink:href=\"#hand\" attributeName=\"opacity\" values=\"1;0\" dur=\"0.3s\" begin=\"2.2s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <!-- 吃完了淡出，避免与移动过来的苹果重叠 -->  <animate xlink:href=\"#chiwan\" attributeName=\"opacity\" values=\"1;0\" dur=\"0.3s\" begin=\"2.2s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <!-- 把字出现 -->  <text x=\"160\" y=\"80\" text-anchor=\"middle\" font-size=\"24\" fill=\"#b85a52\" font-weight=\"bold\" opacity=\"0\">把    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.0s\" fill=\"freeze\"/>  </text>  <!-- 最终：我把苹果吃完了 -->  <g font-size=\"24\" text-anchor=\"middle\" opacity=\"0\" id=\"final\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3.6s\" fill=\"freeze\"/>    <text x=\"100\" y=\"220\" fill=\"#2c3328\">我</text>    <text x=\"180\" y=\"220\" fill=\"#b85a52\" font-weight=\"bold\">把</text>    <text x=\"280\" y=\"220\" fill=\"#2c3328\">苹果</text>    <text x=\"400\" y=\"220\" fill=\"#2c3328\">吃完了</text>  </g>  <text x=\"320\" y=\"260\" text-anchor=\"middle\" font-size=\"15\" fill=\"#4a7a59\" opacity=\"0\">\"把\"就是用手抓：把宾语抓到动词前面，强调\"我对苹果做了什么\"    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.5s\" begin=\"4.2s\" fill=\"freeze\"/>  </text></svg>","动画":{"steps":[{"tokens":["我","吃","了","苹果"],"note":"正常语序：我吃了苹果"},{"tokens":["我","把","苹果","吃","了"],"note":"\"把\"提起宾语，放到动词前"},{"tokens":["我","把","苹果","吃","完","了"],"note":"动词后要有\"着落\"（完/掉/干净），不能光秃秃"}]},"讲解":"把宾语提前到动词前，强调对宾语的处置。公式：主语＋把＋宾语＋动词＋补语/了。","深讲":"公式：主语＋把＋宾语＋动词＋补语/了；动词不能光秃秃，后面要有补语或了表结果；心理动词（喜欢、觉得）不能用把字句。","分类":[{"类":"动词＋了式","说明":"动词后加了，表结果完成。","代表":"把＋宾语＋动词＋了","例子":["我把作业写完了。"]},{"类":"动词＋补语式","说明":"动词后加补语，表处置结果。","代表":"把＋宾语＋动词＋补语","例子":["妈妈把房间收拾干净了。"]}],"怎么认":["句子里有没有把？有。","把后面是不是宾语，动词在宾语后面？是的。","动词后面有没有补语或了？有，才是规范的把字句。"],"辨析":"把字句和被字句的区别：把字句强调处置（我把作业写完了：我处置了作业）；被字句强调承受（杯子被打碎了：杯子承受了打碎）。看主语是处置者还是承受者。","例句解析":[{"句":"我把作业写完了。","析":"把提前了宾语作业，动词写后有了了，是把字句。"},{"句":"他把杯子打碎了。","析":"把提前了宾语杯子，动词打后有了碎了，是把字句。"}],"练习":[{"q":"下面哪个把字句正确？","options":["我把饭吃","我把饭吃完了","我把饭吃着"],"answer":1,"解析":"动词后要有补语或了表结果。","类":"动词＋了式"},{"q":"“妈妈把房间收拾干净了”属于？","options":["动词＋了式","动词＋补语式","被字句","存现句"],"answer":1,"解析":"动词收拾后有补语干净。","类":"动词＋补语式"},{"q":"“他喜欢音乐”能改把字句吗？","options":["他把音乐喜欢了","不能改","他把音乐喜欢着"],"answer":1,"解析":"喜欢是心理动词，无处置义，不能用把。","类":"动词＋了式"}],"口诀":"把字提起宾，动词要有根（补语）","例子":["我把作业写完了","他把杯子打碎了","妈妈把房间收拾干净了","小明把垃圾扔进了垃圾桶。","老师把试卷发下来了。","我把这本书看完了。","爸爸把车修好了。","她把花插进了花瓶。","我们把教室打扫得干干净净。","奶奶把毛衣织好了。","把盐递给我。","我把他介绍给我老板了。","你们把那个问题解决了吗？","你把我手机放在哪儿了？","你能不能把你房间打扫干净？","他已经把钱还给我了。","我可能把手机忘在朋友家了。","他把最后三块蛋糕吃完了。","你把这几句话读一下。","把课文读一遍。","他把手机摔坏过两三次。","请把客人带进去。","把我的眼镜拿过来。","我把作业做完了。","老师把我的名字读错了。","阿姨没有把房间打扫干净。","我没把钱借给他。","你们不要把这件事告诉她。","我们把礼物送给客人了。","他把房子卖给谁了？"],"易错":"✗ 我把书看（动词光秃秃） ✓ 我把书看完了；心理动词（喜欢/觉得）不能用把字句；“把”后面的宾语必须是特指的、说话人和听话人都知道是哪个：✗我把一本书看完了→✓我把这本书看完了（来源：AllSet Grammar Wiki）；否定词（不要/别/没有）只能放在“把”前面，不能放在“把”后面：✓我没有把书看完（来源：AllSet Grammar Wiki）；双宾语把字句：主语＋把＋宾语1＋动词＋给＋宾语2，如“我们把礼物送给客人了”（来源：AllSet Grammar Wiki）；副词放“把”前还是动词后，意思会变：“我们都把作业做完了”（“都”修饰“我们”）vs“他把咖啡都喝完了”（“都”修饰“咖啡”）（来源：AllSet Grammar Wiki）；数量短语的位置：名词量词短语跟在“把”后（我把那两件脏衣服洗干净了），动词量词放在句末（她把这个字写了十遍）（来源：AllSet Grammar Wiki）；知觉动词（看、听、闻、像）不能用把字句，心理动词（爱、喜欢、想、了解、害怕、恨）也一样（来源：AllSet Grammar Wiki）；可能补语不能进把字句：✗我把衣服洗不干净（可能补语讲的是“还没发生”，把字句必须讲实际发生的事）（来源：AllSet Grammar Wiki）；为什么非用“把”不可：不说“放书在桌子上”（这句不合语法——动词后不能直接跟宾语、后面再跟别的成分），必须把宾语提前：“把书放在桌子上”（来源：AllSet Grammar Wiki）；“把”还兼作量词：一词多义别混淆，如“请你把那把伞拿给我”（第一个“把”是介词，第二个“把”是量词）（来源：AllSet Grammar Wiki）；把字句的疑问句有三种问法：加\"吗\"（你们把那个问题解决了吗？）、用疑问词（你把我手机放在哪儿了？/他把钱借给谁了？）、正反问（你能不能把你房间打扫干净？）；提问也不能违反两条铁律——宾语必须特指、必须讲清楚对宾语做了什么（来源：AllSet Grammar Wiki）；把字句不跟时间挂钩：过去的事、现在的要求都能用（来源：AllSet Grammar Wiki）；把字句爱讲\"把宾语怎么样了\"，动词后面最好有\"料\"：结果补语最搭（我把作业做完了、老师把我的名字读错了），趋向补语也搭（请把客人带进去、把我的眼镜拿过来）（来源：AllSet Grammar Wiki）；双宾语把字句常用动词：送、拿、递、卖、借、还、介绍，如\"把盐递给我\"\"我把他介绍给我老板了\"（来源：AllSet Grammar Wiki）；否定词只能放\"把\"前面的道理：否定词放\"把\"里面，等于说\"发生的事是什么都没发生\"，听着别扭，所以只能放外面：阿姨没有把房间打扫干净、我没把钱借给他、你们不要把这件事告诉她（来源：AllSet Grammar Wiki）；副词新例：\"已经\"修饰整句（他已经把钱还给我了）；\"可能\"表推测（我可能把手机忘在朋友家了）（来源：AllSet Grammar Wiki）；数量短语新例：他把最后三块蛋糕吃完了；你把这几句话读一下；把课文读一遍；他把手机摔坏过两三次（来源：AllSet Grammar Wiki）；把字句是SOV语序：主语＋把＋宾语＋动词，\"宾语\"被提前到动词前面，语序从SVO变成了SOV（来源：AllSet Grammar Wiki）","小测":[{"q":"哪句把字句正确？","options":["我把饭吃","我把饭吃完了","我把饭吃着"],"answer":1,"解析":"动词后要有补语或\"了\"表结果。"},{"q":"\"他喜欢音乐\"能改把字句吗？","options":["他把音乐喜欢了","不能改","他把音乐喜欢着"],"answer":1,"解析":"\"喜欢\"无处置义，不能用把。"}],"变式表":{"不变":"主+把+宾+动+补语/了，强调对宾语的处置","可变":{"主语":["我/他/妈妈"],"宾语":["具体（饭/书）","抽象（问题/心）"],"动补":["动+了（吃了）","动+结果补语（写完/洗干净）"]},"边界":"动词后须有'根'（✗我把饭吃）；心理动词不用把（✗我把他喜欢）；不及物动词不用把（✗我把跑步了）","覆盖已确认":["主语","宾语","动补"],"覆盖缺失":[]},"前置知识":["宾语","补语","动词","主语","副词","量词","介词"]},{"name":"被字句","类比":"被字句就像\"领奖台\"：动作的承受者站上主语位，强调它\"遭了什么\"。","动画":{"steps":[{"tokens":["小狗","咬","了","小明"],"note":"主动句：小狗是施事"},{"tokens":["小明","被","小狗","咬","了"],"note":"小明变主语，强调他的遭遇"},{"tokens":["小明","被","咬","伤","了"],"note":"\"被\"后施事可省，结果\"伤\"不能省"}]},"讲解":"主语是动作的承受者。公式：受事＋被/叫/让＋施事＋动词＋补语。","深讲":"被后多为不如意事；被后可以没有施事，直接跟动词。","分类":[{"类":"被＋施事式","说明":"被后有施事，说明谁做的。","代表":"受事＋被＋施事＋动词","例子":["小明被小狗咬了。"]},{"类":"被无施事式","说明":"被后没有施事，只说承受了什么。","代表":"受事＋被＋动词","例子":["杯子被打碎了。"]},{"类":"叫让式","说明":"用叫、让代替被，意思一样。","代表":"受事＋叫/让＋施事＋动词","例子":["他叫雨淋湿了。"]}],"怎么认":["主语是不是承受者？是的。","句子里有没有被、叫、让？有。","被后是施事还是直接动词？施事就是被＋施事式，直接动词就是被无施事式。"],"辨析":"被字句和把字句的区别：被字句主语是承受者（杯子被打碎了）；把字句主语是处置者（我把杯子打碎了）。同一件事，角度不同，句式就不同。","例句解析":[{"句":"小明被小狗咬了。","析":"小明是承受者，被后有施事小狗，是被＋施事式。"},{"句":"我的气球被风吹走了。","析":"气球是承受者，被后有施事风，是被＋施事式。"}],"练习":[{"q":"被字句强调？","options":["谁做的","主语遭受了什么","动作多快"],"answer":1,"解析":"主语是受事，强调遭遇。","类":"被＋施事式"},{"q":"“杯子被打碎了”属于？","options":["被＋施事式","被无施事式","叫让式","把字句"],"answer":1,"解析":"被后没有施事，直接跟动词打碎。","类":"被无施事式"},{"q":"“他被吃了饭”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"被后多为不如意事，吃了饭不是遭遇，不能这样说。","类":"被＋施事式"}],"口诀":"被字一出，受害现身","例子":["小明被小狗咬了","杯子被打碎了","我的气球被风吹走了","作业被我写完了。","杯子被他打碎了。","房间被妈妈收拾干净了。","小偷被警察抓住了。","窗户被风吹开了。","我的书包被雨淋湿了。","庄稼被洪水淹没了。","他被老师表扬了。","球被小明踢进了球门。","衣服被太阳晒干了。"],"易错":"✗ 他被吃了饭 ✓ 他被批评了；\"被\"后多为不如意事","小测":[{"q":"被字句强调？","options":["谁做的","主语遭受了什么","动作多快"],"answer":1,"解析":"主语是受事，强调遭遇。"}],"图示":"<svg viewBox=\"0 0 640 300\" id=\"svg\">  <!-- 主动：猫抓伤了狗 -->  <text x=\"320\" y=\"40\" text-anchor=\"middle\" font-size=\"14\" fill=\"#6b7566\" opacity=\"0\">主动：猫抓伤了狗    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"0.3s\" fill=\"freeze\"/>  </text>  <g font-size=\"24\" text-anchor=\"middle\">    <text x=\"180\" y=\"90\" fill=\"#2c3328\" id=\"cat1\">猫</text>    <text x=\"320\" y=\"90\" fill=\"#2c3328\">抓伤了</text>    <text x=\"460\" y=\"90\" fill=\"#2c3328\" id=\"dog1\">狗</text>  </g>  <!-- 推的动作：狗被推到前面 -->  <g id=\"pushGroup\" opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.2s\" begin=\"1.8s\" fill=\"freeze\"/>    <animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-280,0\" dur=\"1.2s\" begin=\"1.8s\" fill=\"freeze\"/>    <text x=\"460\" y=\"90\" text-anchor=\"middle\" font-size=\"24\" fill=\"#4a7a8c\" font-weight=\"bold\">狗</text>    <!-- 推的手势箭头 -->    <path d=\"M490,90 L520,90\" stroke=\"#4a7a8c\" stroke-width=\"4\" stroke-linecap=\"round\"/>    <polygon points=\"520,80 535,90 520,100\" fill=\"#4a7a8c\"/>  </g>  <animate xlink:href=\"#dog1\" attributeName=\"opacity\" values=\"1;0\" dur=\"0.3s\" begin=\"1.8s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <!-- 猫淡出，避免与推过来的狗重叠 -->  <animate xlink:href=\"#cat1\" attributeName=\"opacity\" values=\"1;0\" dur=\"0.3s\" begin=\"1.8s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <!-- 被字出现 -->  <text x=\"240\" y=\"90\" text-anchor=\"middle\" font-size=\"24\" fill=\"#4a7a8c\" font-weight=\"bold\" opacity=\"0\">被    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.6s\" fill=\"freeze\"/>  </text>  <!-- 最终：狗被猫抓伤了 -->  <g font-size=\"24\" text-anchor=\"middle\" opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3.2s\" fill=\"freeze\"/>    <text x=\"120\" y=\"210\" fill=\"#4a7a8c\" font-weight=\"bold\">狗</text>    <text x=\"200\" y=\"210\" fill=\"#4a7a8c\" font-weight=\"bold\">被</text>    <text x=\"280\" y=\"210\" fill=\"#2c3328\">猫</text>    <text x=\"400\" y=\"210\" fill=\"#2c3328\">抓伤了</text>  </g>  <text x=\"320\" y=\"250\" text-anchor=\"middle\" font-size=\"15\" fill=\"#4a7a59\" opacity=\"0\">\"被\"就是承受：狗是受害者，所以狗站到最前面讲自己的遭遇    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.5s\" begin=\"3.8s\" fill=\"freeze\"/>  </text>  <!-- 对比 -->  <g opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"4.4s\" fill=\"freeze\"/>    <text x=\"200\" y=\"280\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">把：我抓苹果（我主动）</text>    <text x=\"440\" y=\"280\" text-anchor=\"middle\" font-size=\"13\" fill=\"#4a7a8c\">被：狗被抓伤（狗倒霉）</text>  </g></svg>","变式表":{"不变":"主（承受者）+被+施事+动+补语，强调承受","可变":{"施事":["出现（杯子被他打碎了）","省略（杯子被打碎了）"],"动补":["动+了（打碎了）","动+补语（修好了）"]},"边界":"主语是承受者（与把字句主语是处置者相对）；'被'可换'叫/让'（口语）；不及物动词不用被；'被'字句多表不幸（'被表扬了'较少）","覆盖已确认":["施事","动补"],"覆盖缺失":[]},"前置知识":["主语","宾语","补语","动词"]},{"name":"存现句","类比":"存现句就像\"监控画面\"：某地（出现了/消失了）某物，讲的是\"有无\"，不是\"谁干了什么\"。","讲解":"表示某处存在、出现、消失某人/物。公式：处所＋动词＋人/物。如\"门口站着一个人\"。","深讲":"存现句表示某处存在、出现、消失某人或物。公式：处所＋动词＋人/物；主语是处所不是人；动词多为有、站、坐、来、去、走出、掉下。","分类":[{"类":"存在式","说明":"某处存在某人或物。","代表":"处所＋站/坐/写着＋人/物","例子":["门口站着一个人。"]},{"类":"出现式","说明":"某处出现某人或物。","代表":"处所＋走出/掉下＋人/物","例子":["屋里走出一位老人。"]},{"类":"消失式","说明":"某处消失某人或物。","代表":"处所＋少/不见＋人/物","例子":["屋里少了一个人。"]}],"怎么认":["主语是不是处所（门口、屋里、天上）？是的。","动词后面是不是人或物？是的。","整句是不是在说哪里有啥、哪里来了啥、哪里少了啥？是的。"],"辨析":"存现句和一般主谓句的区别：存现句主语是处所（门口站着一个人）；一般主谓句主语是人或物（一个人站在门口）。看主语是处所还是人。","例句解析":[{"句":"门口站着一个人。","析":"主语门口是处所，站着表存在，是存现句。"},{"句":"黑板上写着几个大字。","析":"主语黑板上是处所，写着表存在，是存现句。"}],"练习":[{"q":"哪句是存现句？","options":["我看见一个人","门口站着一个人","一个人站在门口"],"answer":1,"解析":"主语是处所门口，表存在。","类":"存在式"},{"q":"“屋里走出一位老人”属于？","options":["存在式","出现式","消失式","被字句"],"answer":1,"解析":"走出表出现。","类":"出现式"},{"q":"存现句的主语是？","options":["人","物","处所","动词"],"answer":2,"解析":"存现句的主语是处所不是人。","类":"存在式"}],"口诀":"哪里有啥，存现回答","例子":["天上掉下个馅饼","屋里走出一位老人","黑板上写着几个大字","天上有一轮明月。","桌子上放着一本书。","门口站着一位老师。","山上开满了野花。","水里游着一群小鱼。","墙上挂着一幅画。","教室里坐着许多学生。","天空中飞过一群大雁。","院子里种着几棵果树。","远处跑来一只小狗。"],"易错":"存现句的动词多为\"有/站/坐/来/去\"，主语是处所不是人","小测":[{"q":"哪句是存现句？","options":["我看见一个人","门口站着一个人","一个人站在门口"],"answer":1,"解析":"主语是处所\"门口\"，表存在。"}],"图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">天上</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">处所：哪里</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">掉下</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">动词：出现/消失</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">个馅饼</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">事物：出现了什么</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">存现句=监控画面：某处出现/消失某物<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"处所+动词+人/物，表示某处存在/出现/消失","可变":{"动词":["存在（有/是）","出现（来/走进）","消失（死/跑了）"],"处所":["句首（天上掉下个馅饼）","具体/抽象"]},"边界":"主语是处所不是施事；动词后名词是存在物（'天上掉馅饼'：馅饼是存在物）；'有'字句（'我有书'）不是存现句（主语是'我'）","覆盖已确认":["动词","处所"],"覆盖缺失":[]},"前置知识":["主语","谓语"]},{"name":"是…的句","类比":"是…的就像\"聚光灯\"：把\"是\"和\"的\"框住的部分照亮，强调\"就是它\"。","动画":{"steps":[{"tokens":["他","是","昨天","来","的"],"note":"强调时间：是\"昨天\"来的"},{"tokens":["他","是","坐飞机","来","的"],"note":"框住\"坐飞机\"：强调方式"},{"tokens":["他","是","北京","人"],"note":"注意：判断句\"他是北京人\"不用\"的\""}]},"讲解":"强调已发生情况的时间/方式/处所。框住被强调成分。","深讲":"是……的句强调已发生情况的时间、方式、处所：是和的框住被强调的成分；只用于已发生的事，没发生的事不能用。","分类":[{"类":"强调时间式","说明":"是和的框住时间。","代表":"是＋昨天＋来的","例子":["我是昨天来的。"]},{"类":"强调方式式","说明":"是和的框住方式。","代表":"是＋坐火车＋走的","例子":["他是坐火车走的。"]},{"类":"强调处所式","说明":"是和的框住处所。","代表":"是＋在北京＋出生的","例子":["他是在北京出生的。"]}],"怎么认":["句子里有没有是……的框住一个成分？有。","这件事是不是已经发生了？是的。","框住的是时间、方式还是处所？对应就是哪种强调。"],"辨析":"是……的句和判断句的区别：是……的句强调已发生情况的状语（我是昨天来的：强调时间）；判断句是说谁是什么（我是学生）。看是后是不是时间、方式、处所。","例句解析":[{"句":"我是昨天来的。","析":"是和的框住昨天，强调时间。"},{"句":"他是坐火车走的。","析":"是和的框住坐火车，强调方式。"}],"练习":[{"q":"“我是昨天来的”强调？","options":["方式","时间","处所","原因"],"answer":1,"解析":"是和的框住昨天，强调时间。","类":"强调时间式"},{"q":"“他是坐火车走的”强调？","options":["时间","方式","处所","原因"],"answer":1,"解析":"是和的框住坐火车，强调方式。","类":"强调方式式"},{"q":"是……的句只用于？","options":["没发生的事","已发生的事","将来的事","假设的事"],"answer":1,"解析":"只用于已发生的事。","类":"强调时间式"}],"口诀":"是的框住，强调突出","例子":["我是昨天来的","他是坐火车走的","这本书是我昨天买的","他是昨天来的。","我是在图书馆看的这本书。","这件事是他告诉我的。","我们是坐火车去的北京。","这幅画是我画的。","她是去年毕业的。","这个消息是妈妈告诉我的。","我是用毛笔写的字。","他们是步行上山的。","这件毛衣是奶奶织的。","我是昨天来的。（'是'可省：我昨天来的）","我是坐车来的。（'的'不可省：✗我是坐车来）"],"易错":"只用于已发生的事；\"是…的\"中间是被强调的状语","图示":"<svg viewBox=\"0 0 640 200\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><text x=\"320\" y=\"60\" text-anchor=\"middle\" font-size=\"20\" fill=\"#2c3328\">我昨天来的<animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/></text><path d=\"M320,90 L320,120\" stroke=\"#4a7a8c\" stroke-width=\"3\" stroke-linecap=\"round\" opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/></path><text x=\"320\" y=\"160\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">我是昨天来的<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"1.5s\" fill=\"freeze\"/></text><text x=\"320\" y=\"190\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">是…的=聚光灯：框住的部分被照亮强调<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.0s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"是+…+的，强调已然情况的时间/方式/处所等","可变":{"强调":["时间（我是昨天来的）","方式（我是走来的）","处所（我在北京买的）","对象（我是给你买的）"],"省略":["'是'可省（我昨天来的）","'的'不可省"]},"边界":"表已然（✗我是明天来的）；'是'后是强调成分不是谓语；与判断句区别：判断句'是'后是名词（他是老师），是…的句'是'后可接动词短语","覆盖已确认":["强调"],"覆盖缺失":["省略"]},"前置知识":["主语","谓语","助词"]},{"name":"比较句","类比":"比较句就像\"天平\"：左边放一个，右边放一个，看哪边重。","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">比较的一方</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">比他高</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">比+比较点</text></g><text x=\"320\" y=\"160\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">比较句=天平：两边放一放，看哪边重<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"1.9s\" fill=\"freeze\"/></text></svg>","讲解":"A 比 B ＋形容词：A 超过 B。否定用\"没有\"（我没有他高≠我比他矮）。","深讲":"比较句是 A 比 B ＋形容词：A 超过 B；否定用没有（我没有他高≠我比他矮）；更表递进（更好）。","分类":[{"类":"比字句","说明":"用比表示超过。","代表":"A 比 B ＋形容词","例子":["我比他高。"]},{"类":"没有字句","说明":"用没有表示否定比较。","代表":"A 没有 B ＋形容词","例子":["今天没有昨天冷。"]},{"类":"更字句","说明":"用更表示递进。","代表":"A 比 B 更＋形容词","例子":["他比以前更好了。"]}],"怎么认":["句子里有没有比、没有、更？有。","比后面是不是参照对象？是的。","句末是不是形容词？是的。"],"辨析":"没有字句和比字句的区别：没有只否定比（我没有他高：我不如他高，不等于我比他矮）；比是肯定超过（我比他高）。看有没有没有。","例句解析":[{"句":"我比他高。","析":"比后是参照他，句末形容词高，是比字句。"},{"句":"今天没有昨天冷。","析":"没有表示否定比较，是没有字句。"}],"练习":[{"q":"“我没有他高”意思是？","options":["我比他矮","我不如他高","他比我矮"],"answer":1,"解析":"没有只否定比他高，不等于反向。","类":"没有字句"},{"q":"“弟弟比我高半头”属于？","options":["比字句","没有字句","更字句","把字句"],"answer":0,"解析":"比后是参照我，句末高半头。","类":"比字句"},{"q":"“更”表？","options":["否定","递进","比较","假设"],"answer":1,"解析":"更表递进（更好）。","类":"更字句"}],"口诀":"比后参照，形容收尾","例子":["我比他高","今天没有昨天冷","弟弟比我高半头","他比我高。","这本书比那本书有趣。","今天比昨天冷。","小明跑得比小红快。","西瓜比苹果甜。","他的成绩比我好得多。","这座山比那座山高。","夏天比冬天热。","我更喜欢红色。","弟弟不如哥哥高。"],"易错":"\"没有\"表否定比较，不表反向；\"更\"表递进（更好）","小测":[{"q":"\"我没有他高\"意思是？","options":["我比他矮","我不如他高","他比我矮"],"answer":1,"解析":"\"没有\"只否定\"比他高\"，不等于反向。"}],"变式表":{"不变":"比较两者的异同、 high低","可变":{"类型":["比字句（他比我高）","没有（他没有我高）","更/最（更高/最高）","像…一样（像他一样高）"],"比较点":["性质（高）","动作（跑得快）","数量（多）"]},"边界":"'比'后是比较对象（'他比我高'：比我）；'更'须有比较对象（✗他更高了，无对象时表程度加深）；自比（'比以前好'）也成立","覆盖已确认":["类型","比较点"],"覆盖缺失":[]},"前置知识":["形容词","主语"]},{"name":"双重否定","类比":"双重否定就像\"负负得正\"：两个\"不\"撞在一起，变成强烈的肯定。","讲解":"不得不＝必须；不能不＝一定要。语气比单用\"必须\"更强烈、更无奈。","深讲":"双重否定是两个否定词连用，意思变成肯定：不得不＝必须，不能不＝一定要；语气比单用必须更强烈、更无奈。","分类":[{"类":"不得不式","说明":"不得不等于必须。","代表":"不得不＋动词","例子":["我不得不去。"]},{"类":"不能不式","说明":"不能不等于一定要。","代表":"不能不＋动词","例子":["他不能不承认。"]},{"类":"不会不式","说明":"不会不等于一定会。","代表":"不会不＋动词","例子":["他不会不来。"]}],"怎么认":["句子里有没有两个否定词（不、没、无、非）？有。","两个否定算一算，是不是变成肯定？是的。","语气是不是比单说必须更强烈？是的。"],"辨析":"双重否定和单否定不要搞混：不得不去＝必须去（肯定），不是不去；不能不承认＝一定要承认。算清否定，意思就对了。","例句解析":[{"句":"我不得不去。","析":"不得不等于必须，是双重否定。"},{"句":"我不得不承认他是对的。","析":"不得不等于必须承认，是双重否定。"}],"练习":[{"q":"“我不得不去”意思是？","options":["我不去","我必须去","我不想去","我没去"],"answer":1,"解析":"不得不等于必须。","类":"不得不式"},{"q":"“他不能不承认”意思是？","options":["他不承认","他一定要承认","他不想承认","他没承认"],"answer":1,"解析":"不能不等于一定要。","类":"不能不式"},{"q":"“他不会不来”意思是？","options":["他不来","他一定来","他可能不来","他不想来"],"answer":1,"解析":"不会不等于一定会。","类":"不会不式"}],"口诀":"双否变肯，语气加倍","例子":["我不得不去","他不能不承认","我不得不承认他是对的","他不得不承认错误。（=他必须承认错误）","这件事非他莫属。（=这件事一定是他）","没有人不喜欢和平。（=人都喜欢和平）","我不会不去的。（=我一定去）","这不是不重要。（=这很重要）","他无时无刻不在想念家乡。（=他一直想念家乡）","没有谁不渴望成功。（=都渴望成功）","这个道理不讲不明。（=讲了就明）","我不能不帮他。（=我一定要帮他）","没有付出就没有收获。（双重否定表强调）","他不能不说。（弱：语气较轻）","这件事非办不可。（强：语气强烈）"],"易错":"\"不会不\"（他不会不来＝他一定来）别和\"不\"搞混","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">双重否定：两个\"不\"互相抵消</text><text x=\"12\" y=\"44\" font-size=\"13\" class=\"svg-muted\">我不得不去 ＝ ?</text><text x=\"20\" y=\"84\" font-size=\"22\" class=\"svg-ink\">我</text><text x=\"92\" y=\"84\" font-size=\"22\" class=\"svg-accent\" opacity=\"1\">得<animate attributeName=\"opacity\" values=\"1;1;0;0;0;1\" keyTimes=\"0;0.3;0.45;0.9;0.95;1\" dur=\"8s\" /></text><text x=\"164\" y=\"84\" font-size=\"22\" class=\"svg-ink\">去</text><text x=\"56\" y=\"84\" font-size=\"22\" class=\"svg-red\">不<animate attributeName=\"x\" values=\"56;56;104;104;104;56\" keyTimes=\"0;0.3;0.45;0.9;0.95;1\" dur=\"8s\" /><animate attributeName=\"opacity\" values=\"1;1;1;0;0;1\" keyTimes=\"0;0.3;0.45;0.55;0.9;1\" dur=\"8s\" /></text><text x=\"128\" y=\"84\" font-size=\"22\" class=\"svg-red\">不<animate attributeName=\"x\" values=\"128;128;104;104;104;128\" keyTimes=\"0;0.3;0.45;0.9;0.95;1\" dur=\"8s\" /><animate attributeName=\"opacity\" values=\"1;1;1;0;0;1\" keyTimes=\"0;0.3;0.45;0.55;0.9;1\" dur=\"8s\" /></text><text x=\"56\" y=\"84\" font-size=\"22\" class=\"svg-accent\" opacity=\"0\">一定要<animate attributeName=\"opacity\" values=\"0;0;0;1;1;0\" keyTimes=\"0;0.5;0.6;0.9;0.95;1\" dur=\"8s\" /></text><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">两个\"不\"飞到一起抵消 → 我一定要去（肯定）</text></svg>","变式表":{"不变":"两个否定表肯定，语气比单肯定强","可变":{"形式":["不得不（不得不去=必须去）","不会不（不会不知道=肯定知道）","没有…不…（没有人不…=都…）"],"强度":["弱（不能不说）","强（非去不可）"]},"边界":"双否=肯定（'不得不去'=去）；三重否定表否定（'我不是不知道'=知道，实际是双否）；口语'不…不…'（'不吃不喝'）是并列不是双否","覆盖已确认":["形式"],"覆盖缺失":["强度"]},"前置知识":["副词"]},{"name":"歧义句","类比":"歧义句就像\"魔术贴\"：一句话能贴出两种意思，病句题最爱考。","动画":{"steps":[{"tokens":["咬","死","了","猎人","的","狗"],"note":"切分A：(咬死了猎人)的狗——狗咬死了猎人"},{"tokens":["咬","死","了","猎人","的","狗"],"note":"切分B：咬死了(猎人的狗)——猎人的狗被咬死了"}]},"讲解":"一句话有两种理解。消歧方法：换切分、加标点、改语序。","深讲":"病句表意不明多为歧义，改法是明确主语或加标点。","分类":[{"类":"切分歧义","说明":"断句不同，意思不同。","代表":"鸡不吃了","例子":["鸡不吃了。"]},{"类":"语义歧义","说明":"一个词、一个说法有两种意思。","代表":"走了一个小时","例子":["他走了一个小时。"]},{"类":"指代歧义","说明":"代词不知道指谁。","代表":"他说他不去了","例子":["他说他不去了。"]}],"怎么认":["一句话能不能有两种理解？能，就是歧义。","换个切分，意思变不变？变，就是切分歧义。","代词指谁说不清？就是指代歧义。"],"辨析":"歧义句和病句表意不明的关系：歧义句是现象（一句话两种理解），表意不明是毛病（要改掉）；消歧的方法是换切分、加标点、改语序、明确主语。","例句解析":[{"句":"鸡不吃了。","析":"切分不同：鸡不吃／人不吃鸡，是切分歧义。"},{"句":"他走了一个小时。","析":"走可以是离开，也可以是步行，是语义歧义。"}],"练习":[{"q":"“咬死了猎人的狗”有几种理解？","options":["1种","2种","3种"],"answer":1,"解析":"两种切分，两种意思。","类":"切分歧义"},{"q":"“他走了一个小时”属于？","options":["切分歧义","语义歧义","指代歧义","把字句"],"answer":1,"解析":"走有离开和步行两种意思。","类":"语义歧义"},{"q":"“他说他不去了”属于？","options":["切分歧义","语义歧义","指代歧义","存现句"],"answer":2,"解析":"不知道是谁不去，是指代歧义。","类":"指代歧义"}],"口诀":"两切两意，歧义现形","例子":["鸡不吃了（鸡不吃/人不吃鸡）","他走了一个小时（离开/步行）","他说他不去了（到底谁不去？）","咬死了猎人的狗。（谁咬死谁？有歧义）","他背着总经理去开会。（他背？还是总经理背？）","数理化学习经验。（数理化学/习经验？）","我想起来了。（想起/起来？）","开刀的是他父亲。（他动手术？他是医生？）","这辆车没有锁。（没锁车/车没锁？）","他说不好。（说得不好/说不行？）","校长请老师吃饭。（谁请谁？）","雨天没有晴天多。（比较对象不明）","咬死了猎人的狗。（结构歧义：谁咬谁？）","他方便的时候你来。（词汇歧义：'方便'多义）","期中考试。（多音字成因：期中/期终？）","他一个人走了。（指代不明成因：独自去/他先走？）"],"易错":"病句\"表意不明\"多为歧义；改法：明确主语或加标点","小测":[{"q":"\"咬死了猎人的狗\"有几种理解？","options":["1种","2种","3种"],"answer":1,"解析":"两种切分，两种意思。"}],"图示":"<svg viewBox=\"0 0 640 280\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g id=\"wrongG\"><text x=\"320\" y=\"80\" text-anchor=\"middle\" font-size=\"20\" fill=\"#b85a52\">咬死了猎人的狗</text><text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#b85a52\">✘ 谁咬谁？说不清</text><animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;-5,0;5,0;-5,0;0,0\" dur=\"0.4s\" begin=\"1.0s\" fill=\"freeze\"/><animate attributeName=\"opacity\" values=\"1;0\" dur=\"0.5s\" begin=\"1.5s\" fill=\"freeze\"/></g><text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"32\" fill=\"#4a7a59\" opacity=\"0\">✓<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/></text><text x=\"320\" y=\"200\" text-anchor=\"middle\" font-size=\"20\" fill=\"#4a7a59\" font-weight=\"bold\" opacity=\"0\">狗咬死了猎人<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.2s\" fill=\"freeze\"/></text><text x=\"320\" y=\"240\" text-anchor=\"middle\" font-size=\"13\" fill=\"#6b7566\" opacity=\"0\">加主语说清楚，歧义消除<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.6s\" fill=\"freeze\"/></text></svg>","变式表":{"不变":"一句话有两种以上理解","可变":{"类型":["语音歧义（'期中考试'断句）","词汇歧义（'方便'多义）","结构歧义（'咬死了猎人的狗'：谁咬谁）","语义指向歧义（'他一个人走了'）"],"成因":["多音字","多义词","结构","指代不明"]},"边界":"歧义是客观存在（不是病句）；消除靠加语境/标点/改词；病句是错，歧义是'可对可错'——考试常考辨析","覆盖已确认":[],"覆盖缺失":["类型","成因"]},"前置知识":["主语","谓语","宾语","定语"]},{"name":"兼语句","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我请他吃饭。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“他”兼两职：是“请”的宾语，又是“吃”的主语。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">这件事使我很感动。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“我”兼两职：是“使”的宾语，又是“感动”的主体。主语“这件事”是事情的起因。</text></g></svg>","讲解":"一句话里，有个人或物“一身兼两职”：既是前一个动词的宾语，又是后一个动词的主语。","深讲":"兼语句的公式：主语 + 动词1 + 兼语 + 动词2。比如“我请他吃饭”：“他”既是“请”的宾语（我请他），又是“吃”的主语（他吃饭）。动词1多是“让/叫/请/使/派”这类带“使唤”意思的词。否定词放动词1前面：“老师没让我去”。（来源：AllSet Chinese Grammar Wiki，CC BY-NC-SA 3.0）","类比":"兼语句像接力赛：第一棒（请）把接力棒（他）交出去，“他”接到棒立刻跑第二棒（吃）——一个人跑了两棒。","口诀":"一人兼两职，前宾后主是他","例子":["我请他吃饭。","妈妈让我学钢琴。","老师请他进来。","公司派我出国。","这件事使我很感动。","这部电影让大家都哭了。","老师没让我交作业。","他的话使妹妹决定去工作。"],"易错":"“使”偏书面，“让”偏口语；“请”是请求，“让”还可以是允许或致使，别乱换。","分类":[{"类":"使令兼语","说明":"动词1是要求、派遣：请/派/要求/叫。","代表":"请他进来、派我出国","例子":["老师请他进来。","公司派我出国。"]},{"类":"致使兼语","说明":"动词1是导致某种结果或心情：让/使。","代表":"让我感动、使我高兴","例子":["这件事使我很感动。","这部电影让大家都哭了。"]},{"类":"否定式","说明":"不/没放在动词1前面。","代表":"没让我去","例子":["老师没让我交作业。","妈妈没让我看电视。"]}],"怎么认":["找“让/叫/请/使/派”这类词。","看它后面的人后面还有没有动词：有→可能是兼语。","那个人是不是“前是宾、后是主”：我请他（宾）+他吃饭（主）✓。"],"辨析":"兼语句和连动句的区别：连动句是同一个人做两件事（“我去北京看朋友”——去和看都是我）；兼语句是中间换了人（“我请他吃饭”——吃的是他不是我）。看第二件事是谁做的。","例句解析":[{"句":"我请他吃饭。","析":"“他”兼两职：是“请”的宾语（我请他），又是“吃”的主语（他吃饭）。"},{"句":"这件事使我很感动。","析":"“我”兼两职：是“使”的宾语，又是“感动”的主体（我很感动）。主语“这件事”是事情的起因。"}],"练习":[{"q":"“妈妈让我学钢琴”中，兼语是？","options":["妈妈","让","我","钢琴"],"answer":2,"解析":"“我”既是“让”的宾语，又是“学”的主语。","类":"结构"},{"q":"哪句是兼语句？","options":["我去北京看朋友","我请他吃饭","他喜欢唱歌","我们一起回家"],"answer":1,"解析":"“我请他吃饭”中“他”兼两职；“我去北京看朋友”是连动句。","类":"辨析"},{"q":"“老师没让我交作业”的否定词放哪？","options":["让后面","让我中间","让前面","句末"],"answer":2,"解析":"否定词放在动词1“让”的前面。","类":"否定"},{"q":"“使”和“让”有什么不同？","options":["没区别","使偏书面，让偏口语","使只能口语","让只能书面"],"answer":1,"解析":"“使”多用于书面正式场合，“让”口语常用。","类":"辨析"}],"前置知识":["主语","谓语","宾语","动词"]},{"name":"话题句","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">那部电影，看过的人都喜欢。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“那部电影”是话题，“看过的人都喜欢”是评论。正常语序是“看过那部电影的人都喜欢”。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">他身体很好。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">这是主谓谓语句：“他”是大话题，“身体很好”是个小主谓句，说明“他”的情况。</text></g></svg>","讲解":"把要强调的部分提前到句首当“话题”，后面再对它发表“评论”，话题和评论之间常有停顿。","深讲":"话题句的结构：话题 + 评论。比如“那部电影，看过的人都喜欢”：“那部电影”是话题（要强调的），“看过的人都喜欢”是评论。话题常常是宾语提前（“水果，我最爱吃草莓”）。主谓谓语句是话题句的一种：大主语带着小主谓（“他身体很好”：“他”是大话题，“身体很好”是小主谓）。（来源：AllSet Chinese Grammar Wiki，CC BY-NC-SA 3.0）","类比":"话题句像演出报幕：先报节目名（话题：下面请听《那部电影》），再正式演出（评论：看过的人都喜欢）。","口诀":"强调谁提前谁，话题评论逗号隔","例子":["那部电影，看过的人都喜欢。","水果，我最爱吃草莓。","这个问题，你一个人没办法解决。","你借我的钱，还没还吧？","他身体很好。","北京的话，秋天去最好。","那道菜，我已经吃了。","找对象，他特别挑剔。"],"易错":"话题和评论意思要相关；书面写话题句，话题后别忘了逗号（停顿）。","分类":[{"类":"宾语话题","说明":"把宾语提前当话题，后面评论。","代表":"水果，我爱吃","例子":["水果，我最爱吃草莓。","那道菜，我已经吃了。"]},{"类":"主谓谓语句","说明":"大主语 + 小主谓，小主谓说明大主语。","代表":"他身体很好","例子":["他身体很好。","她的话很多。"]},{"类":"时间处所话题","说明":"时间或地点提前，强调背景。","代表":"北京的话","例子":["北京的话，秋天去最好。","明天，我去你家。"]}],"怎么认":["句首的名词后是不是直接跟了个完整句子？是→可能是话题句。","把句首词放回动词后面，句子还通不通？通→是话题提前。","话题后有没有停顿（逗号）？有→更像话题句。"],"辨析":"话题句和一般主谓句的区别：一般主谓句的主语是动作的发出者；话题句的话题不一定是施事（“这件事你决定”——真正做决定的是“你”，“这件事”只是话题）。看句首词是不是动作的发出者。","例句解析":[{"句":"那部电影，看过的人都喜欢。","析":"“那部电影”是话题（被提前的宾语），“看过的人都喜欢”是评论。正常语序是“看过那部电影的人都喜欢”。"},{"句":"他身体很好。","析":"这是主谓谓语句：“他”是大话题，“身体很好”是个小主谓句，说明“他”的情况。"}],"练习":[{"q":"“水果，我最爱吃草莓”中，话题是？","options":["我","最爱","水果","草莓"],"answer":2,"解析":"“水果”被提前到句首当话题，后面是评论。","类":"结构"},{"q":"哪句是话题句？","options":["我吃苹果","那本书，我看了三遍","他跑得快","今天下雨"],"answer":1,"解析":"“那本书”提前当话题，后面“ 我看了三遍”是评论。","类":"辨析"},{"q":"“他身体很好”是什么句式？","options":["主谓句","主谓谓语句","把字句","被字句"],"answer":1,"解析":"大主语“他”+小主谓“身体很好”，是主谓谓语句。","类":"结构"},{"q":"话题句书面写的时候，话题后常加什么？","options":["句号","逗号","问号","顿号"],"answer":1,"解析":"话题后有停顿，书面用逗号隔开。","类":"书写"}],"前置知识":["主语","宾语"]},{"name":"给字被动","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">事情给解决了吗？</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“事情”是承受者，“给”是被动标记，发出者省略了。= 事情被解决了吗？</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">他给老师给批评了一顿。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">完整结构：他+给+老师+给+批评。口语里两个“给”连用很常见。</text></g></svg>","讲解":"口语里的被动句不用“被”，用“给”：事情给解决了吗？= 事情被解决了吗？","深讲":"结构：承受者 + 给 +（动作发出者）+ 给 + 动词。比如“事情给解决了吗”（发出者省略）、“钱给他给花光了”（发出者是“他”，两个“给”）。“给”字被动多用于口语，常带“倒霉、意外”的味道（“车给撞了”“钱包给偷了”）。正式书面语还是用“被”。（来源：AllSet Chinese Grammar Wiki，CC BY-NC-SA 3.0）","类比":"“给”字被动像“被”字的口语替身演员：正式场合“被”上场，胡同里聊天“给”上场，演的是同一出戏。","口诀":"口语被动不用被，给字顶上也对味","例子":["事情给解决了吗？","钱给花光了。","车给撞了。","我的钱包给偷了。","他给老师给批评了一顿。","这事儿给忘了。","手机给摔坏了。"],"易错":"书面正式场合用“被”，口语才用“给”；“给”在这里是被动标记，不是“送给”的动词，别按“给东西”理解。","分类":[{"类":"省略发出者","说明":"不说谁干的，只说结果。","代表":"钱给花光了","例子":["钱给花光了。","车给撞了。"]},{"类":"带发出者","说明":"承受者+给+发出者+给+动词。","代表":"他给老师给批评了","例子":["他给老师给批评了一顿。","事情给他给办了。"]}],"怎么认":["主语是不是受事（被…的那个）？是→可能是被动。","动词前有没有“给”？有→可能是给字被动。","换成“被”字意思变不变？不变→就是被动句。"],"辨析":"给字被动 vs 被字句：意思一样，语体不同（给=口语，被=通用/书面）。给字被动 vs 把字句：把字句强调“处置”（我把作业写完了），给字被动强调“承受”（作业给写完了）。看主语是处置者还是承受者。","例句解析":[{"句":"事情给解决了吗？","析":"“事情”是承受者，“给”是被动标记，发出者省略了。= 事情被解决了吗？"},{"句":"他给老师给批评了一顿。","析":"完整结构：他（承受者）+给+老师（发出者）+给+批评。口语里两个“给”连用很常见。"}],"练习":[{"q":"“钱给花光了”换成“被”字句是？","options":["钱把花光了","钱被花光了","钱给花光被","钱花光了给"],"answer":1,"解析":"“给”换成“被”，意思不变：钱被花光了。","类":"辨析"},{"q":"哪句是给字被动？","options":["我给他钱","车给撞了","把书给他","他给了我一本书"],"answer":1,"解析":"“车给撞了”：车是承受者，“给”是被动标记。其余的“给”是动词（送给）。","类":"辨析"},{"q":"给字被动多用于？","options":["书面正式","口语","古文","法律文书"],"answer":1,"解析":"“给”字被动是口语说法，正式书面语用“被”。","类":"语体"},{"q":"“他给老师给批评了”有几个“给”？","options":["1个","2个","3个","0个"],"answer":1,"解析":"带发出者时是两个“给”：他+给+老师+给+批评。","类":"结构"}],"前置知识":["被字句","主语","宾语"]}]},{"id":"xuci","name":"虚词精讲（16组）","items":[{"name":"了/着/过","类比":"\"了\"像拍照\"咔嚓\"（事成了/情况变了），\"着\"像视频\"录制中\"（持续），\"过\"像相册\"曾经\"（有过经历）。","图示":"<svg viewBox=\"0 0 320 170\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">了 / 着 / 过：一个管\"完\"，一个管\"在\"，一个管\"过\"</text><text x=\"12\" y=\"40\" font-size=\"18\" class=\"svg-accent\">着<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" /></text><text x=\"36\" y=\"40\" font-size=\"15\" class=\"svg-ink\">我吃着饭</text><text x=\"190\" y=\"40\" font-size=\"12\" class=\"svg-accent\">正在进行<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" /></text><rect x=\"12\" y=\"48\" width=\"0\" height=\"4\" rx=\"2\" opacity=\"0.55\" class=\"svg-accent\"><animate attributeName=\"width\" values=\"0;140;140;0;0\" keyTimes=\"0;0.28;0.3;0.33;1\" dur=\"9s\" /></rect><text x=\"12\" y=\"76\" font-size=\"18\" class=\"svg-accent\">了<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" /></text><text x=\"36\" y=\"76\" font-size=\"15\" class=\"svg-ink\">我吃了饭</text><text x=\"190\" y=\"76\" font-size=\"12\" class=\"svg-accent\">已经完成<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" /></text><rect x=\"12\" y=\"84\" width=\"0\" height=\"4\" rx=\"2\" opacity=\"0.55\" class=\"svg-accent\"><animate attributeName=\"width\" values=\"0;0;140;140;0;0\" keyTimes=\"0;0.31;0.33;0.58;0.63;1\" dur=\"9s\" /></rect><text x=\"12\" y=\"112\" font-size=\"18\" class=\"svg-accent\">过<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" /></text><text x=\"36\" y=\"112\" font-size=\"15\" class=\"svg-ink\">我吃过饭</text><text x=\"190\" y=\"112\" font-size=\"12\" class=\"svg-accent\">以前有过<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" /></text><rect x=\"12\" y=\"120\" width=\"0\" height=\"4\" rx=\"2\" opacity=\"0.55\" class=\"svg-accent\"><animate attributeName=\"width\" values=\"0;0;140;140;0;0\" keyTimes=\"0;0.61;0.63;0.88;0.93;1\" dur=\"9s\" /></rect><text x=\"12\" y=\"158\" font-size=\"12\" class=\"svg-muted\">着＝正在、了＝完了、过＝有过经历</text></svg>","动画":{"steps":[{"tokens":["我","吃","了","饭"],"note":"了₁跟动词：吃完了"},{"tokens":["下","雨","了"],"note":"了₂在句末：新情况，天开始下雨"},{"tokens":["他","正","看","着","书"],"note":"着：动作持续进行中"},{"tokens":["我","去","过","北京"],"note":"过：曾经有过去北京的经历"}]},"讲解":"了₁表完成（动词后），了₂表变化（句末）；着表持续；过表经历。","深讲":"了有两种：了₁在动词后表完成，了₂在句末表变化；着表持续；过表经历。注意了₁和了₂不叠用，不能说我昨天去了北京了。","分类":[{"类":"了₁完成式","说明":"动词后的了，表动作完成。","代表":"动词＋了","例子":["我吃了饭。"]},{"类":"了₂变化式","说明":"句末的了，表出现新情况。","代表":"句末＋了","例子":["太好了。"]},{"类":"着持续式","说明":"动词后的着，表动作持续。","代表":"动词＋着","例子":["他看着书。"]},{"类":"过经历式","说明":"动词后的过，表曾经的经历。","代表":"动词＋过","例子":["我去过长城。"]}],"怎么认":["了在动词后还是句末？动词后是了₁，句末是了₂。","动作是不是在持续？持续用着。","是不是在说曾经？曾经用过。"],"辨析":"了₁和了₂的区别：了₁在动词后表完成（我吃了饭）；了₂在句末表变化（太好了）。我吃饭了的了是了₂，表新情况，不是了₁。","例句解析":[{"句":"我吃了饭。","析":"吃了后的了在动词后，表完成，是了₁。"},{"句":"妹妹正哭着找妈妈。","析":"哭着的着表动作持续，是着持续式。"}],"练习":[{"q":"“我吃饭了”的了是？","options":["了₁完成","了₂变化","都是"],"answer":1,"解析":"句末表新情况，是了₂。","类":"了₂变化式"},{"q":"表“曾经”用？","options":["了","着","过"],"answer":2,"解析":"去过＝有过去的经历。","类":"过经历式"},{"q":"“他看着书”的着表？","options":["完成","持续","经历"],"answer":1,"解析":"看着表动作持续。","类":"着持续式"}],"口诀":"了表完成着表持续，过表曾经经历","例子":["我吃了饭","太好了","他看着书","我去过长城","我昨天去过动物园","妹妹正哭着找妈妈","我吃了饭。（了：完成）","他正看着书。（着：进行）","我去过北京。（过：经历）","天黑了。（了：变化）","门开着。（着：状态持续）","他读过这本书。（过：曾经）","下雨了，快回家吧。（了）","他笑着说话。（着）"],"易错":"✗ 我昨天去了北京了（了₁了₂不叠用）","小测":[{"q":"\"我吃饭了\" 的\"了\"是？","options":["了₁完成","了₂变化","都是"],"answer":1,"解析":"句末表新情况（开始吃饭/吃完），是了₂。"},{"q":"表\"曾经\"用？","options":["了","着","过"],"answer":2,"解析":"\"去过\"＝有过去的经历。"}],"对照表":{"维度":["含义","用法","例句","误用"],"对比":[["了₁","含义：在动词后，表动作完成；用法：动词+了₁；例句：我吃了饭；误用：“我吃饭了”的了是了₂不是了₁，不要混"],["了₂","含义：在句末，表变化/新情况；用法：句末+了₂；例句：太好了；误用：“我吃饭了”的了是了₂，表新情况"],["着","含义：表进行/状态持续；用法：动词+着；例句：他看着书；门开着；误用：“正”字句一般不用“着”收尾"],["过","含义：表经历（曾经）；用法：动词+过；例句：我去过长城；误用：表一次完成不用“过”，用“了₁”"]]},"前置知识":["助词","动词"]},{"name":"的/地/得","类比":"的像\"标签\"（贴名词），地像\"滤镜\"（修饰动作），得像\"成绩单\"（动作后打分）。","图示":"<svg viewBox=\"0 0 640 320\" id=\"svg\">  <!-- 正确的 -->  <text x=\"320\" y=\"35\" text-anchor=\"middle\" font-size=\"14\" fill=\"#6b7566\">先看对的：</text>  <g font-size=\"22\" text-anchor=\"middle\">    <text x=\"200\" y=\"75\" fill=\"#2c3328\">他</text>    <text x=\"280\" y=\"75\" fill=\"#4a7a59\" font-weight=\"bold\">快乐地</text>    <text x=\"380\" y=\"75\" fill=\"#2c3328\">跑着</text>  </g>  <text x=\"320\" y=\"105\" text-anchor=\"middle\" font-size=\"16\" fill=\"#4a7a59\" opacity=\"0\">✓ 地：动词前面，稳稳的    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.0s\" fill=\"freeze\"/>  </text>  <!-- 错误的 -->  <text x=\"320\" y=\"150\" text-anchor=\"middle\" font-size=\"14\" fill=\"#6b7566\" opacity=\"0\">再看错的：    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.8s\" fill=\"freeze\"/>  </text>  <g font-size=\"22\" text-anchor=\"middle\" opacity=\"0\" id=\"wrong\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.0s\" fill=\"freeze\"/>    <text x=\"200\" y=\"190\" fill=\"#2c3328\">他</text>    <text x=\"280\" y=\"190\" fill=\"#b85a52\" font-weight=\"bold\" id=\"wrongDe\">快乐的</text>    <text x=\"380\" y=\"190\" fill=\"#2c3328\">跑着</text>  </g>  <!-- 散架效果：错字掉下去 -->  <g opacity=\"0\" id=\"breakApart\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.2s\" begin=\"2.8s\" fill=\"freeze\"/>    <animateTransform attributeName=\"transform\" type=\"translate\" values=\"0,0;0,40\" dur=\"0.6s\" begin=\"2.8s\" fill=\"freeze\"/>    <text x=\"280\" y=\"190\" text-anchor=\"middle\" font-size=\"22\" fill=\"#b85a52\" font-weight=\"bold\" opacity=\"0.5\">快乐的</text>  </g>  <animate xlink:href=\"#wrongDe\" attributeName=\"opacity\" values=\"1;0\" dur=\"0.3s\" begin=\"2.8s\" fill=\"freeze\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"/>  <text x=\"320\" y=\"250\" text-anchor=\"middle\" font-size=\"16\" fill=\"#b85a52\" opacity=\"0\">✗ \"的\"后面要跟名词，\"跑着\"是动词，句子散架了    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3.2s\" fill=\"freeze\"/>  </text>  <!-- 口诀 -->  <g opacity=\"0\">    <animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"4.0s\" fill=\"freeze\"/>    <rect x=\"120\" y=\"270\" width=\"400\" height=\"36\" rx=\"8\" fill=\"#d3e5d6\"/>    <text x=\"320\" y=\"294\" text-anchor=\"middle\" font-size=\"15\" fill=\"#2c3328\">口诀：的地得，不分家；名词动词，找准它</text>  </g></svg>","讲解":"的＋名词（定语），地＋动词（状语），得＋补语。口诀：的地得，不一样；名前的（白勺）的，动前的（土也）地，动后的得。","深讲":"口诀：白勺的贴名，土也地跟动，得后补结果。","分类":[{"类":"的定语式","说明":"的后面是名词，修饰名词。","代表":"的＋名词","例子":["美丽的花。"]},{"类":"地状语式","说明":"地后面是动词，修饰动词。","代表":"地＋动词","例子":["认真地听。"]},{"类":"得补语式","说明":"得后面是补语，补充动词结果。","代表":"动词＋得＋补语","例子":["跑得快。"]}],"怎么认":["后面是不是名词？名词前的用白勺的。","后面是不是动词？动词前的用土也地。","是不是在动词后补结果？补结果的用得。"],"辨析":"的地得不要混：的贴名（美丽的花），地跟动（认真地听），得后补结果（跑得快）。看后面的词是名词、动词还是补语。","例句解析":[{"句":"美丽的花。","析":"的后面是名词花，是定语，用白勺的。"},{"句":"他高兴地笑了。","析":"地后面是动词笑，是状语，用土也地。"}],"练习":[{"q":"“认真_听讲”填？","options":["的","地","得"],"answer":1,"解析":"修饰动词听，用地。","类":"地状语式"},{"q":"“跑_很快”填？","options":["的","地","得"],"answer":2,"解析":"动词后补结果，用得。","类":"得补语式"},{"q":"“美丽_花”填？","options":["的","地","得"],"answer":0,"解析":"后面是名词花，用白勺的。","类":"的定语式"}],"口诀":"白勺的贴名，土也地跟动，得后补结果","例子":["美丽的花","认真地听","跑得快","他高兴地笑了","这道题做得真好","美丽的花。（的+名词）","认真地听讲。（地+动词）","跑得快。（得+补语）","可爱的孩子。（的）","高兴地说。（地）","写得好。（得）","红红的苹果。（的）"],"易错":"的地得是小学高频错；记住\"的地得\"顺口溜","小测":[{"q":"\"认真_听讲\"填？","options":["的","地","得"],"answer":1,"解析":"修饰动词\"听\"，用\"地\"。"},{"q":"\"跑_很快\"填？","options":["的","地","得"],"answer":2,"解析":"动词后补结果，用\"得\"。"}],"对照表":{"维度":["含义","用法","例句","误用"],"对比":[["的","含义：贴名词（定语的标志）；用法：的+名词；例句：美丽的花；误用：❌“认真的话”（修饰动词“说”该用“地”）"],["地","含义：跟动词（状语的标志）；用法：地+动词；例句：认真地听；误用：❌“高兴的话”（修饰动词“说”）→ ✅“高兴地说”"],["得","含义：后接补语（结果/程度）；用法：动词/形容词+得+补语；例句：跑得快；误用：❌“跑的快”→ ✅“跑得快”"]]},"前置知识":["定语","状语","补语","助词"]},{"name":"在/再","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我在教室里读书。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">在表处所教室里，是在处所式。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">妈妈说明天再去公园。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">再表又一次去，是再重复式。</text></g></svg>","讲解":"“在”表处所、存在，“再”表重复、又一次。读音一样（zài），看意思选字。","深讲":"在和再读音一样（zài），意思不同：在表处所、存在，再表重复、又一次。看意思选字，不能只听读音。","分类":[{"类":"在处所式","说明":"在表处所、存在。","代表":"在＋处所","例子":["我在教室里读书。"]},{"类":"再重复式","说明":"再表又一次、重复。","代表":"再＋动词","例子":["妈妈说明天再去公园。"]}],"怎么认":["是不是在说哪里？哪里用在。","是不是在说又一次？又一次用再。","换成处所或又一次，意思通吗？通的就是对的。"],"辨析":"在和再的区别：在是处所（我在教室里），再是重复（再说一遍）。请在说一遍是错的，应为请再说一遍。","例句解析":[{"句":"我在教室里读书。","析":"在表处所教室里，是在处所式。"},{"句":"妈妈说明天再去公园。","析":"再表又一次去，是再重复式。"}],"练习":[{"q":"“请_说一遍”填？","options":["在","再"],"answer":1,"解析":"又一次说，用再。","类":"再重复式"},{"q":"“我_教室里读书”填？","options":["在","再"],"answer":0,"解析":"表处所，用在。","类":"在处所式"},{"q":"“我_吃一次”填？","options":["在","再"],"answer":1,"解析":"又一次吃，用再。","类":"再重复式"}],"例子":["我在教室里读书（处所）","妈妈说明天再去公园（又一次）","✗ 我在吃一次 → ✓ 我再吃一次","我在学校上课。（在：处所）","我们再见面吧。（再：又一次）","他在家里看书。（在）","请再说一遍。（再）","小鸟在天上飞。（在）","明天再来吧。（再）","他在操场上跑步。（在）","吃完饭再出去玩。（再）","鱼在水里游。（在）"],"口诀":"处所在，再又来","易错":"✗ 请在说一遍 → ✓ 请再说一遍","类比":"“在”像图钉📌，钉住地点；“再”像回放键🔁，事情重来一遍。","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["在","含义：表处所；用法：在+处所；例句：我在教室里读书；误用：❌“请在说一遍”→ ✅“请再说一遍”"],["再","含义：表重复（又一次）；用法：再+动词；例句：明天再去公园；误用：❌“我在吃一次”→ ✅“我再吃一次”"]]},"前置知识":["副词","介词"]},{"name":"做/作","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">做作业、做饭、做游戏。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">都是动手干的活，用做。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">作文、作品、作为。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">都是抽象创作、书面词，用作。</text></g></svg>","讲解":"“做”多指具体动手干，“作”多指抽象创作。口语多用“做”，书面语“作”更多。","深讲":"做多指具体动手干，作多指抽象创作。口语多用做，书面语作更多。口诀：动手做，动笔作。","分类":[{"类":"做动手式","说明":"做表具体动手干。","代表":"做作业、做饭、做游戏","例子":["做作业。"]},{"类":"作抽象式","说明":"作表抽象创作、书面。","代表":"作文、作品、作为","例子":["作文。"]}],"怎么认":["是不是动手干的活？动手用做。","是不是写文章、创作？创作、书面用做。","作是多音字（zuō/zuò），作息读zuō，重点记。"],"辨析":"做和作的区别：做是动手（做饭、做游戏），作是动笔、抽象（作文、作品）。做文是错的，应为作文。","例句解析":[{"句":"做作业、做饭、做游戏。","析":"都是动手干的活，用做。"},{"句":"作文、作品、作为。","析":"都是抽象创作、书面词，用作。"}],"练习":[{"q":"“_文”填？","options":["做","作"],"answer":1,"解析":"作文是抽象创作，用作。","类":"作抽象式"},{"q":"“_饭”填？","options":["做","作"],"answer":0,"解析":"做饭是动手干，用做。","类":"做动手式"},{"q":"“作息”读？","options":["zuò xī","zuō xī","zhuō xī"],"answer":1,"解析":"作息的作读zuō。","类":"作抽象式"}],"例子":["做作业、做饭、做游戏（动手）","作文、作品、作为（书面/抽象）","✗ 做文 → ✓ 作文","做作业。（做：从事）","作报告。（作：写作/担任）","做饭。（做）","作文。（作：写文章）","做人要诚实。（做）","作为班长，他很负责。（作）","做梦。（做）","作曲。（作）","做生意。（做）"],"口诀":"动手做，动笔作","易错":"“作”是多音字（zuō/zuò），“作息”读 zuō","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["做","含义：动手、从事（口语常用）；用法：做+具体事；例句：做饭、做游戏；误用：❌“做文”→ ✅“作文”"],["作","含义：动笔、抽象、书面；用法：作+抽象/书面语；例句：作文、作品；误用：❌“做文是错的，应为作文”"]]},"前置知识":["动词"]},{"name":"和/与","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我和妈妈去公园。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">前后能互换：妈妈和我去公园，是连词。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">他和老师谈话。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">前后不能互换，是介词。</text></g></svg>","讲解":"“和”可做连词也可做介词，“与”是书面说法。做连词时前后能互换，做介词时不能。","深讲":"和可做连词也可做介词，与是书面说法。做连词时前后能互换，做介词时不能互换，否则意思变了。","分类":[{"类":"和连词式","说明":"和做连词，前后能互换。","代表":"我和妈妈","例子":["我和妈妈去公园。"]},{"类":"和介词式","说明":"和做介词，前后不能互换。","代表":"和老师谈话","例子":["他和老师谈话。"]},{"类":"与书面式","说明":"与是和的书面说法。","代表":"我与妈妈","例子":["我与妈妈去公园。"]}],"怎么认":["前后换个位置，意思变不变？不变，就是连词。","换了位置意思变了，就是介词。","是不是书面语？书面语多用与。"],"辨析":"和连词和和介词的区别：连词能互换（我和妈妈＝妈妈和我）；介词不能互换（他和老师谈话≠老师和他谈话，意思变了）。","例句解析":[{"句":"我和妈妈去公园。","析":"前后能互换：妈妈和我去公园，是连词。"},{"句":"他和老师谈话。","析":"前后不能互换，是介词。"}],"练习":[{"q":"“我和妈妈去公园”中的和是？","options":["连词","介词","动词"],"answer":0,"解析":"前后能互换，是连词。","类":"和连词式"},{"q":"“他和老师谈话”中的和是？","options":["连词","介词","动词"],"answer":1,"解析":"前后不能互换，是介词。","类":"和介词式"},{"q":"“我与妈妈”中的与是？","options":["口语","书面说法","错别字"],"answer":1,"解析":"与是和的书面说法。","类":"与书面式"}],"例子":["我和妈妈去公园（连词，可换：妈妈和我）","我与妈妈（书面）","他和老师谈话（介词，不可换）","我和他是好朋友。（和：连词）","他与我同岁。（与：连词）","我把书和笔放在桌上。（和）","老师与同学一起劳动。（与）","苹果和香蕉都很甜。（和）","他与大家分享快乐。（与）","爸爸和妈妈去上班了。（和）","我们与时间赛跑。（与）","小猫和小狗在玩耍。（和）"],"口诀":"能互换是连词","易错":"作介词时前后不能换，否则意思变了","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["和（连词）","含义：连接并列成分；用法：前后能互换；例句：我和妈妈＝妈妈和我；误用：互换后意思变了就不是连词"],["和（介词）","含义：引出对象；用法：前后不能互换；例句：他和老师谈话（≠老师和他谈话）；误用：❌把介词“和”当连词互换"],["与","含义：书面语的“和”；用法：多用于书面；例句：我与妈妈同岁；误用：口语少用“与”"]]},"前置知识":["连词","介词"]},{"name":"把/被","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我把教室打扫干净了。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">我处置了教室，是把处置式。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">小明被老师表扬了。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">小明受到表扬，是被遭遇式。</text></g></svg>","讲解":"“把”字句强调处置（对宾语做了什么），“被”字句强调遭遇（主语受了什么）。","深讲":"把字句强调处置（对宾语做了什么），被字句强调遭遇（主语受了什么）。口诀：把字处置，被字受害；被后多为不如意事。","分类":[{"类":"把处置式","说明":"把字句，主语处置宾语。","代表":"把＋宾语＋动词","例子":["我把教室打扫干净了。"]},{"类":"被遭遇式","说明":"被字句，主语受到动作。","代表":"受事＋被＋动词","例子":["小明被老师表扬了。"]}],"怎么认":["主语是不是在处置宾语？是的，用把。","主语是不是受到了什么？是的，用被。","被后多为不如意事，说好事用被要小心。"],"辨析":"把和被的区别：把是处置（我把教室打扫干净了：我处置了教室）；被是遭遇（小明被老师表扬了：小明受到表扬）。看主语是处置者还是承受者。","例句解析":[{"句":"我把教室打扫干净了。","析":"我处置了教室，是把处置式。"},{"句":"小明被老师表扬了。","析":"小明受到表扬，是被遭遇式。"}],"练习":[{"q":"“我把教室打扫干净了”强调？","options":["处置","遭遇","处所","时间"],"answer":0,"解析":"把字句强调处置。","类":"把处置式"},{"q":"“小明被老师表扬了”强调？","options":["处置","遭遇","处所","时间"],"answer":1,"解析":"被字句强调遭遇。","类":"被遭遇式"},{"q":"“我喜欢音乐”能改把字句吗？","options":["我把音乐喜欢了","不能改","我把音乐喜欢着"],"answer":1,"解析":"喜欢无处置义，不能用把。","类":"把处置式"}],"例子":["我把教室打扫干净了（我处置了教室）","小明被老师表扬了（小明受到表扬）","我喜欢音乐 → 不能改成“把”字句","我把作业写完了。（把：处置）","杯子被打碎了。（被：被动）","妈妈把衣服洗干净了。（把）","他被老师表扬了。（被）","他把门关上了。（把）","小偷被警察抓住了。（被）","我把这本书看完了。（把）","庄稼被水淹了。（被）","她把花插进花瓶。（把）"],"口诀":"把字处置，被字受害","易错":"“被”后多为不如意事，说好事用“被”很别扭","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["把","含义：表处置；用法：主语是处置者；例句：我把教室打扫干净了；误用：❌“我喜欢音乐”不能改成“把”字句（“喜欢”不是处置）"],["被","含义：表遭遇（被动）；用法：主语是承受者；例句：小明被老师表扬了；误用：看主语是处置者还是承受者"]]},"前置知识":["把字句","被字句"]},{"name":"吗/呢/吧","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">你去吗？</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">问是非，用吗。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">我们走吧！</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">表商量，用吧。</text></g></svg>","讲解":"“吗”问是非，“呢”问补充或反问，“吧”表商量、祈使。","深讲":"吗问是非，呢问补充或反问，吧表商量、祈使。口诀：吗问是非，呢问补充，吧来商量；陈述句末不能加吗。","分类":[{"类":"吗是非问式","说明":"吗问是不是。","代表":"……吗？","例子":["你去吗？"]},{"类":"呢补充问式","说明":"呢问补充，也可反问。","代表":"……呢？","例子":["你呢？"]},{"类":"吧商量式","说明":"吧表商量、祈使、催促。","代表":"……吧！","例子":["我们走吧！"]}],"怎么认":["是不是在问是非？是非问用吗。","是不是在追问补充？你呢用呢。","是不是在商量、催促？商量、催促用吧。"],"辨析":"吗、呢、吧的区别：吗问是非（你去吗？），呢问补充（你呢？），吧表商量（我们走吧！）。陈述句末不能加吗：我去吗学校是错的。","例句解析":[{"句":"你去吗？","析":"问是非，用吗。"},{"句":"我们走吧！","析":"表商量，用吧。"}],"练习":[{"q":"“你去_？”填？","options":["吗","呢","吧"],"answer":0,"解析":"问是非，用吗。","类":"吗是非问式"},{"q":"“你_？”（追问补充）填？","options":["吗","呢","吧"],"answer":1,"解析":"追问补充，用呢。","类":"呢补充问式"},{"q":"“我们走_！”（商量）填？","options":["吗","呢","吧"],"answer":2,"解析":"表商量，用吧。","类":"吧商量式"}],"例子":["你去吗？（是非问）","你呢？（补充问）","我们走吧！（商量）","快点吧！（催促）","你去过北京吗？（吗：疑问）","他去哪儿了呢？（呢：疑问）","我们一起去吧。（吧：建议）","你吃饭了吗？（吗）","这本书好看呢。（呢：强调）","快点吧，要迟到了。（吧：催促）","你是谁呀？（呢/呀语气）","让我想想吧。（吧：商量）"],"口诀":"吗问是非，呢问补充，吧来商量","易错":"陈述句末不能加“吗”：✗ 我去吗学校","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["吗","含义：问是非；用法：句末，答“是/不是”；例句：你去吗？；误用：❌“我去吗学校”（陈述句末不能加“吗”）"],["呢","含义：问补充/表强调；用法：句末；例句：你呢？；这本书好看呢；误用：“呢”不问是非"],["吧","含义：表商量/催促/建议；用法：句末；例句：我们走吧！；快点吧！；误用：“吧”不是疑问语气"]]},"前置知识":["语气词"]},{"name":"才/就","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他九点才起床。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">九点比想的晚，用才。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">他六点就起床了。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">六点比想的早，用就。</text></g></svg>","讲解":"“才”表晚、少、难（比想的晚/少），“就”表早、多、易（比想的早/多）。","深讲":"才表晚、少、难（比想的晚、少、难），就表早、多、易（比想的早、多、易）。口诀：才嫌晚少难，就嫌早多易；时间＋才/就，意思正好相反，别用反。","分类":[{"类":"才晚少难式","说明":"才表比想的晚、少、难。","代表":"九点才起床","例子":["他九点才起床。"]},{"类":"就早多易式","说明":"就表比想的早、多、易。","代表":"六点就起床","例子":["他六点就起床了。"]}],"怎么认":["是不是比想的晚、少、难？是的，用才。","是不是比想的早、多、易？是的，用就。","换成另一个，意思是不是正好相反？是的，说明才和就不能用反。"],"辨析":"才和就的区别：才是晚、少、难（九点才起床：晚），就是早、多、易（六点就起床了：早）。这么难的题，他才用了五分钟：才是少。","例句解析":[{"句":"他九点才起床。","析":"九点比想的晚，用才。"},{"句":"他六点就起床了。","析":"六点比想的早，用就。"}],"练习":[{"q":"“他九点_起床”（比想的晚）填？","options":["才","就"],"answer":0,"解析":"晚用才。","类":"才晚少难式"},{"q":"“他六点_起床了”（比想的早）填？","options":["才","就"],"answer":1,"解析":"早用就。","类":"就早多易式"},{"q":"“这么难的题，他_用了五分钟”填？","options":["才","就"],"answer":0,"解析":"五分钟是少，用才。","类":"才晚少难式"}],"例子":["他九点才起床（比想的晚）","他六点就起床了（比想的早）","这么难的题，他才用了五分钟（少）","他才十岁，就会背诗了。（才：小/就：顺承）","我等了半天，他才来。（才：晚）","他一看就会了。（就：快）","这么难的题，他才不怕呢。（才：强调）","一下课，同学们就跑出去了。（就）","他才走了三分钟。（才：少）","有志者事竟成，他就是例子。（就：确定）","妈妈才回来，就开始做饭。（才…就…）","这本书才五块钱。（才：便宜）"],"口诀":"才嫌晚少难，就嫌早多易","易错":"时间+才/就，意思正好相反，别用反","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["才","含义：表晚、少、难；用法：数量/时间超出预期地“多耗”；例句：他九点才起床（晚）；这么难的题，他才用了五分钟（少）；误用：❌“他九点就起床”想表达“晚”时不能用“就”"],["就","含义：表早、多、易；用法：数量/时间比预期“省”；例句：他六点就起床了（早）；误用：❌“他六点才起床”想表达“早”时不能用“才”"]]},"前置知识":["副词"]},{"name":"都/也","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">同学们都来了。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">都表全部，是都全部式。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">他跑得快，我也跑得快。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">也表同样，是也同样式。</text></g></svg>","讲解":"“都”表全部、总括，“也”表同样、类推。","深讲":"都表全部、总括，也表同样、类推。口诀：都管全部，也管同样；都和全部意思重复，不能叠用。","分类":[{"类":"都全部式","说明":"都表全部。","代表":"同学们都来了","例子":["同学们都来了。"]},{"类":"也同样式","说明":"也表同样。","代表":"我也想去","例子":["我也想去。"]}],"怎么认":["是不是在说全部？全部用都。","是不是在说同样？同样用也。","都和全部叠用了吗？叠用了就是重复。"],"辨析":"都和也的区别：都是全部（同学们都来了），也是同样（我也想去）。全班都全部来了是错的，都和全部重复了。","例句解析":[{"句":"同学们都来了。","析":"都表全部，是都全部式。"},{"句":"他跑得快，我也跑得快。","析":"也表同样，是也同样式。"}],"练习":[{"q":"“同学们_来了”（全部）填？","options":["都","也"],"answer":0,"解析":"全部用都。","类":"都全部式"},{"q":"“我_想去”（同样）填？","options":["都","也"],"answer":1,"解析":"同样用也。","类":"也同样式"},{"q":"“全班都全部来了”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"都和全部重复了。","类":"都全部式"}],"例子":["同学们都来了（全部）","我也想去（同样）","他跑得快，我也跑得快","我们都爱祖国。（都：全部）","他也会唱歌。（也：同样）","同学们都到齐了。（都）","我也想去。（也）","大家都笑了。（都）","她也不知道。（也）","花草树木都绿了。（都）","你也来啦。（也）","这些题我都会。（都）"],"口诀":"都管全部，也管同样","易错":"✗ 全班都全部来了（“都”和“全部”重复）","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["都","含义：表全部；用法：都+范围；例句：同学们都来了；误用：❌“全班都全部来了”（“都”和“全部”重复）"],["也","含义：表同样；用法：也+相同情况；例句：我也想去；误用：“也”不表全部"]]},"前置知识":["副词"]},{"name":"以/已","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他以第一名的成绩获奖。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">以表凭借，是以凭借式。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">我已经写完作业了。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">已表已经，是已已经式。</text></g></svg>","讲解":"“以”表凭借、按照（yǐ），“已”表已经（yǐ）。同音不同义，看意思选。","深讲":"以和已同音（yǐ），意思不同：以表凭借、按照，已表已经。看意思选字，看偏旁区分。","分类":[{"类":"以凭借式","说明":"以表凭借、按照。","代表":"以第一名的成绩","例子":["他以第一名的成绩获奖。"]},{"类":"已已经式","说明":"已表已经。","代表":"已经写完","例子":["我已经写完作业了。"]}],"怎么认":["是不是在说凭借、按照？凭借用以。","是不是在说已经？已经用已。","以经吃饭是错的，应为已经吃饭。"],"辨析":"以和已的区别：以是凭借（以第一名的成绩），已是已经（已经写完作业）。同音不同义，看意思选。","例句解析":[{"句":"他以第一名的成绩获奖。","析":"以表凭借，是以凭借式。"},{"句":"我已经写完作业了。","析":"已表已经，是已已经式。"}],"练习":[{"q":"“他_第一名的成绩获奖”填？","options":["以","已"],"answer":0,"解析":"凭借用以。","类":"以凭借式"},{"q":"“我_经写完作业了”填？","options":["以","已"],"answer":1,"解析":"已经用已。","类":"已已经式"},{"q":"“以经吃饭”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"应为已经吃饭。","类":"已已经式"}],"例子":["他以第一名的成绩获奖（凭借）","我已经写完作业了（已经）","✗ 以经吃饭 → ✓ 已经吃饭","他已经走了。（已：已经）","我们要以诚待人。（以：用）","会议已结束。（已）","他以优异的成绩毕业。（以）","我早已听说过他。（已）","以理服人。（以）","天色已晚。（已）","他以跑步为乐。（以）","事情已经办妥。（已）"],"口诀":"以表凭借，已表已经","易错":"同音字，看偏旁区分","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["以","含义：表凭借、用；用法：以+凭借物；例句：他以第一名的成绩获奖；误用：❌“以经吃饭”→ ✅“已经吃饭”"],["已","含义：就是“已经”；用法：已+完成；例句：我已经写完作业了；误用：同音不同义，看意思选"]]},"前置知识":["介词","副词"]},{"name":"像/象","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">他像爸爸一样高。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">表相似，用单人像。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">大象的鼻子很长。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">指大象，用象。</text></g></svg>","讲解":"“像”表相似、好像，“象”指大象或形状、现象。","深讲":"像表相似、好像，象指大象或形状、现象。口诀：相似用单人像，大象气象用象；好像不能写成好象。","分类":[{"类":"像相似式","说明":"像表相似、好像。","代表":"像爸爸一样高","例子":["他像爸爸一样高。"]},{"类":"象动物式","说明":"象指大象。","代表":"大象","例子":["大象的鼻子很长。"]},{"类":"象现象式","说明":"象指形状、现象。","代表":"气象","例子":["气象。"]}],"怎么认":["是不是在说相似、好像？相似用单人像。","是不是在说大象？大象用象。","是不是在说气象、现象？现象用象。"],"辨析":"像和象的区别：像是相似（像爸爸一样高），象是大象或现象（大象、气象）。气像是错的，应为气象。","例句解析":[{"句":"他像爸爸一样高。","析":"表相似，用单人像。"},{"句":"大象的鼻子很长。","析":"指大象，用象。"}],"练习":[{"q":"“他_爸爸一样高”填？","options":["像","象"],"answer":0,"解析":"相似用单人像。","类":"像相似式"},{"q":"“大_的鼻子很长”填？","options":["像","象"],"answer":1,"解析":"大象用象。","类":"象动物式"},{"q":"“气_”填？","options":["像","象"],"answer":1,"解析":"气象是现象，用象。","类":"象现象式"}],"例子":["他像爸爸一样高（相似）","大象的鼻子很长","✗ 气像 → ✓ 气象","他像爸爸一样高。（像：好像）","大象的鼻子很长。（象：动物）","天上的云像棉花。（像）","这只小象很可爱。（象）","她的笑容像春风。（像）","画像挂在墙上。（象：形状/画像）","他长得像妈妈。（像）","气象万千。（象：景象）","好像要下雨了。（像）"],"口诀":"相似用单人像，大象气象用象","易错":"“好像”不能写成“好象”","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["像","含义：表相似（好像）；用法：像+比较对象；例句：他像爸爸一样高；误用：❌“气像”→ ✅“气象”"],["象","含义：大象或现象/景象；用法：象+动物/景象；例句：大象的鼻子很长；气象万千；误用：表相似时不用“象”"]]},"前置知识":["动词"]},{"name":"必须/必需","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我们必须按时到校。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">必须后跟动词到校，是必须动作式。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">水是生命必需的。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">必需后跟名词，是必需东西式。</text></g></svg>","讲解":"“必须”是副词，表一定要（后跟动词）；“必需”是动词，表一定需要（后跟名词）。","深讲":"必须和必需意思不同：必须是副词，表一定要，后跟动词；必需是动词，表一定需要，后跟名词。口诀：必须跟动作，必需跟东西。","分类":[{"类":"必须动作式","说明":"必须后跟动词，表一定要。","代表":"必须按时到校","例子":["我们必须按时到校。"]},{"类":"必需东西式","说明":"必需后跟名词，表一定需要。","代表":"必需品、日用品","例子":["水是生命必需的。"]}],"怎么认":["后面是不是动词？动词前用必须。","后面是不是名词、东西？东西前用必需。","必需品、日用品用必需，重点记。"],"辨析":"必须和必需的区别：必须跟动作（必须按时到校），必需跟东西（必需品）。必须品是错的，应为必需品。","例句解析":[{"句":"我们必须按时到校。","析":"必须后跟动词到校，是必须动作式。"},{"句":"水是生命必需的。","析":"必需后跟名词，是必需东西式。"}],"练习":[{"q":"“我们_按时到校”填？","options":["必须","必需"],"answer":0,"解析":"后跟动词，用必须。","类":"必须动作式"},{"q":"“_品、日用品”填？","options":["必须","必需"],"answer":1,"解析":"必需品用必需。","类":"必需东西式"},{"q":"“水是生命_的”填？","options":["必须","必需"],"answer":1,"解析":"后跟名词，用必需。","类":"必需东西式"}],"例子":["我们必须按时到校（后跟动词）","水是生命必需的（后跟名词）","✗ 必须品 → ✓ 必需品","我们必须遵守纪律。（必须：一定要）","水是生命必需的。（必需：需要）","你必须按时到校。（必须）","这是生活必需品。（必需）","做人必须诚实。（必须）","阳光是植物生长必需的。（必需）","他必须完成任务。（必须）","粮食是必需品。（必需）","我们必须努力学习。（必须）"],"口诀":"必须跟动作，必需跟东西","易错":"“必需品、日用品”用“必需”","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["必须","含义：一定要（后跟动作）；用法：必须+动词；例句：我们必须按时到校；误用：❌“必须品”→ ✅“必需品”"],["必需","含义：需要（后跟东西）；用法：必需+名词；例句：水是生命必需的；误用：❌“必需按时到校”"]]},"前置知识":["副词","动词"]},{"name":"哪/那","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">你去哪里？</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">问地点，用哪。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">我在那里等你。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">指地点，用那。</text></g></svg>","讲解":"“哪”表疑问（哪里、哪个），“那”表指示（那里、那个）。","深讲":"哪表疑问（哪里、哪个），那表指示（那里、那个）。口诀：哪是问，那是指；问句用哪，回答用那。","分类":[{"类":"哪疑问式","说明":"哪表疑问。","代表":"哪里、哪个","例子":["你去哪里？"]},{"类":"那指示式","说明":"那表指示。","代表":"那里、那个","例子":["我在那里等你。"]}],"怎么认":["是不是在问？问用哪。","是不是在指？指用那。","问句用哪，回答用那，对号入座。"],"辨析":"哪和那的区别：哪是问（你去哪里？），那是指（我在那里等你）。那里有几个人是错的，应为哪里有几个人。","例句解析":[{"句":"你去哪里？","析":"问地点，用哪。"},{"句":"我在那里等你。","析":"指地点，用那。"}],"练习":[{"q":"“你去_里？”填？","options":["哪","那"],"answer":0,"解析":"问地点，用哪。","类":"哪疑问式"},{"q":"“我在_里等你”填？","options":["哪","那"],"answer":1,"解析":"指地点，用那。","类":"那指示式"},{"q":"“_里有几个人？”（问句）填？","options":["哪","那"],"answer":0,"解析":"问句用哪。","类":"哪疑问式"}],"例子":["你去哪里？（疑问）","我在那里等你（指示）","✗ 那里有几个人？→ ✓ 哪里有几个人？","你去哪儿？（哪：疑问）","那是我的书包。（那：指示）","哪个是你的？（哪）","那座山很高。（那）","你喜欢哪一个？（哪）","那边有很多人。（那）","哪里有困难，哪里就有我们。（哪）","那天我们很开心。（那）","你要去哪里？（哪）"],"口诀":"哪是问，那是指","易错":"问句用“哪”，回答用“那”","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["哪","含义：表疑问；用法：哪+疑问；例句：你去哪里？；误用：❌“那里有几个人？”（问句）→ ✅“哪里有几个人？”"],["那","含义：表指示；用法：那+指示；例句：我在那里等你；误用：❌“哪里风景好”（指代时）→ ✅“那里风景好”"]]},"前置知识":["代词"]},{"name":"不/没","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">我不去。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">不想去，是不意愿式。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">我没去。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">没去成，是没客观式。</text></g></svg>","讲解":"“不”表主观不愿、经常性否定；“没”表客观没有、过去没发生。","深讲":"不表主观不愿、经常性否定，没表客观没有、过去没发生。口诀：不表意愿，没表有无；没常和过搭配表过去。","分类":[{"类":"不意愿式","说明":"不表不想、经常。","代表":"不去、不喜欢","例子":["我不去。"]},{"类":"没客观式","说明":"没表客观没有、没去成。","代表":"没去","例子":["我没去。"]},{"类":"没过去式","说明":"没＋过表过去没发生。","代表":"没来过","例子":["他没来过北京。"]}],"怎么认":["是不是不想去？不想用不。","是不是没去成？没去成用没。","是不是在说过去？过去用没＋过。"],"辨析":"不和没的区别：不去是不想去（主观），没去是没去成（客观）；不喜欢是经常， 没来过是过去。看是意愿还是有无、过去。","例句解析":[{"句":"我不去。","析":"不想去，是不意愿式。"},{"句":"我没去。","析":"没去成，是没客观式。"}],"练习":[{"q":"“我_去”（不想去）填？","options":["不","没"],"answer":0,"解析":"不想去用不。","类":"不意愿式"},{"q":"“我_去”（没去成）填？","options":["不","没"],"answer":1,"解析":"没去成用没。","类":"没客观式"},{"q":"“他_来过北京”（过去）填？","options":["不","没"],"answer":1,"解析":"过去用没＋过。","类":"没过去式"}],"例子":["我不去（不想去）","我没去（没去成）","他没来过北京（过去）","我不喜欢吃辣（经常）","我不喜欢吃辣。（不：意愿/性质否定）","我没吃过。（没：未曾）","他不去。（不）","我没带伞。（没）","今天不冷。（不）","他没来上课。（没）","我不怕困难。（不）","作业还没写完。（没）"],"口诀":"不表意愿，没表有无","易错":"“没”常和“过”搭配表过去：我没看过","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["不","含义：主观否定（意愿/性质）；用法：不+意愿/经常；例句：我不去（不想去）；我不喜欢吃辣（经常）；误用：表“过去未曾”不用“不”"],["没","含义：客观否定（有无/过去）；用法：没+有无/过去；例句：我没去（没去成）；他没来过北京（过去）；误用：表意愿不用“没”：❌“我没去（想表达不想去）”"]]},"前置知识":["副词"]},{"name":"还是/或者","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">你喝水还是喝牛奶？</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">选择问句，用还是。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">周末或者去公园，或者去图书馆。</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">陈述句表选择，用或者。</text></g></svg>","讲解":"“还是”用于选择问句，“或者”用于陈述句表选择。","深讲":"还是用于选择问句，或者用于陈述句表选择。口诀：问句还是，陈述或者；问句里用还是，陈述句里用或者，别用反。","分类":[{"类":"还是问句式","说明":"还是用于选择问句。","代表":"还是喝牛奶？","例子":["你喝水还是喝牛奶？"]},{"类":"或者陈述式","说明":"或者用于陈述句。","代表":"或者去公园，或者去图书馆","例子":["周末或者去公园，或者去图书馆。"]}],"怎么认":["是不是在问？问用还是。","是不是在陈述选择？陈述用或者。","你去或者不去是错的，应为你去还是不去。"],"辨析":"还是和或者的区别：还是问（你喝水还是喝牛奶？），或者陈述（周末或者去公园，或者去图书馆）。看是不是问句。","例句解析":[{"句":"你喝水还是喝牛奶？","析":"选择问句，用还是。"},{"句":"周末或者去公园，或者去图书馆。","析":"陈述句表选择，用或者。"}],"练习":[{"q":"“你喝水_喝牛奶？”填？","options":["还是","或者"],"answer":0,"解析":"问句用还是。","类":"还是问句式"},{"q":"“周末_去公园，_去图书馆”（陈述）填？","options":["还是，还是","或者，或者","还是，或者"],"answer":1,"解析":"陈述句用或者。","类":"或者陈述式"},{"q":"“你去_不去？”填？","options":["还是","或者"],"answer":0,"解析":"问句用还是。","类":"还是问句式"}],"例子":["你喝水还是喝牛奶？（问句）","周末或者去公园，或者去图书馆（陈述）","✗ 你去或者不去？→ ✓ 你去还是不去？","你喝茶还是喝咖啡？（还是：选择问）","他或者去北京，或者去上海。（或者：陈述选择）","你喜欢红色还是蓝色？（还是）","周末或者去爬山，或者去看电影。（或者）","是你去，还是我去？（还是）","他或者跑步，或者游泳。（或者）","你要苹果还是香蕉？（还是）","我们或者今天走，或者明天走。（或者）","你是学生还是老师？（还是）"],"口诀":"问句还是，陈述或者","易错":"问句里用“还是”，陈述句里用“或者”","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["还是","含义：表选择问；用法：用在问句；例句：你喝水还是喝牛奶？；误用：❌“你去或者不去？”→ ✅“你去还是不去？”"],["或者","含义：表陈述中的选择；用法：用在陈述句；例句：周末或者去公园，或者去图书馆；误用：问句中不用“或者”"]]},"前置知识":["连词","选择复句"]},{"name":"又/再辨析","图示":"<svg viewBox=\"0 0 640 180\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">今天他又来了，明天再来。</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“今天…又”：今天的事已发生，用又；“明天…再”：明天的事还没发生，用再。一句里两个时间，两个词。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">再见！</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“再”表将来再一次：这次见完，下次再见。是最常用的“再”字句。</text></g></svg>","讲解":"“又”和“再”都表示“再一次”，但时间分工不同：又管过去（已经又发生了），再管将来（还没发生等下次）。","深讲":"又 + 过去：动作已经重复发生，常带“了”（他又迟到了）。再 + 将来：动作还没发生，等下一次（明天再来吧）。再还有两个本事：表“再一个”（再来一碗）、表“然后”（先看再说）。又还能表“并列更”（又大又圆）。记住：过去用又，将来用再，换错了中国人听着别扭。（来源：AllSet Chinese Grammar Wiki，CC BY-NC-SA 3.0）","类比":"“又”是回放键：播的是已经发生过的事；“再”是预约键：约的是还没发生的事。","口诀":"又是过去再将来，时间错了就露馅","例子":["他又迟到了。","明天再来吧！","今天他又来了，明天再来。","再见！（=再相见）","再来一碗。","又大又圆。","明天又是星期一。","先看再说。"],"易错":"✗“明天又来”（→明天再来）；✗“昨天再迟到”（→昨天又迟到）。看时间选词。","分类":[{"类":"过去又","说明":"动作在过去重复发生，常带“了”。","代表":"他又迟到了","例子":["他又迟到了。","今天他又来了。"]},{"类":"将来再","说明":"动作还没发生，等下一次。","代表":"明天再来","例子":["明天再来吧！","我们下次再来。"]},{"类":"再的其他义","说明":"表“再一个”或“然后”。","代表":"再来一碗、先看再说","例子":["再来一碗。","先看再说。"]}],"怎么认":["看时间：过去的事→又，将来的事→再。","看搭配：带“了”→又；带“吧/要/下次”→再。","看意思：是不是“再一次”？是→在又/再里二选一。"],"辨析":"又/再和“还”的区别：“还”表“仍旧、继续”（他还在睡觉＝没停）；又/再表“重复一次”（他又睡了＝醒了再睡）。一个讲状态延续，一个讲动作重复。","例句解析":[{"句":"今天他又来了，明天再来。","析":"“今天…又”：今天的事已发生，用又；“明天…再”：明天的事还没发生，用再。一句里两个时间，两个词。"},{"句":"再见！","析":"“再”表将来再一次：这次见完，下次再见。是最常用的“再”字句。"}],"练习":[{"q":"“明天____来吧”填哪个？","options":["又","再","还","也"],"answer":1,"解析":"明天的事还没发生，用“再”。","类":"时间"},{"q":"“他昨天____迟到了”填哪个？","options":["再","又","还","就"],"answer":1,"解析":"昨天的事已发生，用“又”。","类":"时间"},{"q":"“____大____圆”填哪个词？","options":["再","又","还","更"],"answer":1,"解析":"“又…又…”表并列：又大又圆。","类":"并列"},{"q":"哪句是错的？","options":["他又迟到了","明天再来","昨天再下雨","再来一碗"],"answer":2,"解析":"“昨天”已过去，该用“又”：昨天又下雨。","类":"易错"}],"前置知识":["副词"]}]}],"module":"语法知识库","标准":"《义务教育语文课程标准》附录三·语法修辞知识要点","说明":"覆盖词类、短语、单句成分、复句、修辞、病句六大块，为中考语文基础知识与作文语言服务"},"logic":{"categories":[{"id":"gainian","name":"形式逻辑基础","items":[{"name":"概念：定义与划分","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">白马不是马</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">白马≠马，混淆层次</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">定义不能循环</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">好定义</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"人是能制造工具的动物\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">坏定义</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"人是两条腿的动物\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">好划分</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"学生\\\"按年级分为一年级/二年级/三年级</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">坏划分</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"水果\\\"按颜色分红的、按大小分大的</text></g></svg>","目标":"今天学会给概念下定义、给大类做划分。","类比":"概念就像抽屉标签：定义是写清标签上是什么，划分是把大抽屉分成小格。","讲解":"定义揭示内涵（是什么），划分揭示外延（有哪些）。定义=种差+属概念。","口诀":"定义讲内涵，划分列外延","例子":["白马不是马：白马（种）≠马（属），混淆层次","定义不能循环","好定义：\"人是能制造工具的动物\"（种差\"能制造工具\"+属\"动物\"）","坏定义：\"人是两条腿的动物\"（鸡也是，种差不唯一）","好划分：\"学生\"按年级分为一年级/二年级/三年级（标准统一）","坏划分：\"水果\"按颜色分红的、按大小分大的（标准不一）","比喻不是定义：\"老师是辛勤的园丁\"很美，但不是定义","好定义：\"椅子是供人坐的家具\"（属\"家具\"＋种差\"供人坐\"，一听就知道是什么）","坏定义：\"西瓜是夏天吃的东西\"（只讲了季节，没讲出西瓜本身的样子和特点）","坏划分：\"把同学分成男生和戴眼镜的\"（标准交叉：戴眼镜的男生两边都算，子项不互斥）"],"深讲":"定义回答“这是什么”，要抓住这个东西跟同类不一样的地方（种差），再说出它属于哪个大类（属）。划分回答“有哪些”，要按一个标准一次分完，分出来的小类不能重叠、不能漏掉。定义和划分是一对搭档：先定义清楚，才能分得干净。","怎么认":["先找属：这个东西属于哪个大类？","再找种差：它跟同类比，特别在哪里？","检查划分：是不是一个标准分到底？小类有没有重叠或漏掉？"],"辨析":"定义和划分别混：定义是给一个概念“画像”（内涵），划分是给一个大类“分家”（外延）。“人是能制造工具的动物”是定义；“动物分为哺乳动物、鸟类、鱼类……”是划分。","例句解析":[{"句":"白马不是马：白马（种）≠马（属），混淆层次","析":"“白马”是“马”下面的一个小类，把小类和大类画等号，就像说“苹果不是水果”一样，层次搞混了。"},{"句":"好划分：\"学生\"按年级分为一年级/二年级/三年级（标准统一）","析":"一个标准（年级）一次分完，每个学生只属于一个年级，不重叠、不遗漏，这就是合格的划分。"}],"易错":"划分标准要统一，不能一会儿按颜色一会儿按大小","练习":[{"q":"给“钢笔”下定义，哪个最好？","options":["钢笔是笔","钢笔是用来写字的笔","钢笔是学生用的东西"],"answer":1,"解析":"属（笔）＋种差（用来写字）。A只有属没种差，C种差不唯一（学生用的东西太多了）。"},{"q":"“把水果按颜色分为红的、大的”错在哪里？","options":["标准不统一","颜色分错了","水果不能分"],"answer":0,"解析":"一会儿按颜色一会儿按大小，两个标准混在一起，小类会重叠。"},{"q":"下面哪个是划分？","options":["椅子是供人坐的家具","动物分为哺乳动物和鸟类","西瓜是夏天吃的东西"],"answer":1,"解析":"“分为……”是把大类分小类；另外两个都是在给单个概念下定义（一个好一个坏）。"}],"动画":{"steps":[{"tokens":["属概念","＋","种差","＝","定义"],"note":"定义公式：先找大类（属），再说出区别（种差）"},{"tokens":["人","是","会制造工具的","动物"],"note":"动物（属）＋会制造工具（种差）＝人"},{"tokens":["✗","人","是","人类的一员"],"note":"错：循环定义，用\"人类\"解释\"人\"等于没说"}]},"小测":[{"q":"给\"学生\"下定义，哪个对？","options":["学生是上学的人","学生是在学校学习的人","学生是学生"],"answer":1,"解析":"属（人）＋种差（在学校学习）。A太宽，C循环。"}],"前置知识":[]},{"name":"三段论","目标":"今天学会用三段论推出结论：大前提加小前提，得出结论。","类比":"三段论就像接力赛：大前提交棒给小前提，推出结论。","图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">大前提：凡人皆有死</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">大范围的真理</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">小前提：苏格拉底是人</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">具体归属</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">结论：苏格拉底有死</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">必然推出</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">三段论=接力赛：大前提交棒给小前提<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","讲解":"大前提（一般）+小前提（个别）→结论。","口诀":"大套小，推出结论跑不了","例子":["凡人皆有死，苏格拉底是人，所以苏格拉底有死","大前提：所有金属都导电；小前提：铜是金属；结论：铜导电","大前提：鲸是哺乳动物；小前提：哺乳动物用肺呼吸；结论：鲸用肺呼吸","错例：鸟会飞，企鹅是鸟，所以企鹅会飞（大前提\"鸟会飞\"不真）","错例：人是动物，狗是动物，所以人是狗（中项\"动物\"不周延）","有效式：下雨地就湿；下雨了→所以地湿了（肯定前件）","大前提：鸟类都用肺呼吸；小前提：鸽子是鸟类；结论：鸽子用肺呼吸","大前提：植物都需要阳光；小前提：阳台上的绿萝是植物；结论：绿萝需要阳光","错例：下雨地就湿；地湿了→所以下雨了（错：洒水车洒水也会湿，肯定后件推不出前件）","大前提：所有偶数都能被2整除；小前提：14是偶数；结论：14能被2整除"],"深讲":"三段论是大前提、小前提、结论三句话的接力：大前提讲一般道理，小前提把个别情况套进去，结论自然跑出来。关键是中间那个词（中项）要在两句话里真正搭上桥，而且前提本身要是真的。","怎么认":["先找结论：它要证明什么？","再找大前提（一般道理）和小前提（个别情况）。","检查两点：前提是不是真的？中间词有没有真正搭上桥？"],"辨析":"三段论和“因为……所以……”不完全一样：日常的因为所以常常只说一个理由；三段论必须有两个前提，一个讲一般、一个讲个别，结论是被“推”出来的，不是直接喊出来的。","例句解析":[{"句":"大前提：所有金属都导电；小前提：铜是金属；结论：铜导电","析":"“金属”是中项，在大前提里讲所有金属，在小前提里把铜放进金属，桥搭上了，结论站得住。"},{"句":"错例：人是动物，狗是动物，所以人是狗（中项\"动物\"不周延）","析":"“动物”这个词两头都没说全——人只是动物中的一小部分，狗也是另一小部分，两小部分不能因为同属动物就画等号。"}],"易错":"两个坑最常见：一是前提本身不真（“鸟都会飞”），结论就不可靠；二是中项两头都不周延（“人是动物，狗是动物”），两个小类不能硬凑成一对。","练习":[{"q":"“所有鸟都会飞，企鹅是鸟，所以企鹅会飞”问题出在哪？","options":["小前提错了","大前提不全真","结论推错了"],"answer":1,"解析":"企鹅、鸵鸟都不会飞，“所有鸟都会飞”这个大前提本身不真，结论就靠不住。"},{"q":"补全三段论：大前提：植物都需要水；小前提：仙人掌是植物；结论是？","options":["仙人掌不需要水","仙人掌需要水","所有植物都是仙人掌"],"answer":1,"解析":"把小前提套进大前提：仙人掌属于植物，所以也需要水。"},{"q":"“下雨地就湿；地湿了，所以下雨了”错在哪里？","options":["前提错了","肯定了后件，推不出前件","结论太长"],"answer":1,"解析":"地湿的原因很多（洒水、拖地），从“地湿”不能倒推出“下雨”，这是肯定后件的毛病。"}],"动画":{"steps":[{"tokens":["所有","人","都会","死"],"note":"大前提：一般道理"},{"tokens":["苏格拉底","是","人"],"note":"小前提：个别情况"},{"tokens":["所以","苏格拉底","会","死"],"note":"结论：水到渠成"}]},"小测":[{"q":"三段论哪项错了？大前提：鸟会飞。小前提：企鹅是鸟。结论：企鹅会飞","options":["大前提错了","小前提错了","推理错了"],"answer":0,"解析":"大前提\"鸟会飞\"不全真（鸵鸟企鹅不会），前提错结论就不可靠。"}],"前置知识":["概念：定义与划分"]},{"name":"四大逻辑规律","目标":"今天认识四大逻辑规律：同一律、矛盾律、排中律、充足理由律。","类比":"四律就像思维交通规则：违反就撞车（自相矛盾）。","图示":"<svg viewBox=\"0 0 640 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">同一律</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">前后说的一个意思</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">矛盾律</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">不能自相矛盾</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">排中律</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">非此即彼，必有一真</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">充足理由律</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">断言要有证据</text></g><text x=\"320\" y=\"280\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">四律=思维交通规则：违反就撞车<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3.3s\" fill=\"freeze\"/></text></svg>","讲解":"同一律（概念确定）、矛盾律（不自相矛盾）、排中律（非此即彼）、充足理由律（言之有据）。","口诀":"同一矛盾排中足，思维守法不糊涂","动画":{"steps":[{"tokens":["这杯","咖啡","不能","一会儿变茶"],"note":"同一律：概念要确定，前后一致"},{"tokens":["今天","下雨了","＋","没下雨","＝","✗"],"note":"矛盾律：不能自相矛盾"},{"tokens":["灯","开","或","关"],"note":"排中律：非此即彼，不许骑墙"},{"tokens":["猫聪明","因为","会开门"],"note":"充足理由律：说观点要给理由"}]},"例子":["同一律：讨论\"成功\"时，前后必须指同一个意思，不能一会儿说成绩一会儿说快乐","矛盾律：不能同时说\"这本书我看过\"又说\"这本书我没看过\"（同一意义上）","排中律：\"小明及格了\"和\"小明没及格\"，必有一真（非此即彼）","充足理由律：说\"他作弊了\"要有证据，不能空口断言","违反排中律：\"这次考试要么第一要么倒数第一\"（还有中间名次）","违反同一律：辩论时把\"自由\"一会儿讲成\"为所欲为\"，一会儿讲成\"自律\"","同一律：写作文说\"我的妈妈\"，全文都要指同一个人，不能写着写着变成奶奶","充足理由律：说\"我们班最干净\"，要拿出证据：地面没纸屑、桌椅排整齐","违反充足理由律：\"他肯定偷懒了\"——没有证据，只是\"我觉得\"，这就是缺理由","排中律：\"今天是星期一\"和\"今天不是星期一\"，必有一真"],"深讲":"四条规律是思维的四条底线：同一律——说话前后同一个词指同一个意思；矛盾律——同一个意义上不能又肯定又否定；排中律——非此即彼的两边必有一真；充足理由律——下判断要拿出理由。四条一起守，话才讲得清楚、站得住。","怎么认":["先问：同一个词前后意思变了吗？（同一律）","再问：有没有自己打自己？（矛盾律）","是“非此即彼”吗？中间还有没有第三种？（排中律）","最后问：理由拿出来了吗？（充足理由律）"],"辨析":"矛盾律和排中律最容易混：矛盾律是“不能两个都真”（不能又下雨又没下雨）；排中律是“不能两个都假”（“及格”和“没及格”必有一真）。一个管“不能都真”，一个管“不能都假”。","例句解析":[{"句":"违反排中律：\"这次考试要么第一要么倒数第一\"（还有中间名次）","析":"第一和倒数第一不是“非此即彼”，中间还有第二名、第三名……硬说“要么这个要么那个”，就是排中律用错了地方。"},{"句":"充足理由律：说\"他作弊了\"要有证据，不能空口断言","析":"“作弊”是严重的判断，没有证据就说出口，等于没理由下结论——充足理由律要求每个判断都有根据。"}],"易错":"排中律只管“非此即彼”的两种情况：中间还有别的情况时不能硬套（“第一还是倒数第一”中间还有很多名次）；矛盾律管的是同一个意义上的自相矛盾，换了意思就不算（“我喜欢吃苹果”和“我不喜欢吃青苹果”不矛盾）。","练习":[{"q":"“讨论'勇敢'时，一会儿说敢举手，一会儿说敢打架”违反了哪条规律？","options":["矛盾律","同一律","排中律"],"answer":1,"解析":"同一个词“勇敢”前后意思偷偷换了，违反同一律。"},{"q":"“这盏灯既开着又没开着”违反了哪条规律？","options":["充足理由律","矛盾律","排中律"],"answer":1,"解析":"同一个意义上又肯定又否定，自己打自己，违反矛盾律。"},{"q":"“我觉得他跑得最快”作为判断缺什么？","options":["缺同一律","缺充足理由","缺排中律"],"answer":1,"解析":"“我觉得”不是理由，要拿出计时成绩或比赛名次，才算有充足理由。"}],"前置知识":["概念：定义与划分"]},{"name":"推理三兄弟：演绎/归纳/类比","目标":"今天学会分清三种推理：演绎、归纳、类比。","类比":"演绎像\"漏斗\"（从大到小），归纳像\"堆塔\"（从小堆到大），类比如\"照镜子\"（看A像B）。","图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">演绎</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">漏斗：从大到小，人会死→苏格拉底会死</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">归纳</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">堆塔：从小到大，看一万只乌鸦都黑</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">类比</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">照镜子：地球有水→火星可能有</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">演绎必然，归纳或然，类比要看本质<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","讲解":"演绎：一般→个别（三段论）；归纳：个别→一般（看多了总结）；类比：A像B，B有某性→A也有。","口诀":"演绎漏斗归纳塔，类比照镜子","例子":["演绎：人会死→苏格拉底会死","归纳：乌鸦都是黑的（看了一万只）","类比：地球有水有生命→火星有水→可能有生命","演绎：三角形内角和180°→这个三角形内角和也是180°（数学证明）","归纳：尝了十个苹果都甜→这箱苹果大概是甜的（或然，非必然）","类比错例：蝙蝠会飞，鸟会飞→蝙蝠是鸟（表面像，本质不同）","演绎：直角三角形的两条直角边是3和4，斜边就是5（勾股定理套用）","归纳：班里十个同学都喜欢踢足球，大概全班很多同学喜欢踢足球（只是大概，不是必然）","类比：水管堵了水流不畅，血管堵了血液不畅→血管也要“疏通”（医生打比方）","归纳错例：昨天吃冰淇淋拉肚子，就说所有冰淇淋都不好（一次个例推全体，样本太小）"],"深讲":"三兄弟方向不同：演绎从一般道理出发，结论是必然的（前提真，结论一定真）；归纳从很多个别例子出发，结论只是“大概”，例子越多越可信；类比从相似出发，结论也是“可能”，关键看像的是本质还是表面。","怎么认":["看方向：一般→个别是演绎，个别→一般是归纳。","看关系：A像B所以A可能像B那样，是类比。","看把握：说“一定”的是演绎，说“大概、可能”的是归纳或类比。"],"辨析":"归纳和类比都只能得“可能”，但路子不同：归纳是“见得多了，总结规律”（看了一万只乌鸦）；类比是“这个像那个，借来推一推”（地球像火星）。演绎最保险，但前提必须真。","例句解析":[{"句":"归纳：尝了十个苹果都甜→这箱苹果大概是甜的（或然，非必然）","析":"十个苹果只是这箱的一部分，结论只能说“大概”，不能说“一定”——归纳的结论永远留有余地。"},{"句":"类比错例：蝙蝠会飞，鸟会飞→蝙蝠是鸟（表面像，本质不同）","析":"会飞只是表面相似，蝙蝠是胎生哺乳动物，鸟是卵生——类比只看表面就会推错。"}],"易错":"归纳的\"枚举\"不完全会翻车（黑天鹅）；类比要本质像，不能表面像","练习":[{"q":"“所有矩形的对角线相等，这个图形是矩形，所以它的对角线相等”是什么推理？","options":["归纳","类比","演绎"],"answer":2,"解析":"从一般定理套到个别图形，是演绎（前提真结论必然真）。"},{"q":"“连续三天都下雨，明天大概也会下雨”是什么推理？","options":["演绎","归纳","类比"],"answer":1,"解析":"从几天的个别情况推明天的一般情况，是归纳，结论只是“大概”。"},{"q":"“自行车胎破了跑不快，人的血管堵了也跑不快”这是在？","options":["演绎","归纳","类比"],"answer":2,"解析":"拿自行车和人作比较、借来推一推，是类比；要小心只看表面相似。"}],"小测":[{"q":"\"看到10只白天鹅，得出天鹅都是白的\"是什么推理？","options":["演绎","归纳","类比"],"answer":1,"解析":"从个别到一般，是归纳（不完全归纳，有风险）。"}],"前置知识":["概念：定义与划分"]}]},{"id":"luojibing","name":"病句里的逻辑错误","items":[{"name":"自相矛盾","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他是众多死难者中幸免的一个</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">对</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他是众多遇难者中幸免的一个</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">错</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">大约三十多人</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">对</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">三十多人</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">这场球赛胜负未分，结果双方打成平局</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">对</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">这场球赛胜负未分，双方最终握手言和</text></g></svg>","目标":"今天学会认出自相矛盾：前后说法打架的句子。","讲解":"前后说法打架：他是众多死难者中幸免的一个（都死了还幸免？）。","口诀":"前后打架自己吵，改掉一个就好了","例子":["错：他是众多死难者中幸免的一个","对：他是众多遇难者中幸免的一个","错：大约三十多人（\"大约\"和\"多\"自相矛盾）","对：三十多人","错：这场球赛胜负未分，结果双方打成平局","对：这场球赛胜负未分，双方最终握手言和","错：这道题我不会做，但我已经做出来了","对：这道题我一开始不会做，后来做出来了","错：操场上一个人也没有，只有小明在跑步","对：操场上只有小明在跑步"],"深讲":"自相矛盾是句子自己打自己：前半句说一个意思，后半句又说相反的意思，两句话不能同时是真的。找它的方法是把前后分句拆开，问一句“这两句能同时成立吗”——不能，就是自相矛盾。","怎么认":["把句子拆成前后两半。","每半各是什么意思？写下来比一比。","两半能不能同时是真的？不能，就是自相矛盾。"],"辨析":"自相矛盾和“前后不一致”不一样：前后不一致可能是话题跑偏了；自相矛盾是同一个点上自己否定自己，比如“都死了”又“幸免”，同一个“死”字两边打架。","例句解析":[{"句":"错：他是众多死难者中幸免的一个","析":"“死难者”就是已经死了的人，“幸免”是没死——同一个人既死了又没死，自己打自己。把“死难”改成“遇难”（遇到灾难的人，可死可活）就通了。"},{"句":"错：大约三十多人（\"大约\"和\"多\"自相矛盾）","析":"“大约”表示不确定，“多”表示超过三十——一个说“大概”，一个说“肯定超过”，两个意思撞车，留一个就行：“三十多人”。"}],"易错":"检查前后分句能否同时为真","练习":[{"q":"“大约五十多个同学参加了比赛”错在哪里？","options":["数字不对","大约和多自相矛盾","同学写错了"],"answer":1,"解析":"“大约”和“多”都表示不确定/超过，两个意思打架，删掉一个：“五十多个同学”。"},{"q":"下面哪句自相矛盾？","options":["他是遇难者中幸免的一个","他是死难者中幸免的一个","他是幸存者中的一个"],"answer":1,"解析":"“死难者”已经死了，不可能“幸免”；“遇难者”只是遇到灾难，可死可活，才能幸免。"},{"q":"“这场球赛胜负未分，结果双方打成平局”为什么错？","options":["平局写错了","胜负未分和打成平局意思打架","球赛写错了"],"answer":1,"解析":"“胜负未分”是还没分出胜负，“打成平局”是已经比完了——前半句说没比完，后半句说比完了，前后打架。"}],"动画":{"steps":[{"tokens":["众多","死难者","中"],"note":"死难者＝已经死了"},{"tokens":["幸免","的","一个"],"note":"幸免＝没死"},{"tokens":["✗","死了","＋","没死"],"note":"撞车！改\"死难\"为\"遇难\""}]},"决策树":"①把句子拆成前后两半→②每半各是什么意思？写下来比一比→③两半能同时是真吗？→能：不是自相矛盾，转查其他逻辑错误→不能：自相矛盾，删掉或改掉其中一半","前置知识":["四大逻辑规律"]},{"name":"主客倒置","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">爱迪生这个名字对我们不陌生</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">对</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">我们对爱迪生这个名字不陌生</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">错</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">这部电影对观众很感动</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">对</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">观众对这部电影很感动</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他的事迹对我们很感动</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">对</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">我们对他的事迹很感动</text></g></svg>","目标":"今天学会认出主客倒置：谁对谁说反了。","讲解":"谁对谁说反了：京剧对她很熟悉→她对京剧很熟悉。","口诀":"谁感受谁在前，东西不能当主角","例子":["错：爱迪生这个名字对我们不陌生","对：我们对爱迪生这个名字不陌生","错：这部电影对观众很感动","对：观众对这部电影很感动","错：他的事迹对我们很感动","对：我们对他的事迹很感动","错：这个问题对他很清楚","对：他对这个问题很清楚","错：这首古诗对我们很熟悉","对：我们对这首古诗很熟悉"],"深讲":"有些感受词（熟悉、陌生、清楚、感动、了解）的主人只能是人：是“人对东西熟悉”，不是“东西对人熟悉”。东西不会“熟悉”谁、“感动”谁，把东西放在主语位置，就是主客倒置。改法是把人和东西的位置对调。","怎么认":["找感受词：熟悉、陌生、清楚、感动、了解。","问：谁在感受？感受的一方应该是人。","如果主语是东西（电影、名字、事迹），就是倒置，对调人和东西的位置。"],"辨析":"主客倒置和“被动句”不一样：“我被老师表扬了”主语是我，动作是我接受的，没错；主客倒置是感受的主人错了——“电影对观众很感动”里，真正感动的是观众，不是电影。","例句解析":[{"句":"错：爱迪生这个名字对我们不陌生","析":"“不陌生”的感受主人是我们——是我们对名字不陌生。名字不会“对我们陌生”，把“我们”和“名字”对调就对了。"},{"句":"错：这部电影对观众很感动","析":"感动的是观众，电影是让人感动的东西。主语应该是“观众”，电影不能“感动”观众作主语——对调：“观众对这部电影很感动”。"}],"易错":"不是所有“对……”的句子都倒置：“老师对我们很亲切”没错（亲切的是老师，老师是人）；只有感受词（熟悉、陌生、清楚、感动、了解）的主人必须是人，东西作主语才算倒置。","练习":[{"q":"“这首诗对我们很熟悉”错在哪里？","options":["诗不能作主语","熟悉的主人应该是我们，不是诗","我们写错了"],"answer":1,"解析":"“熟悉”是人的感受，应该是“我们对这首诗很熟悉”，诗不会熟悉我们。"},{"q":"下面哪句是对的？","options":["故宫对游客不陌生","游客对故宫不陌生","故宫很熟悉游客"],"answer":1,"解析":"熟悉的主人是游客：游客对故宫不陌生。A和C都把故宫当成了感受的主人。"},{"q":"“老师对我们很亲切”有没有主客倒置？","options":["有","没有","说不清"],"answer":1,"解析":"亲切的是老师，老师是人，主语没错——不是所有“对”字句都是倒置，只有感受词的主人错了才算。"}],"决策树":"①找感受词：熟悉、陌生、清楚、感动、了解→②谁在感受？→是人：检查主谓搭配对吗→是东西（电影、名字、事迹）：主客倒置→③对调人和东西的位置→通顺了吗？→通顺：改对→还别扭：转查搭配不当","前置知识":["主语","宾语"]},{"name":"强加因果","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">因为他是北方人，所以思想守旧</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">错</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">早上没吃鸡蛋，所以没考好</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">错</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他穿了红衣服，所以比赛赢了</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">对</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">昨晚熬夜刷题，今天上课精神不振</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">检验法</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">问一句\\\"前者真能推出后者吗\\\"，推不出就是强加因果</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">错</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">因为他个子高，所以数学一定好</text></g></svg>","目标":"今天学会认出强加因果：没有因果硬说因果。","讲解":"无因果硬说因果：因为他来自北方，思想还是旧的一套。","口诀":"没有因果别硬凑，先问一句推得出","易错":"问一句：前者真能推出后者吗","例子":["错：因为他是北方人，所以思想守旧（地域推不出思想）","错：早上没吃鸡蛋，所以没考好（毫无关联）","错：他穿了红衣服，所以比赛赢了（迷信式因果）","对：昨晚熬夜刷题，今天上课精神不振（真实因果）","检验法：问一句\"前者真能推出后者吗\"，推不出就是强加因果","错：因为他个子高，所以数学一定好（身高推不出数学）","错：因为今天是星期三，所以要下雨（星期推不出天气）","错：因为教室里坐满了人，所以这节课一定讲得好（人数推不出质量）","对：多喝水、早睡觉，感冒好得快（身体恢复需要休息和水分）","对：每天练字半小时，字越写越好看（练习带来进步）"],"深讲":"强加因果是把两件碰巧一起出现的事，硬说成“因为……所以……”。检验办法就一句：前者真能推出后者吗？推不出，就是强加。比如“穿红衣服”和“比赛赢了”只是碰巧，红衣服不会让人跑得更快。","怎么认":["找出“因为”后面的原因和“所以”后面的结果。","问：原因真能推出结果吗？换个情况还成立吗？","推不出，或者只是碰巧一起出现，就是强加因果。"],"辨析":"强加因果和“真实因果”的区别在“必然”：熬夜→上课没精神，是身体规律，换谁都一样；穿红衣服→比赛赢，换件衣服也可能赢——经不起“换一换”检验的，就是强加。","例句解析":[{"句":"错：因为他是北方人，所以思想守旧（地域推不出思想）","析":"“北方人”是出生地，“思想守旧”是个人想法，出生地推不出想法——两件事没有因果链，硬凑就是强加。"},{"句":"对：昨晚熬夜刷题，今天上课精神不振（真实因果）","析":"熬夜少睡→白天没精神，是身体的真实规律，换谁熬夜都一样，这才叫因果。"}],"练习":[{"q":"“他早上吃了鸡蛋，所以考试考好了”错在哪里？","options":["鸡蛋不能吃","吃鸡蛋和考好没有因果","考试写错了"],"answer":1,"解析":"吃鸡蛋不会让人变聪明，两件事只是碰巧同一天发生，硬说因果就是强加。"},{"q":"下面哪个是真实因果？","options":["穿新鞋所以跑得快","下雨所以地面湿了","戴眼镜所以成绩好"],"answer":1,"解析":"雨水落到地上，地面自然会湿，这是真实规律；新鞋、眼镜和跑得快、成绩好没有因果。"},{"q":"检验因果最好的办法是？","options":["看两件事是不是同一天发生","问一句“前者真能推出后者吗”","看句子有没有“因为”"],"answer":1,"解析":"同一天发生不等于有因果；有没有“因为”也不作数——关键看前者能不能推出后者。"}],"决策树":"①找出\"因为\"后面的原因和\"所以\"后面的结果→②原因真能推出结果吗？→能：不是强加因果→不能/存疑：换个情况还成立吗？→成立：因果成立→不成立：强加因果，删掉因果关联词或改写","前置知识":["因果复句","概念：定义与划分"]},{"name":"以偏概全","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">我班三个同学近视，所以全班都近视</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">错</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他北方人，北方人都豪爽</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">错</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">我去过一次北京很堵，所以北京天天堵</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">错</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">两个学霸都熬夜，所以熬夜才能当学霸</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">对</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">调查显示我班80%同学近视，需注意用眼</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">写作提醒</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">举例后必须\\\"扣题分析\\\"，摆个例子就下大结论必翻车</text></g></svg>","目标":"今天学会认出以偏概全：拿部分当全部。","类比":"以偏概全就像\"盲人摸象\"：摸到腿说象是柱子，摸到鼻子说象是管子。","讲解":"拿部分当全部。看到几个就下结论全体，犯了\"简单枚举\"的错。","口诀":"部分推全体，十有八九错","例子":["错：我班三个同学近视，所以全班都近视","错：他北方人，北方人都豪爽","错：我去过一次北京很堵，所以北京天天堵","错：两个学霸都熬夜，所以熬夜才能当学霸","对：调查显示我班80%同学近视，需注意用眼（有数据支撑≠以偏概全）","写作提醒：举例后必须\"扣题分析\"，摆个例子就下大结论必翻车","错：我家猫怕水，所以所有猫都怕水","错：他一次考试没考好，就说他不是学习的料","错：只看到操场上有几个纸团，就说我们学校卫生最差","对：问了全班同学才说“我们班大多数同学喜欢踢球”（调查全体再下结论）"],"深讲":"以偏概全是拿一小部分当全部：看到几个人、几件事，就敢说“都”“天天”“所有”。想下“全部”的结论，要么调查全体，要么有足够大的抽样和数据；只凭几个例子就下大结论，一定翻车。","怎么认":["找结论里的大词：都、天天、所有、肯定。","问：结论是凭几个例子下的？还是调查了全体/有数据？","只凭几个例子就下大结论，就是以偏概全。"],"辨析":"以偏概全和“举例论证”不一样：举例论证是拿例子当证据，结论留有余地（“可见……很重要”）；以偏概全是拿例子当全部，结论说死（“所以全班都……”）。例子后面有没有“扣题分析”、结论有没有留余地，是分水岭。","例句解析":[{"句":"错：我班三个同学近视，所以全班都近视","析":"三个同学只是全班的一小部分，从三个人推到全班，样本太小——要下“全班”的结论，得调查全班。"},{"句":"对：调查显示我班80%同学近视，需注意用眼（有数据支撑≠以偏概全）","析":"这个结论有调查数据支撑，“80%”也不是“全部”——有数据、留余地，就不是以偏概全。"}],"易错":"议论文举例后一定要\"扣题分析\"，不能例子一摆就下大结论","练习":[{"q":"“我去过一次北京很堵，所以北京天天堵”错在哪里？","options":["北京不堵","一次经历推不出天天","去字写错了"],"answer":1,"解析":"一次堵车只是某一天的情况，推不到“天天”——以偏概全。"},{"q":"下面哪个不是以偏概全？","options":["两个学霸熬夜，所以熬夜才能当学霸","调查了全班才说大多数同学喜欢踢球","我家猫怕水，所以所有猫都怕水"],"answer":1,"解析":"调查了全班再下结论，有全体数据支撑；另外两个都是拿个别推全体。"},{"q":"写议论文时，举例后最应该做什么？","options":["再举一个例子","扣题分析，把例子和观点连起来","直接下大结论"],"answer":1,"解析":"摆个例子就下大结论是以偏概全；要分析例子为什么能证明观点，结论才站得住。"}],"决策树":"①找结论里的大词：都、天天、所有、肯定→②结论凭几个例子下的？→调查了全体/有数据：不是以偏概全→只凭几个例子：以偏概全→③改法：缩小结论范围（\"有些\"\"部分\"）或补充依据","前置知识":["概念：定义与划分"]}]},{"id":"lunzheng","name":"议论文论证逻辑","items":[{"name":"举例论证","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">樊锦诗守敦煌</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">事例+坚守的分析+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">论\\\"勤奋\\\"</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">匡衡凿壁偷光+分析\\\"条件再差也不放弃\\\"+回扣\\\"勤奋成就人生\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">论\\\"诚信\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">曾子杀猪+分析\\\"对孩子也守信\\\"+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">论\\\"创新\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">鲁班观草叶造锯+分析\\\"观察+思考\\\"+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">反例</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">只摆事例不分析=\\\"例子堆砌\\\"，分析才是得分点</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">公式</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">分论点→事例简述→扣题分析→小结回扣</text></g></svg>","目标":"今天学会举例论证：用事例证明分论点，分析才是灵魂。","类比":"举例就像证人出庭：光有观点不行，得叫证人作证。","讲解":"公式：分论点+事例简述+扣题分析+小结回扣。事例是载体，分析才是灵魂。","口诀":"观点事例加分析，回扣分论才扎实","例子":["樊锦诗守敦煌：事例+坚守的分析+回扣","论\"勤奋\"：匡衡凿壁偷光+分析\"条件再差也不放弃\"+回扣\"勤奋成就人生\"","论\"诚信\"：曾子杀猪+分析\"对孩子也守信\"+回扣","论\"创新\"：鲁班观草叶造锯+分析\"观察+思考\"+回扣","反例：只摆事例不分析=\"例子堆砌\"，分析才是得分点","公式：分论点→事例简述（100字内）→扣题分析→小结回扣","论\"坚持\"：同桌每天练字一页，一学期后字大变样+分析\"每天一小步\"+回扣","论\"诚信\"：小明答应还书按时还+分析\"小事守信才靠得住\"+回扣","论\"勤奋\"：班长每天早读半小时，英语越读越顺+分析\"天天练才有语感\"+回扣","论\"分享\"：小红把新书借给同学，全班都爱上了阅读+分析\"分享让快乐翻倍\"+回扣"],"深讲":"举例论证不是“讲个故事就完事”：故事只是证据，真正说服人的是后面的分析——这个例子为什么能证明我的观点。没有分析的例子，再感人也只是“堆材料”。记住公式：分论点→事例简述（越短越好，100字内）→扣题分析→小结回扣。","怎么认":["先找分论点：这段要证明什么？","再看事例：故事讲的是不是这回事？","最后看分析：有没有讲清“这个例子为什么能证明观点”？没有，就是例子堆砌。"],"辨析":"举例论证和“讲故事”的区别在“扣题”：讲故事讲完就完了；举例论证讲完必须回扣——“这说明……”“可见……”。没有回扣的例子，读者不知道你想证明什么。","例句解析":[{"句":"论\"勤奋\"：匡衡凿壁偷光+分析\"条件再差也不放弃\"+回扣\"勤奋成就人生\"","析":"事例只讲了“凿壁偷光”的意思，重点在分析“条件再差也不放弃”——分析把事例和“勤奋”连起来，回扣点明观点，结构才完整。"},{"句":"反例：只摆事例不分析=\"例子堆砌\"，分析才是得分点","析":"光摆事例，读者只能看到故事，看不到观点。分析是桥梁：没有桥，事例到不了观点那边。"}],"易错":"两个坑：一是事例写太长（超过100字），挤占分析空间；二是事例讲完不分析不回扣，变成例子堆砌。记住：分析才是得分点。","练习":[{"q":"举例论证最关键的一步是？","options":["事例讲得长","扣题分析","事例讲得感人"],"answer":1,"解析":"事例只是证据，分析把事例和观点连起来——没有分析就是例子堆砌。"},{"q":"“论勤奋：匡衡凿壁偷光。”这样写缺什么？","options":["缺事例","缺分析和回扣","缺分论点"],"answer":1,"解析":"只有事例没有分析，读者不知道这个故事怎么证明勤奋——要补“条件再差也不放弃”的分析和回扣。"},{"q":"事例简述应该多长？","options":["越长越好","100字内，越短越好","不用写事例"],"answer":1,"解析":"事例是载体不是主角，100字内讲清即可，篇幅要留给分析和回扣。"}],"前置知识":["概念：定义与划分"]},{"name":"道理论证","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">论\\\"坚持\\\"</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">荀子\\\"锲而不舍，金石可镂\\\"+解释+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">论\\\"学习方法\\\"</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">朱熹\\\"读书有三到，心到眼到口到\\\"+阐释+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">论\\\"谦虚\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"满招损，谦受益\\\"+阐释为什么适用+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">论\\\"团结\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"人心齐，泰山移\\\"+阐释+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">忌</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">名言堆三四句却不阐释=白费，阐释才是得分点</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">公式</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">分论点→名言/定理→阐释→回扣</text></g></svg>","目标":"今天学会道理论证：用名言定理证明观点，并讲清为什么。","类比":"道理论证就像\"请权威背书\"：名人名言、定理公理往那一摆，分量立马不同。","讲解":"公式：分论点+名言/定理+阐释（为什么这句能证明观点）+回扣。","口诀":"名言开道，阐释跟上","例子":["论\"坚持\"：荀子\"锲而不舍，金石可镂\"+解释+回扣","论\"学习方法\"：朱熹\"读书有三到，心到眼到口到\"+阐释+回扣","论\"谦虚\"：\"满招损，谦受益\"+阐释为什么适用+回扣","论\"团结\"：\"人心齐，泰山移\"+阐释+回扣","忌：名言堆三四句却不阐释=白费，阐释才是得分点","公式：分论点→名言/定理→阐释（为什么能证明）→回扣","论\"学习态度\"：《论语》\"学而不思则罔，思而不学则殆\"+阐释+回扣","论\"诚信\"：《论语》\"人而无信，不知其可也\"+阐释+回扣","论\"谦虚\"：《论语》\"三人行，必有我师焉\"+阐释+回扣","提醒：名言要和分论点贴得紧，贴不上的名言再有名也是白摆"],"深讲":"道理论证是“请权威来背书”：名人名言、定理、公理自带分量。但名言自己不会说话——必须阐释：这句名言为什么能证明我的观点？不阐释的名言堆得再多，也只是“贴标签”，不是论证。","怎么认":["找名言：引的是谁的话、哪条定理？","找阐释：有没有讲这句为什么能证明观点？","找回扣：最后有没有回到分论点？"],"辨析":"道理论证和举例论证的区别：举例是拿“事”证明（匡衡的故事），道理论证是拿“理”证明（荀子的话、定理）。一个讲事实，一个讲道理；写议论文时两者常常配合用。","例句解析":[{"句":"论\"坚持\"：荀子\"锲而不舍，金石可镂\"+解释+回扣","析":"荀子的话讲“不停地刻，连金石都能刻穿”——阐释要把“刻”对应到“坚持”，再回扣“坚持才能成事”，名言才算用上了。"},{"句":"忌：名言堆三四句却不阐释=白费，阐释才是得分点","析":"三四句名言排队站岗，看起来有气势，其实都没和观点连上线——阐释才是把名言变成论证的那一步。"}],"易错":"名言不能堆砌，阐释（为什么适用）才是得分点","练习":[{"q":"道理论证里最不能少的是？","options":["名言的数量","阐释（为什么能证明观点）","名言的作者名气"],"answer":1,"解析":"名言再有名，不阐释就和观点连不上线——阐释才是得分点。"},{"q":"论“谦虚”引用“满招损，谦受益”，接下来最应该写什么？","options":["再引一句名言","阐释为什么骄傲招损、谦虚受益","直接结尾"],"answer":1,"解析":"要讲清这句为什么能证明谦虚——骄傲让人看不见缺点，谦虚让人不断进步。"},{"q":"下面哪种是道理论证？","options":["讲匡衡凿壁偷光的故事","引用荀子“锲而不舍，金石可镂”并阐释","正反两个例子对照"],"answer":1,"解析":"引用名言讲道理是道理论证；讲故事是举例论证；正反对照是对比论证。"}],"前置知识":["概念：定义与划分"]},{"name":"对比论证","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">论\\\"勤奋\\\"</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">方仲永荒废 vs 匡衡凿壁</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">论\\\"诚信\\\"</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">曾子杀猪守信 vs 周幽王烽火戏诸侯失信</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">论\\\"节俭\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">朱元璋节俭 vs 石崇斗富奢靡</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">论\\\"谦虚\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">孔子不耻下问 vs 项羽刚愎自用</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">结构</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">正面事例+反面事例+对比分析→结论</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">提醒</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">对比点要扣住分论点，不能为对比而对比</text></g></svg>","目标":"今天学会对比论证：正反例子一对比，结论就清楚了。","类比":"对比就像\"照妖镜\"：正反一放，好坏立现。","讲解":"正面例子+反面例子+对比分析，得出结论。是非分明，说服力强。","口诀":"正反对照，是非自现","例子":["论\"勤奋\"：方仲永荒废 vs 匡衡凿壁","论\"诚信\"：曾子杀猪守信 vs 周幽王烽火戏诸侯失信","论\"节俭\"：朱元璋节俭 vs 石崇斗富奢靡","论\"谦虚\"：孔子不耻下问 vs 项羽刚愎自用","结构：正面事例+反面事例+对比分析→结论","提醒：对比点要扣住分论点，不能为对比而对比","论\"认真\"：小明检查三遍全对 vs 小刚交卷就跑错一半","论\"坚持\"：每天练跑步的同学越跑越轻松 vs 三天打鱼两天晒网的同学一直喘","论\"合作\"：小组分工的同学做得又快又好 vs 单打独斗的同学手忙脚乱","论\"阅读\"：爱读书的同学写作文有话说 vs 从不读书的同学对着作文纸发呆"],"深讲":"对比论证是“正反一放，好坏立现”：正面例子和反面例子放在一起，对比的点必须扣住分论点。对比不是为了热闹——比完要分析：为什么一个成、一个败？分析出原因，结论才有说服力。","怎么认":["找正面和反面两个例子。","看对比点：是不是扣住分论点？（论勤奋就比勤奋不勤奋，别比别的）","看对比分析：比完有没有讲清原因、得出结论？"],"辨析":"对比论证和“举两个例子”不一样：举两个正面例子是举例论证；一正一反、比出高下才是对比论证。没有反面，就没有对比。","例句解析":[{"句":"论\"勤奋\"：方仲永荒废 vs 匡衡凿壁","析":"一个天赋好却荒废，一个条件差却勤奋——天赋和条件都不是决定因素，对比点正好扣住“勤奋”，结论“勤奋成就人生”就立住了。"},{"句":"提醒：对比点要扣住分论点，不能为对比而对比","析":"论勤奋却对比“谁长得高”，比得再热闹也没用——对比点跑偏，论证就跑偏。"}],"易错":"两个坑：一是对比点跑偏（论勤奋比长相）；二是比完不分析，只把两个例子并排放，读者看不出你想说什么。比完一定要分析原因、得出结论。","练习":[{"q":"对比论证必须有什么？","options":["两个正面例子","一正一反两个例子","三个例子"],"answer":1,"解析":"一正一反、比出高下才是对比；两个正面例子只是举例论证。"},{"q":"论“坚持”，下面哪组对比最合适？","options":["小明高 vs 小刚矮","每天练跑步越跑越轻松 vs 三天打鱼一直喘","小红爱笑 vs 小军爱哭"],"answer":1,"解析":"对比点必须扣住“坚持”：天天练和三天打鱼，正好是坚持和不坚持。"},{"q":"对比完两个例子，最应该做什么？","options":["再比一组","分析原因、得出结论","直接换话题"],"answer":1,"解析":"比完要分析为什么一个成一个败，结论才有说服力；只并排放例子等于没论证。"}],"前置知识":["概念：定义与划分"]},{"name":"常见谬误","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">滑坡</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">今天不上补习班，明天就考不上大学</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">人身攻击</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他学习不好，他的话不可信</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">偷换概念</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">辩论\\\"作业该不该多\\\"时把\\\"作业\\\"偷换成\\\"学习\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">稻草人</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">你说\\\"该减少作业\\\"，他反驳\\\"你就是不想学习\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">滑坡</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">这次考砸→考不上高中→找不到工作→人生完蛋</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">诉诸权威</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"专家都说对，所以一定对\\\"</text></g></svg>","目标":"今天学会认出四种谬误：偷换概念、滑坡、人身攻击、稻草人。","类比":"谬误就像逻辑陷阱：看起来有道理，一脚踩空。","讲解":"偷换概念（白马非马式）、滑坡谬误（可能性变必然性）、人身攻击（不驳观点驳人）、稻草人（曲解对方再打）。","口诀":"偷滑人稻，谬误四套","例子":["滑坡：今天不上补习班，明天就考不上大学","人身攻击：他学习不好，他的话不可信","偷换概念：辩论\"作业该不该多\"时把\"作业\"偷换成\"学习\"（概念变了）","稻草人：你说\"该减少作业\"，他反驳\"你就是不想学习\"（曲解后再打）","滑坡：这次考砸→考不上高中→找不到工作→人生完蛋（可能变必然）","诉诸权威：\"专家都说对，所以一定对\"（不看论证看头衔）","循环论证：\"这本书好，因为它就是好书\"（用结论证明结论）","诉诸感情：\"你忍心看我不及格吗？所以这道题应该算我对\"（用同情代替论证）","非黑即白：\"不喜欢数学，就是讨厌学习\"（中间还有很多情况）","因果倒置：\"因为他成绩好，所以老师喜欢他\"（也可能是老师喜欢才成绩好，因果说反了）"],"深讲":"谬误是“看起来有道理，其实站不住”的话。常见四套：偷换概念（中途换了词的意思）、滑坡谬误（把可能说成必然）、人身攻击（不驳观点驳人）、稻草人（先曲解对方再打）。另外还有循环论证（用结论证明结论）、诉诸权威（只看头衔不看论证）、非黑即白（中间还有别的情况却说只有两种）。","怎么认":["问：词的意思中途换了吗？（偷换概念）","问：每一步因果都必然吗？（滑坡）","问：反驳的是观点还是人？（人身攻击）","问：打的是对方原话，还是曲解后的靶子？（稻草人）"],"辨析":"滑坡谬误和“合理推测”不一样：“不好好复习可能考不好”是合理推测（说“可能”）；“这次考砸→找不到工作→人生完蛋”是滑坡（把可能说成必然，还一环套一环）。","例句解析":[{"句":"滑坡：这次考砸→考不上高中→找不到工作→人生完蛋（可能变必然）","析":"每一步都只是“可能”，连起来却说成了“必然”——考砸不一定考不上高中，考不上高中也不一定找不到工作，链条每环都要打问号。"},{"句":"稻草人：你说\"该减少作业\"，他反驳\"你就是不想学习\"（曲解后再打）","析":"对方原话是“减少作业”，被曲解成“不想学习”再打倒——打的是自己立的稻草靶子，不是对方真正的观点。"}],"易错":"认谬误时别乱扣帽子：先确认对方原话到底是什么（防稻草人误判），再确认每步因果是不是必然（防滑坡误判）。扣错帽子，自己就成了诡辩的一方。","练习":[{"q":"“他普通话不标准，他讲的道理肯定不对”犯了什么谬误？","options":["滑坡谬误","人身攻击","偷换概念"],"answer":1,"解析":"普通话标不标准和道理对不对没关系，攻击人而不反驳观点，是人身攻击。"},{"q":"“这本书好，因为它就是好书”犯了什么谬误？","options":["循环论证","滑坡谬误","稻草人"],"answer":0,"解析":"用结论“就是好书”来证明结论“这本书好”，原地打转，是循环论证。"},{"q":"“不喜欢数学，就是讨厌学习”犯了什么谬误？","options":["诉诸权威","非黑即白","人身攻击"],"answer":1,"解析":"不喜欢数学和讨厌学习之间还有很多情况（喜欢语文、喜欢画画），硬说成只有两种，是非黑即白。"}],"动画":{"steps":[{"tokens":["滑坡：","不上补习班","→","考不上大学"],"note":"可能性被说成必然性：每环因果经得起问吗？"},{"tokens":["人身攻击：","他成绩差","→","话不可信"],"note":"不驳观点驳人：成绩差≠观点错"},{"tokens":["稻草人：","曲解对方","→","打倒假想敌"],"note":"先歪曲再反驳：打的是自己立的靶子"}]},"小测":[{"q":"\"你这么胖，还好意思谈健康饮食？\"犯了什么谬误？","options":["滑坡谬误","人身攻击","偷换概念"],"answer":1,"解析":"攻击人而不反驳观点，是人身攻击。"}],"前置知识":["举例论证","道理论证"]}]},{"id":"tuili","name":"日常语言推理","items":[{"name":"言外之意","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">问</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">蛋糕好吃吗？答：盘子很漂亮。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">妈妈</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"你房间真'整洁'啊！\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">问</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">这道题难吗？答：全班最高分60。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">\\\"你先走吧，我还有点事\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">\\\"改天请你吃饭\\\"</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">识别</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">违反\\\"相关</text></g></svg>","目标":"今天学会听出言外之意：话里没明说的意思。","类比":"言外之意就像冰山：说出口的只是水面上的尖，意思藏在水下。","讲解":"合作原则：说话默认 truthful、相关、清楚。违反处即有言外之意。","口诀":"话里有话藏水下，违反常规是信号","例子":["问：蛋糕好吃吗？答：盘子很漂亮。（=不好吃）","妈妈：\"你房间真'整洁'啊！\"（=乱得不行，反话）","问：这道题难吗？答：全班最高分60。（=很难）","\"你先走吧，我还有点事\"（=不想跟你一起走）","\"改天请你吃饭\"（=客套话，不必当真）","识别：违反\"相关","清楚\"的地方，就有言外之意","问：电影好看吗？答：还行。（=一般，没直说不好看）","爸爸：\"你的袜子在阳台上晒太阳呢！\"（=袜子晒好了，快去收）","问：这件衣服贵吗？答：也就我一个月零花钱吧。（=很贵）","\"我等了你一个世纪！\"（=等了很久，别迟到了）"],"深讲":"说话有个默认规矩：说真话、说相关的、说清楚。话里一旦违反了规矩——答非所问、故意反着说、说得含糊——听话的人就知道：字面意思不是真意思，真意思藏在水下。找言外之意，就是找“哪里违反了规矩”。","怎么认":["先听字面：他原话是什么意思？","再找违规：答非所问？反话？含糊其辞？客套话？","最后推真意：结合场合，他真正想说的是什么？"],"辨析":"言外之意和“说谎”不一样：说谎是想让你相信假话；言外之意是说话人默认你能听懂——“盘子很漂亮”不是骗你蛋糕好吃，是委婉告诉你“不好吃”。一个是骗，一个是暗示。","例句解析":[{"句":"问：蛋糕好吃吗？答：盘子很漂亮。（=不好吃）","析":"问蛋糕，答盘子——违反了“相关”规矩。故意不提蛋糕，就是在委婉说“蛋糕不好吃，不好意思直说”。"},{"句":"妈妈：\"你房间真'整洁'啊！\"（=乱得不行，反话）","析":"房间明明很乱，妈妈却说“整洁”——故意违反“说真话”规矩。反着说，就是要你听出“乱得不行，快收拾”。"}],"易错":"别把所有话都听出言外之意：“改天请你吃饭”是客套，但“明天请你吃饭”就是真约——场合和说法决定有没有言外之意；直说的话，别硬找弦外之音。","练习":[{"q":"问：电影好看吗？答：还行。这句话的言外之意最可能是？","options":["电影很好看","电影一般，没直说不好看","电影还没上映"],"answer":1,"解析":"“还行”含糊其辞，没直说“好看”——违反“说清楚”规矩，真意是“一般”。"},{"q":"“你的袜子在阳台上晒太阳呢！”爸爸真正想说的是？","options":["袜子喜欢晒太阳","快去把袜子收回来","阳台阳光很好"],"answer":1,"解析":"这不是讲袜子，是提醒：袜子晒好了，快去收——暗示藏在陈述句里。"},{"q":"下面哪句是反话（言外之意和字面相反）？","options":["你房间真整洁啊（房间很乱时）","明天请你吃饭","我作业写完了"],"answer":0,"解析":"房间乱却说“整洁”，字面和真意相反，是反话；另外两句是直说。"}],"决策树":"①先听字面：他原话是什么意思？→②再找违规：答非所问？反话？含糊其辞？客套话？→都没违规：按字面理解→有违规：结合场合推真意→③验证：真意符合说话人身份和场合吗？→符合：就是言外之意→不符合：重新推","前置知识":[]},{"name":"因果链","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">铁钉→马掌→战马→将军→战争→帝国</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">熬夜→上课犯困→听不懂→成绩下滑→考不上</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">多读书→词汇量大→作文好→语文高分</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">断链反例</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">早上没吃早饭→考试失利</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">方法</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">对每环连问5个\\\"为什么\\\"，问到底就是根因</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">写作</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">议论文\\\"因果论证\\\"就是摆出一条完整因果链</text></g></svg>","目标":"今天学会找因果链：一环扣一环，每环都问为什么。","类比":"因果链就像多米诺：失了一颗铁钉，亡了一个帝国。","讲解":"找因果要一环扣一环，每环都经得起问为什么（5个为什么）。","口诀":"找因一环一环问，断了链条不算数","例子":["铁钉→马掌→战马→将军→战争→帝国","熬夜→上课犯困→听不懂→成绩下滑→考不上高中（每环都经得起问为什么）","多读书→词汇量大→作文好→语文高分（链条完整）","断链反例：早上没吃早饭→考试失利（中间缺环节，链条不牢）","方法：对每环连问5个\"为什么\"，问到底就是根因","写作：议论文\"因果论证\"就是摆出一条完整因果链","多运动→身体壮→不容易生病→少请假→功课不掉队（链条完整）","上课走神→笔记没记全→复习没材料→考试丢分（每环都问为什么）","断链反例：多喝水→成绩变好（中间缺环节：喝水和成绩没有链条）","五问法：字写不好→为什么？练得少→为什么练得少？没安排时间→为什么没安排？玩手机占了时间→根因：时间管理"],"深讲":"因果链是把“因为……所以……”接成长串：A→B→C→D，每一环都要经得起问“为什么”。有一环问不下去，链条就断了，结论就站不住。“5个为什么”就是检查工具：对每一环连问5次为什么，问到底就找到根因。","怎么认":["把事情写成一串：A→B→C→D。","对每一环问“为什么”：B真的是A造成的吗？","有一环答不上来，就是断链——结论不可靠。"],"辨析":"因果链和“单因果”不一样：单因果只讲一对（熬夜→困）；因果链讲一串（熬夜→困→听不懂→成绩下滑）。链越长，越要一环一环查——长链最容易在中间断掉。","例句解析":[{"句":"熬夜→上课犯困→听不懂→成绩下滑→考不上高中（每环都经得起问为什么）","析":"每环都能问“为什么”：为什么犯困？因为熬夜。为什么听不懂？因为犯困。一环扣一环，链条才牢。"},{"句":"断链反例：早上没吃早饭→考试失利（中间缺环节，链条不牢）","析":"没吃早饭和考试失利之间缺了好几环（饿→没精神→没发挥好），直接跳过去就是断链——不能这么推。"}],"易错":"长链条最容易犯两个错：一是中间跳环（熬夜直接跳到考不上大学）；二是把“相关”当“因果”（公鸡打鸣和天亮一起出现，不是谁造成谁）。每环都要问一句“为什么”。","练习":[{"q":"“多喝水→成绩变好”错在哪里？","options":["水喝得不够多","中间缺环节，链条不牢","成绩不能变好"],"answer":1,"解析":"喝水和成绩之间没有链条——缺了环节直接跳，就是断链。"},{"q":"“成绩下滑”用5个为什么找根因，第一步问什么？","options":["为什么成绩下滑","为什么要考试","为什么有学校"],"answer":0,"解析":"从结果往回问：为什么下滑？→没听懂→为什么没听懂？→上课困……一环一环问到底。"},{"q":"下面哪条是完整的因果链？","options":["早上没吃早饭→考试失利","多读书→词汇量大→作文好→语文高分","公鸡打鸣→天亮"],"answer":1,"解析":"读书→词汇→作文→高分，每环都经得起问为什么；A跳环，C是相关不是因果。"}],"决策树":"①把事情写成一串：A→B→C→D→②对每一环问\"为什么\"：B真的是A造成的吗？→都答得上：链条可靠→有环答不上：断链→③断链处：缺证据就补证据，真无关就推倒重来","前置知识":["因果复句"]},{"name":"因果链：多米诺","目标":"今天学会连续问五个为什么，一直找到根因。","类比":"因果就像多米诺骨牌：失了一颗铁钉，丢了一只马掌，亡了一个帝国。","图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">少一颗铁钉</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">小原因</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">掉马掌→折战马→伤将军</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">环环相扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">亡一个帝国</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">大后果</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">因果链=多米诺：五个为什么问到底<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","练习":[{"q":"“忘带红领巾→被扣分→班级丢了流动红旗”这是？","options":["普通因果","多米诺（小因大果）","没有因果"],"answer":1,"解析":"起点只是忘带红领巾，终点却是全班丢红旗——小起因放大成大结果，是多米诺。"},{"q":"“每天读10分钟→一学期读完六本→作文有话写了”说明了什么？","options":["读书没用","小习惯顺着链条会放大","作文不用练"],"answer":1,"解析":"每天10分钟很小，顺着链条传下去，变成了一学期六本、作文有话写——好习惯的多米诺。"},{"q":"“我今天多吃了一块糖，所以长胖了”错在哪里？","options":["糖不能吃","一小因推不出大果，链条没连上","长胖写错了"],"answer":1,"解析":"一块糖和长胖之间没有连上的链条——硬放大就是错的，不是多米诺。"}],"动画":{"steps":[{"tokens":["少了","一颗铁钉"],"note":"起点：小得不起眼"},{"tokens":["丢了","一只马掌"],"note":"连锁：铁钉→马掌"},{"tokens":["亡了","一个帝国"],"note":"终点：蝴蝶效应"}]},"讲解":"找因果要一环扣一环，每环都问\"为什么\"，连续问5次到根因。","口诀":"因果链条环环扣，五个为什么问到底","小测":[{"q":"\"因为他是北方人，所以思想守旧\"错在哪环？","options":["籍贯推不出思想","北方人确实守旧","没错"],"answer":0,"解析":"籍贯→思想这环因果不成立，是强加因果。"}],"例子":["完整链：少一颗铁钉→掉一只马掌→折一匹战马→伤一位将军→败一场战争→亡一个帝国","五问法：成绩下滑→为什么没听懂→为什么上课困→为什么熬夜→为什么玩手机→根因：缺自律","反例：公鸡打鸣→天亮（把\"相关\"当\"因果\"，还颠倒了）","反例：熬夜→考不上大学（跳了三环，链条不牢）","口诀应用：环环相扣+五个为什么问到底","小原因大后果：忘带红领巾→被扣分→班级丢了流动红旗→全班一周的努力白费","小习惯大变化：每天读10分钟→一个月读完一本书→一学期读完六本→作文有话写了","推倒第一块：早上赖床10分钟→赶不上校车→迟到→错过早读→一天都心慌","反例：只推倒一块牌，别的牌没动——\"我今天多吃了一块糖，所以长胖了\"（一小因推不出大果，链条没连上）","好习惯多米诺：整理书包→第二天不慌→上课专注→作业写得快→有空多读一本书"],"深讲":"多米诺讲的是“小原因、大后果”：第一块牌很小，倒下去却能推倒一整排。生活里也是这样：一个小习惯（每天读10分钟）、一个小疏忽（忘带红领巾），顺着链条传下去，会变成很大的结果。所以别小看第一块牌——推倒它之前，先想想后面会倒什么。","怎么认":["找第一块牌：最小的那个起因是什么？","顺着看：它推倒了什么？那一块又推倒了什么？","看到终点：小起因是不是变成了大结果？是，就是多米诺。"],"辨析":"多米诺和普通因果链的区别在“放大”：普通因果链只要求环环相扣；多米诺还要求越传越大——小起因、大终点。如果起因和结果差不多大（多喝水→多上厕所），那只是因果链，不是多米诺。","例句解析":[{"句":"完整链：少一颗铁钉→掉一只马掌→折一匹战马→伤一位将军→败一场战争→亡一个帝国","析":"起点只是一颗铁钉，终点却是一个帝国——每一环都比前一环大，这就是多米诺的“放大”。"},{"句":"反例：公鸡打鸣→天亮（把\"相关\"当\"因果\"，还颠倒了）","析":"公鸡打鸣和天亮只是同时出现，不是因果；真要说，也是天亮在前、打鸣在后——相关≠因果，因果还说反了。"}],"易错":"多米诺最容易犯的错是“硬放大”：一小因推不出大果时，链条其实没连上（“多吃一块糖所以长胖了”）。放大必须每环都真，不能为了效果硬推。","决策树":"①找第一块牌：最小的那个起因是什么？→②顺着看：它推倒了什么？那一块又推倒了什么？→③到终点：小起因变成大结果了吗？→是：多米诺成立→否：链条中断，找断点→④警惕：每环都必然吗？→有偶然环：多米诺夸大，降级为\"可能\"","前置知识":["因果链"]}]}]},"reading":{"categories":[{"id":"tongyong","items":[{"name":"三遍阅读法","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">第一遍泛读</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">抓体裁、抓主旨</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">第二遍精读</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">析结构、圈关键句</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">第三遍跳读</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">带着题目找答案区</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">泛读只看标题+首尾段，1分钟定体裁</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">精读圈出过渡句、抒情议论句</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">跳读</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">题干关键词→原文定位→前后三句找答案</text></g></svg>","例子":["第一遍泛读：抓体裁、抓主旨","第二遍精读：析结构、圈关键句","第三遍跳读：带着题目找答案区","泛读只看标题+首尾段，1分钟定体裁","精读圈出过渡句、抒情议论句（主旨常藏这里）","跳读：题干关键词→原文定位→前后三句找答案"],"口诀":"泛读抓主旨，精读析结构，跳读找答案","易错":"切忌没读完文章就匆忙答题","讲解":"中考阅读的标准流程，先整体后局部","怎么认":["第一遍通读：不查生词、不纠结细节，3分钟内读完，标出自然段号，心里回答'这篇文章讲了什么事'。","第二遍带题读：读题干、圈题眼，带着问题回原文找答案，关键句下画线。","第三遍验证读：写完答案后，把每个答案代回原文，检查'题干问的'和'我答的'是不是一回事。"],"例句解析":[{"句":"题：'三遍阅读法'中，第二遍读的主要任务是什么？","析":"走三遍流程：第一遍已通读全文知道大意；第二遍的关键是'带题'——读题干、圈题眼（如'主要任务'），回原文定位到讲第二遍的段落；第三遍验证：答案'带着题目找答案、圈画关键句'与原文'先整体后局部'的第二步一致，确认无误。"}],"前置知识":[]},{"name":"找中心句","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">开头总起句、结尾总结句</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">段落首句尾句</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">议论文开头</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"勤奋是成功之母\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">记叙文结尾</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"这就是我的母亲\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">抒情议论句多是中心句，叙事句一般不是</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">独立成段的句子，常是中心句或过渡句</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["开头总起句、结尾总结句","段落首句尾句","议论文开头：\"勤奋是成功之母\"（开门见山亮观点）","记叙文结尾：\"这就是我的母亲\"（点题+抒情）","抒情议论句多是中心句，叙事句一般不是","独立成段的句子，常是中心句或过渡句"],"口诀":"开头结尾重点看，首尾常把中心担","易错":"中心句多是议论抒情句，不是叙事句","讲解":"中心句常出现在开头结尾、段落首尾，多为概括性语句","怎么认":["先看段首和段尾：中心句八成藏在这两个位置，先读这两句。","找总结性词语：'总之''可见''因此''归根结底'后面的句子多半是中心句。","做减法验证：删掉举例、数据、细节描写，剩下的主干如果能概括全段，就是中心句。"],"例句解析":[{"句":"段落：'春天来了。小草探出头来，柳树抽出新芽，燕子从南方飞回来。总之，大自然在春天苏醒了。'中心句是哪句？","析":"按步骤找：先看段首段尾——段尾'总之，大自然在春天苏醒了'；再看标志词——'总之'是典型总结词；做减法验证——删掉小草、柳树、燕子三个例子，剩下的'大自然在春天苏醒了'正好概括全段。三步都指向最后一句，确认。"}],"前置知识":["主语","谓语"]},{"name":"语境意识","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">词语含义到上下文中找</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">答案组织紧扣文章中心</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">\\\"他'火'了\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">语境是演出→走红，不是着火</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">\\\"这个人很'冷'\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">语境是待人→冷漠，不是温度</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">答题引用原文，别自己编</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">开放题也要先扣文本再引申</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["词语含义到上下文中找","答案组织紧扣文章中心","\"他'火'了\"：语境是演出→走红，不是着火","\"这个人很'冷'\"：语境是待人→冷漠，不是温度","答题引用原文，别自己编","开放题也要先扣文本再引申"],"口诀":"词不离句，句不离段，段不离篇","易错":"脱离文本的过度推断是丢分主因","讲解":"一切答案以文本为依据，联系上下文","怎么认":["词语题先把词放回原句，连读三遍，不许脱离上下文猜词义。","看前后句的逻辑关系：是转折（但是）、因果（所以）、并列（同时）？关系决定词义方向。","用全文主旨做终审：凡是和主旨矛盾的理解，一律排除。"],"例句解析":[{"句":"'他这个人很冷，但心肠极热。'中'冷'是什么意思？","析":"走语境三步：放回原句读——'冷'后紧跟转折'但心肠极热'；看逻辑关系——'但'表转折，'冷'与'热'相反，'冷'应指外表冷漠；用主旨终审——全句褒扬此人，'冷'不能解作'心寒、恶劣'。答案：外表冷淡、不热情。"}],"前置知识":[]},{"name":"关键句定位","图示":"<svg viewBox=\"0 0 640 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">关键句定位</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">开头句、结尾句、过渡句、抒情议论句常藏着主旨</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">读题干圈题眼：人名、时间、关键词，带着题眼去原文'扫描'。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">锁定四类句子优先看：开头句、结尾句、过渡句、抒情议论句，主旨多藏在这里。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">逐字核对：把题干的每个词和原文对应句比对，偷换概念的最爱玩'差不多'游戏。</text></g></svg>","例子":["体现作者立场的句子","过渡句、抒情议论句、比喻句","\"总之\"\"因此\"后面的句子常是总结句","独立成段的一句话：强调","过渡","主旨","反问句：\"难道这不是爱吗？\"（=这就是爱，立场句）","开头设问自答处，常是全文纲领"],"口诀":"立场过渡抒情议论，比喻连问要留神","易错":"独立成段的句子常有特殊作用","讲解":"开头句、结尾句、过渡句、抒情议论句常藏着主旨","怎么认":["读题干圈题眼：人名、时间、关键词（如'第一次'），带着题眼去原文'扫描'。","锁定四类句子优先看：开头句、结尾句、过渡句、抒情议论句，主旨多藏在这里。","逐字核对：把题干的每个词和原文对应句比对，偷换概念的最爱玩'差不多'游戏。"],"例句解析":[{"句":"题：'作者在开头写那是一个寒冷的冬天有什么作用？'如何定位？","析":"三步定位：圈题眼——'开头''冬天'；锁定句子类型——开头句，属'四类关键句'之首；逐字核对——'寒冷的冬天'是环境描写，对应'开头：奠定感情基调/渲染气氛'。答案：渲染悲凉气氛，为下文做铺垫。"}],"前置知识":["找中心句"]}],"name":"通用阅读方法"},{"id":"tixing","items":[{"name":"概括内容","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">模式</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">什么人＋在什么情况下＋做什么事＋什么结果</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">如</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">本文记叙了小明在雨天坚持上学的故事</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">要素法</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">时间+地点+人物+起因+经过+结果</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">合并段意</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">每段小标题→连成一句话</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">摘录法</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">找中心句，稍加改造</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">忌</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">只写\\\"本文写了一件事\\\"</text></g></svg>","例子":["模式：什么人＋在什么情况下＋做什么事＋什么结果","如：本文记叙了小明在雨天坚持上学的故事","要素法：时间+地点+人物+起因+经过+结果（记叙文）","合并段意：每段小标题→连成一句话","摘录法：找中心句，稍加改造","忌：只写\"本文写了一件事\"（缺要素=白答）"],"口诀":"人物事件加结果，要素齐全才算数","易错":"必须包括“人物+事情”两要素","讲解":"要素归纳法/合并段意法/摘录中心句","怎么认":["分段：按时间、地点、情节转折把文章切成2-4块。","每段一句话：套'谁＋做了什么＋结果如何'，删掉修饰和细节。","合并同类项：把各段一句话连起来，删重复、留主干，字数压到题干要求内。"],"例句解析":[{"句":"概括《小巷深处》讲了一个什么故事？（限30字）","析":"走三步：分段——'我'被领养→长大后嫌弃养母→养母为'我'付出→'我'醒悟；每段一句话——'养女嫌弃养母'是主干；合并——'养女由嫌弃养母到理解感恩'（14字）。检查：要素齐（谁+转变+结果），30字内，确认。"}],"前置知识":["找中心句","三遍阅读法"]},{"name":"标题赏析","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">问</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">为什么以“灯”为题？</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">答</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">①本义②深层③线索/主旨作用</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">《背影》</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">本义父亲的背影+深层父爱+线索</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">《春》</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">本义春天+深层对未来的希望+开篇点题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">标题是人名的</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">多以人物为线索</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">赞美人物</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["问：为什么以“灯”为题？","答：①本义（文章写灯）②深层（灯象征希望）③线索/主旨作用","《背影》：本义父亲的背影+深层父爱+线索（以背影串全文）","《春》：本义春天+深层对未来的希望+开篇点题","标题是人名的：多以人物为线索","赞美人物","答题：本义+深层（象征/双关）+结构作用（线索/点题）"],"口诀":"本义深层两层皮，线索主旨不能离","讲解":"标题是文眼：概括情节、作线索、点明中心、象征义","怎么认":["先判标题类型：是线索（贯穿全文的物）、象征（一语双关）、悬念（设问反常），还是直白概括？","数它在文中出现几次：反复出现的标题多半是线索或象征。","量它与中心的距离：标题是'文眼'，赏析最后必须落到'点明中心/深化主旨'上。"],"例句解析":[{"句":"赏析标题《背影》。","析":"三步走：判类型——'背影'是父亲形象的浓缩，属'象征+线索'型；数出现——文中四写背影（望父买橘特写），是全文线索；量距离——背影凝聚父爱，标题点明'父子深情'的中心。答案：以'背影'为线索象征父爱，点明中心，含蓄感人。"}],"前置知识":["比喻","找中心句"]},{"name":"词句赏析","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">问</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">赏析“小草偷偷地钻出来”</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">答</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">①拟人手法②写出小草的生机与春天的气息③表达作者对春天的喜爱</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">\\\"月光如水\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">比喻+写月光皎洁+烘托宁静</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">\\\"他攥紧了拳头\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">动作描写+写紧张愤怒+为下文爆发铺垫</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">万能三步</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">手法→内容→情感</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">主旨</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["问：赏析“小草偷偷地钻出来”","答：①拟人手法②写出小草的生机与春天的气息③表达作者对春天的喜爱","\"月光如水\"：比喻+写月光皎洁+烘托宁静","\"他攥紧了拳头\"：动作描写+写紧张愤怒+为下文爆发铺垫","万能三步：手法→内容→情感","主旨","忌：只说\"用了比喻\"不分析（=没答）"],"口诀":"手法内容加主旨，三步走完是满分","易错":"只答手法不分析内容，或只谈内容不扣主旨","讲解":"万能三步：手法判定→内容解析→情感/主旨升华","怎么认":["先判定：是修辞（比喻/拟人/排比）还是锤炼过的动词/形容词？先给它'定性'。","再解内容：这个手法/这个词，把什么写成了什么样？（本体+喻体+特征）","最后升华：这个效果服务于什么情感或主旨？赏析不点主旨等于没答完。"],"例句解析":[{"句":"赏析'小草偷偷地从土里钻出来'。","析":"走万能三步：判定——'偷偷''钻'是拟人；解内容——把小草写成调皮的孩子，写出春草破土时的轻盈与生命力；升华——表达作者对春天的喜爱之情。检查：手法+内容+情感三件套齐了。"}],"前置知识":["比喻","拟人","语境意识"]},{"name":"结构作用","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">问</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">中间段落的作用？</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">答</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">承上启下；内容上深化主题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">塑造形象</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">开头</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">开篇点题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">设置悬念</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">埋伏笔</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["问：中间段落的作用？","答：承上启下；内容上深化主题","塑造形象","开头：开篇点题","设置悬念","埋伏笔","奠定感情基调","结尾：总结全文","升华主旨","首尾呼应","戛然而止留余味","中间：承上启下","插叙补背景","为下文铺垫","公式：结构（承上启下）+内容（写了什么）+主旨（对中心的作用）"],"口诀":"结构内容两分说","易错":"开头段还可能是设置悬念、埋伏笔","讲解":"开头：开篇点题/设置悬念；中间：承上启下；结尾：总结/升华/首尾呼应","怎么认":["先看位置：开头、中间、结尾，三种位置各有一套固定答法。","开头三选一：开篇点题/设置悬念/渲染气氛奠定基调；中间认准'承上启下'（过渡）；结尾三选一：总结全文/升华主旨/首尾呼应。","套'内容+结构+主旨'：先说这段写了什么，再说结构作用，最后点对主旨的贡献。"],"例句解析":[{"句":"'文章结尾写道：这就是我的母亲。'有什么作用？","析":"三步：看位置——结尾；选答法——结尾三选一中'总结全文+点明中心'最贴切；套三件套——内容上总结对母亲的回忆，结构上收束全文，主旨上点明'母爱伟大'的中心。答案：总结全文，点明中心，升华情感。"}],"前置知识":["三遍阅读法"]},{"name":"推断题","图示":"<svg viewBox=\"0 0 640 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">推断题</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">基于原文信息的适度推理，不夸大不缩小</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">先排除：凡是原文直接能找到原话的，那是信息题不是推断题，先划掉。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">找逻辑链：A→B→C，每一环都必须能在原文找到依据，链条断了就不能选。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">防'过度'：选项的说法比原文多出一层意思，一律不选。</text></g></svg>","例子":["三步：定位依据→适度推理→验证选项","依据必须在原文，不能靠常识脑补","排除\"原文原话\"项（那不是推断）","排除\"过度推断\"项（原文没给这么多）","排除\"逻辑矛盾\"项（与原文冲突）"],"口诀":"回到原文找依据，适度推理不臆断","易错":"排除“原文直接出现”（不是推断）、“过度推断”、“逻辑矛盾”项","讲解":"基于原文信息的适度推理，不夸大不缩小","怎么认":["先排除：凡是原文直接能找到原话的，那是信息题不是推断题，先划掉。","找逻辑链：A→B→C，每一环都必须能在原文找到依据，链条断了就不能选。","防'过度'：选项的说法比原文多出一层意思（'一定''必然''所有'），一律不选。"],"例句解析":[{"句":"原文：'他每天提前一小时到校，从不间断。'可推断出什么？A.他热爱学习 B.他家离学校很远 C.他一定是班长","析":"走三步：排除——三项原文都没直说；找逻辑链——'提前一小时+从不间断'→自律→A'热爱学习'有依据，B'家远'无依据（也可能是起得早）；防过度——C'一定是班长'超出信息量。答案：A。"}],"前置知识":["因果链","关键句定位"]},{"name":"开放探究","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">问</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">你认同作者的观点吗？为什么？</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">答</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">观点明确+文本支撑+联系实际</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">先亮观点，别绕弯子</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">理由必须引原文，不能空表态</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">联系实际举一例</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">言之成理即可，角度自选但要自圆其说</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["问：你认同作者的观点吗？为什么？","答：观点明确（我认为……）+文本支撑（引用原文）+联系实际","先亮观点，别绕弯子","理由必须引原文，不能空表态","联系实际举一例（生活/名人事例）","言之成理即可，角度自选但要自圆其说"],"口诀":"观点明确，文本支撑，联系实际","易错":"只表态不给理由，或理由脱离文本","讲解":"立场+论据（原文）+引申，言之成理即可","怎么认":["先亮观点：第一句就表明赞成/反对/辩证，不许模棱两可。","找依据：2个从原文找（引用原句），1个从生活或课外知识找，三足鼎立才站得稳。","控分寸：语言'有理有据有度'，不偏激、不跑题，结尾回扣原文。"],"例句解析":[{"句":"'你赞成文中主人公的做法吗？为什么？'","析":"三步走：亮观点——'我赞成'；找依据——原文'他把机会让给了更需要的人'（依据1）、'事后他说帮人就是帮己'（依据2），生活中'让座'现象类似（依据3）；控分寸——'这种利他行为值得提倡，但也要量力而行'，回扣原文。"}],"前置知识":["概括内容"]}],"name":"常考题型与答题公式"},{"id":"wenti","items":[{"name":"记叙文","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">六要素</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">时间地点人物，起因经过结果</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">线索</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">人物</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">事件</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">情感</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">物品</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">人称</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">第一人称亲切，第二人称抒情，第三人称客观</text></g></svg>","例子":["六要素：时间地点人物，起因经过结果","线索：人物","事件","情感","物品","人称：第一人称亲切，第二人称抒情，第三人称客观","顺序：顺叙/倒叙（设悬念）/插叙（补背景）","详略：详写主旨相关，略写次要","结尾常抒情议论点题"],"口诀":"六要素加线索，记叙文不迷路","易错":"","讲解":"以叙事写人为核心，抓线索理思路","怎么认":["找六要素：时间、地点、人物、起因、经过、结果，先搭骨架。","抓线索：时间线/物件（如'一枚戒指'）/情感变化，看哪条线把材料穿起来。","品细节：细节描写（动作/神态/语言）都是为刻画人物、表达主旨服务的，赏析时点出来。"],"例句解析":[{"句":"判断文体并说出线索：《风筝》全文围绕'风筝'展开，写'我'由毁筝到愧悔。","析":"三步：六要素齐（儿时/故乡/'我'与弟弟/毁筝/愧悔），是记叙文；抓线索——'风筝'贯穿始终，是物件线索；品细节——'我'毁筝时的动作细节，刻画了年少无知，为后文愧悔做铺垫。"}],"前置知识":["三遍阅读法"]},{"name":"议论文","图示":"<svg viewBox=\"0 0 640 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">议论文</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">观点+材料+证明方法</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">找论点：看标题、开头、结尾，旗帜最鲜明、能'一句话概括全文'的就是论点。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">分论据：道理论据和事实论据，看作者摆了哪些'证据'。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">辨方法：举例论证/道理论证/对比论证/比喻论证，对号入座。</text></g></svg>","例子":["论点（中心论点/分论点）","论据（事实/道理）","论证（举例/道理/对比/比喻）","中心论点常在标题","开头","结尾，标志词\"总之\"\"由此可见\"","事实论据要概括叙述，别抄原文长段","论证方法判断：看是讲事例","讲道理","正反比","打比方"],"口诀":"论点论据论证，三要素要分清","易错":"中心论点常在标题或开头结尾","讲解":"观点+材料+证明方法","怎么认":["找论点：看标题、开头、结尾，旗帜最鲜明、能'一句话概括全文'的就是论点。","分论据：道理论据（名言/原理/公理）和事实论据（事例/数据），看作者摆了哪些'证据'。","辨方法：举例论证/道理论证/对比论证/比喻论证，对号入座。"],"例句解析":[{"句":"分析《谈骨气》的论证思路。","析":"三步：找论点——开头'我们中国人是有骨气的'；分论据——文天祥/闻一多事例（事实论据）+'富贵不能淫'名言（道理论据）；辨方法——举例+道理+对比（三个事例层层递进）。思路：提出论点→举例证明→总结。"}],"前置知识":["举例论证","道理论证"]},{"name":"说明文","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">说明对象+说明方法</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">说明顺序</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">时间</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">空间</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">逻辑</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">语言</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">准确平实，\\\"大约\\\"\\\"可能\\\"表估计</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">下定义 vs 作诠释</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">前者严谨，后者通俗</text></g></svg>","例子":["说明对象+说明方法（举例子/列数字/打比方/作比较）","说明顺序：时间","空间","逻辑","语言：准确平实，\"大约\"\"可能\"表估计（删了就不准确）","下定义 vs 作诠释：前者严谨（\"……是……\"），后者通俗","列数字最直观，打比方最生动","逻辑顺序：总分","主次","现象到本质"],"口诀":"对象方法加顺序","易错":"说明方法判断是高频考点","讲解":"介绍事物事理，语言准确平实","怎么认":["抓对象：标题+首段，第一句常直接点出说明对象。","理顺序：时间顺序（发展过程）、空间顺序（由外到内）、逻辑顺序（总分/主次）。","辨方法：下定义/举例子/列数字/打比方/作比较，看到'比如''例如''据统计'就圈出来。"],"例句解析":[{"句":"分析《中国石拱桥》首段的说明方法。","析":"三步：抓对象——'石拱桥'；理顺序——首段由'石拱桥'总体介绍到'赵州桥'具体，是逻辑顺序中的'由总到分'；辨方法——'赵州桥横跨37米'是列数字，'像彩虹一样'是打比方。"}],"前置知识":["三遍阅读法"]},{"name":"散文","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">形散神聚</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">线索串材料</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">借景抒情、托物言志</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">线索</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">情感/游踪/物品</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">语言优美，善用修辞和意象</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">主旨含蓄</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">读出言外之意，别只看表面</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">托物言志</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">《爱莲说》以莲喻君子</text></g></svg>","例子":["形散神聚：线索串材料","借景抒情、托物言志","线索：情感/游踪/物品（《背影》以背影为线索）","语言优美，善用修辞和意象","主旨含蓄：读出言外之意，别只看表面","托物言志：《爱莲说》以莲喻君子"],"口诀":"线索串珠，情感是魂","易错":"散文主旨常含蓄，要读出言外之意","讲解":"抒情性强，意境优美","怎么认":["找'神'：形散神聚，先问'作者贯穿全文的情感/哲理是什么'，这就是'神'。","看意象：作者选了哪些物象（如'荷''月''柳'），每个意象寄托了什么情。","品语言：散文语言含蓄，慢读，圈出反复出现的词，那就是情感密码。"],"例句解析":[{"句":"《荷塘月色》中'荷'的意象寄托了什么？","析":"三步：找'神'——全文'淡淡的喜悦夹杂淡淡的哀愁'；看意象——荷'出淤泥而不染'，寄托作者洁身自好、不与世俗同流合污的情怀；品语言——'亭亭''袅娜'等词反复出现，情感密码是'高洁'。"}],"前置知识":["比喻","记叙文"]}],"name":"文体辨识与策略"}],"module":"阅读理解方法技巧库","标准":"综合中考语文阅读题型与课标阅读要求整理","说明":"覆盖通用阅读方法、六大常考题型答题公式、四大文体策略，与语法库的修辞/句式知识联动"},"writing":{"categories":[{"id":"shenti","items":[{"name":"抓题眼","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">《那盏灯》</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“灯”是题眼，引申为希望</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">指引</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">《温暖》</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“温暖”是情感核心</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">《第一次》</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"第一次\\\"是题眼，写人生初体验</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">《风景》</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">可实写自然风景，可虚写\\\"心灵风景\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">《礼物》</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"礼物\\\"可实物可抽象</text></g></svg>","例子":["《那盏灯》：“灯”是题眼，引申为希望","指引","《温暖》：“温暖”是情感核心","《第一次》：\"第一次\"是题眼，写人生初体验","《风景》：可实写自然风景，可虚写\"心灵风景\"","《礼物》：\"礼物\"可实物可抽象（教诲也是礼物）","方法：圈出题目中最能决定立意的词"],"口诀":"瞻前顾后一字不漏，题眼就是开门钥匙","易错":"跑题多因没审清题眼","讲解":"精细审题第一步：圈关键词，找准题目核心词（题眼）","怎么认":["圈关键词：把题目中最关键的1-2个词圈出来，多为动词或形容词（如'最美''那一刻'）。","问限制：这个词限制了什么？对象（写谁）、范围（哪件事）、情感（什么态度），三问定边界。","全程回扣：写每段前自查'这段扣题眼了吗'，结尾必须点题眼。"],"例句解析":[{"句":"题目《那一刻，我长大了》，题眼是什么？","析":"三步：圈关键词——'那一刻''长大了'；问限制——'那一刻'限制了时间（一个瞬间）、'长大了'限制了内容（成长感悟）；全程回扣——选材必须是一个瞬间的顿悟，结尾点'长大'。题眼：'那一刻'（时间）+'长大了'（成长）。"}],"前置知识":[]},{"name":"辨题型","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">命题作文</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">按题目写；材料作文：抓关键句立意</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">半命题</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">先补题再写</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">命题作文</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">题目即要求，一个字别改</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">半命题</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">《___，我的最爱》先补题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">材料作文</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">读懂材料倾向，别断章取义</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">话题作文</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">话题≠题目，自拟标题更出彩</text></g></svg>","例子":["命题作文：按题目写；材料作文：抓关键句立意","半命题：先补题再写","命题作文：题目即要求，一个字别改","半命题：《___，我的最爱》先补题（补具体事物）","材料作文：读懂材料倾向，别断章取义","话题作文：话题≠题目，自拟标题更出彩"],"口诀":"文题类型先分清，含义文体都要明","易错":"材料作文最忌断章取义、只抓局部","讲解":"注意文题类型、含义、文体类别、选材指向、立意信息","怎么认":["看形式：命题（一个字不能改）、半命题（先补题）、材料（先读懂材料）、话题（范围最宽）。","看文体要求：'文体不限'可写记叙/议论；'写一篇记叙文'必须记叙。","定开篇策略：命题开门见山点题；材料作文先概述材料再亮观点。"],"例句解析":[{"句":"题目《____，我的最爱》（半命题），如何下手？","析":"三步：看形式——半命题，先补题（如'读书，我的最爱'）；看文体——无限制，选最拿手的记叙；定开篇——补题后开门见山，'读书，是我的最爱'，直接点题。"}],"前置知识":["抓题眼"]},{"name":"审题六审","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">一审文题类型，二审文题含义，三审题眼，四</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">审文体</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">让写记叙文就别写成议论文</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">审选材指向</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"校园生活\\\"就别写家庭琐事</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">审立意信息</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">题目情感倾向</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">六审漏一审，跑题风险翻倍</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["一审文题类型，二审文题含义，三审题眼，四审文体，五审选材指向，六审立意信息","审文体：让写记叙文就别写成议论文","审选材指向：\"校园生活\"就别写家庭琐事","审立意信息：题目情感倾向（\"珍惜\"→正面）","六审漏一审，跑题风险翻倍"],"口诀":"类型含义题眼，文体选材立意","易错":"","讲解":"中考作文复习指导总结的审题六个要点","怎么认":["一审题眼：圈核心词；二审体裁：记叙/议论/不限；三审人称：第一/第三人称。","四审范围：时间/空间/对象限制；五审重点：题目侧重写什么；六审要求：字数、'不少于600字'等硬杠。","列清单：把六审结果写在草稿纸上，动笔前逐项打勾。"],"例句解析":[{"句":"用六审分析《我的初中生活》（600字以上，文体不限）。","析":"走六审：题眼'初中生活'；体裁不限→选记叙；人称第一人称'我'；范围锁定初中三年；重点在'生活'（事）而非'感想'；要求600字以上。清单列完，选材'军训''运动会'等，动笔。"}],"前置知识":["抓题眼","辨题型"]}],"name":"审题"},{"id":"liyi","items":[{"name":"立意三标准","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">正确</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">集中</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">深刻</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">正确</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">不能宣扬作弊、报复等负能量</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">集中</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">一篇只讲一个道理，贪多嚼不烂</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">深刻</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">从\\\"妈妈很辛苦\\\"挖到\\\"理解与感恩\\\"</text></g></svg>","例子":["正确（价值观端正）","集中（一个中心）","深刻（有思考）","正确：不能宣扬作弊、报复等负能量","集中：一篇只讲一个道理，贪多嚼不烂","深刻：从\"妈妈很辛苦\"挖到\"理解与感恩\""],"口诀":"中心是灵魂，正确集中深","易错":"立意贪多求全是大忌","讲解":"确立文章中心思想，犹如文章灵魂","怎么认":["先求正确：符合主流价值观，不偏激、不消极，'正确'是底线。","再求深刻：透过现象看本质，多问一个'为什么'（'为什么感动？因为母爱无私'）。","最后求新颖：在正确、深刻的基础上，找一个独特的角度切入。"],"例句解析":[{"句":"题目《感动》，三个立意：A.陌生人帮我指路 B.母亲深夜陪我复习 C.环卫工凌晨扫街，对比优劣。","析":"用三标准检验：A正确但浅；B正确、有真情实感，深刻度中等；C正确，且'平凡岗位的不平凡坚守'比B更深刻、新颖。排序：C＞B＞A。选C。"}],"前置知识":["审题六审"]},{"name":"立意八类","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">生命意义</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">生活感悟的滋味</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">自然景物</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">对周遭世界的感悟</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">情感体验</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">珍藏的人和事</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">享受幸福</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">温暖与智慧的情节</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">成功成长</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">花季酸甜苦辣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">道德修养</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">诚信</text></g></svg>","例子":["生命意义：生活感悟的滋味","自然景物：对周遭世界的感悟","情感体验：珍藏的人和事","享受幸福：温暖与智慧的情节","成功成长：花季酸甜苦辣","道德修养：诚信","勇敢","善良","哲理品悟：生活细节提炼规律","告别往昔：值得珍藏的片段"],"口诀":"生命自然情感，幸福成长道德，哲理告别","易错":"8类有交叉，按题目选最贴切的一类","讲解":"中高考作文立意范畴基本不出这8类，备考时每类准备一个典型题材","怎么认":["先吃透八类：亲情/友情/成长/励志/爱国/环保/文化/哲理（备考时每类备一个典型题材）。","审题时对号入座：题目往哪类靠，就调用哪类的素材库。","一题多立：同一题目试着往2-3类上靠，选最新颖深刻的那类。"],"例句解析":[{"句":"题目《坚守》，如何调用八类素材？","析":"三步：吃透八类——'坚守'可往励志类（备考素材：女排精神）或文化类（非遗传承人）靠；对号入座——'坚守'最贴励志类；一题多立——试'亲情类'（母亲坚守陪伴）也成立，但励志类更新颖。定：励志类，素材女排。"}],"前置知识":["立意三标准"]},{"name":"审题立意方法（材料作文）","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">抓关键句法、主旨倾向法、由果溯因法、求同</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">抓关键句</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">材料中的议论句多是\\\"题眼\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">由果溯因</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">从结果倒推原因找立意</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">求同存异</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">多则材料找共同点</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">辩证分析</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">看到\\\"失去\\\"也想到\\\"得到\\\"</text></g></svg>","例子":["抓关键句法、主旨倾向法、由果溯因法、求同分析法、辩证分析法","抓关键句：材料中的议论句多是\"题眼\"","由果溯因：从结果倒推原因找立意","求同存异：多则材料找共同点","辩证分析：看到\"失去\"也想到\"得到\""],"口诀":"全面分析抓关键，辩证因果多角度","易错":"过多纠缠局部细节会偏题","讲解":"高考常用：先整体把握材料，再抓关键词句作突破口，用辩证/因果/对比等思维多角度审视","怎么认":["整体把握：先读懂材料讲了一个什么事/什么理，不急于下结论。","抓关键词句：材料中反复出现、议论性强的句子，就是立意突破口。","多角度审视：用辩证（正反两面）、因果（为什么会这样）、对比（古今/中外）三种思维各想一遍，选最深的。"],"例句解析":[{"句":"材料：'小树问大树：为什么你长这么高？大树说：我把根扎得更深。'如何立意？","析":"三步：整体把握——讲根基与成长的关系；抓关键词——'根扎得更深'是突破口；多角度——因果思维：因为根深所以长高→立意'打好基础才能走得更远'；辩证思维：高与深、表与里的统一。定：'基础决定高度'。"}],"前置知识":["审题六审","立意三标准"]}],"name":"立意"},{"id":"xuancai","items":[{"name":"选材三原则","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">熟悉</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">动情</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">独特</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">熟悉</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">写亲身经历，细节才真实</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">动情</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">自己没感动，读者不会感动</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">独特</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">大家都写\\\"雨中送伞\\\"，你写\\\"雨后初晴\\\"就跳出来</text></g></svg>","例子":["熟悉（亲身经历）","动情（真体验真感受）","独特（与众不同）","熟悉：写亲身经历，细节才真实","动情：自己没感动，读者不会感动","独特：大家都写\"雨中送伞\"，你写\"雨后初晴\"就跳出来"],"口诀":"熟悉动情加独特，第一人称最稳妥","易错":"考场瞎编乱造易出纰漏","讲解":"选自己最熟悉、最动情的生活来写，用第一人称写亲身经历","怎么认":["选最熟悉的：写自己亲身经历的，细节才真实，编的故事一读就假。","选最动情的：自己写的时候有感觉（想哭/想笑），读者才会有感觉。","用第一人称：'我'的视角最有代入感，除非题目要求第三人称。"],"例句解析":[{"句":"题目《难忘的一件事》，三个备选：A.编的救火故事 B.奶奶教我包饺子 C.看过的电影情节。选哪个？","析":"用三原则检验：A是编的，细节必假，排除；C是别人的故事，无真情实感，排除；B亲身经历、最熟悉，包饺子时奶奶的手、面粉的香都记得，真情实感。选B。"}],"前置知识":["立意三标准"]},{"name":"素材积累","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">8个立意范畴各备1个典型题材</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">平时记录</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">春花秋月、校园草木、家庭琐事</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">每类备1个\\\"万能素材\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">建素材本</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">按\\\"人物</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">事件</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">金句\\\"分类记</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["8个立意范畴各备1个典型题材","平时记录：春花秋月、校园草木、家庭琐事","每类备1个\"万能素材\"（如\"外婆的灶台\"可套亲情/成长/乡愁）","建素材本：按\"人物","事件","金句\"分类记","从课文找：朱自清《背影》可化用父爱题材","从时事找：神舟发射可套\"奋斗","家国\"立意"],"口诀":"8类题材常备，观察生活常记","易错":"","讲解":"把8个立意范畴各准备一个生动题材，考场直接调用","怎么认":["建素材库：按八类（亲情/友情/成长/励志/爱国/环保/文化/哲理），每类准备1个最生动的题材，写成100字小卡片。","一材多用：同一个素材，换角度能套不同题目（如'女排精神'可套坚守/拼搏/团结）。","考场调用：审题定立意后，直接从素材库提取对应卡片，改头换面用。"],"例句解析":[{"句":"素材卡'母亲雨中送伞'，能套哪些题目？","析":"三步：建卡——亲情类素材卡'母亲雨中送伞（100字）'；一材多用——《感动》（母爱）、《那一刻我长大了》（懂事瞬间）、《爱》（亲情之爱）都能套；考场调用——题目《温暖》→提取此卡→开头'雨点砸在伞面上，也砸在我心里'，直接用。"}],"前置知识":[]},{"name":"细节描写","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">写人</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">外貌</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">动作</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">神态</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">语言</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">心理</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">写事</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">细节+环境描写</text></g></svg>","例子":["写人：外貌","动作","神态","语言","心理","写事：细节+环境描写","抓住“最动人的那个细节”","动作链：\"抓起书包—冲出门—跳上车\"（连续动词）","神态+心理：\"他低头抠着衣角，心里像打翻了调料瓶\"","环境烘托：\"蝉鸣聒噪\"衬烦躁，\"细雨如丝\"衬忧愁","忌：流水账\"然后…然后…\"（无细节=无画面）"],"口诀":"人物六描写，事件抓细节","易错":"没有细节的叙事是流水账","讲解":"细节是记叙文的生命，环境描写烘托气氛","怎么认":["找'特写镜头'：把最动人的瞬间定格，写动作/神态/语言（如'她的手在抖'胜过'她很激动'）。","用环境烘托：人物心情好写'阳光'，心情差写'阴雨'，环境是心情的外衣。","删空话：'非常''很''十分'删掉，换成具体可感的细节。"],"例句解析":[{"句":"把'妈妈很辛苦'升级为细节描写。","析":"三步：找特写——'妈妈鬓角的白发在灯下格外刺眼，她揉了揉发酸的腰'；环境烘托——'窗外夜已深，只有厨房的灯还亮着'；删空话——删掉'很辛苦'三字，辛苦已在细节里。升级完成。"}],"前置知识":["选材三原则"]}],"name":"选材"},{"id":"jiegou","items":[{"name":"总分总结构","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">开头点题→中间分述→结尾升华</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">记叙文可用1-3-1或1-4-1</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">开头</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">开门见山点题，别绕三圈</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">中间</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">3-4个小片段</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">分论点，各成一段</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">结尾</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">回扣标题+升华</text></g></svg>","例子":["开头点题→中间分述→结尾升华","记叙文可用1-3-1或1-4-1（开头1段、中间3-4段、结尾1段）","开头：开门见山点题，别绕三圈","中间：3-4个小片段","分论点，各成一段","结尾：回扣标题+升华（抒情/议论）","忌\"大肚子\"：中间一段写半页，头尾各两行"],"口诀":"总分总最稳，六七段最顺","易错":"忌“大肚子作文”（中间一段超长）/大头/大尾巴","讲解":"考场最保险的结构；六七百字配六七段，视觉协调","怎么认":["总起：开头1段，点题+亮观点（50字内）。","分述：中间4-5段，每段一个分论点/一个事例，段首句就是小标题。","总结：结尾1段，重申观点+升华，首尾呼应。六七百字配六七段。"],"例句解析":[{"句":"用总分总结构安排《论坚持》（议论文）。","析":"三步：总起——'坚持是成功的基石'（点题）；分述——分论点1'坚持需要目标'（事例：马拉松）、分论点2'坚持需要方法'（事例：庖丁解牛）、分论点3'坚持需要心态'（事例：爱迪生）；总结——'坚持到底，方见彩虹'，呼应开头。6段650字。"}],"前置知识":[]},{"name":"一线穿珠","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">以人物品质为主线，串起几个典型片段</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">如《我的老师》</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">线索可是物品</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">《背影》以\\\"背影\\\"串起四次相见</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">线索可是情感</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">从\\\"讨厌\\\"到\\\"理解\\\"母亲</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">线索可是时间</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">童年—少年—现在</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">每个\\\"珠子\\\"都要扣住这根线</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["以人物品质为主线，串起几个典型片段","如《我的老师》","线索可是物品：《背影》以\"背影\"串起四次相见","线索可是情感：从\"讨厌\"到\"理解\"母亲","线索可是时间：童年—少年—现在","每个\"珠子\"（片段）都要扣住这根线"],"口诀":"一线串珠不旁逸","易错":"","讲解":"无贯穿中心事件时，以人物活动/品质为主线组织材料","怎么认":["定主线：没有一个中心事件时，找一条线——人物（如'奶奶'）、物件（如'老照片'）、情感（如'愧疚'）。","选珍珠：围绕主线选3-4个材料，每个材料独立成段。","穿起来：开头点线，中间每段扣线，结尾收线，一线到底。"],"例句解析":[{"句":"用一线穿珠写《奶奶的味道》。","析":"三步：定主线——'奶奶做的饭菜香'为线；选珍珠——珍珠1'饺子香'（除夕）、珍珠2'粥香'（生病时）、珍珠3'粽子香'（端午）；穿起来——开头'奶奶的味道，是我记忆的线'，每段以香味过渡，结尾'线断了，香还在'。"}],"前置知识":["记叙文"]},{"name":"开头技巧","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">一句话开头</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">直接交代时间地点人物事件</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">悬念开头</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">名句开头</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">排比开头</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">名句开头</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"长风破浪会有时\\\"→引出\\\"追梦\\\"主题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">排比开头</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"母爱是伞，父爱是山…\\\"→排比造势</text></g></svg>","例子":["一句话开头：直接交代时间地点人物事件","悬念开头","名句开头","排比开头","名句开头：\"长风破浪会有时\"→引出\"追梦\"主题","排比开头：\"母爱是伞，父爱是山…\"→排比造势","悬念开头：\"那天，我做了一个决定…\"→勾住读者","忌：开头超过5行还不见主题"],"口诀":"开头不过5行，开门见山最行","易错":"开头玩技巧过长会喧宾夺主","讲解":"开篇两三句点出记叙要点或明确主题，简洁洗练","怎么认":["开门见山：第一句就点题（如'那是我最难忘的一天'），不绕弯子。","设悬念：用反常/疑问开篇（如'谁也没想到，那场雨改变了我'），勾住读者。","控字数：开头两三句、50字内必须入题，考场不许'千呼万唤始出来'。"],"例句解析":[{"句":"为《第一次坐过山车》写两种开头并点评。","析":"三步：开门见山版——'第一次坐过山车，我差点哭出来。'（点题快）；设悬念版——'如果再给我一次机会，我绝不上那辆车。'（勾人）；控字数——两版都在30字内入题。考场推荐悬念版，更抓人。"}],"前置知识":[]},{"name":"结尾技巧","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">抒情结尾</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">升华情感</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">议论结尾</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">点明哲理、照应标题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">首尾呼应</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">开头\\\"灯\\\"，结尾\\\"这盏灯，至今照着我\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">名句收束</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"会当凌绝顶\\\"→升华\\\"进取\\\"主题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">戛然而止</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">故事停在高潮，余味悠长</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">忌</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">结尾另起新话题</text></g></svg>","例子":["抒情结尾：升华情感","议论结尾：点明哲理、照应标题","首尾呼应：开头\"灯\"，结尾\"这盏灯，至今照着我\"","名句收束：\"会当凌绝顶\"→升华\"进取\"主题","戛然而止：故事停在高潮，余味悠长","忌：结尾另起新话题（跑题前兆）"],"口诀":"结尾抒情或议论，照应标题点中心","易错":"结尾忌另起新话题","讲解":"记叙文结尾抒情+哲理，议论文结尾重申论点","怎么认":["记叙文：抒情+哲理（如'那一刻我明白，成长就是学会承担'），忌喊口号。","议论文：重申论点+升华（如'让坚持成为习惯，成功自会敲门'）。","首尾呼应：结尾的关键词与开头呼应，形成闭环。"],"例句解析":[{"句":"为《那一刻，我长大了》写结尾（开头：'雨下得很大，我站在校门口不知所措。'）。","析":"三步：记叙文用抒情+哲理——'雨还在下，但我心里已放晴。原来，长大就是在无人撑伞时，学会为自己撑伞。'；首尾呼应——'雨'呼应开头，'撑伞'升华；检查：无口号，有哲理。"}],"前置知识":["开头技巧"]}],"name":"结构"},{"id":"yuyan","items":[{"name":"短句为主","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">一个句子主谓宾定状补齐了，就用句号</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">忌一逗到底</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">长句拆短</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"他跑进教室放下书包拿出课本\\\"→\\\"他跑进教室。放下书包，拿出课本。\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">短句有节奏感</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">适合写紧张场面</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">一逗到底最易犯语病</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">长短结合</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">叙事用短句，抒情可偶用长句</text></g></svg>","例子":["一个句子主谓宾定状补齐了，就用句号","忌一逗到底","长句拆短：\"他跑进教室放下书包拿出课本\"→\"他跑进教室。放下书包，拿出课本。\"","短句有节奏感：适合写紧张场面","一逗到底最易犯语病（成分残缺/搭配不当）","长短结合：叙事用短句，抒情可偶用长句"],"口诀":"短句有力，长句易病","易错":"长句最易犯语病（呼应语法库病句）","讲解":"句子短促有力，节奏好且不易出错","怎么认":["一切两行：凡是超过两行的长句，拆成两个短句。","多用句号：'。'越多，节奏越明快，也越不容易病句。","长短结合：三五个短句后，来一个长句收束，有节奏感。"],"例句解析":[{"句":"把长句'因为当时天已经很晚了而且还下着很大的雨所以我就决定还是先在同学家住一晚明天再回去'改短。","析":"三步：切两行——'天很晚了。雨很大。我决定在同学家住一晚。'；多用句号——4个句号，节奏明快；长短结合——'明天再回去。'收束。改后无病句，节奏好。"}],"前置知识":["主语","谓语"]},{"name":"修辞点缀","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">比喻拟人排比设问，点缀2-3处即可</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">比喻</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"父爱如山\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">排比</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">开头</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">结尾各一组，气势立现</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">设问自答</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"什么是勇敢？勇敢是…\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">忌</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">为修辞而修辞，堆砌成\\\"油腻文\\\"</text></g></svg>","例子":["比喻拟人排比设问，点缀2-3处即可","比喻：\"父爱如山\"（2-3处，多了就腻）","排比：开头","结尾各一组，气势立现","设问自答：\"什么是勇敢？勇敢是…\"","忌：为修辞而修辞，堆砌成\"油腻文\""],"口诀":"修辞2-3处，语言即出彩","易错":"堆砌修辞会油腻","讲解":"呼应语法库8种修辞，恰当使用让语言出彩","怎么认":["每段一修辞：记叙文每段至少用一个比喻/拟人/排比，不许'白开水'。","点到为止：修辞是'点缀'不是'堆砌'，一处用好胜过三处用滥。","呼应语法库：比喻/拟人/夸张/排比/对偶/反复/设问/反问，8种轮着用。"],"例句解析":[{"句":"给'天上的星星很多'加修辞点缀。","析":"三步：每段一修辞——用比喻：'天上的星星，像撒在黑布上的碎钻'；点到为止——一句即可，不再加排比；呼应语法库——这是'比喻'，本体星星、喻体碎钻。点缀完成。"}],"前置知识":["比喻","拟人","排比"]},{"name":"描写升级","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">动作描写</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">连续动词</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">语言描写</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">神态+潜台词</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">环境描写</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">烘托人物心情</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">\\\"讲故事\\\"变\\\"演故事\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">别说\\\"他很生气\\\"，写\\\"他攥紧拳头，指节发白\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">五感调动</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">写雨不只写\\\"大\\\"，写\\\"砸在伞上的脆响\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">动静结合</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"蝉鸣\\\"动+\\\"树影\\\"静</text></g></svg>","例子":["动作描写：连续动词","语言描写：神态+潜台词","环境描写：烘托人物心情","\"讲故事\"变\"演故事\"：别说\"他很生气\"，写\"他攥紧拳头，指节发白\"","五感调动：写雨不只写\"大\"，写\"砸在伞上的脆响\"","动静结合：\"蝉鸣\"动+\"树影\"静","忌：通篇叙述无描写=嚼蜡"],"口诀":"写人要有动作语言，写事要有细节环境","易错":"","讲解":"描写是把“讲故事”变成“演故事”的关键","怎么认":["五感全开：视觉+听觉+嗅觉+味觉+触觉，能调动几种调动几种。","动静结合：静态描写（'湖面如镜'）+动态描写（'鱼跃起'），有动有静。","删'讲'留'演'：'他很生气'是讲，'他一拳砸在桌上，茶杯跳了起来'是演，删讲留演。"],"例句解析":[{"句":"把'公园很美'升级为描写。","析":"三步：五感全开——'桂花香飘过来（嗅觉），鸟叫声此起彼伏（听觉），湖面闪着碎金（视觉）'；动静结合——'柳枝垂着不动（静），一只蜻蜓点水而过（动）'；删讲留演——删掉'很美'二字，美已在描写里。升级完成。"}],"前置知识":["细节描写","修辞点缀"]}],"name":"语言"}],"module":"写作技巧库","标准":"综合中高考作文指导（审题/立意/选材/结构/语言）与课标写作要求整理","说明":"覆盖考场作文全流程：审题→立意→选材→结构→语言，与语法库（病句/修辞/句式）联动"}};